window.__Q=window.__Q||{};window.__Q["prev/8/A1"]=[{"q":"低位小肠梗阻的患者，可有腹胀、腹痛、剧烈呕吐及排便、排气停止的症状，其呕吐物的性质应是","o":["呕吐棕黄色带粪臭的内容物","呕吐大量胃、肠、胰液和胆汁的内容物","剧烈呕吐胃内容物后呕吐血液","呕吐大量隔宿食物","喷射性呕吐"],"a":0,"e":"低位小肠梗阻时肠内容物淤滞、细菌繁殖，呕吐出现较晚，呕吐物为棕黄色、带粪臭味的小肠内容物。粪臭味是低位梗阻的典型特点，不含胆汁则提示梗阻平面在十二指肠乳头以上。"},{"q":"下列不属于入院记录的书写形式的是","o":["入院记录","再次或多次入院记录","24h内出入院记录","24h内入院死亡记录","死亡病例讨论记录"],"a":4,"e":"入院记录包括入院记录、再次或多次入院记录、24小时内入出院记录和24小时内入院死亡记录。死亡病例讨论记录属病程记录中的讨论记录，于病人死亡一周内由科主任主持完成。"},{"q":"主动脉瓣第二听诊区位于","o":["心尖部","胸骨左缘第2肋间","胸骨右缘第2肋间","胸骨左缘第4、5肋间","胸骨左缘第3肋间"],"a":4,"e":"主动脉瓣第二听诊区即Erb区，位于胸骨左缘第3肋间。主动脉瓣区在胸骨右缘第2肋间，肺动脉瓣区在胸骨左缘第2肋间，三尖瓣区在胸骨左缘第4、5肋间。"},{"q":"下述引起局部性水肿疾病的原因均正确，但除外","o":["肢体局部炎症","肢体静脉血栓形成","上腔静脉阻塞","门静脉压力增高","象皮腿"],"a":3,"e":"门静脉压力增高引起的是肝源性全身性水肿，呈全身性分布。局部性水肿包括炎症性、淋巴回流障碍性和静脉回流障碍性三类，上腔静脉阻塞、静脉血栓、象皮腿均属局部性水肿。"},{"q":"下列关于肝脏的描述均正确，但除外","o":["肝脏位置因体位、呼吸而改变","右肋缘下正常时触不到肝脏","右肋缘下触到肝脏即是肝大","直立与吸气时，肝稍下降","单靠触诊不能完全判断肝大"],"a":2,"e":"腹壁松软的瘦长体型者深吸气时可在肋弓下触及肝下缘1cm以内，属正常范围，故肋缘下触及肝脏不等于肝大。正常成人肝脏一般肋缘下触不到，肝位置随体位和呼吸改变，直立及吸气时稍下降。"},{"q":"低钾血症是指血清钾低于","o":["3.4mmol/L","3.5mmol/L","4.1mmol/L","4.7mmol/L","5.6mmol/L"],"a":1,"e":"血清钾低于3.5mmol/L即为低钾血症，其中3.0～3.5mmol/L为轻度，2.5～3.0mmol/L为中度，低于2.5mmol/L为重度。常见原因为摄入不足、丢失过多及细胞外钾向细胞内转移。"},{"q":"以Hb为标准，下列可认为有贫血的是","o":["男性Hb＜125g/L，女性Hb＜115g/L","成年男性Hb＜125g/L，成年女性Hb＜115g/L","男性Hb＜120g/dl，女性Hb＜110g/dl","男性Hb＜125g/dl，女姓Hb＜115g/dl","成年男性Hb＜120g/L，成年女性Hb＜110g/L"],"a":4,"e":"我国贫血的诊断标准为成年男性Hb＜120g/L、成年女性（非妊娠）Hb＜110g/L、孕妇＜100g/L，低于界值即认为有贫血。单位须用g/L，写作g/dl则数值与单位不符。"},{"q":"内生肌酐清除率参考值是","o":["50～70ml/min","70～90ml/min","80～120ml/min","120～130ml/min","130～150ml/min"],"a":2,"e":"内生肌酐清除率反映肾小球滤过功能，成人参考区间为80～120ml/min，老年人随年龄增长有自然下降趋势。其测定须用体表面积校正，并连续留取24小时尿液。"},{"q":"以下哪种细胞与杀伤无关","o":["NK细胞","LAK细胞","Th细胞","TIL细胞","K细胞"],"a":2,"e":"Th细胞是辅助性T细胞，通过分泌细胞因子辅助B细胞和细胞毒性T细胞应答，本身不直接杀伤靶细胞。NK、LAK、TIL细胞及K细胞均具直接杀伤或ADCC杀伤作用。"},{"q":"下列叙述正确地描述了心前区震颤的是","o":["常见于瓣膜关闭不全的病变","它是触诊时感觉到的较强烈的振动感","它的出现表明心力衰竭","狭窄越重，震颤越强，极度狭窄时，震颤最强","它是器质性心脏病的特征性体征"],"a":4,"e":"震颤是触诊时触及的微细振动，与听诊杂音相对应，见于瓣膜狭窄或关闭不全、先天性心脏病等，是器质性心脏病的特征性体征。瓣膜极度狭窄、血流极少时震颤反而减弱或消失。"},{"q":"发热发生机制中，共同的基本因素是","o":["外源性致热原","内生性致热原","前列腺素","精氨酸加压素","白介素"],"a":1,"e":"各种致热因素最终均通过激活单核巨噬细胞等释放内源性致热原，后者经血-脑脊液屏障作用于体温调定点，使调定点上移而发热，故内源性致热原是发热的共同基本环节。"},{"q":"腹部视诊检查内容不包括","o":["腹外形","呼吸运动","腹壁静脉","胃肠型","腹壁紧张度"],"a":4,"e":"腹壁紧张度属触诊内容，靠触诊判断腹肌有无痉挛与抵抗。腹部视诊观察腹外形、呼吸运动、腹壁静脉、胃肠型及蠕动波、腹壁皮肤与脐部等。"},{"q":"负性心尖冲动最常见于","o":["粘连性心包炎","左心室肥大","左侧胸腔积液","大量心包积液","急性心肌梗死"],"a":0,"e":"心脏收缩时心尖部胸壁搏动内陷称负性心尖搏动，见于粘连性心包炎或心包与周围组织广泛粘连。重度右室肥厚致心脏顺钟向转位、左心室向后移位时也可出现。"},{"q":"最常见的第二心音分裂是","o":["生理分裂","通常分裂","固定分裂","反常分裂","逆分裂"],"a":1,"e":"通常分裂是临床最常见的S2分裂，受呼吸影响，见于右室排血时间延长如二尖瓣狭窄伴肺动脉高压、肺动脉瓣狭窄，或左室射血时间缩短如二尖瓣关闭不全、室间隔缺损。"},{"q":"下列属于中性粒细胞反应性增多的是","o":["原发性血小板增多症","白血病","急性感染或炎症","骨髓纤维化症","真性红细胞增多症"],"a":2,"e":"急性感染或炎症是中性粒细胞反应性增多最常见的原因，急性化脓性感染时尤为显著。白血病、骨髓纤维化、原发性血小板增多症和真性红细胞增多症属骨髓增殖性肿瘤，为克隆性增多。"},{"q":"下列关于舒张期额外心音的叙述正确的是","o":["喷射音","喀喇音","奔马律","舒张期隆隆样杂音","舒张期叹气样杂音"],"a":2,"e":"奔马律是发生于舒张期的额外心音，与原有S1、S2组成三音心律，为心肌严重损害的体征，常见于心力衰竭、急性心肌梗死、重症心肌炎和扩张型心肌病。喷射音、喀喇音位于收缩期。"},{"q":"抗体的特异性是由下列哪一区段决定的","o":["重链和轻链","重链易变区","轻链易变区","重链和轻链的易变区","重链和轻链的恒定区"],"a":3,"e":"抗体的抗原结合部位由重链和轻链的易变区共同构成，该区氨基酸序列高度可变，决定抗体与抗原结合的特异性。恒定区决定抗体的类别及效应功能。"},{"q":"下列各项为捻发音的特点，但应除外","o":["是一种极细而均匀一致的湿啰音","颇似在耳边用手指捻发时发出之音","产生是由于黏着、陷闭的肺泡壁被气流冲开重新充气","正常人在临床上不可能出现此种改变","少数人在数次深吸气或咳嗽后可消失"],"a":3,"e":"捻发音为极细而均匀一致的湿啰音，因黏着陷闭的肺泡壁被气流冲开重新充气而产生。正常人在深吸气或咳嗽后亦可于肺底闻及，数次深呼吸后即消失，并非病理状态所独有。"},{"q":"为鉴别黄疸类型，最有意义的检查项目是","o":["总胆红素","结合胆红素","非结合胆红素","结合胆红素/总胆红素","尿胆原"],"a":3,"e":"结合胆红素与总胆红素的比值对鉴别黄疸类型最有价值：CB/STB＜20%提示溶血性黄疸，20%～50%为肝细胞性黄疸，＞50%为梗阻性黄疸。单测某一项胆红素难以区分类型。"},{"q":"血清铜蓝蛋白降低最常见于","o":["肝豆状核变性","肝硬化","肝转移癌","各种感染","白血病"],"a":0,"e":"肝豆状核变性（Wilson病）为常染色体隐性遗传的铜代谢障碍，血浆铜蓝蛋白合成减少，游离铜沉积于肝和脑基底核，血清铜蓝蛋白降低是其重要生化特征，角膜可见K-F环。"},{"q":"梨形心最常见于下列何种疾病","o":["肺源性心脏病","冠状动脉粥样硬化性心脏病","二尖瓣狭窄","二尖瓣关闭不全","主动脉瓣关闭不全"],"a":2,"e":"二尖瓣狭窄时左心房增大并伴肺动脉段扩大，心腰丰满或膨出，心浊音界呈梨形。主动脉瓣关闭不全表现为向左下增大的靴形心，肺源性心脏病则为右心室增大。"},{"q":"下列属于非感染性发热的疾病是","o":["肺结核","肺炎","急性肾盂肾炎","伤寒","中暑"],"a":4,"e":"中暑属物理性损害所致的非感染性发热，因散热障碍使体温升高。肺结核、肺炎、急性肾盂肾炎和伤寒均由病原体感染引起，属感染性发热。"},{"q":"可以引起QT间期缩短的药物是","o":["地高辛","美托洛尔","普罗帕酮","胺碘酮","利多卡因"],"a":0,"e":"地高辛可缩短心室复极时间，使QT间期缩短，并出现ST段鱼钩样下移和T波倒置。胺碘酮、普罗帕酮、美托洛尔和利多卡因则多使QT间期延长。"},{"q":"下列试验检测纤溶功能的是","o":["凝血酶凝固时间测定","可溶性纤维蛋白单体复合物的检查","纤维蛋白肽A测定","凝血酶-抗凝血酶Ⅲ复合物测定","纤维蛋白肽B测定"],"a":1,"e":"可溶性纤维蛋白单体复合物是凝血酶生成敏感而特异的分子标志物：凝血酶使纤维蛋白原先后脱去纤维蛋白肽A和肽B，剩余纤维蛋白单体聚合成可溶性复合物，反映凝血与纤溶系统的激活。"},{"q":"关于主要症状的特点，不包括","o":["部位","性质","发展与演变过程","持续时间及程度","缓解与加重的因素"],"a":2,"e":"症状的特点包括部位、性质、持续时间、程度以及缓解与加重的因素；病情的发展与演变在现病史中单列一项，指主要症状的变化或新症状的出现，不属主要症状的特点。"},{"q":"下面情况易致低血钾的是","o":["严重腹泻","高热","创伤","急性肾衰少尿期","缺氧"],"a":0,"e":"严重腹泻时含钾丰富的消化液大量丢失，血容量减少又致醛固酮分泌增多、尿钾排出增加，故易致低血钾。急性肾衰竭少尿期、创伤和缺氧多引起高血钾。"},{"q":"下列均为腹部触诊的正确方法，但除外","o":["边触诊边观察被检查者的表情","一律遵循自左下腹开始逆时针方向触诊原则","触诊脾脏时可向右侧卧位","触诊肾脏时可用坐位或立位","被检查者两手自然放于躯干两侧两腿屈曲"],"a":1,"e":"腹部触诊原则是先触诊健康部位、再逐渐移向病变区域，以免造成病人感受的错觉。自左下腹逆时针至右下腹再到脐部是腹部叩诊的顺序，并非触诊必须一律遵循。"},{"q":"关于二尖瓣关闭不全的叙述，下列哪项是正确的","o":["相对性二尖瓣关闭不全的杂音粗糙","二尖瓣瓣叶和腱索病变可引起相对性二尖瓣关闭不全","左心室扩大可引起器质性二尖瓣关闭不全","功能性二尖瓣关闭不全的杂音在原因去除后可消失","器质性二尖瓣关闭不全杂音为递增型"],"a":3,"e":"功能性（相对性）二尖瓣关闭不全由左心室扩大致二尖瓣环扩张引起，杂音柔和，随心脏缩小、病因去除而减轻或消失。器质性者杂音粗糙，呈全收缩期一贯型。"},{"q":"正常人心尖搏动位于第5肋间的哪一部位","o":["胸骨左缘外0.5～1、0cm","左锁骨中线内0.5～1.0cm","左锁骨中线外0.5～1.0cm","左锁骨中线外1.0～2.0cm","左腋前线内0.5～1.0cm"],"a":1,"e":"正常成人心尖搏动位于第5肋间、左锁骨中线内侧0.5～1.0cm处，搏动直径为2.0～2.5cm。左心室增大时搏动向左下移位，右心室增大时向左移位。"},{"q":"用于评价阻塞性通气功能障碍程度的指标为","o":["FEV1/FVC","FEV1%pred","PEF","FVC","MEF50"],"a":1,"e":"阻塞性通气功能障碍的程度按FEV1占预计值百分比分级：≥70%为轻度，60%～69%中度，50%～59%中重度，35%～49%重度，＜35%极重度。FEV1/FVC用于判定有无阻塞而非程度。"},{"q":"心脏收缩时，心脏哪一部分形成心尖冲动","o":["左心房","右心房","右心室","左心室","全心"],"a":3,"e":"心尖搏动主要由心室收缩时心尖向前冲击前胸壁相应部位而形成，心尖部由左心室构成，故形成心尖搏动的是左心室。右心室增大时心尖搏动可向左移位。"},{"q":"诊断思维应该注意的问题，不包括","o":["现象和本质","主要和次要","局部和整体","典型和不典型","高花费和低花费"],"a":4,"e":"诊断思维应注意现象与本质、主要与次要、局部与整体、典型与不典型、静态与动态等关系。医疗费用的高低不属于诊断思维应把握的问题。"},{"q":"细胞外铁消失，铁粒幼细胞＜10%，最可能的疾病是","o":["铁粒幼细胞贫血","溶血性贫血","缺铁性贫血","巨幼红细胞贫血","再生障碍性贫血"],"a":2,"e":"缺铁性贫血早期骨髓贮存铁即已耗尽，细胞外铁呈阴性，铁粒幼红细胞常＜15%甚至为0。铁粒幼细胞贫血则细胞外铁增加，并见环形铁粒幼红细胞＞15%。"},{"q":"下述何种情况肺下界移动度不消失","o":["膈神经麻痹","肺气肿","血气胸","胸腔大量积液","广泛胸膜肥厚粘连"],"a":1,"e":"肺气肿时肺组织弹性回缩力下降，肺下界下移而移动度仅减弱并不消失。胸腔大量积液、气胸、广泛胸膜肥厚粘连时肺下界及移动度不能叩得，膈神经麻痹时亦消失。"},{"q":"导致排尿困难的动力性梗阻原因是","o":["前列腺癌","膀胱结核","糖尿病","前列腺增生症","先天性后尿道发育不全"],"a":2,"e":"糖尿病自主神经病变引起神经源性膀胱，逼尿肌收缩无力而致排尿困难，属动力性梗阻。前列腺癌、前列腺增生、膀胱结核及后尿道发育异常均属机械性梗阻。"},{"q":"下列为肺部叩诊呈过清音的正确描述，但应除外","o":["比清音的音调高","持久性良好","呈较深的回声","声音相对较强","极易听到"],"a":0,"e":"过清音音调较清音低、音响较清音强，介于鼓音与清音之间，见于肺组织含气量增多、弹性减弱如肺气肿。称其音调比清音高与定义正好相反。"},{"q":"丝虫病引起的淋巴管炎可导致","o":["阴囊湿疹","阴囊水肿","阴囊象皮肿","阴囊疝","鞘膜积液"],"a":2,"e":"阴囊象皮肿表现为阴囊皮肤水肿、粗糙、增厚如橡皮样，多由血丝虫病引起的淋巴管炎或淋巴管阻塞所致，属淋巴回流障碍性水肿。"},{"q":"中度贫血是指","o":["Hb 60～90g/L","Hb 30～60g/L","Hb＜30g/L","Hb＜参考值低值至90g/L","Hb＜35g/L"],"a":0,"e":"贫血按血红蛋白浓度分级：轻度＞90g/L但低于参考区间下限，中度60～90g/L，重度30～59g/L，极重度＜30g/L。中度贫血者体力劳动时出现心慌气短。"},{"q":"下列哪一项是左室肥大的可靠体征","o":["心尖冲动向左下移位","心尖抬举性搏动","心界向左扩大","心界向右扩大","心尖冲动向左移位"],"a":1,"e":"心尖区抬举性搏动指心尖区徐缓有力、可使指端抬起并持续至S2开始的搏动，是左心室肥厚的可靠体征。胸骨左下缘收缩期抬举性搏动则提示右心室肥厚。"},{"q":"正常人每昼夜尿量常为","o":["400～1500ml","500～2500ml","1000～2000ml","1000～2500ml","2500ml以上"],"a":2,"e":"正常成人24小时尿量为1000～2000ml。24小时尿量少于400ml或每小时少于17ml为少尿，少于100ml为无尿，超过2500ml为多尿。"},{"q":"尿液胆红素阳性是指","o":["溶血性黄疸","肝性和梗阻性黄疸合并严重肾损伤","血液中结合胆红素浓度＞34μmol/L","血液中非结合胆红素浓度＞34μmol/L","是肾脏损伤的标志"],"a":2,"e":"结合胆红素为水溶性，可经肾小球滤过。当血中结合胆红素超过肾阈34μmol/L时，尿胆红素试验即呈阳性，故其阳性反映血中结合胆红素浓度升高。"},{"q":"除下列情况外，均可出现红细胞尿","o":["再生障碍性贫血","系统性红斑狼疮","急性溶血","流行性出血热","感染性心内膜炎"],"a":2,"e":"急性溶血时游离血红蛋白经肾排出形成血红蛋白尿，尿隐血阳性而镜检无红细胞，属血红蛋白尿而非红细胞尿。再障、系统性红斑狼疮、流行性出血热及感染性心内膜炎均可出现血尿。"},{"q":"关于颈部包块的性质判断，错误的是","o":["若颈部包块弹性大又无全身症状，应考虑囊肿的可能","淋巴结肿大，质地不硬，有轻度压痛时，可能为非特异性炎症","颈部包块为圆形，表面光滑、有囊样感，压迫能使之缩小，可能为囊状瘤","淋巴结肿大，质地较硬，且伴有纵隔、胸腔或腹腔病变的症状或体征，应诊断为淋巴结结核","如为全身性、无痛性淋巴结肿大，多见于血液系统疾病"],"a":3,"e":"颈部淋巴结质地较硬，并伴纵隔、胸腔或腹腔病变的症状体征时，应首先考虑恶性肿瘤的淋巴结转移。淋巴结结核多伴粘连、破溃及结核中毒症状。"},{"q":"鉴别肝源性水肿和心源性水肿最有意义的体征是","o":["腹水","颜面部水肿","肝大","双下肢凹陷性水肿","颈静脉怒张"],"a":4,"e":"颈静脉怒张提示体循环淤血，是右心衰竭的体征，伴肝大时属心源性水肿；肝源性水肿虽有腹水与肝大，但无颈静脉怒张，故此项最具鉴别意义。"},{"q":"诊断的目的不包括","o":["弄清疾病的内在联系","让病人知道自己是患了何种疾病","为了更好的防治疾病","安慰亲属，解除不必要的担忧","越早弄清疾病的诊断，越能使病人更早的恢复健康"],"a":3,"e":"诊断的目的在于弄清疾病的内在联系、及时防治疾病并使病人尽早恢复健康。安慰亲属、解除其担忧属医患沟通内容，并非诊断的目的。"},{"q":"作为中性粒细胞增多的原因，下列中最常见的为","o":["急性感染和化脓性炎症","中毒","急性失血","恶性肿瘤","心肌梗死"],"a":0,"e":"中性粒细胞增多最常见的原因是急性感染和化脓性炎症，以急性化脓性细菌感染最显著。中毒、急性失血、恶性肿瘤及心肌梗死亦可致增多，但相对少见。"},{"q":"PT延长见于","o":["因子Ⅰ、Ⅱ、Ⅴ、Ⅷ、Ⅹ异常","因子Ⅰ、Ⅱ、Ⅴ、Ⅶ、Ⅹ异常","因子Ⅰ、Ⅴ、Ⅷ、Ⅸ、Ⅹ异常","因子Ⅱ、Ⅶ、Ⅸ、Ⅹ、Ⅺ异常","因子Ⅰ、Ⅱ、Ⅴ、Ⅸ、Ⅹ异常"],"a":1,"e":"PT反映外源性凝血途径，延长见于先天性因子Ⅱ、Ⅴ、Ⅶ、Ⅹ缺乏及低（无）纤维蛋白原血症，也见于口服抗凝药、肝病和DIC。因子Ⅷ、Ⅸ属内源性途径，由APTT检测。"},{"q":"支配眼球运动的三对脑神经是","o":["动眼神经、展神经、滑车神经","三叉神经、展神经、动眼神经","展神经、滑车神经、视神经","滑车神经、展神经、面神经","视神经、副神经、三叉神经"],"a":0,"e":"动眼神经、滑车神经和展神经分别为第Ⅲ、Ⅳ、Ⅵ对脑神经，共同支配眼球运动，合称眼球运动神经。视神经司视觉，三叉神经司面部感觉与咀嚼运动。"},{"q":"前清蛋白比清蛋白更能早期反映肝细胞损害的原因是","o":["其血清浓度高","半衰期短","易于测定","浓度恒定","分子量小"],"a":1,"e":"前清蛋白半衰期约2天，明显短于白蛋白的约20天，肝细胞受损时其血清浓度下降更早、更显著，故比白蛋白更能早期反映肝细胞损害。"},{"q":"对类风湿关节炎描述不正确的是","o":["一般以腕、掌指、近端指间关节肿痛为首发症状","关节晨僵时间大于60min","关节肿痛对称分布","晚期有关节畸形","常伴有皮肤黏膜损害"],"a":4,"e":"类风湿关节炎以对称性多关节肿痛为特征，好发于腕、掌指及近端指间关节，晨僵常＞60分钟，晚期出现关节畸形。皮肤黏膜损害是系统性红斑狼疮的常见表现。"},{"q":"下列疾病叩诊浊音，但须除外哪一项","o":["胸膜肥厚","胸腔积液","肺实变","肺肝界上移","肺含气量增多"],"a":4,"e":"肺组织含气量增多、弹性减弱时叩诊呈过清音，见于肺气肿。胸膜肥厚、胸腔积液、肺实变及肺肝界上移均使叩诊音变浊或变实。"},{"q":"成人高血压的诊断标准中，正确的是","o":["收缩压≥18.7kPa（140mmHg）和（或）舒张压≥12kPa（90mmHg）","收缩压＞20kPa（150mmHg）和（或）舒张压＞12kPa（90mmHg）","收缩压＞21..3kPa（160mmHg）和（或）舒张压＞12kPa（90mmHg）","收缩压≥21.3kPa（160mmHg）和（或）舒张压≥12.7kPa（95mmHg）","收缩压≥21.3kPa（160mmHg）和（或）舒张压＞13.3kPa（100mmHg）"],"a":0,"e":"未使用降压药物时，非同日3次测量诊室血压，收缩压≥140mmHg和（或）舒张压≥90mmHg即可诊断高血压。140mmHg相当于18.7kPa，90mmHg相当于12.0kPa。"},{"q":"心电图表现：①P波时限增宽＞0.11s；②P波形态有切迹，双峰，峰距≥0.04s。提示诊断为","o":["左心房肥大","右心房肥大","左心室肥厚","右心室肥厚","双心房肥大"],"a":0,"e":"P波时限≥0.12秒、呈双峰且峰距≥0.04秒，以Ⅰ、Ⅱ、aVL导联最明显，为左心房肥大的表现，因常见于二尖瓣疾病又称二尖瓣型P波。右心房肥大表现为P波高尖。"},{"q":"急性白血病患者的出血主要是","o":["血小板减少","多种凝血因子缺乏","白血病细胞浸润血管壁","弥散性血管内凝血","严重贫血使血管壁缺氧"],"a":0,"e":"急性白血病时白血病细胞浸润骨髓，抑制巨核细胞系，血小板生成减少，是出血最主要的原因。凝血因子缺乏与DIC也可发生，但属次要因素。"},{"q":"提示终末期肾衰竭的Ccr值为","o":["＜50ml/min","＜40ml/min","＜30ml/min","＜20ml/min","＜10ml/min"],"a":4,"e":"Ccr＜10ml/min时肾脏对利尿剂反应极差，应结合临床进行肾脏替代治疗，属终末期肾衰竭。Ccr＜30ml/min时噻嗪类利尿剂常无效，不宜应用。"},{"q":"可提示陈旧性心肌梗死的心电图改变是","o":["QRS波群低电压","电轴显著左偏","ST段上抬","冠状T出现","V3～V5的Q波＞0.04s"],"a":4,"e":"异常Q波或QS波是心肌梗死的坏死型图形，提示陈旧性心肌梗死，V3～V5导联Q波时限＞0.04秒为前壁梗死表现。ST段抬高见于急性期，冠状T波提示心肌缺血。"},{"q":"肺泡呼吸音增强见于下列情况，但除外","o":["发热","贫血","运动","酸中毒","肺气肿"],"a":4,"e":"肺泡呼吸音增强见于发热、贫血、运动及酸中毒等使呼吸运动增强、肺泡通气量增加的情况。肺气肿时肺泡弹性减退、含气量增多，肺泡呼吸音反而减弱。"},{"q":"一名视物模糊的患者入院进行检查，接诊医生哪一项检查不是视神经检查内容","o":["视力检查","视野检查","视网膜检查","视盘检查","玻璃体检查"],"a":4,"e":"视神经检查包括视力、视野和眼底检查，眼底检查观察视盘、视网膜血管及视网膜。玻璃体属屈光间质，其检查归内眼检查，不属视神经检查内容。"},{"q":"关于正常人血压的叙述，正确的是","o":["上肢血压高于下肢","下肢血压高于上肢","上、下肢血压相等","男性上肢血压高，女性下肢血压高","女性上肢血压高，男性下肢血压高"],"a":1,"e":"正常下肢血压高于上肢20～40mmHg，与下肢动脉口径及血流阻力有关。若下肢血压低于上肢，应考虑主动脉缩窄或胸腹主动脉型大动脉炎。"},{"q":"关于肠鸣音以下均正确，除外","o":["肠鸣音活跃可见于胃肠道大出血","肠鸣音正常为每分钟3～4次","肠鸣音减弱可见于腹膜炎","肠鸣音为肠管内气体和液体流动产生","肠鸣音消失为持续3～5min无肠鸣音"],"a":1,"e":"正常肠鸣音约每分钟4～5次，餐后频繁而明显，休息时稀疏。活跃指每分钟10次以上而音调不高亢，减弱见于腹膜炎、低血钾，持续3～5分钟未闻及为消失。"},{"q":"玫瑰疹常出现的部位在","o":["面颊部","颈背部","肩部","胸腹部","四肢"],"a":3,"e":"玫瑰疹为淡红色小斑丘疹，直径2～3mm，压之退色，多出现于胸腹部，是伤寒和副伤寒的特征性皮疹，一般分批出现，数日内消退。"},{"q":"心尖部舒张期室性奔马律最常见于","o":["风湿性心脏病，二尖瓣狭窄","风湿性心脏病，二尖瓣关闭不全","原发性高血压（Ⅲ期）","法洛四联症","肺源性心脏病"],"a":2,"e":"舒张早期奔马律（室性奔马律）提示心肌严重受损或心室舒张期负荷过重，最常见于高血压性心脏病并发左心衰竭。左室奔马律于呼气时较清楚。"},{"q":"关于主动脉缩窄的临床表现，以下说法不正确的是","o":["下肢血压明显高于上肢","腹主动脉、股动脉脉搏微弱或不能触及","胸骨旁及中上腹搏动显著伴震颤","胸骨左缘可闻及收缩中后期吹风样杂音","伴有二叶主动脉瓣者，主动脉瓣区可闻及收缩期杂音或兼有舒张期杂音"],"a":0,"e":"主动脉缩窄时降主动脉血流受阻，上肢血压升高而下肢血压明显低于上肢，股动脉搏动微弱或不能触及，胸骨旁及中上腹可见侧支循环搏动。"},{"q":"细胞质中不含颗粒的细胞是","o":["早幼粒细胞","中幼粒细胞","晚幼红细胞","幼淋巴细胞","幼单核细胞"],"a":2,"e":"粒系自早幼粒细胞起胞质出现嗜天青颗粒，中幼粒细胞以后出现特异性颗粒；幼淋巴细胞及幼单核细胞胞质也可见颗粒。幼红细胞胞质内无颗粒。"},{"q":"一患者右胸大量积气，下列体征不正确的是","o":["气管移向右侧","右侧语颤减弱","右侧叩诊鼓音","右肺呼吸音弱","肝浊音界下移"],"a":0,"e":"大量气胸时患侧胸膜腔压力增高，气管和心脏被推向健侧，故气管应向左移位。患侧语颤减弱、叩诊鼓音、呼吸音减弱，右侧气胸时肝浊音界下移。"},{"q":"下列哪种疾病肝叩诊浊音界缩小","o":["肝炎","肝淤血","脂肪肝","Budd-Chiari综合征","肝硬化"],"a":4,"e":"肝硬化时肝体积缩小、质地变硬，肝浊音界缩小，急性重型病毒性肝炎亦可缩小。肝炎、肝淤血、脂肪肝及Budd-Chiari综合征多致肝大、肝浊音界扩大。"},{"q":"心脏叩诊相对浊音界呈梨形改变，最常见于","o":["主动脉瓣关闭不全","主动脉瓣狭窄","肺源性心脏病","二尖瓣狭窄","二尖瓣关闭不全"],"a":3,"e":"二尖瓣狭窄致左心房及肺动脉段增大，心腰丰满或膨出，心浊音界呈梨形。主动脉瓣关闭不全为靴形心，肺源性心脏病则为右心室增大向两侧扩大。"},{"q":"当体重减轻低于标准体重（ ）时称为消瘦","o":["5%","10%","15%","18、5%","20%"],"a":1,"e":"体重低于标准体重的10%即可诊断为消瘦；超过标准体重10%为超重，超过20%为肥胖。按BMI判定，＜18.5kg/m²亦属消瘦。"},{"q":"用袖带法测量上、下肢血压，正常时下肢血压较上肢血压高，其范围为","o":["5～10mmHg","20～40mmHg","10～20mmHg","30～40mmHg","40～60mmHg"],"a":1,"e":"袖带法测量时正常下肢血压较上肢高20～40mmHg。若下肢血压低于上肢，应考虑主动脉缩窄或胸腹主动脉型大动脉炎。"},{"q":"下列情况下可以使左右两肺前界间浊音区缩小的是","o":["扩张型心肌病","心包积液","主动脉瘤","肺门淋巴结肿大","肺气肿"],"a":4,"e":"两肺前界间的浊音区即心脏绝对浊音区，心脏扩大、心包积液、主动脉瘤或肺门淋巴结明显肿大时扩大；肺气肿时肺过度充气、心界缩小，故该浊音区缩小。"},{"q":"下列情况下，均可引起第一心音减弱，但应除外","o":["二尖瓣狭窄","二尖瓣关闭不全","P-R间期延长","心肌炎","心肌梗死"],"a":0,"e":"二尖瓣狭窄时左室充盈减少，收缩开始时二尖瓣位置低垂，关闭振动幅度大，S1亢进。二尖瓣关闭不全、P-R间期延长、心肌炎和心肌梗死均使S1减弱。"},{"q":"二尖瓣脱垂综合征是","o":["心率增快，出现在S2之后，音调低弱，与S1和S2的间距相仿","位于S2之后，调高，短促响亮，呈拍击性","位于S2之后，中频，短促响亮，胸骨左缘容易听见","位于S2之后，音调较低，随体位变动","位于S2之后，音调高，短促清脆，可伴心尖区收缩晚期杂音"],"a":4,"e":"二尖瓣脱垂时瓣叶于收缩中晚期突然绷紧、脱入左房，产生高调、短促、清脆的喀喇音，位于S1后0.08秒以上，常伴收缩晚期杂音，合称二尖瓣脱垂综合征。"},{"q":"细胞质内含有嗜天青颗粒的细胞是","o":["中幼粒细胞","早幼粒细胞","晚幼粒细胞","原单核细胞","分叶核粒细胞"],"a":1,"e":"粒系细胞发育至早幼粒细胞时，胞质开始出现大小、形态和数目不一、分布不均的紫红色嗜天青颗粒；中幼粒细胞以后才出现特异性颗粒。"},{"q":"最常见血清MAO活性增高的疾病是","o":["急性肝炎","慢性肝炎活动期","肝硬化","肝癌","暴发性肝衰竭"],"a":2,"e":"血清MAO活性与体内结缔组织增生呈正相关，80%以上的重症肝硬化及伴肝硬化的肝癌病人MAO增高，是观察肝纤维化程度的指标。急性肝炎时MAO大多正常。"},{"q":"二尖瓣狭窄时，下列体征提示瓣膜弹性尚好的是","o":["心尖部可触及舒张期震颤","开瓣音","舒张期杂音随体位改变","肺动脉第二音亢进","心尖部舒张期杂音"],"a":1,"e":"开瓣音出现于S2后0.05～0.06秒，因弹性尚好的瓣叶在舒张早期迅速开放后突然停止、振动而产生，提示瓣膜弹性与活动度尚好；瓣叶钙化僵硬时开瓣音消失。"},{"q":"下列各项为既往史内容，但除外","o":["病人过去的健康状况","预防接种史","曾有肝炎接触史","到过传染病流行区","过敏史"],"a":3,"e":"到过传染病流行区属个人史中的社会经历，用于推断潜伏期和感染来源。既往史包括过去健康状况、曾患疾病、外伤手术、预防接种史及过敏史。"},{"q":"下述是冲击触诊法，或称浮沉触诊法，但除了","o":["检查者以右手三、四个手指并拢","并拢的三、四个手指与腹壁呈70°～90°角","置并拢手指于腹壁相应的部位上","并拢的手指作数次急速而较有力的冲击动作","并拢的手指作数次轻柔的、缓慢的按压动作"],"a":4,"e":"冲击触诊法以并拢的示、中、环三指与腹壁呈70°～90°角，作数次急速而较有力的冲击动作，借指端感觉浮沉的脏器或包块，用于大量腹水时触诊肝脾。"},{"q":"风湿性心脏病主动脉瓣关闭不全的主要体征是","o":["心浊音界向左下扩大","主动脉瓣区第二心音减弱或消失","胸骨左缘第3肋间舒张期叹气样杂音","Austin Flint杂音","毛细血管搏动征"],"a":2,"e":"主动脉瓣关闭不全的特征性体征为主动脉瓣第二听诊区（胸骨左缘第3肋间）舒张期递减型叹气样杂音，前倾坐位、深呼气末最清楚，向胸骨左缘及心尖传导。"},{"q":"有关临床思维的要素是","o":["临床实践","科学思维","临床实践，科学思维","主观判断","经验再现"],"a":2,"e":"临床思维的两大要素是临床实践与科学思维：通过病史采集、体格检查等实践活动发现并分析问题，再以科学思维归纳判断，两者反复循环、相互促进。"},{"q":"下列疾病见不到棒状小体的是","o":["M2","M3","M4","M5","急性淋巴细胞白血病"],"a":4,"e":"棒状小体（Auer小体）由胞质内嗜天青颗粒融合而成，见于急性粒细胞白血病和急性单核细胞白血病，M2、M3、M4、M5均可见，急性淋巴细胞白血病不见。"},{"q":"以下尿蛋白含量均称为蛋白尿，但需除外","o":["尿蛋白定量试验20～80mg/24h","尿蛋白定量试验＞100mg/L","尿蛋白定量试验＞150mg/24h","蛋白质定性试验阳性","尿蛋白定量试验3、5g/24h"],"a":0,"e":"尿蛋白定量正常参考区间为0～80mg/24h，故20～80mg/24h仍属正常。尿蛋白定性阳性、定量＞150mg/24h或＞100mg/L方称蛋白尿。"},{"q":"以下哪项属于特异性杀伤瘤细胞","o":["TDTH细胞","K细胞","M¢","NK细胞","CTL细胞"],"a":4,"e":"CTL即CD8+细胞毒性T细胞，经MHCⅠ类分子识别肿瘤抗原后特异性杀伤靶细胞，并具免疫记忆。NK细胞、K细胞和巨噬细胞的杀伤不依赖抗原特异性。"},{"q":"下列疾病中S1增强的是","o":["大面积心肌梗死","扩张型心肌病","心肌炎","二尖瓣狭窄","大量心包积液"],"a":3,"e":"二尖瓣狭窄时左室充盈减慢减少，收缩开始时二尖瓣位置低垂，关闭振动幅度大，故S1亢进。大面积心肌梗死、心肌炎、扩张型心肌病及大量心包积液均使S1减弱。"},{"q":"左腋中线脾的浊音界长度为","o":["4～7cm","7～9cm","9～10cm","11～12cm","12～13cm"],"a":0,"e":"正常脾脏浊音区位于左腋中线第9～11肋之间，长度约4～7cm，前方不超过腋前线。脾浊音区扩大见于各种脾肿大，缩小见于左侧气胸、胃扩张和肠胀气。"},{"q":"下列各项均为大量腹水的体征，但除外","o":["蛙腹","波动感","振水音","移动性浊音","脐疝"],"a":2,"e":"振水音是胃内大量液体与气体存留时经冲击胃部产生的气液撞击声，见于幽门梗阻或胃扩张。大量腹水表现为蛙腹、液波震颤、移动性浊音及脐疝。"},{"q":"关于主诉的写作要求，下列哪项不正确","o":["提示疾病主要属何系统","提示疾病的急性或慢性","指出发生并发症的可能","指出疾病发生发展及预后","文字精练、术语准确"],"a":3,"e":"主诉由主要症状或体征及其持续时间构成，要求文字精练、术语准确，可提示疾病所属系统及系急性或慢性。疾病的发生发展及预后由现病史反映，不属主诉要求。"},{"q":"个人史包括","o":["主要症状的特点","药物食物过敏史","出生地及居住时间","夫妻关系","生育次数"],"a":2,"e":"个人史记录出生地及长期居留地、生活习惯与烟酒嗜好、职业及毒物粉尘放射性接触史、有无冶游史。过敏史属既往史，夫妻关系与生育次数属婚姻生育史。"},{"q":"下列凝血因子中哪组凝血因子为维生素K依赖因子","o":["Ⅰ，Ⅲ，Ⅳ，Ⅴ","Ⅱ，Ⅶ，Ⅹ，Ⅺ","Ⅱ，Ⅶ，Ⅸ，Ⅹ","Ⅷ，Ⅸ，Ⅺ，Ⅻ","Ⅲ，Ⅴ，Ⅶ，Ⅹ"],"a":2,"e":"维生素K依赖的凝血因子为Ⅱ、Ⅶ、Ⅸ、Ⅹ，其合成需维生素K参与γ-羧基谷氨酸的形成。缺乏时PT、APTT延长，补充维生素K后可被纠正。"},{"q":"下列不引起腹式呼吸减弱的是","o":["腹膜炎症","腹水","急性腹痛","腹腔内巨大肿物","胸腔积液"],"a":4,"e":"腹式呼吸减弱见于腹膜炎症、大量腹水、急性腹痛及腹腔内巨大肿物等使膈肌运动受限的腹部病变。胸腔积液主要使患侧胸式呼吸减弱，腹式呼吸常代偿性增强。"},{"q":"心外膜下损伤时，ST段如何偏移","o":["ST段弓背向上抬高","ST段无变化","ST段压低","ST段弓背向下抬高","ST段压低合并T波倒置"],"a":0,"e":"心外膜下心肌损伤时，损伤电流的ST向量指向心外膜面，使面向该处的导联ST段抬高，急性心肌梗死呈弓背向上型；心内膜下损伤则表现为ST段压低。"},{"q":"下列哪项是有关T细胞检查的常用试验","o":["抗体依赖细胞介导的细胞毒测定","E玫瑰花结形成试验","酵母菌花环试验","免疫球蛋白测定","补体含量测定"],"a":1,"e":"T细胞表面具有绵羊红细胞受体（E受体），与绵羊红细胞结合形成花结，即E玫瑰花结形成试验，用于检测T细胞数量及比例。酵母菌花环试验检测补体受体，针对B细胞。"},{"q":"健康人可见哪种管型","o":["红细胞管型","透明管型","白细胞管型","颗粒管型","脂肪管型"],"a":1,"e":"健康人尿中偶见透明管型，0～1个/HPF，由T-H蛋白、白蛋白及少量氯化物构成。红细胞、白细胞、颗粒及脂肪管型均提示肾实质或肾单位病变。"},{"q":"革兰阴性细菌的致热物质主要是","o":["外毒素","螺旋毒素","溶血素","全菌体、肽聚糖和内毒素","细胞毒因子"],"a":3,"e":"革兰阴性菌的致热物质为全菌体、肽聚糖和内毒素，其中内毒素即细胞壁脂多糖，是主要致热成分，细菌死亡自溶后释放，激活单核巨噬细胞产生内源性致热原。"},{"q":"病态窦房结综合征心电图改变的特点不包括","o":["持续窦性心动过缓，心率＜50次/min","应用阿托品后心率明显增快","窦性停搏或窦房传导阻滞","可有双结病变","常出现慢快综合征"],"a":1,"e":"病态窦房结综合征的窦性心动过缓持续存在，且不易被阿托品等药物纠正，这正是其特点。心电图还可有窦性停搏、窦房传导阻滞、双结病变及慢-快综合征。"},{"q":"主治医师首次查房记录应当于患者入院（ ）小时内完成","o":["24","48","36","72","12"],"a":1,"e":"主治医师首次查房记录应于病人入院48小时内完成，上级医师查房记录须由查房医师审阅并签名。入院记录一般应于病人入院24小时内完成。"},{"q":"“三凹征”是指","o":["胸骨上窝、锁骨下窝、肋间隙向内凹陷","锁骨下窝、锁骨上窝、肋间隙向内凹陷","胸骨上窝、锁骨下窝、肋间隙向外凹陷","胸骨上窝、锁骨上窝、肋间隙向外凹陷","胸骨上窝、锁骨上窝、肋间隙向内凹陷"],"a":4,"e":"三凹征见于上呼吸道部分梗阻，吸气时呼吸肌强烈收缩使胸内负压急剧增高，致胸骨上窝、锁骨上窝及肋间隙向内凹陷，常伴高调吸气性喉鸣和干咳。"},{"q":"过敏性紫癜导致皮肤黏膜出血的机制是","o":["血管壁缺陷","血小板数量异常","血小板质量异常","凝血因子活性下降","纤溶亢进"],"a":0,"e":"过敏性紫癜属血管壁结构和功能缺陷所致出血，毛细血管壁受损、通透性增高，表现为四肢对称性、高出皮肤的紫癜，血小板计数正常。"},{"q":"呼吸深大见于","o":["肺纤维化","段性肺不张","急性肺炎","支气管肺癌","酮症酸中毒"],"a":4,"e":"严重代谢性酸中毒时细胞外液HCO3-不足、pH降低，机体通过深而快的呼吸排出CO2代偿，称库斯莫尔呼吸，见于糖尿病酮症酸中毒和尿毒症酸中毒。"},{"q":"颈静脉搏动最常见于","o":["二尖瓣关闭不全","上腔静脉阻塞","三关瓣关闭不全","心脏压塞","主动脉瓣关闭不全"],"a":2,"e":"三尖瓣关闭不全时收缩期右心室血液反流入右心房，压力传至颈静脉，使颈静脉出现收缩期搏动，并伴肝脏收缩期搏动。上腔静脉阻塞表现为颈静脉充盈怒张而非搏动。"},{"q":"血尿伴腰腹部绞痛，放射至会阴部，最常见于","o":["肾结石","肾结核","膀胱结石","输尿管结石","肾肿瘤"],"a":3,"e":"输尿管结石移动时刺激输尿管平滑肌痉挛，产生腰部绞痛并向会阴部放射，同时损伤黏膜引起血尿，是肾绞痛最典型的病因。膀胱结石多表现为尿流中断。"},{"q":"关于医院感染和社区感染，叙述正确的是","o":["医院感染为内源性，社区感染为外源性","前者的病原体主要是条件致病菌，后者为典型致病菌","二者的易感者相同","二者均为多重耐药的病原体","前者较易治疗，后者较难治疗"],"a":1,"e":"医院感染的病原体大多数为人体正常菌群或条件致病菌，多发生于免疫力低下的住院病人；社区感染则以典型致病菌为主。两者易感人群与耐药状况不同。"},{"q":"维持细胞外液渗透压的主要离子是","o":["钾离子和氯离子","钾离子和磷酸氢根","钠离子和氯离子","钠离子和磷酸氢根","钠离子和碳酸氢根"],"a":2,"e":"钠离子是细胞外液的主要阳离子，氯离子是主要阴离子，二者以氯化钠形式存在，共同维持细胞外液的容量与渗透压。钾离子主要分布于细胞内液。"},{"q":"血浆凝血酶原时间，超过正常对照（ ）以上有临床意义","o":["3s","5s","7s","10s","12s"],"a":0,"e":"血浆凝血酶原时间测定须设正常对照值，测定值超过正常对照值3秒以上即为异常，是外源性凝血系统较灵敏且最常用的筛选试验。"},{"q":"下腹壁反射是由下述哪个胸段脊髓神经节支配","o":["胸3～4节","胸5～6节","胸7～8节","胸9～10节","胸11～12节"],"a":4,"e":"腹壁反射分上、中、下三部分，分别由胸髓7～8节、9～10节和11～12节支配；下腹壁反射沿腹股沟上方向由外向内轻划引出。"},{"q":"急性肾功能不全时，下列检查不必要的是","o":["自由水清除率","内生肌酐清除率","尿渗量","血清蛋白电泳","血肌酐"],"a":3,"e":"急性肾损伤须评价肾小球滤过与肾小管浓缩功能，内生肌酐清除率、血肌酐、尿渗量及自由水清除率均有价值。血清蛋白电泳用于肝脏疾病和浆细胞病，与肾功能评价无关。"},{"q":"下列哪种疾病骨髓巨核细胞减少","o":["血友病","缺铁性贫血","ITP","急性再生障碍性贫血","巨幼细胞贫血"],"a":3,"e":"急性再生障碍性贫血骨髓造血细胞显著减少，巨核细胞明显减少或缺如，血小板生成障碍。ITP时巨核细胞正常或增多但伴成熟障碍，缺铁及巨幼细胞贫血巨核细胞不减少。"},{"q":"产生全身性水肿的病因不会是","o":["肝硬化","缩窄性心包炎","肾病综合征","下肢静脉血栓形成","尿毒症"],"a":3,"e":"下肢静脉血栓形成使静脉回流受阻，只引起患肢局限性水肿。肝硬化、缩窄性心包炎、肾病综合征及尿毒症分别经低蛋白血症、静脉压升高和水钠潴留产生全身性水肿。"},{"q":"pH为7.48，标准碳酸氢盐超过45mmol/L时，下描述最准确的是","o":["受呼吸影响较大","是反应呼吸性碱中毒的指标","是准确反应代谢性酸碱平衡失调的指标","肯定为代谢性碱中毒","受代谢影响较大"],"a":2,"e":"标准碳酸氢盐是在标准条件下测得的HCO3-，不受呼吸因素影响，是准确反映代谢性酸碱平衡的指标。本例SB超过45mmol/L，提示存在代谢性碱中毒。"},{"q":"18岁女性，Hb 80g/L，属于","o":["正常","轻度贫血","中度贫血","重度贫血","极重度贫血"],"a":2,"e":"18岁女性Hb 80g/L，低于成年女性110g/L的诊断界值，按贫血程度分级60～90g/L为中度贫血，体力劳动时可出现心慌气短。"},{"q":"肺心病的心电图改变中，错误的是","o":["右心房肥大","极度顺钟向转位","肺性P波","肢体导联QRS波群低电压","左心房肥大"],"a":4,"e":"肺源性心脏病的心电图改变包括右心房肥大（肺型P波）、极度顺钟向转位、肢体导联QRS波群低电压和右心室肥厚。左心房肥大呈二尖瓣型P波，见于二尖瓣疾病。"},{"q":"正常成年人体内HbF占","o":["98%","60%","50%","3%","＜1%"],"a":4,"e":"正常成人血红蛋白以HbA为主，HbA2占2.5%～3.5%，HbF＜1%。新生儿HbF可达6%～93%，出生后逐渐被HbA替代。"},{"q":"一患者因突发左胸剧痛被送至急诊科，医师应最先了解","o":["患者姓名等一般项目","胸痛发作的时间及特点","胸痛的治疗过程","患者的既往健康状况","患者的家族史"],"a":1,"e":"急诊胸痛须首先问清发作时间、性质、诱因及放射部位，以判断急性冠脉综合征等危重病因、争取再灌注时间，一般项目与既往史可随后补充。"},{"q":"最常见血钠降低的情况是","o":["大量应用利尿剂","原发性醛固酮增多症","大面积烧伤渗液","昏迷","肾上腺皮质功能亢进症"],"a":0,"e":"大量应用噻嗪类或袢利尿剂使钠随尿丢失增多，是低钠血症最常见的肾性原因。原发性醛固酮增多症及肾上腺皮质功能亢进症多引起高钠血症。"},{"q":"常见诊断失误的原因不包括","o":["主观臆断","病人欠配合","医学知识不足","病史资料不完整、不准确","体格检查不细致、不全面"],"a":2,"e":"官方答案为【医学知识不足】，但依据教材，正确答案为【病人欠配合】。教材明确指出医学知识不足、缺乏临床经验是构成误诊的常见原因，故不属“不包括”之列。"},{"q":"舌头萎缩、舌体较小，舌面光滑呈粉红色或红色，见于","o":["慢性萎缩性胃炎","黏液性水肿","严重脱水","长期发热","维生素B2缺乏"],"a":0,"e":"镜面舌表现为舌乳头萎缩、舌体缩小、舌面光滑呈粉红色或红色，见于巨幼细胞性贫血、恶性贫血及慢性萎缩性胃炎。"},{"q":"由卧位或下蹲位到迅速站立时，可使下列何种疾病的杂音增强","o":["二尖瓣狭窄","特发性肥厚性主动脉瓣下狭窄","肺动脉瓣狭窄","主动脉瓣狭窄","三尖瓣狭窄"],"a":1,"e":"从卧位或下蹲位迅速站立时回心血量骤减，左室容量缩小使流出道梗阻加重，故梗阻性肥厚型心肌病（特发性肥厚性主动脉瓣下狭窄）的杂音增强，其余瓣膜杂音多减轻。"},{"q":"S2出现的时间是","o":["与房室瓣关闭同时发生","与半月瓣开放同时发生","与半月瓣关闭同时发生","与心房收缩同时发生","在舒张晚期发生"],"a":2,"e":"S2主要由主动脉瓣和肺动脉瓣突然关闭、血流在大血管内突然减速引起瓣膜振动而产生，故与半月瓣关闭同时发生，在心底部的主动脉瓣区和肺动脉瓣区最清楚。"},{"q":"左锁骨上触及肿大坚硬的淋巴结，考虑为","o":["肺癌","消化道肿瘤","甲状腺癌","鼻咽癌","乳房癌"],"a":1,"e":"左锁骨上淋巴结（Virchow淋巴结）经胸导管接收腹腔脏器的淋巴回流，此处触及肿大坚硬的淋巴结常提示胃癌等消化道肿瘤转移。"},{"q":"关于慢性肾盂肾炎，哪项不正确","o":["可反复急性发作","可有高血压","可有低热","尿路刺激症状可不明显","肾小管功能正常"],"a":4,"e":"慢性肾盂肾炎为慢性间质性病变，肾小管浓缩功能受损出现最早，尿渗量降低。临床可反复急性发作，伴低热、高血压，而尿路刺激症状常不明显。"},{"q":"关于乙型肝炎病毒的性状，哪项是错误的","o":["病毒核心为双股DNA，属于包膜病毒","HbsAg本身不具有传染性","血清中检测不到核心抗原","HbeAg阳性表明处于感染恢复期","HbeAg可刺激机体产生抗-HBe"],"a":3,"e":"HBeAg阳性表明乙型肝炎处于活动期，病毒复制活跃、传染性强；抗-HBe出现才提示复制减弱、病情趋于恢复。HBcAg主要位于肝细胞核内，血清中不易检出。"},{"q":"以下免疫球蛋白类型，在人体血清中含量最高的是","o":["IgM","IgA","IgE","IgG","IgD"],"a":3,"e":"IgG占人体总免疫球蛋白的70%～80%，是血清中含量最高、最主要的免疫球蛋白，属再次免疫应答抗体，并可穿过胎盘。IgM分子量最大，IgA主要存在于黏膜分泌液。"},{"q":"下列各项均为腹内积气临床表现，但除外","o":["全腹膨隆","腹内呈球形","两侧腰部膨出不明显","移动体位其形状无明显改变","蛙腹"],"a":4,"e":"腹内大量积气时全腹膨隆呈球形，两侧腰部膨出不明显，移动体位时形状无明显改变。蛙腹是大量腹腔积液平卧时液体下沉于两侧、腹部扁而宽的表现。"},{"q":"如图，心电图诊断考虑","o":["右心房肥大","左心房肥大","右心室肥厚","左心室肥厚","左心房室增大"],"a":1,"e":"官方题库缺失图片"},{"q":"非肝细胞合成，但肝实质细胞受损时，其生成可以增多的蛋白质是","o":["糖蛋白","脂蛋白","白蛋白","各种转运蛋白","球蛋白"],"a":4,"e":"球蛋白中的γ球蛋白由B淋巴细胞和浆细胞产生，并非肝细胞合成。肝实质受损尤其慢性炎症时，单核吞噬细胞系统受刺激，γ球蛋白生成增加，故球蛋白升高。"},{"q":"维生素C缺乏症（坏血病）导致皮肤黏膜出血的机制是","o":["毛细血管壁缺陷","小静脉管壁缺陷","血小板聚集功能异常","血小板释放功能异常","凝血因子合成异常"],"a":0,"e":"维生素C是胶原合成中脯氨酸、赖氨酸羟化的必需辅因子，缺乏时毛细血管基底膜胶原合成障碍、管壁脆性增加，属毛细血管壁缺陷所致的皮肤黏膜出血。"},{"q":"二尖瓣狭窄时心浊音界出现哪种改变","o":["靴形","梨形","普大型","三角形","第3肋间心左界向外扩大"],"a":1,"e":"二尖瓣狭窄致左心房及肺动脉段增大，心腰消失或膨出，心浊音界呈梨形。靴形见于主动脉瓣关闭不全，普大型见于左、右心室均增大。"},{"q":"患者突然高热、胸痛、咳嗽，呼吸困难，下列哪项有助于肺炎实变与胸腔积液的鉴别","o":["呼吸运动","气管位置","叩诊音","胸膜摩擦音","肺泡呼吸音"],"a":4,"e":"肺实变时支气管呼吸音传导增强，患侧可闻及支气管呼吸音且语音共振增强；胸腔积液时肺泡呼吸音与语音共振均减弱或消失，听诊肺泡呼吸音的改变最直接。"},{"q":"咯血患者在咯血前常有下列症状，除了","o":["喉部痒感","胸闷","上腹部不适","咳嗽","焦虑"],"a":2,"e":"咯血前常有喉部痒感、胸闷、咳嗽及焦虑等先兆，血液随咳嗽由气道咳出。上腹部不适伴恶心是呕血的前驱表现，提示出血来自上消化道。"},{"q":"下面哪一项不是浅反射检查内容","o":["角膜反射","腹壁反射","提睾反射","眼心反射","跖反射"],"a":3,"e":"浅反射是刺激皮肤、黏膜或角膜引起的反应，包括角膜反射、腹壁反射、提睾反射和跖反射。眼心反射属自主神经反射检查，不属浅反射。"},{"q":"诊断急性阑尾炎的最重要依据是","o":["转移性右下腹痛","McBurney点压痛、反跳痛","加压左下腹部突然松手引起右下腹痛","腰大肌征阳性","直肠指检有局部触痛"],"a":1,"e":"右下腹McBurney点显著而固定的压痛和反跳痛是诊断急性阑尾炎最重要的依据。转移性右下腹痛见于70%～80%的病人，但缺乏该体征不能确诊。"},{"q":"MCV、MCH、MCHC均明显低于参考值下限的贫血是","o":["再生障碍性贫血","巨幼细胞贫血","缺铁性贫血","失血性贫血","急性失血"],"a":2,"e":"缺铁性贫血为小细胞低色素性贫血，MCV、MCH、MCHC均低于参考值下限，RDW增高。巨幼细胞贫血为大细胞性，再障及急性失血多为正常细胞性。"},{"q":"内生致热原是","o":["由中枢神经系统产生的能引起体温升高的内在介质","由产热器官产生的能引起体温升高的内在介质","由产热原细胞产生的能引起体温升高的神经激素","由产EP细胞在发热激活物的作用下，产生和释放的能引起体温升高的物质","由产EP细胞在磷酸激酶的作用下，产生和释放的能引起体温升高的物质"],"a":3,"e":"内生致热原由产EP细胞（单核巨噬细胞、中性粒细胞等）在发热激活物作用下产生并释放，如IL-1、TNF和干扰素，经血-脑脊液屏障作用于体温调定点。"},{"q":"医生发现患者右侧舌咽神经损伤，临床检查不可能发现以下哪项表现","o":["右侧咽反射迟钝","右侧软腭抬举减弱","腭垂偏向右侧","声音嘶哑","饮水呛咳"],"a":2,"e":"一侧舌咽、迷走神经受损时患侧软腭上抬减弱、咽反射迟钝，腭垂偏向健侧，故右侧损伤应偏向左侧。声音嘶哑与饮水呛咳则常见于患侧。"},{"q":"剑突下异常搏动见于","o":["右心室肥大","左心室肥大","右位心","大量腹水","门静脉高压"],"a":0,"e":"剑突下（胸骨左下缘）收缩期搏动见于右心室肥大，深吸气后搏动增强、压迫时冲击指端。腹主动脉瘤的搏动冲击指掌面，且深吸气时减弱。"},{"q":"脉压增大不可能出现的体征是","o":["De Musset征","Traube征","Duroziez征","Kussmaul征","点头征"],"a":3,"e":"De Musset点头征、Traube枪击音、Duroziez双重杂音及毛细血管搏动征均为脉压增大的周围血管征。Kussmaul征指吸气时颈静脉怒张加重，见于缩窄性心包炎和心脏压塞。"},{"q":"下列关于Kernig征检查的描述，哪项错误","o":["仰卧位","一侧髋关节屈成直角","抬高小腿","正常可将膝关节伸达150°以上","阳性为伸膝受限伴疼痛"],"a":3,"e":"Kernig征检查时病人仰卧，一侧髋、膝关节屈曲成直角后抬高小腿伸膝，正常人膝关节可伸达135°以上；伸膝受阻伴疼痛与屈肌痉挛为阳性。"},{"q":"肺泡呼吸音减弱可见于下列情况，除了","o":["重症肌无力","大量腹水","胸膜肥厚","重症哮喘","酸中毒"],"a":4,"e":"酸中毒时血液酸度增高刺激呼吸中枢，呼吸深长，肺泡呼吸音增强。重症肌无力、大量腹水、胸膜肥厚及重症哮喘均因通气动力不足、胸廓活动受限或气道阻塞使肺泡呼吸音减弱。"},{"q":"人体最重要的散热途径是","o":["肺","皮肤","小便","粪便","肌肉"],"a":1,"e":"皮肤是人体最重要的散热途径，经辐射、传导、对流和蒸发散发热量，约占散热总量的90%。肺通过呼吸蒸发、尿液和粪便仅排出少量热量。"},{"q":"结合胆红素进入胆道后还原为尿胆原，在肠内被吸收入肝的比例是","o":["1%～5%","5%～10%","10%～15%","10%～20%","25%～30%"],"a":3,"e":"结合胆红素在肠内被细菌酶还原为尿胆原，大部分随粪便排出，小部分（10%～20%）经肠道吸收入肝，再转变为结合胆红素排入肠腔，构成胆红素的肠肝循环。"},{"q":"右肺肺活量占全肺肺活量的百分数为","o":["55%","50%","45%","60%","40%"],"a":0,"e":"右肺肺活量占全肺肺活量的55%，左肺占45%，与右肺容积较大相适应。肺活量为深吸气量加补呼气容积，反映一次呼吸的最大通气能力。"},{"q":"心电图ST段下移呈鱼钩形改变应考虑","o":["低血钾","低血钙","洋地黄作用","高钾血症","心肌梗死"],"a":2,"e":"洋地黄使动作电位2位相缩短、3位相坡度减小，心电图上ST段呈下垂型压低，T波双向或倒置，ST-T形成特征性的鱼钩样改变，并伴QT间期缩短。"},{"q":"临床表现为体温骤降，常见于","o":["败血症","风湿热","结缔组织病","伤寒","霍奇金病"],"a":4,"e":"霍奇金淋巴瘤可出现回归热，体温骤升至39℃以上、持续数日后又骤然降至正常，高热期与无热期规律交替。败血症多为弛张热，伤寒为稽留热。"},{"q":"关于腹腔积液的描述，下列各项均正确，但除外","o":["平卧时腹型呈扁而宽状","侧卧时下腹部膨出","脐部突出","可见尖腹","常见腹壁静脉曲张"],"a":4,"e":"大量腹腔积液平卧时腹部扁而宽呈蛙腹，侧卧时下腹膨出，脐可突出，腹膜炎症或肿瘤浸润时呈尖腹。腹壁静脉曲张由门静脉高压或腔静脉阻塞引起，并非腹腔积液本身的表现。"},{"q":"特异性酯酶染色呈强阳性反应，见于","o":["晚期的原始细胞","嗜酸性粒细胞","淋巴细胞","早幼粒细胞","单核细胞"],"a":3,"e":"氯乙酸AS-D萘酚酯酶即特异性酯酶，主要存在于粒系细胞，自早幼粒细胞至成熟中性粒细胞均呈阳性，早幼粒细胞反应最强，酶活性随细胞成熟而减弱。"},{"q":"下列各项均为编写病历的基本要求，但除外","o":["内容要客观、真实","格式要规范","应选用通俗易懂的用词","填写要全面","字迹要清楚"],"a":2,"e":"病历书写要求内容客观真实、格式规范、填写全面、字迹清楚，并使用规范的医学术语。通俗易懂的口语用于问诊时与病人交流，不用于病历书写。"},{"q":"急性腹膜炎的患者腹部检查的腹膜炎三联征是","o":["腹式呼吸减弱，腹肌紧张和压痛","腹式呼吸增强，腹肌紧张和压痛","腹肌紧张、压痛和反跳痛","腹部膨胀、腹肌紧张和反跳痛","肝浊音上界消失，腹肌紧张和压痛"],"a":2,"e":"急性腹膜炎的典型三联征为腹肌紧张、压痛和反跳痛，是壁腹膜受炎症刺激的表现。弥漫性腹膜炎时腹式呼吸明显减弱或消失，可伴腹部膨隆。"},{"q":"深吸气后，可使下列何种疾病的杂音增强","o":["二尖瓣狭窄","二尖瓣关闭不全","肺动脉瓣关闭不全","主动脉瓣关闭不全","主动脉瓣狭窄"],"a":2,"e":"深吸气时胸腔负压增大，回心血量和右心室排血量增加，使与右心相关的杂音增强，如肺动脉瓣、三尖瓣的狭窄与关闭不全。左侧瓣膜杂音多在呼气时增强。"},{"q":"出血时间和凝血时间均延长的疾病是","o":["血小板减少性紫癜","过敏性紫癜","血友病甲、乙、丙","纤维蛋白缺乏症","弥散性血管内凝血"],"a":4,"e":"DIC时血小板与凝血因子大量消耗并继发纤溶亢进，故出血时间与凝血时间均延长。血小板减少性紫癜仅出血时间延长，血友病仅凝血时间延长。"},{"q":"不可能引起颈椎活动受限的疾病是","o":["颈肌纤维组织炎","强直性脊柱炎","颈椎病","先天性斜颈","颈椎结核"],"a":3,"e":"先天性斜颈由胸锁乳突肌挛缩引起，表现为头向患侧偏斜、下颌转向健侧，颈椎本身结构正常、活动不受限。颈肌纤维组织炎、强直性脊柱炎、颈椎病和颈椎结核均累及颈椎而致活动受限。"},{"q":"哪种疾病的气管位置居中","o":["肺实变","肺不张","胸腔积液","胸膜肥厚","气胸"],"a":0,"e":"肺实变时肺体积既不缩小也不增大，气管位置居中。肺不张和胸膜肥厚使气管移向患侧，胸腔积液和气胸则使气管移向健侧。"},{"q":"过氧化物酶染色呈强阳性反应的疾病是","o":["急性淋巴细胞白血病","急性粒细胞白血病","急性单核细胞白血病","急性红白血病","慢性淋巴细胞白血病"],"a":1,"e":"急性粒细胞白血病的原始及早幼粒细胞过氧化物酶活性明显增强，染色呈强阳性；急性单核细胞白血病多为弱阳性或阴性，急性淋巴细胞白血病、红白血病及慢性淋巴细胞白血病均呈阴性。"},{"q":"下列疾病中不会发生中心型发绀的是","o":["Eisenmenger综合征","慢性阻塞性肺病","原发性肺动脉高压","右心衰竭","大量胸腔积液"],"a":3,"e":"中心型发绀由肺通气换气障碍或心内右向左分流致动脉血氧饱和度下降引起，常见于Eisenmenger综合征、慢性阻塞性肺病、原发性肺动脉高压和大量胸腔积液；右心衰竭属周围型发绀。"},{"q":"TDTH细胞的特征是","o":["CD8＋Tc细胞","CD4＋Th1细胞","CD8＋Ts细胞","CD4＋Th2细胞","CD3＋Th2细胞"],"a":1,"e":"TDTH即迟发型超敏反应T细胞，为CD4+Th1细胞，通过释放IL-2、IFN-γ等细胞因子介导以单核细胞浸润为主的炎症；CD8+Tc为细胞毒性T细胞，Th2主要辅助B细胞。"},{"q":"抬举性心尖冲动见于","o":["腹主动脉瘤","肺心病右心室肥大","升主动脉瘤或主动脉弓瘤","Broadbent征","高血压左心室肥大"],"a":4,"e":"左心室肥大时心肌收缩力增强，心尖搏动徐缓有力，可使手指尖端抬起并持续至第二心音开始，称抬举性心尖搏动；胸骨左下缘抬举样搏动才是右心室肥厚的指征。"},{"q":"下列哪种不属于正常细胞性贫血","o":["再生障碍性贫血","急性失血性贫血","溶血性贫血","地中海贫血","白血病所致贫血"],"a":3,"e":"正常细胞性贫血指MCV、MCH、MCHC均在正常范围，见于再生障碍性贫血、急性失血性贫血、溶血性贫血及白血病所致贫血；地中海贫血属小细胞低色素性贫血。"},{"q":"免疫球蛋白的同种型抗原决定簇位于","o":["C区","V区","超变区","C区和V区","C区和超变区"],"a":0,"e":"免疫球蛋白的同种型抗原决定簇位于重链和轻链的恒定区，为同一种属所有个体共有；独特型决定簇才位于V区尤其是超变区。"},{"q":"细胞圆形，直径13～15mm，核常分叶呈眼镜形，浆内充满均匀橘红色颗粒，为何种细胞的特点","o":["N（中性粒细胞）","E（嗜酸性粒细胞）","B（嗜碱性粒细胞）","L（淋巴细胞）","M（单核细胞）"],"a":1,"e":"嗜酸性粒细胞胞体圆形，直径13～15μm，胞核多分两叶呈眼镜形，胞质充满粗大均匀、紧密排列的橘红色颗粒；中性粒细胞颗粒细小淡紫红，嗜碱性粒细胞颗粒粗大深紫黑并遮盖胞核。"},{"q":"下列关于第一心音（S1）叙述正确的是","o":["声音较清脆，历时较短","与心尖冲动同时出现","心底部听诊最清楚","半月瓣关闭引起的振动","房室瓣开放引起的振动"],"a":1,"e":"第一心音由房室瓣关闭引起，音调低钝、强度较响、历时约0.1秒，与心尖搏动同时出现，在心尖部最响；半月瓣关闭产生的是第二心音。"},{"q":"变异型心绞痛的心电图表现为","o":["相关导联ST段呈弓背向上型抬高，变化迅速，出现病理性Q波","普通导联ST段呈凹面向上型太高（aVR、V1导联除外），不出现病理性Q波","ST段呈凹面向上型抬高，主要为J点抬高，多见于胸导联，不出现病理性Q波","相关导联ST段呈弓背向上型抬高，持续达数个月，有病理性Q波","相关导联一过性ST段抬高，对应导联ST段下移，变化迅速"],"a":4,"e":"变异型心绞痛由冠状动脉痉挛引起，发作时相关导联出现一过性ST段抬高，常伴高耸T波和对应导联ST段下移，变化迅速，一般不出现病理性Q波。"},{"q":"诊断贫血最可靠的指标是","o":["外周血红细胞数","血细胞比容","皮肤颜色改变","外周血血红蛋白浓度","红细胞平均血红蛋白含量"],"a":3,"e":"血红蛋白浓度直接反映红细胞携氧能力，贫血时其下降程度与临床症状平行，是诊断贫血最可靠的指标；红细胞数易受血浆容量影响，血细胞比容敏感性较差。"},{"q":"关于病历书写及修改，正确的是","o":["实习期及试用期医务人员不能书写病历","实习期及试用期医务人员可以书写病历，但需要本医疗机构合法执业的医务人员审核修改并签名","修改病历应该在48h内完成，上级医师审核签名在左侧，并以斜线隔开","进修医生不能在接收其进修的医疗机构书写病历","病历书写过程中出现错字错句，应当用涂改液抹去，然后在原处继续书写，签名及注明修改日期"],"a":1,"e":"实习期及试用期医务人员可以书写病历，但须由具有本医疗机构执业资格的上级医务人员审阅、修改并签名；进修及规范化培训人员经认定后同样可以书写。"},{"q":"腱鞘滑膜炎最常见于","o":["强直性脊柱炎","风湿性关节炎","老年性骨关节炎","类风湿性关节炎","内生软骨瘤"],"a":3,"e":"类风湿关节炎以滑膜炎为基本病变，腱鞘滑膜常同时受累，出现腱鞘炎和梭形指；风湿性关节炎为游走性大关节疼痛，骨关节炎以关节软骨退变为主。"},{"q":"急性左心衰竭患者多采用的体位是","o":["被动体位","强迫坐位","强迫站立位","强迫仰卧位","强迫侧卧位"],"a":1,"e":"急性左心衰竭时肺淤血致呼吸困难，病人被迫采取坐位即端坐呼吸，以利辅助呼吸肌参与、加大膈肌活动度并减少回心血量、减轻心脏负荷。"},{"q":"蜘蛛痣常见的部位不包括","o":["面颈部","肩部","胸部","腹部","手背"],"a":3,"e":"蜘蛛痣是皮肤小动脉末端分支扩张形成的血管痣，多分布于面、颈、上胸部、肩部及上肢手背等上腔静脉分布区，腹部不属于其好发部位。"},{"q":"诊断尿路感染的最重要依据是","o":["有尿频、尿急、尿痛症状","腰痛和肾区叩击痛","有真性细菌尿","有白细胞尿","有蛋白尿"],"a":2,"e":"真性细菌尿指清洁中段尿培养检出有意义的致病菌，是诊断尿路感染最重要的依据；尿频尿急尿痛及白细胞尿仅为提示性表现，可见于非感染性疾病。"},{"q":"下列有关低血压的叙述正确的是","o":["指血压＜90/70mmHg","常伴有脉压减小","为血管紧张度降低所致","主要见于严重贫血","可见于多发性大动脉炎"],"a":1,"e":"低血压时心排血量减少、外周血管收缩，收缩压下降较舒张压明显，脉压常减小；诊断标准为血压低于90/60mmHg，可见于休克、多发性大动脉炎等。"},{"q":"强直性脊柱炎病变特点不包括","o":["青壮年男性多见","常累及骶髂关节","胸椎常后凸畸形","病变常下行性进展","仰卧位脊柱不能伸直"],"a":3,"e":"强直性脊柱炎多见于青壮年男性，自骶髂关节起病沿脊柱上行性进展，胸椎呈弧形后凸、脊柱强直固定，仰卧位亦不能伸直；下行性进展不是其特点。"},{"q":"交替脉常见于","o":["心包积液","肺源性心脏病","左心衰竭","休克","伤寒"],"a":2,"e":"交替脉指节律规则而强弱交替出现的脉搏，系左心室收缩力强弱交替所致，是左心衰竭的重要体征；心包积液出现的是奇脉，休克多为细弱脉。"},{"q":"气管与食管的感觉是通过（ ）传入的","o":["三叉神经","面神经","交感神经","迷走神经","听神经"],"a":3,"e":"气管与支气管、食管的感觉纤维均经迷走神经传入，构成咳嗽、吞咽等反射的传入通路；三叉神经支配面部感觉，面神经司面肌运动。"},{"q":"剑突下心尖冲动见于","o":["肺心病右室肥大","升主动脉瘤或主动脉弓瘤","Broadbent征","高血压左室肥大","扩张型心肌病"],"a":0,"e":"右心室肥大时心脏沿长轴顺钟向转位，心尖搏动可移至剑突下，见于肺源性心脏病；左心室肥大时心尖搏动向左下移位。"},{"q":"最常出现惊厥伴瞳孔扩大与舌咬伤的疾病是","o":["癫痫大发作","癔症发作","低钙性抽搐","一氧化碳中毒","结核性脑膜炎"],"a":0,"e":"癫痫大发作时全身强直阵挛、呼吸暂停、发绀并可有大小便失禁，发作中易咬伤舌、瞳孔散大；癔症发作瞳孔多正常，低钙抽搐无意识丧失。"},{"q":"最容易引起重叠性奔马律的疾病是","o":["心功能不全伴心动过速","心功能不全伴正常心率","心功能不全伴二度房室传导阻滞","二度房室传导阻滞","完全性左束支传导阻滞"],"a":0,"e":"重叠性奔马律由舒张早期奔马律与舒张晚期奔马律重叠而成，见于心率增快的心功能不全，因舒张期过短使两音重合；心率正常时两音分开而不重叠。"},{"q":"以下哪项不是共济运动相关检查","o":["指鼻试验","跟膝胫试验","闭目难立征","快速轮替试验","凯尔尼格征"],"a":4,"e":"凯尔尼格征属脑膜刺激征，检查屈髋伸膝时阻力增高并伴疼痛；指鼻试验、跟膝胫试验、闭目难立征和快速轮替试验均用于评价共济运动。"},{"q":"二尖瓣狭窄时最能提示肺动脉高压的体征是","o":["开瓣音响亮","心尖部第一心音增强","心界向两侧扩大","心尖部舒张期杂音","肺动脉瓣第二心音亢进、分裂"],"a":4,"e":"二尖瓣狭窄致肺动脉高压时肺动脉瓣关闭延迟，P2亢进并出现通常分裂，是肺动脉高压的听诊依据；开瓣音和S1亢进反映瓣膜活动度而非肺动脉压。"},{"q":"与JAK2基因突变相关最密切的是","o":["真性红细胞增多症","原发性血小板增多症","原发性骨髓纤维化","慢性髓细胞白血病","系统性肥大细胞增多症"],"a":0,"e":"JAK2 V617F突变见于95%以上的真性红细胞增多症，也可见于原发性血小板增多症和原发性骨髓纤维化；慢性髓细胞白血病的标志是BCR-ABL融合基因。"},{"q":"下述哪项描述最符合急性肺水肿的肺部查体所见","o":["两肺底细小水泡音","两肺底捻发音","两肺野布满湿啰音","两肺野布满干啰音","一侧肺底湿啰音"],"a":2,"e":"急性肺水肿时肺泡内充满水肿液，双肺野可满布湿啰音并伴哮鸣音；两肺底湿啰音多见于肺淤血和支气管肺炎，局限性湿啰音提示局部病变。"},{"q":"结合胆红素增高为主的黄疸产生的机制主要是","o":["胆红素排泄障碍","胆红素结合障碍","胆红素摄取障碍","胆红素来源过多","胆红素肾脏排泄障碍"],"a":0,"e":"结合胆红素增高为主的黄疸见于胆汁淤积，因胆红素排入胆道受阻、反流入血所致；摄取和结合障碍引起的是非结合胆红素升高为主的黄疸。"},{"q":"血浆碱剩余（BE）的正常值约为","o":["0±3mmol/L","－1±3mmol/L","5mmol/L","10mmol/L","15mmol/L"],"a":0,"e":"碱剩余指在标准条件下将血液滴定至pH7.40所需的酸或碱量，正常为0±3mmol/L，正值提示代谢性碱中毒，负值提示代谢性酸中毒。"},{"q":"晕厥的临床表现不包括","o":["短暂的意识丧失","由一过性广泛的脑供血不足所致","突然发作，迅速恢复","发作时四肢肌张力消失而倒地","可以表现为持续的昏迷"],"a":4,"e":"晕厥由一过性全脑供血不足引起，表现为突然发生的短暂意识丧失，数秒至数分钟内自行恢复，四肢肌张力消失而倒地；持续昏迷属意识障碍而非晕厥。"},{"q":"肠鸣音消失，常见于","o":["麻痹性肠梗阻","急性腹膜炎早期","急性胃肠炎","习惯性便秘","上消化道出血"],"a":0,"e":"肠鸣音消失指持续听诊3～5分钟仍未闻及，见于麻痹性肠梗阻和急性腹膜炎；机械性肠梗阻肠鸣音亢进呈金属音，急性胃肠炎肠鸣音活跃。"},{"q":"关于心源性水肿体征，错误的是","o":["首先出现在身体下垂部","严重时出现胸腔积液、腹水","肺水肿","可有肝大","颈静脉怒张"],"a":2,"e":"心源性水肿是体循环淤血的表现，首先出现在身体下垂部位，可伴颈静脉怒张、肝大、胸腹腔积液；肺水肿属内脏器官局部水肿，不列入水肿范畴。"},{"q":"用于评价大气道功能状态的指标为","o":["FEV1/FVC","FEV1%pred","PEF","FVC","MEF50"],"a":2,"e":"最大呼气流量PEF反映呼吸肌力量及大气道有无阻塞，是评价大气道功能的指标；FEV1/FVC和MEF50主要反映小气道阻塞，FVC反映肺容量。"},{"q":"大量咯血是指每日咯血量为","o":["200ml以上","300ml以上","400ml以上","500ml以上","600ml以上"],"a":3,"e":"每日咯血量在100ml以内为小量，100～500ml为中等量，500ml以上或一次咯血100～500ml为大量；大咯血多见于空洞性肺结核、支气管扩张和慢性肺脓肿。"},{"q":"用于评价限制性通气功能障碍指标为","o":["FEV1/FVC","FEV1%pred","PEF","FVC","MEF50"],"a":3,"e":"限制性通气功能障碍以肺容量减少为特征，FVC、VC下降而FEV1/FVC正常或升高；FVC是评价限制性通气障碍的主要指标，PEF反映大气道功能。"},{"q":"关于外源性致热原种类的描述，错误的是","o":["包括细菌及细菌毒素","炎性渗出物","无菌性坏死组织","抗原抗体复合物","肿瘤坏死因子"],"a":4,"e":"外源性致热原包括细菌及其毒素、病毒、炎性渗出物、无菌性坏死组织和抗原抗体复合物等；肿瘤坏死因子属内源性致热原，作用于体温调节中枢使调定点上移。"},{"q":"下列均为正常肾脏查体所具有的特征，但除外","o":["表面光滑","无压痛","可触到切迹","随呼吸上下移动","肾前方叩诊呈实音"],"a":2,"e":"正常肾脏表面光滑、质实而无压痛，可随呼吸上下移动，肾区叩诊呈实音；可触及切迹是脾脏的形态特征，用于脾肿大时的鉴别。"},{"q":"正常人平卧时，颈外静脉在锁骨下缘和下颌角的充盈水平是","o":["下2/3以内","下1/2以内","下1/3以内","上1/3以内","不显露"],"a":0,"e":"正常人立位或坐位时颈外静脉不显露，平卧时稍见充盈，充盈水平不超过锁骨上缘至下颌角距离的下2/3；超过此限提示颈静脉压升高。"},{"q":"网织红细胞减少的贫血是","o":["再生障碍性贫血","巨幼细胞贫血","缺铁性贫血","急性失血性贫血","急性溶血性贫血"],"a":0,"e":"网织红细胞反映骨髓红系造血功能，其减少见于再生障碍性贫血和纯红细胞再生障碍性贫血；溶血性贫血、急性失血及缺铁性贫血治疗有效时网织红细胞增多。"},{"q":"当医生用手触诊患者腹部时，出现压痛后，手指压于疼痛部位稍停片刻，使压痛感觉趋于稳定，然后迅速将手抬起，如此时患者感觉腹痛骤然加重，并伴有痛苦表情或呻吟，称为反跳痛，这一体征表示的意义是","o":["脏器的炎症已累及腹膜的脏层","脏器的炎症已累及腹膜的壁层","脏器的炎症已发生穿破","脏器的炎症已波及邻近脏器","脏器的炎症已波及大网膜"],"a":1,"e":"反跳痛指按压后迅速抬手时腹痛骤然加重，提示炎症已累及腹膜壁层；仅有压痛而无反跳痛多为脏器炎症尚未波及壁层腹膜。"},{"q":"以下哪项心电图特征不可能出现在仅有左房增大的患者","o":["P波振幅4mm","P波时限0.16s","P波双向","P波切迹","V1导P波负向部分大于0.04s"],"a":0,"e":"P波振幅4mm即0.4mV，已达右心房肥大的标准；左心房增大表现为P波增宽、双峰或V1导联负向部分加深增宽，单纯左房增大不会出现P波高尖。"},{"q":"脉压增大可见于哪种疾病","o":["主动脉瓣关闭不全","主动脉瓣狭窄","心包积液","严重左心衰竭","全心衰竭"],"a":0,"e":"主动脉瓣关闭不全时舒张期血液反流，收缩压升高、舒张压降低，脉压明显增大，并出现水冲脉等周围血管征；主动脉瓣狭窄及心包积液则脉压减小。"},{"q":"关于右室肥大的心电图表现，下列哪个描述是错误的","o":["V1导联R/S≤1，呈r型或rS型","V5导联R/S≤1或S波比正常加深","aVR导联以R波为主R/q或R/S≥1","RV1＋SV5＞1、05mV（重度＞1.20mV）","心电轴右偏≥＋90°（重度可大于110°）"],"a":0,"e":"右心室肥厚时V1导联R/S≥1，呈R型或Rs型，V5导联R/S≤1，电轴右偏；V1导联R/S≤1、呈rS型是正常图形，不是右室肥厚的表现。"},{"q":"不符合心房扑动诊断条件的是","o":["QRS波群时限增宽","可见F波","心房率250～350次/min","无等电位线","P波消失"],"a":0,"e":"心房扑动时心电图P波消失，代之以频率250～350次/分的锯齿状F波，F波之间无等电位线；QRS波群形态多正常，时限一般不增宽。"},{"q":"鉴别中度昏迷与深昏迷最有价值的要点是","o":["各种刺激无反应","不能唤醒","无自主运动","深浅反射均消失","大小便失禁"],"a":3,"e":"中度昏迷对剧烈刺激尚有反应、角膜反射减弱、瞳孔对光反射迟钝；深昏迷则各种刺激无反应、深浅反射均消失，故深浅反射状态最有鉴别价值。"},{"q":"关于血压叙述正确的是","o":["测量时被测上肢裸露，肘部高于心脏水平","测量前30min禁烟和咖啡等","测量时声音突然变小而低沉为舒张压","正常人两上肢血压略有差异，可相差15～20mmHg","测量时为操作方便，应将听诊器体件塞于袖带内"],"a":1,"e":"测量血压前半小时内应禁烟、禁咖啡并排空膀胱，安静休息至少5分钟；被测上肢应裸露并与心脏同高，听诊器体件不得塞入袖带内。"},{"q":"hCG尿液检测最好收集","o":["晨尿","清洁中段尿","全天尿液","尿道口拭子","血液"],"a":0,"e":"晨尿浓缩且未受饮食干扰，hCG浓度较高，是妊娠试验和尿细菌培养的首选标本；随机尿易受稀释影响而出现假阴性。"},{"q":"下列缓冲对中哪一对缓冲能力最强","o":["[HPO42－]/[H2PO4－]为2mol/L、0.5mol/L","[HPO42－]/[H2PO4－]为1.6mol/L、0.4mol/L","[HPO42－]/[H2PO4－]为1.2mol/L、0.3mol/L","[HPO42－]/[H2PO4－]为1.0mol/L、0.25mol/L","[HPO42－]/[H2PO4－]为2.4mol/L、0.6mol/L"],"a":4,"e":"缓冲对的缓冲能力取决于其总浓度，浓度越高缓冲能力越强；各组HPO42-/H2PO4-比值均为4∶1，其中2.4mol/L与0.6mol/L一组总浓度最高。"},{"q":"大叶性肺炎实变期肺部体征不正确的是","o":["语音震颤增强","叩诊呈浊音","可听到管样呼吸音","可听到哮鸣音","可听到胸膜摩擦音"],"a":3,"e":"大叶性肺炎实变期语音震颤增强、叩诊浊音、可闻及管样呼吸音及胸膜摩擦音；哮鸣音由气道痉挛或狭窄产生，见于支气管哮喘，不是实变期体征。"},{"q":"前列腺增生手术后尿失禁与下列哪项因素无关","o":["括约肌损伤","不稳定膀胱","膀胱出口梗阻","后尿道损伤刺激及创面感染","膀胱尿道角度改变"],"a":4,"e":"前列腺增生术后尿失禁与尿道括约肌损伤、不稳定膀胱、膀胱出口梗阻及后尿道创面刺激感染有关；膀胱尿道角度改变主要与女性压力性尿失禁相关。"},{"q":"血小板膜糖蛋白GPⅠb与下列哪种血小板功能有关","o":["黏附功能","分泌功能","聚集功能","止血功能","血块收缩功能"],"a":0,"e":"血小板膜糖蛋白GPⅠb与vWF结合，再与内皮下胶原连接，介导血小板黏附于血管损伤部位；GPⅡb/Ⅲa则介导血小板聚集。"},{"q":"以血红蛋白为标准，贫血是指成年男性血红蛋白","o":["＜120g/L","＜110g/L","＜100g/L","＜90g/L","＜80g/L"],"a":0,"e":"我国诊断贫血以血红蛋白浓度为标准，成年男性＜120g/L、成年女性＜110g/L即可诊断；血红蛋白直接反映携氧能力，较红细胞计数更为可靠。"},{"q":"医生在给患者体检时，发现其双眼调节反射和辐辏反射均消失。最可能是下列哪种神经病变所致","o":["视神经损害","动眼神经损害","展神经损害","面神经损害","三叉神经损害"],"a":1,"e":"动眼神经支配内直肌和睫状肌，损害时双眼内聚及晶状体调节均障碍，故集合反射与调节反射同时消失；展神经损害仅致眼球外展受限。"},{"q":"巨幼细胞贫血的原因是","o":["铁缺乏","RBC内在缺陷","RBC以外因素","骨髓造血功能障碍","叶酸缺乏"],"a":4,"e":"叶酸和维生素B12缺乏使DNA合成障碍，红系细胞核发育落后于胞质，形成巨幼细胞贫血；铁缺乏引起的是小细胞低色素性贫血。"},{"q":"心尖冲动有力，呈抬举样，见于","o":["甲亢","发热","左心室肥大","剧烈运动","消瘦"],"a":2,"e":"左心室肥大时心肌收缩力增强，心尖搏动徐缓有力并可抬举手指，呈抬举样；甲亢、发热、剧烈运动仅使搏动增强而持续时间短促。"},{"q":"关于小红细胞常见于以下情况，但应除外","o":["缺铁性贫血","小细胞低色素性贫血","铁粒幼细胞贫血","遗传性球形细胞增多症","巨幼细胞贫血"],"a":4,"e":"巨幼细胞贫血红细胞体积增大、MCV升高，属大细胞性贫血；缺铁性贫血、铁粒幼细胞贫血和地中海贫血均表现为小细胞低色素，遗传性球形细胞增多症红细胞小且厚。"},{"q":"关于肺肝界，哪项是错误的","o":["肺气肿时肺肝界下移","肺不张时肺肝界上移","腹腔积液时，肺肝界下移","肺底积液时，肺肝界上移","鼓肠时，肺肝界上移"],"a":2,"e":"肺肝界即肝脏绝对浊音界上界，腹腔积液或鼓肠时膈肌上抬，肺肝界上移而非下移；肺气肿时下移，肺不张及肺底积液时上移。"},{"q":"胸导联低电压的定义","o":["QRS波群振幅都小于0.5mV","QRS波群振幅都小于0.8mV","QRS波群振幅都小于1mV","QRS波群正向或负向振幅都小于0.5mV","QRS波群正向或负向振幅都小于0.8mV"],"a":1,"e":"六个胸导联QRS波群振幅即正向与负向绝对值之和均小于0.8mV称胸导联低电压；肢体导联均小于0.5mV为肢体导联低电压。"},{"q":"第一心音强弱不等，最常见于","o":["P-R间期延长","P-R间期缩窄","甲状腺功能亢进症","心房颤动","左心衰竭"],"a":3,"e":"心房颤动时心室率绝对不规则，心室舒张期充盈量多少不一，使第一心音强弱不等并伴脉搏短绌；完全性房室传导阻滞时S1强弱不等但心律规则。"},{"q":"急性纤维蛋白性心包炎具有的特征性体征是","o":["心尖冲动减弱或消失","心包叩击音","心包摩擦音","腹水","颈静脉怒张"],"a":2,"e":"急性纤维蛋白性心包炎时脏、壁层心包因纤维蛋白沉积而粗糙，心脏搏动时产生心包摩擦音，屏气时仍存在，为最具特征性的体征；积液增多后摩擦音可消失。"},{"q":"铁蛋白增高的疾病是","o":["恶性肿瘤","缺铁性贫血","红斑狼疮","营养不良","维生素C缺乏"],"a":0,"e":"铁蛋白是反映体内贮存铁的指标，恶性肿瘤、炎症、肝脏疾病及铁负荷过多时均可增高；缺铁性贫血、营养不良时铁蛋白降低。"},{"q":"关于血尿概念下列各项均正确，但除外","o":["血尿的尿色可以正常","血尿的尿色呈洗肉水样","当尿液呈酸性时血尿颜色可呈暗黑色","当尿液呈碱性时血尿为红色","血尿即为血红蛋白尿"],"a":4,"e":"血尿指尿中红细胞增多，轻者尿色可正常而仅镜检异常；血红蛋白尿呈酱油色、镜检无或仅少量红细胞，两者本质不同。"},{"q":"最常引起手指关节梭形肿胀的疾病是","o":["指关节结核","风湿性关节炎","类风湿关节炎","尺神经损伤","正中神经损伤"],"a":2,"e":"类风湿关节炎累及指间关节时，关节周围软组织梭形肿胀，形成双手对称的梭形指，晚期向尺侧偏斜；风湿性关节炎以游走性大关节疼痛为主。"},{"q":"肺部叩诊呈浊音或实音常见于","o":["支气管哮喘","肺内大空洞","肺气肿","大叶性肺炎","气胸"],"a":3,"e":"大叶性肺炎实变期肺组织含气量明显减少，叩诊呈浊音或实音；肺气肿呈过清音，气胸及肺内大空洞呈鼓音，支气管哮喘多为过清音。"},{"q":"下列哪种腹型属于健康正力型","o":["腹部平坦","腹部低平","腹部膨隆","蛙腹","尖腹"],"a":0,"e":"健康成年人平卧时前腹壁大致与肋缘至耻骨联合同一平面或略低凹，称腹部平坦，属正力型；低平见于消瘦者，膨隆、蛙腹及尖腹均属异常。"},{"q":"双侧心室肥大的心电图表现包括","o":["只显示左室肥大","只显示右室肥大","同时显示双室肥大","大致正常","同时显示双房、双室肥大"],"a":2,"e":"双侧心室肥厚时心电图可表现为大致正常、仅显示一侧肥厚或同时出现双室肥厚图形，因双侧除极向量可相互抵消，故并非简单相加。"},{"q":"以下不是呼气性呼吸困难的特点的是","o":["呼气费力","呼气时间延长","呼气缓慢","出现“三凹征”","常伴哮鸣音"],"a":3,"e":"呼气性呼吸困难因肺泡弹性减弱和小支气管痉挛，表现为呼气费力、缓慢、时间延长并伴哮鸣音；三凹征是吸气性呼吸困难的特征。"},{"q":"肺气肿时可出现下列体征，但应除外","o":["触诊语颤增强","桶状胸","叩诊过清音","肺下界下移","呼吸音减弱"],"a":0,"e":"肺气肿时肺组织含气量增多、传导减弱，语音震颤减弱，同时出现桶状胸、叩诊过清音、肺下界下移及呼吸音减弱；语颤增强见于肺实变和肺内大空洞。"},{"q":"P-R间期的正常值为","o":["0.05～0.10s","0.06～0.10s","0.10～0.12s","0.10～0.20s","0.12～0.20s"],"a":4,"e":"PR间期自P波起点至QRS波群起点，代表心房除极至心室开始除极的时间，正常0.12～0.20秒；老年人及心动过缓者可略延长，但不超过0.22秒。"},{"q":"下列组合正确的是","o":["左侧卧位——主动脉瓣关闭不全的舒张期杂音明显","坐位前倾位——二尖瓣狭窄的舒张期杂音明显","深吸气时——左心发生的杂音增强","深呼气时——右心发生的杂音增强","作Valsalva动作——特发性肥厚性主动脉瓣下狭窄杂音增强"],"a":4,"e":"深吸气后紧闭声门用力呼气即Valsalva动作，使回心血量减少，多数杂音减弱，而梗阻性肥厚型心肌病的杂音反而增强；左侧卧位使二尖瓣狭窄杂音增强。"},{"q":"本例心电图最可能的病变冠脉是","o":["左前降支","左旋支","右冠脉","后降支","钝缘支"],"a":0,"e":"官方题库缺失图片"},{"q":"下述为湿啰音特点的描述，但应除外","o":["呼吸音外的附加音","吸气时较明显，也可出现于呼气早期","部位较恒定，性质不易变","一次常连续多个出现","中、小水泡音不能同时存在"],"a":4,"e":"湿啰音为呼吸音外的附加音，吸气时或吸气终末明显，部位恒定、性质不易变，一次常连续多个出现，中、小湿啰音可同时存在，咳嗽后减轻或消失。"},{"q":"McBurney压痛点的位置在","o":["脐与右髂前上棘连线的中点上","脐与左髂前上棘连线的中外1/3交界处","脐与右髂前上棘连线的中外1/3交界处","脐水平线上右腹直肌外缘","两髂前上棘连线与右耻骨结节垂直线的相交点"],"a":2,"e":"麦氏点位于脐与右髂前上棘连线中、外1/3交界处，是阑尾根部的体表投影，该处压痛提示阑尾炎；其左下腹对称部位为罗夫辛征检查点。"},{"q":"下述情况的体温升高不属于生理性体温波动的是","o":["妇女月经前期","妇女妊娠期","剧烈运动后","流行性感冒","进食后"],"a":3,"e":"生理性体温波动包括月经前期、妊娠期、进食后及剧烈运动后体温轻度升高；流行性感冒由病原体及其致热原引起发热，属病理性发热。"},{"q":"音乐性杂音最常见于","o":["二尖瓣狭窄","室间隔缺损","房间隔缺损","感染性心内膜炎","肺动脉瓣狭窄"],"a":3,"e":"感染性心内膜炎时赘生物附着、瓣叶穿孔或腱索断裂，使杂音变得粗糙呈乐音样，称音乐性杂音，常提示瓣膜急性损害；单纯狭窄或间隔缺损杂音多较柔和。"},{"q":"关于法洛四联症的临床表现，不正确的是","o":["严重发绀及杵状指","脉搏正常","S1正常，但S2缺少肺动脉瓣成分","可有抬举性心尖冲动","胸骨缘较低位置可闻及收缩期喷射性杂音伴随震颤"],"a":3,"e":"法洛四联症为右心室肥大，可闻及胸骨左下缘收缩期喷射性杂音伴震颤，S2肺动脉瓣成分减弱或消失；心尖抬举样搏动提示左心室肥大，不是本病表现。"},{"q":"关于结核性渗出性胸膜炎的胸腔积液，不正确的是","o":["多呈草黄色，易自行凝固","比重大于1.018","蛋白含量大于30g/L","细胞成分以嗜酸性粒细胞为主","李凡他试验阳性"],"a":3,"e":"结核性渗出性胸膜炎积液多为草黄色渗出液，比重大于1.018、蛋白＞30g/L、李凡他试验阳性，细胞以淋巴细胞为主；嗜酸性粒细胞增多见于气胸、肺梗死等。"},{"q":"下列哪种情况可以判定为消瘦","o":["BMI＜17","BMI＜17、5","BMI＜18","BMI＜18、5","BMI＜19"],"a":3,"e":"目前采用体重指数判定消瘦，BMI＜18.5kg/m²为消瘦，18.5～23.9kg/m²为正常；BMI≥24为超重，≥28为肥胖。"},{"q":"关于脾脏轻度肿大正确的是","o":["深吸气时脾缘不超过肋下2cm","深呼气时脾缘不超过肋下2cm","深吸气时脾缘不超过肋下3cm","深呼气时脾缘不超过肋下3cm","平静呼吸脾缘不超过肋下3cm"],"a":0,"e":"脾缘在深吸气时不超过肋下2cm为轻度肿大，超过2cm但在脐水平线以上为中度，超过脐水平线或前正中线为高度肿大即巨脾。"},{"q":"语音震颤减弱或消失见于下列疾病，但除外","o":["肺气肿","阻塞性肺不张","气胸","肺梗死","胸壁皮下气肿"],"a":3,"e":"语音震颤减弱见于肺气肿、阻塞性肺不张、气胸、胸腔积液及胸壁皮下气肿；肺梗死属肺实变，语音震颤反而增强。"},{"q":"大量胸腔积液部位的叩诊音应为","o":["清音","过清音","实音","浊鼓音","空瓮音"],"a":2,"e":"大量胸腔积液时液体隔绝了声波传导，叩诊呈实音，积液区呼吸音和语音共振减弱或消失；积液区上方因压迫性肺不张可闻及支气管呼吸音。"},{"q":"脑脊液白细胞数300×106/L以上，以淋巴细胞为主，蛋白质增高，糖和氯化物明显降低，首先考虑哪种诊断的可能","o":["细菌性脑膜炎","病毒性脑膜炎","结核性脑膜炎","隐球菌性脑膜炎","流行性乙型脑炎"],"a":2,"e":"脑脊液细胞数中度增高、以淋巴细胞为主、蛋白增高、糖和氯化物明显降低且氯化物降低最显著，是结核性脑膜炎的典型改变；化脓性脑膜炎以中性粒细胞为主。"},{"q":"关于收缩早期喷射音，下列哪项是正确的","o":["肺动脉喷射音于呼气时增强，吸气时减弱","肺动脉喷射音于吸气时增强，呼气时减弱","肺动脉喷射音于胸骨右缘2、3肋间最响","主动脉喷射音于呼气时增强，吸气时减弱","主动脉喷射音于吸气时增强，呼气时减弱"],"a":0,"e":"肺动脉收缩期喷射音在肺动脉瓣区最响，吸气时减弱、呼气时增强；主动脉收缩期喷射音在主动脉瓣区最响，不受呼吸影响。"},{"q":"大量腹水的体征是","o":["尺压试验阳性","腹部浊音呈移动性","腹部浊音无移动性","振水音阳性","仰卧位浊音区在中腹部"],"a":1,"e":"大量腹水时液体因重力沉积于腹腔低位，改变体位后浊音区随之移动，称移动性浊音；巨大卵巢囊肿的浊音位于腹中部且不移动。"},{"q":"管样呼吸音可见于下列疾病，但除外","o":["肺癌","大叶肺炎","肺脓肿","肺结核","胸腔积液时积液区上方"],"a":0,"e":"管样呼吸音见于肺组织实变、压迫性肺不张及肺内大空洞，如大叶性肺炎、肺脓肿、肺结核及胸腔积液区上方；肺癌本身不产生管样呼吸音。"},{"q":"临床表现为咯血伴呛咳的疾病是","o":["大叶性肺炎","支气管肺癌","肺脓肿","湿性支气管扩张","化脓性肺炎"],"a":1,"e":"咯血伴呛咳多见于支气管肺癌和支原体肺炎，因肿瘤刺激气道或分泌物刺激引起；大叶性肺炎咯铁锈色痰，肺脓肿及支气管扩张多伴脓痰。"},{"q":"下列属于体表标志的是","o":["肋弓下缘","左上腹","右上腹","左下腹","麦氏点"],"a":0,"e":"肋弓下缘由第8～10肋软骨连接构成，是腹部体表的上界，用于腹部分区及肝脾测量；左上腹、右上腹等属分区名称，麦氏点是压痛点定位标志。"},{"q":"诊断学的辅助检查也包括一些特殊检查，但不包括","o":["心电图检查","超声检查","内窥镜检查","磁共振检查","建立遗传基因实验室与否的检查"],"a":4,"e":"诊断学的辅助检查包括心电图、超声、内镜、磁共振及各类特殊检查；是否建立遗传基因实验室属实验室建设问题，不是辅助检查项目。"},{"q":"下列哪项提示滑车神经受损","o":["眼上睑下垂","眼球向内活动受限","眼球向下及外展运动减弱","眼球向上活动受限","视野变小"],"a":2,"e":"滑车神经支配上斜肌，损害时眼球向下及向外运动减弱，病人下楼梯困难并出现复视；动眼神经麻痹表现为上睑下垂和眼球向内、向上活动受限。"},{"q":"S1出现的时间是","o":["与半月瓣关闭同时发生","与房室瓣关闭同时发生","在舒张早期发生","在心室射血高峰发生","在心室收缩中晚期发生"],"a":1,"e":"第一心音的主要成分由二尖瓣和三尖瓣关闭、瓣叶突然紧张产生振动形成，出现在心室收缩开始时，与房室瓣关闭同时；半月瓣关闭形成第二心音。"},{"q":"中毒不会引起高铁血红蛋白血症性发绀的物质是","o":["亚硝酸盐","地高辛","磺胺","苯胺","伯氨喹"],"a":1,"e":"高铁血红蛋白血症由苯胺、硝基苯、伯氨喹、亚硝酸盐及磺胺类中毒引起，二价铁被氧化为三价铁而失去携氧能力；地高辛不引起高铁血红蛋白血症。"},{"q":"下列属于心源性水肿的体征的是","o":["颈静脉怒张","肝脾大","非凹陷性水肿","胸壁上肢静脉怒张","单侧肢体水肿"],"a":0,"e":"心源性水肿伴体循环淤血，颈静脉怒张及肝颈静脉回流征阳性是其重要体征；肝脾大亦可见于肝源性，非凹陷性水肿提示黏液性水肿。"},{"q":"心脏听诊能诊断的心律失常中，最常见的是","o":["房性心动过速","室性心动过速","心房颤动","窦性心动过缓","完全性房室传导阻滞"],"a":2,"e":"心房颤动和期前收缩通过听诊即可作出诊断，其心律绝对不规则、第一心音强弱不等并伴脉搏短绌，是听诊最常发现的心律失常。"},{"q":"消化性溃疡有诊断意义的症状是","o":["反酸、嗳气","恶心、呕吐","呕吐隔夜食","出汗、脉缓","节律性上腹部疼痛"],"a":4,"e":"消化性溃疡上腹痛具有慢性、周期性、节律性特点，胃溃疡多在餐后痛、十二指肠溃疡多在饥饿痛及夜间痛，节律性疼痛最具诊断意义。"},{"q":"腹部检查的正确顺序是","o":["听诊、视诊、叩诊、触诊","听诊、视诊、触诊、叩诊","视诊、听诊、叩诊、触诊","视诊、听诊、触诊、叩诊","视诊、叩诊、触诊、听诊"],"a":2,"e":"腹部检查应先视诊，再听诊以免触诊引起肠蠕动干扰肠鸣音，随后叩诊，最后触诊；触诊是腹部检查最重要的方法，放在最后可减少刺激。"},{"q":"该符号代表第几颗牙","o":["右上第一尖牙","左上第—尖牙","右上中切牙","左上中切牙","左下第一磨牙"],"a":2,"e":"官方题库缺失图片"},{"q":"心动周期中的等容收缩期相当于","o":["半月瓣开放而房室瓣关闭","半月瓣及房室瓣均处于关闭状态","心室内压急剧下降","出现心室射血高峰","出现心室快速充盈"],"a":1,"e":"等容收缩期心室开始收缩，室内压迅速上升超过房内压使房室瓣关闭，但尚未超过主动脉压，半月瓣仍关闭，故两瓣均处于关闭状态，心室容积不变。"},{"q":"严重吸气性呼吸困难不会出现","o":["端坐呼吸","鼻翼翕动","咯粉红色泡沫痰","呼吸加深加快","三凹征"],"a":2,"e":"严重吸气性呼吸困难出现三凹征、鼻翼翕动、呼吸加深加快及端坐呼吸；咯粉红色泡沫痰由急性左心衰竭肺水肿引起，属心源性呼吸困难。"},{"q":"下图所示心电图的诊断是","o":["二度Ⅱ型房室传导阻滞","二度Ⅰ型房室传导阻滞","三度房室传导阻滞","房性期前收缩","室性期前收缩"],"a":1,"e":"官方题库缺失图片"},{"q":"以下不符合扩张型心肌病心脏体征的是","o":["心界扩大","心音增强","可闻及第三或第四心音","奔马律","有时心尖部可闻及收缩期杂音"],"a":1,"e":"扩张型心肌病心室扩大、心肌收缩力减弱，心尖搏动减弱，心音低钝，可闻及第三或第四心音及奔马律，心尖部常有相对性收缩期杂音；心音增强不是其表现。"},{"q":"下列不属于一般项目的内容是","o":["籍贯","民族","入院日期","发病日期","记录日期"],"a":3,"e":"一般项目包括姓名、性别、年龄、籍贯、出生地、民族、婚姻、职业、入院日期、记录日期及病史陈述者；发病日期属现病史内容。"},{"q":"关于FDP，错误的是","o":["FDP是在纤溶亢进时产生的纤溶酶的作用下，纤维蛋白或纤维蛋白原被分解后产生的降解产物的总称","原发性和继发性纤维蛋白溶解活性增高时，血中纤维蛋白（原）降解产物含量升高","原发性纤维蛋白溶解功能亢进，FDP降低","继发性纤维蛋白溶解功能亢进，FDP增高","FDP主要反映纤维蛋白溶解功能"],"a":2,"e":"FDP是纤维蛋白和纤维蛋白原在纤溶酶作用下降解的产物，原发性与继发性纤溶亢进时均升高，故原发性纤溶亢进时FDP并不降低。"},{"q":"第二心音生理分裂中，下列哪项是正确的","o":["深吸气末可听到第二心音分裂，呼气时又成为单一的第二心音","深呼气时可听到第二心音分裂，吸气时又成为单一的第二心音","与呼吸无关","卧位时可听到第二心音分裂，立位时则无","左侧卧位时明显，右侧卧位时则减轻"],"a":0,"e":"生理性S2分裂因深吸气时右心回心血量增加、肺动脉瓣关闭进一步延迟，于深吸气末可闻及分裂，呼气时两成分重新靠拢而恢复为单一心音，青少年多见。"},{"q":"关于心脏杂音的叙述正确的是","o":["收缩期杂音分为0～5的等级","2/6级以上杂音通常见于器质性病变","杂音是由血流加速形成旋涡所致","5级杂音在听诊器离胸壁一定距离也能听到","杂音与震颤一起存在"],"a":2,"e":"血流加速至一定程度时层流被破坏形成湍流或涡流，冲击心壁、瓣膜和腱索使之振动而产生杂音；杂音强度分6级，3级以上才提示器质性病变。"},{"q":"头发全脱落称","o":["全秃","普秃","斑秃","假性斑秃","头癣"],"a":0,"e":"头发全部脱落称全秃，常由斑秃发展而来；普秃指头发及全身毛发均脱落，斑秃为局限性斑片状脱发，假性斑秃为瘢痕性脱发。"},{"q":"被检查者直立位两上肢自然下垂时，肩胛下角位于","o":["第3或第4肋骨","第5或第6肋骨","第7或第8肋骨","第9或第10肋骨","第11或第12肋骨"],"a":2,"e":"直立位两上肢自然下垂时，肩胛下角平第7或第8肋骨，相当于第8胸椎水平，是后胸部计数肋骨和定位的标志。"},{"q":"Duroziez双重杂音见于下列疾病，但除外","o":["主动脉瓣关闭不全","严重贫血","维生素B1缺乏性心脏病","主动脉瓣狭窄","甲状腺功能亢进"],"a":3,"e":"Duroziez双重杂音见于主动脉瓣关闭不全、严重贫血、甲状腺功能亢进及维生素B1缺乏性心脏病等脉压增大的情况；主动脉瓣狭窄脉压减小，不出现该杂音。"},{"q":"适用于大量腹水时肝脾及腹腔包块检查的是","o":["深部滑行触诊法","深压触诊法","双手触诊法","冲击触诊法","浅部触诊法"],"a":3,"e":"冲击触诊法即浮沉触诊法，以并拢的三指取70°～90°角在腹壁作急速冲击，使腹水暂时移开而触及肝脾或包块，适用于大量腹水时深部脏器触诊。"},{"q":"成熟T细胞的特性包括","o":["自身耐受","记忆","介导免疫应答","特异性杀伤","非特异性杀伤"],"a":0,"e":"成熟T细胞经胸腺内阳性与阴性选择获得自身MHC限制性和自身耐受，对自身抗原不应答；记忆和特异性杀伤仅为部分亚群的功能。"},{"q":"患者具有持续发热、相对缓脉、肝脾大、玫瑰疹等临床特点，诊断应考虑","o":["病毒感染","白血病","斑疹伤寒","伤寒","败血症"],"a":3,"e":"持续发热、相对缓脉、肝脾大、玫瑰疹及白细胞减少是伤寒的典型表现，玫瑰疹多分布于胸腹部，为病灶周围血管扩张所致。"},{"q":"器质性心脏病的体征之一是","o":["心尖向左下移位","心前区触及震颤","心尖部闻及3/6级的收缩期杂音","剑下心尖冲动","听到第三心音"],"a":1,"e":"心前区触及震颤是器质性心脏病的重要体征，见于瓣膜狭窄及先天性心血管病；心尖向左下移位虽可见于左室肥大，但也可由其他原因引起。"},{"q":"下列各项均为现病史的内容，但除外","o":["病因与诱因","伴随症状","诊治、用药经过","病程中一般情况","与现病有密切关系的疾病"],"a":4,"e":"现病史包括起病情况与患病时间、病因与诱因、主要症状特点、病情发展与演变、伴随症状、诊治经过及病程中一般情况；与现病有密切关系的疾病属既往史。"},{"q":"咯血与呕血鉴别点不正确的是","o":["血色鲜红","痰中带血","有支气管扩张症病史","咯出物为酸性反应","咯血前有咳嗽、喉部痒感"],"a":3,"e":"咯血来自呼吸道，血中混有痰及泡沫，呈碱性反应；呕血来自上消化道，混有食物残渣和胃液，呈酸性反应，并伴黑便。"},{"q":"患者咳嗽，咳痰成砖红色胶冻样痰液时，首先考虑感染因素为","o":["军团菌","肺炎克雷伯杆菌","铜绿假单胞菌","曲霉菌","肺炎球菌"],"a":1,"e":"砖红色胶冻样痰由肺炎克雷伯菌的黏稠荚膜物质与坏死组织混合形成，是肺炎克雷伯菌肺炎的特征性表现；肺炎链球菌肺炎为铁锈色痰。"},{"q":"下列哪种疾病不会出现血块收缩不良的结果","o":["血小板减少症","血小板无力症","血友病","低纤维蛋白原症","血小板增多症"],"a":2,"e":"血块收缩依赖血小板收缩蛋白及纤维蛋白原，血小板减少、血小板无力症、血小板增多症及低纤维蛋白原血症均可致收缩不良；血友病为凝血因子缺乏，血块收缩正常。"},{"q":"四肢对称性紫癜伴关节痛或腹痛、血尿常见于","o":["血小板减少性紫癜","过敏性紫癜","血友病","维生素K缺乏症","播散性血管内凝血"],"a":1,"e":"过敏性紫癜为血管壁功能异常所致，紫癜呈四肢对称性、高出皮肤，可伴关节痛、腹痛及血尿；血小板减少性紫癜血小板计数减低，血友病为深部血肿。"},{"q":"病理反射出现是由于","o":["脊髓反射弧的损害","神经系统兴奋性普遍增高","基底节受损","锥体束受损","脑干网状结构损害"],"a":3,"e":"病理反射是锥体束病损时失去对脑干和脊髓的抑制作用而释放的异常反射，如Babinski征；1岁半以内婴幼儿出现属生理性。"},{"q":"有关诊断思维的基本原则，正确的是","o":["现象和本质不统一","面面俱到","只关注某一系统变化","只关注典型症状","首先应考虑器质性疾病"],"a":4,"e":"器质性疾病与功能性疾病鉴别困难时应首先考虑器质性疾病的诊断，以免延误治疗；诊断功能性疾病前必须排除器质性病变。"},{"q":"正常人血清中的胆红素主要是","o":["结合胆红素","未结合胆红素","与球蛋白结合的胆红素","与总蛋白结合的胆红素","与白蛋白结合的胆红素"],"a":1,"e":"正常人血清胆红素以非结合胆红素为主，其与白蛋白结合运输，不能经肾滤过；结合胆红素含量很低，尿中一般检测不到。"},{"q":"可出现气管移向健侧的疾病为","o":["肺实变","肺气肿","肺不张","胸膜肥厚","气胸"],"a":4,"e":"气胸时胸膜腔积气，患侧胸廓饱满、呼吸动度减弱，气管及心脏被推向健侧，叩诊呈鼓音，呼吸音减弱或消失；肺不张与胸膜肥厚则使气管移向患侧。"},{"q":"图中所示心电图最可能的诊断是","o":["心房颤动","心房扑动","房性心动过速","窦性心动过速","阵发性室上性心动过速"],"a":1,"e":"官方题库缺失图片"},{"q":"腹部触诊柔韧感最常见于","o":["自发性腹膜炎","慢性膀胱炎","急性盆腔炎","结核性腹膜炎","弥漫性腹膜炎"],"a":3,"e":"结核性腹膜炎因腹膜增厚、粘连及干酪样坏死，触诊腹壁呈柔韧感即揉面感，是其特征性体征；急性弥漫性腹膜炎表现为腹肌紧张呈板状。"},{"q":"下列疾病临床多表现为弛张热，但需除外","o":["重症肺结核","风湿热","化脓性肺炎","急性肾盂肾炎","败血症"],"a":3,"e":"弛张热体温在39℃以上、24小时内波动超过2℃，见于败血症、风湿热、重症肺结核及化脓性炎症；急性肾盂肾炎多为间歇热。"},{"q":"下列中细胞质内不含有特异性颗粒的细胞是","o":["早幼粒细胞","中幼粒细胞","晚幼粒细胞","杆状核细胞","分叶核粒细胞"],"a":0,"e":"早幼粒细胞胞质内只含紫红色嗜天青颗粒，尚无特异性颗粒；中幼粒细胞以后各阶段胞质才出现中性、嗜酸性或嗜碱性特异性颗粒。"},{"q":"呼气延长可见于","o":["肺不张","胸腔积液","气胸","支气管哮喘急性发作期","间质性肺炎"],"a":3,"e":"支气管哮喘急性发作时小支气管痉挛、黏膜水肿致气道阻塞，呼气阻力增大，表现为呼气费力、呼气时间延长并伴哮鸣音。"},{"q":"下列是关于气胸体征的描述，错误的是","o":["患侧胸廓膨满","气管移向健侧","叩诊为鼓音","患侧呼吸音弱","听到支气管呼吸音"],"a":4,"e":"气胸时患侧胸廓膨满、气管移向健侧、叩诊鼓音、呼吸音减弱或消失；支气管呼吸音见于肺实变和压迫性肺不张，气胸不出现。"},{"q":"决定热型的依据是","o":["体温的高低","体温的上升速度","一定体温的持续时间","体温的曲线形态","体温的下降速度"],"a":3,"e":"将不同时间测得的体温数值连成体温曲线，其不同形态称热型，热型由体温曲线的形态决定，是判断发热病因的重要线索。"},{"q":"抬高患者头部，观察患者双下肢是否同时屈髋屈膝，是以下哪个检查","o":["Babinski征","颈强直","kernig征","Brudzinski征","Hoffmann征"],"a":3,"e":"布鲁津斯基征为病人仰卧、下肢伸直，检查者托起枕部使头部前屈，出现双髋与膝关节同时屈曲为阳性，提示脑膜刺激征；凯尔尼格征为屈髋伸膝时抵抗。"},{"q":"下列各项是器质性心脏病的体征，但应除外","o":["抬举性心尖冲动","心前区触及震颤","心尖部听到舒张期杂音","心尖部听到3/6级收缩期杂音","胸骨左缘2肋间听到连续性杂音"],"a":3,"e":"心前区震颤、抬举性心尖搏动、舒张期杂音及连续性杂音均提示器质性心脏病；心尖部3/6级收缩期杂音可为发热、贫血等高动力状态下的功能性杂音。"},{"q":"Austin-Flint杂音为何种杂音","o":["相对性三尖瓣关闭不全杂音","器质性主动脉瓣狭窄杂音","相对性二尖瓣狭窄杂音","器质性肺动脉瓣狭窄杂音","功能性二尖瓣关闭不全杂音"],"a":2,"e":"Austin-Flint杂音由中重度主动脉瓣关闭不全时反流血液限制二尖瓣开放，形成相对性二尖瓣狭窄所致，呈柔和递减型舒张中晚期杂音，无震颤和开瓣音。"},{"q":"毛细血管搏动征最常见于","o":["主动脉瓣关闭不全","主动脉瓣狭窄","肺动脉瓣狭窄","肺动脉瓣关闭不全","二尖瓣狭窄"],"a":0,"e":"毛细血管搏动征见于脉压明显增大的疾病，以主动脉瓣关闭不全最典型，也可见于甲状腺功能亢进、严重贫血和动脉硬化；主动脉瓣狭窄脉压减小。"},{"q":"下列对肺下界的体表位置描述正确的是","o":["锁骨中线第5肋间隙，腋中线第7肋间隙","锁骨中线第5肋间隙，腋中线第8肋间隙","锁骨中线第6肋间隙，腋中线第7肋间隙","锁骨中线第6肋间隙，腋中线第8肋间隙","锁骨中线第6肋间隙，腋中线第9肋间隙"],"a":3,"e":"平静呼吸时肺下界位于锁骨中线第6肋间隙、腋中线第8肋间隙、肩胛线第10肋间隙，两侧大致相同，深吸气时下移约2cm。"},{"q":"诊断过程中，进一步检查的选择原则，下列错误的是","o":["首先考虑可能性小的诊断","首先考虑简易的诊断方法","首先考虑对患者无创的检查","首先考虑证实诊断的措施","首先考虑可能性大的诊断"],"a":0,"e":"进一步检查应首先考虑可能性大的诊断、无创、简易、经济并能证实或排除诊断的方法，从概率最高的疾病入手，而不是优先考虑可能性小的诊断。"},{"q":"腹部叩诊鼓音，可出现于","o":["穿透性溃疡","不完全肠梗阻","大量腹水","巨大卵巢囊肿","胃肠穿孔"],"a":4,"e":"胃肠穿孔后游离气体聚积于膈下，肝浊音界缩小或消失，腹部鼓音范围明显增大；大量腹水和巨大卵巢囊肿叩诊呈浊音。"},{"q":"下列情况凝血酶凝固时间延长，但应除外","o":["严重肝脏病","弥散性血管内凝血","血友病","纤维蛋白原少","AT-Ⅲ活性增高"],"a":2,"e":"凝血酶凝固时间反映纤维蛋白原转变为纤维蛋白的过程，严重肝病、DIC、纤维蛋白原减少及AT-Ⅲ活性增高时延长；血友病为因子Ⅷ、Ⅸ缺乏，TT正常。"},{"q":"水肿患者，下列伴随症状中考虑心源性可能性大的是","o":["颜面水肿","肝颈静脉反流征阳性","肝大","腹水","伴胸腔积液和肺部啰音"],"a":1,"e":"肝颈静脉回流征阳性提示右心衰竭，是心源性水肿的重要伴随体征；颜面水肿多见于肾源性，单纯肝大亦可见于肝源性水肿。"},{"q":"下列情况均可见中性粒细胞增多，除外","o":["高温或严寒","流感","化脓菌引起的感染","手术创伤","脾破裂"],"a":1,"e":"中性粒细胞增多见于化脓性感染、手术创伤、脾破裂、高温严寒及急性失血等；流感等病毒感染时白细胞总数及中性粒细胞常减少。"},{"q":"主动脉瓣关闭不全合并器质性二尖瓣狭窄时，最有诊断意义的心脏杂音是主动脉瓣区舒张期叹气样杂音加上","o":["肺动脉瓣第二心音亢进","心尖部第一心音亢进","二尖瓣开放拍击音","心尖部舒张期隆隆样杂音","心尖部Austin Flint杂音"],"a":3,"e":"主动脉瓣关闭不全产生的Austin-Flint杂音易与二尖瓣狭窄混淆，若同时闻及心尖部舒张期隆隆样杂音并伴S1亢进、开瓣音，则提示合并器质性二尖瓣狭窄。"},{"q":"下列关于左室舒张早期奔马律的叙述均正确，但应除外","o":["见于器质性心脏病病人","心率常大于100次/min","体位改变时可消失","声音较响，距S2较远","听诊心尖部最清楚"],"a":2,"e":"舒张早期奔马律见于严重器质性心脏病，心率多在100次/分以上，音调低、距S2较远，心尖部最清楚，不随体位改变而消失；坐位消失是生理性S3的特点。"},{"q":"缺铁性贫血与铁粒幼细胞贫血的鉴别要点是","o":["血清总铁结合力","骨髓铁染色","红细胞内游离原卟啉测定","血清铁","MCV、MCH、MCHC测定"],"a":1,"e":"缺铁性贫血骨髓细胞外铁消失、铁粒幼细胞明显减少；铁粒幼细胞贫血细胞外铁增加并出现环形铁粒幼细胞，骨髓铁染色是二者鉴别的关键。"},{"q":"呼吸浅快不易见于","o":["呼吸肌麻痹","严重鼓肠","腹水","肺炎","镇静剂过量"],"a":3,"e":"官方答案为【肺炎】，但依据教材，正确答案为【镇静剂过量】。镇静剂过量抑制呼吸中枢，表现为呼吸浅慢；肺炎、胸膜炎、胸腔积液、腹水及呼吸肌麻痹均可致呼吸浅快。"},{"q":"免疫性溶血性贫血首选的筛选试验是","o":["Rous试验","Ham试验","Coombs试验","Heinz小体检查","网织红细胞测定"],"a":2,"e":"抗人球蛋白试验即Coombs试验，检测红细胞表面或血清中的不完全抗体，直接试验阳性提示自身免疫性溶血性贫血，是免疫性溶血性贫血的首选筛选试验。"},{"q":"直肠指检一般能够发现直肠癌总数的","o":["40%～49%","50%～59%","60%～69%","70%～79%","80%～89%"],"a":3,"e":"直肠癌多位于直肠中下段，直肠指检可触及质地坚硬、表面不平的肿块，约70%～79%的直肠癌可经指检发现，是简单而重要的检查方法。"},{"q":"血尿伴尿频、尿急、尿痛，最常见于","o":["急性膀胱炎","肾肿瘤","神经源性膀胱","丝虫病","多囊肾"],"a":0,"e":"血尿伴尿频、尿急、尿痛提示病变位于膀胱或尿道，最常见于急性膀胱炎；肾肿瘤、多囊肾多为无痛性血尿，神经源性膀胱无炎性细胞。"},{"q":"下列触诊肝脏的方法不正确的是","o":["检查者右手中间三指并拢，掌指关节弯曲","被检查者深呼气时，检查者手指压向深部触诊肝脏","被检查者深吸气时，检查者手指向前上触诊肝缘","检查者左手托住被检查者右腰部，拇指置于肋部","有腹水者可应用浮沉触诊法（冲击触诊法）"],"a":0,"e":"触诊肝脏时右手四指应并拢、掌指关节伸直，与肋缘大致平行放置，随呼气向深部按压、吸气时向上迎触肝缘；掌指关节弯曲属叩诊或冲击触诊的手法。"},{"q":"血清钙的正常参考值为","o":["0.97～1.61mmol/L","1.29～1.94mmol/L","2.25～2.75mmol/L","3.9～5.6mmol/L","9.0～11.0mmol/L"],"a":2,"e":"血清总钙参考值为2.25～2.75mmol/L，离子钙为1.10～1.34mmol/L；低于2.25mmol/L为低钙血症，超过2.58mmol/L为高钙血症。"},{"q":"下列各项是医生用视诊方法了解患者身体局部改变的内容，但不包括哪一项","o":["皮肤","黏膜","舌苔","湿度","毛发"],"a":3,"e":"视诊可了解皮肤、黏膜、舌苔、毛发及胸廓、关节外形等局部改变；湿度需通过触诊感知，属触诊内容。"},{"q":"生长发育成熟前腺垂体功能减退可导致","o":["生长激素缺乏性侏儒症","巨人症","呆小病","佝偻病","阉人症"],"a":0,"e":"青春期前腺垂体功能减退使生长激素分泌不足，骨骺闭合前生长受阻，导致垂体性侏儒症，身材匀称矮小；功能亢进则引起巨人症。"},{"q":"急性肾盂肾炎所致腰背痛的特点不包括","o":["伴肾区叩痛","尿检异常","伴有尿频尿急","常伴腰部、腹股沟区绞痛感","伴有高热、寒战等全身中毒症状"],"a":3,"e":"急性肾盂肾炎所致腰痛伴肾区叩痛、尿检异常、尿频尿急及高热寒战等全身中毒症状；腰部向腹股沟放射的绞痛是肾绞痛即结石的特点。"},{"q":"核左移是指外周血中中性粒细胞","o":["细胞体积变小","细胞核偏位，常常位于左侧","分叶超过5叶以上者超过3%","杆状核粒细胞增多或（和）出现更早阶段的粒细胞","细胞数明显增高"],"a":3,"e":"核左移指外周血非分叶核中性粒细胞包括杆状核、晚幼粒、中幼粒甚至早幼粒的百分率超过5%，提示骨髓贮备释放增加，见于急性感染和类白血病反应。"},{"q":"二尖瓣脱垂综合征是指","o":["收缩中期喀喇音合并收缩晚期杂音","收缩晚期喀喇音合并收缩中期杂音","收缩早期喀喇音合并收缩中期杂音","收缩晚期喀喇音合并收缩早期杂音","收缩中期喀喇音合并收缩早期杂音"],"a":0,"e":"二尖瓣脱垂时瓣叶在收缩中晚期脱入左房，腱索突然拉紧产生收缩中期喀喇音，并因瓣膜关闭不全出现收缩晚期杂音，二者并存即二尖瓣脱垂综合征。"},{"q":"下列为瞳孔的调节反射检查法，哪项不正确","o":["置右手示指于病人视线1m以外处为目标","嘱病人平视1m以外的目标","右手示指慢慢移近病人眼球约20cm处","右手示指迅速移近病人眼球约20cm处","观察病人的瞳孔是否逐渐缩小"],"a":2,"e":"集合反射需将目标由1m以外逐渐移近至距眼球5～10cm，正常可见双眼内聚、瞳孔缩小；20cm处尚未达到检查终点，不能作为规范的操作方法。"},{"q":"在心脏杂音产生的主要机制中，应除外哪一项","o":["血流加速","血液黏稠度下降","瓣膜口狭窄或关闭不全","人工瓣膜","心腔内漂浮物"],"a":3,"e":"杂音源于血流由层流转为湍流，血流加速、黏滞度降低、瓣膜狭窄或关闭不全、心腔漂浮物及大血管扩张均可产生；人工瓣膜属医源性额外心音，不属杂音形成机制。"},{"q":"尿内尿胆原明显增高是","o":["梗阻性黄疸","肝细胞性黄疸","溶血性黄疸","红细胞寿命正常","体内胆红素生成正常且胆管通畅"],"a":2,"e":"溶血时红细胞大量破坏，非结合胆红素生成增多，经肠肝循环生成的尿胆原随之明显增加，尿胆原强阳性是溶血性黄疸的典型改变；肝细胞性黄疸多为正常或轻度增加。"},{"q":"伤寒的特征性皮疹是","o":["斑疹","玫瑰疹","丘疹","斑丘疹","荨麻疹"],"a":1,"e":"玫瑰疹为直径2～3mm的鲜红色圆形斑疹，拉紧皮肤或按压可消退、松开复现，多分布于胸腹部，是伤寒和副伤寒的特征性皮疹。"},{"q":"下列各项均可出现肝浊音界缩小，但除外","o":["右心功能不全","胃肠穿孔","暴发性肝衰竭","暴发肝炎","肝硬化"],"a":0,"e":"右心功能不全引起肝淤血肿大，肝浊音界反而扩大；胃肠穿孔致膈下积气、暴发性肝衰竭和肝硬化使肝体积缩小，均表现为肝浊音界缩小或消失。"},{"q":"低血压的定义为血压低于","o":["90/60mmHg","100/60mmHg","90/50mmHg","80/60mmHg","100/50mmHg"],"a":0,"e":"成人肱动脉血压低于90/60mmHg称低血压；高血压的诊断界值为非同日3次测量收缩压≥140mmHg和/或舒张压≥90mmHg，二者共同构成血压水平的判断标准。"},{"q":"关于成人尿量，下列说法错误的是","o":["24h尿量大于2000ml称为多尿","24h尿量少于400ml称为少尿","24h尿量少于100ml称为无尿","每小时尿量少于17ml称为少尿","正常尿量为每天1000～2000ml"],"a":0,"e":"成人24小时尿量大于2500ml才称多尿，1000～2000ml为正常尿量；少于400ml或每小时少于17ml为少尿，少于100ml为无尿。"},{"q":"下列缓冲对中哪一对的pH不是7、4","o":["[HCO3－]/[H2CO3]为2mol/L/0.1mol/L","[HCO3－]/[H2CO3]为1mol/L/0.05mol/L","[HPO42－]/[H2PO4-]为2mol/L/0.5mol/L","[HPO42－]/[H2PO4-]为1mol/L0.25mol/L","[HCO3－]/[H2CO3]为1mol/L/0.04mol/L"],"a":4,"e":"按Henderson-Hasselbalch方程，[HCO3⁻]/[H2CO3]为20/1时血浆pH为7.4；1/0.04的比值为25，代入后pH约为7.5，故该缓冲对不能维持pH 7.4。"},{"q":"下列是构成心脏左界的成分，但应除外","o":["主动脉结","肺动脉段","升主动脉根部","左心房","左心室"],"a":2,"e":"心脏左界自第2肋间起由主动脉结、肺动脉段、左心耳和左心室构成；升主动脉根部位于胸骨右缘，构成心右界而非左界。"},{"q":"中输尿管点的位置是在","o":["髂前上棘水平腹直肌外缘","脐水平线上腹直肌外缘","腹直肌外缘与肋弓交点","右侧位置稍低相当于肾盂位置","相当于输尿管第一狭窄处"],"a":0,"e":"中输尿管点位于髂前上棘水平腹直肌外缘，相当于输尿管第二狭窄处，是输尿管结石的压痛点；肋弓与腹直肌外缘交点则为胆囊点。"},{"q":"下消化道内镜检查的并发症不包括","o":["术后发热","肠穿孔","肠出血","肠系膜裂伤","心脑血管意外"],"a":0,"e":"下消化道内镜的并发症主要有肠穿孔、肠出血、肠系膜裂伤及心脑血管意外；术后发热多见于肺活检等操作后继发感染，不列入结肠镜的常见并发症。"},{"q":"下列各项为真性内脏痛，但应除外","o":["钝痛","酸痛","烧灼痛","刺痛","绞痛"],"a":2,"e":"真性内脏痛由内脏器官受牵拉、痉挛、缺血及炎症刺激引起，定位不确切，性质多为钝痛、酸痛、绞痛，对切割、烧灼等刺激不敏感，故烧灼痛不属典型表现。"},{"q":"下列各项均是肝脏检查内容，但除外","o":["肝下缘位置","质地","表面","搏动","Mc Burney点压痛"],"a":4,"e":"肝脏触诊应描述肝下缘位置、质地、表面与边缘、压痛及搏动等；McBurney点压痛是急性阑尾炎的体征，属腹部压痛检查内容。"},{"q":"腹部检查时发现胆囊肿大，无压痛，但伴有皮肤巩膜明显黄染，首先考虑的病变是","o":["胰头癌","胰体癌","急性胆囊炎","急性胆管炎","急性黄疸性肝炎"],"a":0,"e":"无压痛性胆囊肿大伴进行性加深的黄疸即库瓦西耶征阳性，提示胰头癌压迫胆总管致胆道梗阻；急性胆囊炎、急性胆管炎均有明显右上腹压痛和感染表现。"},{"q":"S1强弱不等可见于下列情况，但除外","o":["窦性心动过速","室性心动过速","心房颤动","频发期前收缩","三度房室传导阻滞"],"a":0,"e":"S1强弱不等见于心房颤动、频发期前收缩和三度房室传导阻滞；窦性心动过速时心室充盈及房室瓣位置相对恒定，S1强度一致。"},{"q":"有关诊断思维的基本原则，不正确的是","o":["首先考虑常见病与多发病","应当考虑当地流行和发生的传染病与地方病","首先应考虑器质性疾病","首先应考虑可治性疾病","尽量考虑少发病的常见表现而不是常见疾病的特别表现"],"a":4,"e":"诊断思维要求首先考虑常见病、多发病、器质性疾病和可治性疾病，并警惕当地流行的传染病与地方病；应以常见病的典型或特别表现解释病情，而非少见病的常见表现。"},{"q":"反映肝硬化肝脏合成功能减退的指标是","o":["碱性磷酸酶","丙氨酸氨基转移酶","乳酸脱氢酶","白蛋白","γ谷氨酰转肽酶"],"a":3,"e":"白蛋白全部由肝细胞合成，肝硬化时功能性肝细胞减少使血清白蛋白降低，是反映肝脏合成功能减退的敏感指标；ALP、GGT主要反映胆汁淤积。"},{"q":"方肩最常见于","o":["肩关节脱位","先天性肩胛高耸症","脊柱侧弯","锁骨骨折","外伤性肩锁关节脱位"],"a":0,"e":"肩关节脱位后肱骨头脱出关节盂，肩峰突出、肩部弧形轮廓消失而呈方肩，三角肌萎缩亦可呈方肩；锁骨骨折表现为肩下垂，肩锁关节脱位呈肩章状。"},{"q":"抗凝血酶Ⅲ活性增高见于","o":["妊娠","新生儿","弥散性血管内凝血","血友病","脑梗死"],"a":3,"e":"抗凝血酶Ⅲ活性增高见于血友病、白血病及再生障碍性贫血的急性出血期，也见于口服抗凝药治疗；DIC、血栓性疾病及肝病时其活性减低。"},{"q":"代谢性酸中毒时","o":["NaHCO3/H2CO3＜20/1，继发性H2CO3↑","NaHCO3/H2CO3＞20/1，继发性H2CO3↑","NaHCO3/H2CO3＜20/1，继发性H2CO3↓","NaHCO3/H2CO3＞20/1，继发性H2CO3↓","NaHCO3/H2CO3＜10/1，继发性H2CO3↓"],"a":2,"e":"代谢性酸中毒时HCO3⁻原发性减少，[HCO3⁻]/[H2CO3]小于20/1；机体经肺代偿使H2CO3继发性降低，PaCO2下降。"},{"q":"发热激活物又称EP诱导物，包括","o":["IL-1和TNF","CRH和NOS","内生致热原和某些体外代谢产物","前列腺素和其体内代谢产物","外致热原和某些体内产物"],"a":4,"e":"发热激活物又称EP诱导物，包括外致热原和某些体内产物，作用于产EP细胞使其释放内生致热原；IL-1与TNF本身属内生致热原。"},{"q":"有关病历书写不正确的是","o":["首次病程由经管的住院医师书写","病程记录一般可2～3天记录1次","危重病人需每天或随时记录","会诊意见应记录在病历中","不需要记录各项检查结果及分析意见"],"a":4,"e":"病程记录须记录重要辅助检查结果及其临床意义并加以分析判断，作为调整诊疗的依据；首次病程由住院医师书写，危重病人随时记录。"},{"q":"关于尿胆红素测定，下列叙述正确的是","o":["正常可出现阳性反应","肝细胞黄疸时，尿胆红素中度增加","梗阻性黄疸时，尿胆红素阴性","溶血性黄疸时，尿胆红素明显增加","严重肾损伤时，尿胆红素明显增加"],"a":1,"e":"肝细胞性黄疸时肝细胞摄取、结合及排泄胆红素均障碍，结合胆红素反流入血，尿胆红素呈阳性且程度中等；梗阻性黄疸为强阳性，溶血性黄疸为阴性。"},{"q":"下列左心衰竭时呼吸困难的描述，错误的是","o":["主要是体循环淤血所致","可出现阵发性呼吸困难","多在夜间睡眠时发生","重者气喘、出汗、有哮鸣音","重者两肺底部有湿啰音"],"a":0,"e":"左心衰竭呼吸困难由肺淤血致弥散障碍、肺泡张力增高、肺泡弹性减退及肺循环压力升高引起；体循环淤血是右心衰竭的机制，归属错误。"},{"q":"全腹肌紧张触之如板状腹，见于","o":["急性弥漫性腹膜炎","急性胆囊炎","急性肠炎","急性胃炎","结核性腹膜炎"],"a":0,"e":"急性胃肠穿孔或脏器破裂致急性弥漫性腹膜炎时，腹膜受强烈刺激引起腹肌反射性痉挛，腹壁强直硬如木板，称板状腹；结核性腹膜炎多呈柔韧感。"},{"q":"心电图ST段抬高出现于心肌梗死的","o":["超级损伤期","急性期","亚急性期","陈旧期","全程"],"a":1,"e":"急性期梗死灶周围心肌严重损伤，ST段呈弓背向上抬高并与T波融合；超急性期以高大T波为主，亚急性期ST段回落伴T波倒置，陈旧期仅遗留病理性Q波。"},{"q":"心电图V1、V2导联R波≥0.04秒和R/S≥1且T波正向，提示心肌梗死部位为","o":["前壁","侧壁","广泛前壁","下壁","后壁"],"a":4,"e":"正后壁心肌梗死时V7～V9出现异常Q波，与之相对的V1、V2导联呈镜像改变，即R波增高增宽、R/S≥1、ST段压低及T波高尖正向。"},{"q":"增生性脊柱炎的腰背痛特点不正确的是","o":["多见于50岁以上的患者","晨起感腰痛，酸胀、僵直","过多活动后腰痛减轻","疼痛以傍晚明显","腰椎无明显压痛"],"a":2,"e":"增生性脊柱炎多于50岁后发病，晨起腰部酸胀僵直，稍活动后减轻，但过多活动又使疼痛加重，傍晚最明显，叩击腰部反有舒适感。"},{"q":"检查抗核抗体常用方法是","o":["直接荧光抗体试验","间接荧光抗体试验","胶乳凝集试验","ELISA法","免疫比浊法"],"a":1,"e":"抗核抗体以HEp-2细胞或猴肝为抗原基质，用间接免疫荧光法检测，可同时报告滴度与荧光核型，敏感性高，是筛查结缔组织病的首选方法。"},{"q":"书写日常病程记录时，对病情稳定的患者，至少（ ）天记录一次病程记录","o":["1","2","3","4","5"],"a":2,"e":"病情稳定的病人至少3天书写一次病程记录；病重者至少2天一次，病危者每天至少一次且记录时间具体到分钟。"},{"q":"反映远曲小管和集合管功能的试验是","o":["浓缩稀释试验","PSP排泄试验","血肌酐尿素测定","内生肌酐清除率","同位素肾图"],"a":0,"e":"昼夜尿比密试验通过测定尿量与尿比密，反映远端肾小管和集合管的稀释与浓缩功能；内生肌酐清除率则反映肾小球滤过功能。"},{"q":"气管移向患侧的疾病是","o":["肺实变","肺气肿","胸腔积液","气胸","胸膜粘连"],"a":4,"e":"胸膜粘连、增厚及肺不张使患侧胸膜腔压力降低，纵隔与气管被牵拉移向患侧；胸腔积液、气胸使气管移向健侧，肺实变时气管居中。"},{"q":"下列哪种情况导致QT间期延长的可能最小","o":["服用西沙比利","服用阿奇霉素","血钾2.8mmol/L","血钠160mmol/L","伊布利特复律治疗"],"a":3,"e":"低血钾、低血钙及西沙比利、阿奇霉素、伊布利特等药物均可延长QT间期；血钠升高不直接影响心室复极，与QT间期延长关系最小。"},{"q":"关于肾脏正常位置，正确的是","o":["肾上极相当于第10胸椎","肾下极相当于第4腰椎","肾门对第12胸椎平面","在后腹膜前","右肾较左肾约低1～2cm"],"a":4,"e":"右肾受肝右叶推移，位置较左肾低约1～2cm；肾门约平第1腰椎，左肾上极平第11胸椎、下极平第2腰椎，双肾均位于腹膜后。"},{"q":"35岁男性，腹痛半个月，既往史应关注的问题，除外","o":["有无肝炎病史","有无胆囊炎病史","有无腹部手术史","有无过敏史","有无恶心、呕吐史"],"a":4,"e":"既往史应询问与腹痛有关的肝炎、胆囊炎、腹部手术及药物过敏史；恶心、呕吐属本次腹痛的伴随症状，应记入现病史。"},{"q":"不常见腕关节变形的疾病是","o":["尺神经损伤","强直性脊柱","骨折","腱鞘囊肿","桡神经损伤"],"a":1,"e":"强直性脊柱炎主要累及脊柱和骶髂关节，表现为脊柱强直、胸段后凸，不引起腕关节变形；尺神经、桡神经损伤及骨折、腱鞘囊肿均可致腕部畸形。"},{"q":"低热的体温在","o":["37.2～38℃","37.3～38℃","37.3～38、1℃","37.2～38、1℃","37.1～38℃"],"a":1,"e":"以口腔温度为标准，37.3～38℃为低热，38.1～39℃为中等度热，39.1～41℃为高热，41℃以上为超高热。"},{"q":"二尖瓣狭窄第一心音亢进是因为","o":["心脏开始收缩时，二尖瓣前叶处于最低位置","心脏开始收缩时，二尖瓣后叶关闭延迟","心脏收缩力加强","二尖瓣前叶增厚","乳头肌功能失调"],"a":0,"e":"二尖瓣狭窄使心室充盈减少，收缩开始时二尖瓣前叶低垂，关闭时瓣叶振动幅度大，且左室内压上升加速，故S1亢进；瓣叶钙化僵硬时S1反而减弱。"},{"q":"下列心音均属于舒张期额外心音，但除外","o":["肿瘤扑落音","开瓣音","奔马律","肺动脉喷射音","四音律"],"a":3,"e":"肺动脉喷射音发生于收缩早期、紧接S1后出现，属收缩期额外心音；开瓣音、肿瘤扑落音及各类奔马律均出现在舒张期。"},{"q":"主动脉瓣听诊区第二心音增强，最常见于","o":["二尖瓣狭窄","二尖瓣关闭不全","高血压","左心功能不全","主动脉瓣关闭不全"],"a":2,"e":"主动脉瓣区第二心音由主动脉瓣关闭产生，其强度取决于主动脉内压力；高血压时主动脉压升高、瓣膜关闭振动增强，故A2亢进最为常见。"},{"q":"下列体征适用于深部触诊法检查，除了","o":["胆囊点压痛","乙状结肠包块","板状腹","大量腹水时的肝脏冲击触诊","阑尾点反跳痛"],"a":2,"e":"板状腹由腹肌强直所致，经视诊和浅部触诊即可判定；胆囊点压痛、阑尾点反跳痛、乙状结肠包块及大量腹水时的肝脏冲击触诊均需深部触诊。"},{"q":"不含血红素的物质是","o":["肌红蛋白","铜蓝蛋白","血红蛋白","细胞色素酶","过氧化物酶"],"a":1,"e":"铜蓝蛋白为含铜的α2球蛋白，不含血红素；肌红蛋白、血红蛋白、细胞色素酶和过氧化物酶均以血红素为辅基。"},{"q":"Kussmaul呼吸是指","o":["剧烈运动，呼吸深快","酮症酸中毒深长呼吸","呼吸衰竭潮式呼吸","巴比妥中毒间停呼吸","忧郁叹息样呼吸"],"a":1,"e":"Kussmaul呼吸指严重代谢性酸中毒时出现的深长而规则的呼吸，见于糖尿病酮症酸中毒和尿毒症酸中毒，是肺排出CO2进行代偿的表现。"},{"q":"图像中的ECG诊断不考虑下列哪一项","o":["一度房室传导阻滞","病理性Q波","频发室性期前收缩","多源性室性期前收缩","急性心肌梗死"],"a":4,"e":"官方题库缺失图片"},{"q":"关于肺前界的叩诊，正确的是","o":["正常肺前界相当于心的相对浊音界","右肺前界相当于胸骨旁2cm的位置","左肺前界相当于胸骨线第4～6肋间隙位置","心脏扩大时，左右两肺前界间浊音区扩大","肺气肿时，左右两肺前界间浊音区扩大"],"a":3,"e":"正常肺前界相当于心脏绝对浊音界，右肺前界在胸骨线，左肺前界在胸骨旁线第4～6肋间；心脏扩大、心包积液时两侧肺前界间浊音区扩大，肺气肿时缩小。"},{"q":"杂音最响的部位，主要取决于","o":["瓣膜的解剖位置及其在体表投影的一致性","瓣膜损害的程度","杂音产生的部位及血流方向","呼吸的影响","体位的改变"],"a":2,"e":"杂音最响部位取决于杂音产生的部位及血流方向，即病变瓣膜或异常通道所在处和血流冲击的方向；瓣膜损害程度影响响度而不决定部位。"},{"q":"心脏叩诊时卧位时较立位时心底部浊音区增宽，常见于","o":["全心衰竭","心肌病","心包积液","心肌炎","上纵隔肿物"],"a":2,"e":"心包积液时液体随体位流动，卧位聚于心底部使该处浊音区增宽，坐位时心界呈烧瓶样；全心衰竭、心肌病等不随体位出现此种改变。"},{"q":"下腔静脉阻塞时，腹壁静脉的血流方向是","o":["脐以上，静脉血流自下向上","脐以上，静脉血流自上向下","脐以下，静脉血流自上向下","脐上、下，静脉血流自下向上","脐上、下，静脉血流自上向下"],"a":3,"e":"下腔静脉阻塞时，脐上、脐下腹壁静脉均经交通支向上经胸壁静脉回流，血流方向自下而上；上腔静脉阻塞时脐以上血流自上而下。"},{"q":"患者，男，38岁，超声心动图显示二尖瓣脱垂。查体可发现","o":["收缩早期喀喇音","开瓣音","收缩前期奔马律","收缩中晚期喀喇音","舒张中晚期喀喇音"],"a":3,"e":"二尖瓣脱垂时瓣叶在收缩中晚期脱入左房，腱索突然拉紧产生收缩中晚期喀喇音，常伴收缩晚期杂音，合称二尖瓣脱垂综合征。"},{"q":"合成补体的主要细胞是","o":["骨髓细胞和胸腺细胞","骨髓细胞和B细胞","胸腺细胞和B细胞","T细胞和B细胞","肝细胞、巨噬细胞"],"a":4,"e":"补体主要由肝细胞和巨噬细胞合成，肝细胞产生C3、C4、C9等主要成分；骨髓细胞、T细胞与B细胞并非补体的主要来源。"},{"q":"下列均为胆囊肿大的体征，除外","o":["右上腹压痛","梨形或圆形肿物","随呼吸移动","自左向右蠕动","囊性感"],"a":3,"e":"胆囊肿大时右上腹可触及随呼吸上下移动的梨形或圆形囊性肿物，伴压痛；自左向右蠕动是胃蠕动波的特征，与胆囊无关。"},{"q":"正常人的血钾浓度（mmol/L）为","o":["3","5","6","7","7.5"],"a":1,"e":"血钾参考区间为3.5～5.5mmol/L，所列数值中5mmol/L处于正常范围；低于3.5mmol/L为低钾血症，高于5.5mmol/L为高钾血症。"},{"q":"关于心前区震颤的叙述，下列哪项是正确的","o":["狭窄越重，杂音越强","有震颤则肯定有器质性心脏病","一般情况下，震颤的强弱与血流速度成反比","震颤是视诊时看到的一种细小振动","只有瓣膜口狭窄才产生震颤"],"a":1,"e":"触及震颤提示存在器质性心血管病变，多见于瓣膜狭窄和室间隔缺损；震颤强弱与血流速度成正比，狭窄极重致血流明显减少时震颤反可减弱。"},{"q":"诊断肝纤维化最有意义的指标是","o":["MAO（单胺氧化酶）","GGT","ALT","AFP","ALP"],"a":0,"e":"单胺氧化酶来自肝线粒体，血清MAO升高与肝纤维组织增生相关，是反映肝纤维化程度的指标；ALT、GGT、ALP、AFP分别反映肝细胞损伤、胆汁淤积与肝癌。"},{"q":"对多话与唠叨的患者","o":["适当的鼓励患者讲出其感受","应采取坦然、理解、不卑不亢的态度","分次进行告知，告诉患者问诊的内容及时间限制","语言通俗易懂，注意必要的重复","由家长代述"],"a":2,"e":"对多话唠叨者应有礼貌地限定问诊范围，分次进行问诊并告知问诊内容与时间限制，避免表现不耐烦而失去病人信任。"},{"q":"某些典型症状的鉴别诊断可利用诊断流程图，这属于哪种临床思维方式","o":["演绎推理","归纳推理","类比推理","模式识别","横向列举"],"a":0,"e":"诊断流程图将鉴别诊断提纲按逻辑树逐层二分，由一般原理推论个别病例，属演绎推理；归纳推理则从个别资料概括出共性结论。"},{"q":"中度昏迷与深度昏迷最有价值的鉴别是","o":["对各种刺激均无反应","眼球无转动","大小便失禁","肌张力增高","深浅反射均消失"],"a":4,"e":"中度昏迷对强烈刺激仍有反应、角膜反射减弱而深反射存在；深度昏迷时深浅反射均消失，是两者最有价值的鉴别点。"},{"q":"关于第一心音的正确叙述中，应除外","o":["标志着心室收缩的开始","房室瓣突然关闭瓣叶突然紧张引起的振动","第一心音与心尖冲动同时出现","半月瓣突然关闭引起瓣膜振动","第一心音在心尖部听诊最清楚"],"a":3,"e":"第一心音由二尖瓣和三尖瓣关闭、瓣叶突然紧张振动产生，标志心室收缩开始，与心尖搏动同时出现，心尖部最响；半月瓣关闭形成第二心音。"},{"q":"下列疾病脉压减低的是","o":["严重贫血","甲状腺功能亢进症","主动脉瓣关闭不全","缩窄性心包炎","动脉导管未闭"],"a":3,"e":"缩窄性心包炎因心脏舒张受限、每搏输出量减少而使脉压变小；贫血、甲亢、主动脉瓣关闭不全及动脉导管未闭均使脉压增大。"},{"q":"水冲脉最常见于下列何种疾病","o":["甲状腺功能亢进症","贫血","高热","主动脉瓣关闭不全","主动脉瓣狭窄"],"a":3,"e":"水冲脉由收缩压升高、舒张压降低致脉压增大，脉搏骤起骤落，最常见于主动脉瓣关闭不全；甲亢、贫血亦可出现但程度较轻。"},{"q":"下列哪项是收缩期额外心音","o":["奔马律","开瓣音","喀喇音","心包叩击音","肿瘤扑落音"],"a":2,"e":"喀喇音发生于收缩早期或收缩中晚期，属收缩期额外心音；奔马律、开瓣音、心包叩击音及肿瘤扑落音均位于舒张期。"},{"q":"细胞内液的主要阳离子是","o":["Na＋","Mg2＋","K＋","Ca2＋","Mn2＋"],"a":2,"e":"钾是细胞内液的主要阳离子，约98%分布于细胞内；钠为细胞外液的主要阳离子，二者共同维持细胞内外渗透压与静息膜电位。"},{"q":"一患者以斜颈、垂肩来诊，查双肩抬肩动作减弱。此见于","o":["舌咽神经损伤","前庭神经损伤","迷走神经损伤","副神经损伤","面神经损伤"],"a":3,"e":"副神经支配胸锁乳突肌和斜方肌，一侧损伤时该侧耸肩无力、肩下垂、头不能转向对侧，出现斜颈与垂肩。"},{"q":"下列哪项不是手术同意书包含的内容","o":["术前诊断","上级医师查房意见","术中或术后可能出现的并发症、手术风险","手术名称","患者签署意见并签名"],"a":1,"e":"手术同意书包括术前诊断、手术名称、术中术后可能出现的并发症与手术风险及患者签署意见并签名；上级医师查房意见属病程记录内容。"},{"q":"腹部胀大在耻骨上方叩诊出现弧形上缘凹向脐部的浊音区，应见的病征是","o":["尿潴留","腹水","妊娠子宫","子宫肌瘤","卵巢囊肿"],"a":1,"e":"腹腔积液时液体沉于腹腔低位，耻骨上方叩诊浊音区上缘凹向脐部；膀胱尿潴留所致浊音区上缘凸向脐部，排尿或导尿后转为鼓音即可鉴别。"},{"q":"有关叩诊方法的叙述，下列错误的是","o":["叩诊胸部时可取坐位或卧位","叩诊腹部时常取仰卧位","确定有无腹水或腹水量很少时，可嘱患者取肘膝位","一般叩诊可达到的深度约为2～3cm","有直接叩诊法和间接叩诊法两种"],"a":3,"e":"叩诊一般可达到5～7cm深度，并非2～3cm；叩诊胸部可取坐位或卧位，腹部多取仰卧位，少量腹水可嘱病人取肘膝位检查。"},{"q":"病原菌侵入血流并在其中大量繁殖，产生毒性代谢产物，引起严重的全身中毒症状，称为","o":["毒血症","败血症","菌血症","脓毒血症","内毒素血症"],"a":1,"e":"败血症指病原菌侵入血流并在其中大量繁殖、产生毒性代谢产物，引起严重全身中毒症状；仅短暂入血而无繁殖者称菌血症。"},{"q":"下列血浆离子浓度的变化能帮助诊断代谢性碱中毒的是","o":["[HCO3－]升高，伴有[K＋]下降，[Cl－]相对下降","[HCO3－]升高，伴有[K＋]升高，[Cl－]相对下降","[HCO3－]升高，伴有[K＋]下降，[Cl－]相对升高","[HCO3－]下降，伴有[K＋]升高，[Cl－]相对升高","[HCO3－]下降，伴有[K＋]下降，[Cl－]相对下降"],"a":0,"e":"代谢性碱中毒时HCO3⁻原发性升高，常伴血钾降低和血氯相对降低；低氯低钾是代谢性碱中毒的常见原因。"},{"q":"正常成人粪便中的主要菌群是","o":["产气杆菌","变形杆菌","芽孢菌","大肠埃希氏菌","肠球菌"],"a":3,"e":"成人粪便中的主要菌群为大肠埃希菌、厌氧杆菌和肠球菌，婴儿以双歧杆菌和拟杆菌为主；产气肠杆菌、变形杆菌多为过路菌。"},{"q":"肝硬化门脉高压最突出的临床表现是","o":["食管-胃底静脉曲张","腹水","脾大","脐周及腹壁静脉曲张","脾功亢进"],"a":1,"e":"腹腔积液是失代偿期肝硬化门静脉高压最突出的临床表现，病人直立时下腹饱满、仰卧时腹部两侧膨隆呈蛙腹，提示预后不良。"},{"q":"常见总胆红素、结合胆红素和非结合胆红素均增高的疾病是","o":["溶血性贫血","胆道完全阻塞","胆道部分阻塞","肾脏功能障碍","肝细胞严重损伤"],"a":4,"e":"肝细胞严重损伤时摄取、结合及排泄胆红素均障碍，血中非结合胆红素与结合胆红素同时升高，故总胆红素及两种胆红素均增高。"},{"q":"在CH50检测中，灭活补体的温度和时间是","o":["37℃ 1h","50℃ 30min","56℃ 30min","56℃ 1h","60℃ 30min"],"a":2,"e":"补体不耐热，56℃加热30分钟即被灭活，故CH50检测前需以56℃30分钟处理血清以去除内源性补体干扰，同时保留其他待测成分。"},{"q":"血浆凝血酶原时间延长，见于","o":["血小板减少症","血小板无力症","血友病","严重肝病","因子Ⅻ缺乏"],"a":3,"e":"凝血酶原时间反映外源性凝血途径，严重肝病时凝血因子Ⅱ、Ⅴ、Ⅶ、Ⅹ合成减少，PT延长；血小板疾病、血友病及因子Ⅻ缺乏时PT正常。"},{"q":"下列哪种属于病理性多尿","o":["慢性肾炎水肿应用利尿剂后","静脉输入多量液体后","大量饮水后","慢性肾盂肾炎","慢性心衰水肿应用利尿剂后"],"a":3,"e":"慢性肾盂肾炎因肾间质受损、肾小管浓缩功能减退而出现病理性多尿；大量饮水、静脉输液及使用利尿剂后的多尿属生理性或药物性。"},{"q":"脊柱后凸成畸形一般不见于","o":["佝偻病","强直性脊柱炎","结核病","类风湿性关节炎","脊髓退行性变"],"a":3,"e":"脊柱后凸畸形见于佝偻病、脊柱结核、强直性脊柱炎及椎体退行性变；类风湿关节炎主要累及四肢小关节，不引起脊柱后凸。"},{"q":"胸骨右缘第2肋间触及收缩期震颤，最常见于","o":["主动脉瓣狭窄","主动脉瓣关闭不全","肺动脉瓣狭窄","肺动脉瓣关闭不全","动脉导管未闭"],"a":0,"e":"胸骨右缘第2肋间为主动脉瓣区，该处收缩期震颤提示主动脉瓣狭窄；肺动脉瓣狭窄的震颤位于胸骨左缘第2肋间，动脉导管未闭则为胸骨左缘第2肋间连续性震颤。"},{"q":"12对脑神经属于单纯感觉神经的有","o":["嗅神经、前庭蜗神经、视神经","动眼神经、面神经、迷走神经","视神经、舌下神经、迷走神经","视神经、舌下神经、舌咽神经","前庭蜗神经、三叉神经、迷走神经"],"a":0,"e":"十二对脑神经中纯感觉神经为嗅神经、视神经和前庭蜗神经；三叉、面、舌咽、迷走神经为混合神经，动眼、滑车、展、副及舌下神经属运动神经。"},{"q":"下述是问诊的方法，但应除外","o":["医生先与病人过渡性交谈","问诊一般先由主诉开始","问诊一般先由医生做些疾病的提示开始","问诊先由简易问题开始","问诊时医生的态度要诚恳友善"],"a":2,"e":"问诊应从主诉开始，先提简单易答的开放性问题，经过渡性交谈建立信任，态度诚恳友善；医生先做疾病提示属诱导性提问，应予避免。"},{"q":"使纤维蛋白降解为FDP的物质是","o":["因子Ⅻ","活化素","凝血酶","纤维蛋白单体","纤溶酶"],"a":4,"e":"纤溶酶降解纤维蛋白和纤维蛋白原，生成FDP及D-二聚体；凝血酶的作用是使纤维蛋白原转变为纤维蛋白单体，二者方向相反。"},{"q":"吸气性呼吸困难的典型体征为","o":["肋间隙增宽","呼吸动度减小","端坐呼吸","三凹征","发绀"],"a":3,"e":"上呼吸道梗阻时胸腔负压显著增大，出现胸骨上窝、锁骨上窝及肋间隙凹陷，即三凹征，是吸气性呼吸困难最典型的体征。"},{"q":"PR段反映心脏哪些结构的电活动","o":["心房除极和复极的过程","心房除极、复极过程及房室结电活动","心房复极过程及房室结、希氏束电活动","心房复极过程及房室结、希氏束、束支的电活动","心房除极、复极过程及房室结、希氏束、束支电活动"],"a":3,"e":"PR段反映心房复极过程及房室结、希氏束和束支的电活动；P波反映心房除极，QRS波反映心室除极，T波反映心室复极。"},{"q":"二尖瓣狭窄时，哪种体征提示可行球囊扩张术","o":["第一心音亢进","P2亢进","心尖区舒张期杂音有后期增强","二尖瓣开放拍击音","第一心音亢进及二尖瓣开放拍击音"],"a":4,"e":"第一心音亢进与开瓣音并存说明二尖瓣瓣叶弹性尚好、活动度佳且无明显钙化，是经皮球囊二尖瓣成形术的适应证；瓣叶僵硬钙化时开瓣音消失。"},{"q":"下列各项叩诊均能产生浊鼓音，但应除外","o":["肺不张","肺炎充血期","肺炎实变期","肺炎消散期","肺水肿"],"a":2,"e":"浊鼓音见于肺泡壁松弛、含气量减少而仍残存气体的病变，如肺不张、肺炎充血期与消散期、肺水肿；肺炎实变期肺泡充满渗出物，叩诊呈浊音或实音。"},{"q":"主动脉瓣关闭不全的舒张期杂音，最易听到的部位","o":["胸骨右缘第2肋间","胸骨左缘第2肋间","胸骨左缘第3、4肋间","心尖部","胸骨下端左、右缘"],"a":2,"e":"主动脉瓣关闭不全的舒张期叹气样杂音在主动脉瓣第二听诊区，即胸骨左缘第3、4肋间最清楚，前倾坐位、深呼气末更易闻及。"},{"q":"鉴别肝细胞性黄疸与梗阻性黄疸时，下列检查哪项是错误的","o":["尿胆红素","谷丙转氨酶","血清非结合胆红素定量","尿胆原","碱性磷酸酶"],"a":0,"e":"肝细胞性黄疸与梗阻性黄疸时尿胆红素均为阳性，不能据以鉴别；尿胆原、血清非结合胆红素定量及碱性磷酸酶、转氨酶的变化才具鉴别价值。"},{"q":"咳浆液性粉红色泡沫样痰的疾病是","o":["肺栓塞","急性肺水肿","白血病","粟粒样肺结核","重症肺炎"],"a":1,"e":"急性肺水肿时肺毛细血管压急剧升高，血浆与红细胞漏入肺泡并随气体搅拌，形成浆液性粉红色泡沫样痰，是急性左心衰竭的典型表现。"},{"q":"恶心时迷走神经兴奋常伴有下列症状，但除外","o":["皮肤苍白","出汗","血压降低","寒战","心动过缓"],"a":3,"e":"恶心时迷走神经兴奋可致皮肤苍白、出汗、流涎、血压降低和心动过缓；寒战是体温上升期骨骼肌节律性收缩产热的表现，与恶心无关。"},{"q":"下列为急性病容所见，但不包括","o":["面色潮红","兴奋不安","鼻翼翕动","面容憔悴","口唇疱疹"],"a":3,"e":"急性病容表现为面色潮红、兴奋不安、鼻翼扇动、口唇疱疹、表情痛苦，见于急性感染性疾病；面容憔悴属慢性病容。"},{"q":"病历书写的基本规则和要求不包括","o":["病历应当按照规定的内容书写，并有相应医务人员签名","病历要正规、真实、准确、完整，重点突出、层次分明","实习医师和毕业后第1年住院医师要书写住院病历和首次病程记录","住院病历最迟应于患者入院后24h内完成","书写应使用中文和医学术语"],"a":2,"e":"首次病程记录须由住院医师或值班医师书写，实习医师不得独立完成；住院病历可由实习医师书写但须经注册医师审阅签名，故该说法不符合规定。"},{"q":"下列均为腹部体表标志，但除外","o":["腹上角","髂前上棘","脊肋角","髂后上棘","腹中线"],"a":3,"e":"腹部体表标志包括腹上角、肋弓下缘、髂前上棘、腹中线及腹直肌外缘等；髂后上棘位于臀部，属腰骶部标志，不用于腹部体表定位。"},{"q":"张先生因为消化道出血在某医院第2次住院，入院后6小时死亡，住院医生应完成下列哪种病历记录","o":["再次入院记录","表格式入院病历","24小时内入院死亡记录","入院记录","死亡记录"],"a":2,"e":"病人入院不足24小时死亡应书写24小时内入院死亡记录，于死亡后24小时内完成，内容与24小时内入出院记录相同，仅将出院诊断改为死亡原因与死亡诊断。"},{"q":"室性期前收缩引起的心悸感觉是","o":["恐惧感","紧缩感","停跳感","压榨感","灼热感"],"a":2,"e":"期前收缩后有较长代偿间歇，使下一次心搏增强，病人感到心脏停顿或落空，即停跳感，是心律不齐引起心悸的典型描述。"},{"q":"叩诊肝脏的绝对浊音界，其叩诊音改变为","o":["清音→浊音","清音→实音","浊音→实音","浊音→清音","浊音→鼓音"],"a":2,"e":"肝绝对浊音界处肝直接贴附胸壁而未被肺遮盖，叩诊由清音转为浊音为相对浊音界，再向下1～2肋间浊音变为实音，即为绝对浊音界。"},{"q":"外源性致热原的特点，正确的是","o":["分子量小","致热性可被蛋白酶类水解","能激活血液中的中性粒细胞","直接作用体温调节中枢","在体内最终由肝、肾灭活和排泄"],"a":2,"e":"外源性致热原多为大分子物质，不能通过血脑屏障，而是激活血液中的中性粒细胞、嗜酸性粒细胞和单核巨噬细胞系统，使其释放内源性致热原。"},{"q":"类风湿因子测定最常用于","o":["类风湿性关节炎","系统性红斑狼疮（SLE）","硬皮病","皮肌炎","风湿性心脏病"],"a":0,"e":"类风湿因子是变性IgG刺激机体产生的自身抗体，主要存在于类风湿关节炎病人的血清和关节液中，是该病最重要且最常用的血清学指标。"},{"q":"下列各项均是用叩诊法确定肝上界的内容，但除外","o":["一般沿右锁骨中线叩","由肺区向腹部叩诊","用重叩诊法","当清音转浊音时为肝上界","肝上界称肝相对浊音界"],"a":2,"e":"确定肝上界沿右锁骨中线、右腋中线和右肩胛线由肺区向下叩，用力适当，清音转为浊音处即肝上界；重叩诊使振动范围过大，易掩盖界线的细微变化。"},{"q":"肾下垂的检体诊断标准是","o":["深呼气时触到1/2以上的肾","深吸气时触到1/2以上的肾","平静呼吸时触到1/2以上的肾","深呼气时触到肾下极","深吸气时触到肾下极"],"a":1,"e":"深吸气时能触到1/2以上的肾脏即为肾下垂；正常仅偶可触及右肾下极，瘦长体型者肾脏较易触及，需与肝、脾肿大鉴别。"},{"q":"下列舒张早期奔马律的特点，但应除外","o":["又称第三心音奔马律","也称室性奔马律","常出现在有严重器质性心脏病的病人","多在心率较快时出现","不受呼吸的影响"],"a":4,"e":"舒张早期奔马律受体位和呼吸影响，左室奔马律呼气时清楚、右室奔马律吸气时清楚，心率较快时明显，出现提示严重器质性心脏病。"},{"q":"下列左心衰竭引起呼吸困难的特点均正确，但除外","o":["活动时出现或加重","休息时减轻或缓解","仰卧时加重","坐位时减轻","与体位无关"],"a":4,"e":"左心衰竭呼吸困难于活动时出现或加重，休息后减轻，仰卧加重、坐位减轻即端坐呼吸，显然与体位密切相关。"},{"q":"尿频可见于以下哪种情况","o":["生理性尿频","急性肾小球肾炎","IgA肾病","紫癜性肾炎","慢性肾炎"],"a":0,"e":"生理性尿频因饮水过多、精神紧张或气候寒冷引起，每次尿量不少且无尿急尿痛；急性肾小球肾炎等以血尿、蛋白尿和水肿为主要表现。"},{"q":"焦虑患者常常伴有的生理症状不包括","o":["心悸","血压升高","皮肤红润","尿频","腹泻"],"a":2,"e":"焦虑时交感神经兴奋，出现心悸、血压升高、尿频、腹泻及出汗，皮肤多苍白湿冷而非红润。"},{"q":"支气管舒张试验主要用于诊断","o":["肺气肿","哮喘","肺炎","肺不张","肺纤维化"],"a":1,"e":"支气管舒张试验吸入β2受体激动剂后复测FEV1，据其改善率判断气道阻塞的可逆性，主要用于协助支气管哮喘的诊断与鉴别。"},{"q":"年轻人出现“冠状T波”，除考虑冠状动脉粥样硬化性心脏病外，首先应排除","o":["扩张型心肌病","肥厚型心肌病","心肌炎","心包炎","先天性心脏病"],"a":1,"e":"年轻人出现深而对称的冠状T波应首先排除心尖部肥厚型心肌病，该病T波深倒置易误认为心肌缺血或心肌梗死；冠心病多见于中老年且有危险因素。"},{"q":"心尖冲动减弱并弥散常见于","o":["心包大量积液","缩窄性心包炎","心肌炎或心肌病","左侧胸腔积液","肥胖"],"a":2,"e":"心肌炎、心肌病时心肌收缩力减弱，心尖搏动减弱且范围弥散；心包积液、缩窄性心包炎及肥胖使搏动减弱但范围不增大。"},{"q":"正常心尖冲动位置在","o":["胸骨左缘第4肋间锁骨中线内侧0.5～1cm处","胸骨左缘第5肋间锁骨中线内侧1.5～2cm处","胸骨左缘第6肋间锁骨中线内侧1～2cm处","胸骨左缘第5肋间锁骨中线内侧0.5～1cm处","胸骨左缘第5肋间锁骨中线外侧1～2cm处"],"a":3,"e":"正常心尖搏动位于第5肋间左锁骨中线内侧0.5～1.0cm，搏动直径2.0～2.5cm，由心室收缩时心尖向前冲击前胸壁形成。"},{"q":"诊断麻痹性肠梗阻时腹部持续听诊至少","o":["30～50s","1～2min","2～3min","3～5min","5～10min"],"a":3,"e":"诊断麻痹性肠梗阻须在腹部持续听诊3～5分钟仍未闻及肠鸣音，并以手指轻叩或搔弹腹部验证，方可判定肠鸣音消失。"},{"q":"下列主动脉瓣关闭不全引起周围血管征的叙述正确的是","o":["有效循环血量增加，致水冲脉","舒张期主动脉血液反流、脉压增大","收缩压升高幅度大于舒张压升高幅度","静脉压升高致De-Musset征","毛细血管扩张导致毛细血管搏动"],"a":1,"e":"主动脉瓣关闭不全时舒张期主动脉血液反流入左室，舒张压下降、收缩压升高致脉压增大，从而出现水冲脉、枪击音等周围血管征。"},{"q":"视诊的内容包括下列各项，但应除外","o":["面容","表情","体位","步态","波动"],"a":4,"e":"视诊观察发育与营养、意识状态、面容与表情、体位、步态及皮肤黏膜等；波动只能由触诊感知，不属视诊内容。"},{"q":"不符合干性啰音听诊特点的是","o":["吸气、呼气均可听到","部位易变性大","吸气时音强而高","咳嗽时可多可少","不同性质的干性啰音可同时存在"],"a":2,"e":"干性啰音音调较高、呼气时明显且持续时间长，部位不恒定、性质易变，咳嗽后可增多或减少，同一病人可同时存在不同性质者。"},{"q":"痢疾患者的粪便为","o":["黏液便","干结便","脓血便","米泔水样便","白陶土样便"],"a":2,"e":"细菌性痢疾累及结肠黏膜，出现脓血便伴腹痛和里急后重；米泔水样便见于霍乱，白陶土样便见于梗阻性黄疸。"},{"q":"检查视力时，针孔视力较裸眼视力有明显提高，说明患者的视力下降可能为下列何种原因所致","o":["精神因素","结膜炎","屈光不正","视神经疾病","黄斑疾病"],"a":2,"e":"针孔镜遮挡周边光线、缩小弥散圈，若针孔视力较裸眼明显提高，说明视力下降主要由屈光不正引起；视神经或黄斑疾病则不能改善。"},{"q":"下列为心房颤动听诊的特点，但应除外","o":["心律绝对不规则","第一心音强弱不等","脉率少于心率","吸气时心率快，呼气时心率慢","脉搏短绌"],"a":3,"e":"心房颤动听诊特点为心律绝对不规则、第一心音强弱不等、脉搏短绌即脉率少于心率；吸气增快、呼气减慢的随呼吸心律变化属窦性心律不齐。"},{"q":"本例心电图最可能的诊断是","o":["左室肥厚","右室增大","左房增大","右房增大","房室内径正常"],"a":0,"e":"官方题库缺失图片"},{"q":"下列各项均有肾区叩痛，但除外","o":["肾结石","肾盂肾炎","肾衰竭","肾炎","肾周围炎"],"a":2,"e":"肾区叩痛见于肾结石、肾盂肾炎、肾炎及肾周围炎等肾实质或肾周炎症；肾衰竭属肾功能损害，一般无肾区叩击痛。"},{"q":"淤血性周围性发绀常见于哪种疾病","o":["严重休克","上腔静脉压迫综合征","急性呼吸窘迫综合征","弥漫性肺间质纤维化","法洛四联症"],"a":1,"e":"淤血性周围性发绀由体循环淤血、周围血流缓慢、氧被过度摄取所致，见于右心衰竭、缩窄性心包炎及上腔静脉阻塞综合征；严重休克属缺血性周围性发绀。"},{"q":"正常人尿中可见到下列细胞，但除外","o":["红细胞","白细胞","小圆上皮细胞","表层移行上皮细胞","扁平上皮细胞"],"a":2,"e":"正常尿中可见少量红细胞、白细胞、扁平上皮细胞及表层移行上皮细胞；小圆上皮细胞即肾小管上皮细胞，正常不应出现，出现提示肾小管损伤。"},{"q":"重搏脉最常见于","o":["伤寒病","心包积液","左心衰竭","贫血","高热"],"a":0,"e":"重搏脉指一次心搏后脉搏出现第二次隆起，见于伤寒等使外周血管阻力降低、舒张期血管再充盈的疾病；交替脉则见于左心衰竭。"},{"q":"下列关于主动脉瓣狭窄的说法正确的是","o":["常见水冲脉","常伴有S2固定分裂","杂音向颈根部传导","可导致A2增强","为主动脉瓣副区最响的收缩期递增递减型杂音"],"a":2,"e":"主动脉瓣狭窄的收缩期喷射性杂音向颈部及颈根部传导，A2减弱并常伴震颤；水冲脉、S2固定分裂及A2增强均不属其表现。"},{"q":"所谓一元论，就是指","o":["只考虑一种疾病","所有病史资料只能用一种疾病解释","所有病史资料尽量用一种疾病解释","诊断不明确时，可考虑按功能性疾病治疗","只能考虑一种疾病"],"a":2,"e":"一元论要求尽量用一种疾病解释病人的全部临床资料，只有在确实无法解释时才考虑多种疾病并存，而非只考虑一种疾病或牵强附会。"},{"q":"下列疾病引起发热均为感染性，但应除外","o":["细菌侵入机体后","病毒侵入机体后","支原体侵入机体后","感染后低热","寄生虫侵入机体后"],"a":3,"e":"感染性发热由病毒、细菌、支原体、立克次体、真菌及寄生虫等病原体感染引起；感染治愈后低热为体温调节功能未恢复所致，属非感染性发热。"},{"q":"PaO2显著下降而PaCO2无增加的疾病主要见于","o":["COPD所致呼吸衰竭","气道阻塞所致呼吸衰竭","ARDS所致呼吸衰竭","低通气综合征所致呼吸衰竭","延髓中枢受损所致呼吸衰竭"],"a":2,"e":"ARDS以肺内分流和弥散障碍为主，表现为PaO2显著降低而PaCO2正常或降低，属Ⅰ型呼吸衰竭；COPD、气道阻塞及低通气综合征多为PaCO2升高的Ⅱ型。"},{"q":"下列哪一项不属于神经源性膀胱","o":["多发性硬化","脑梗死","帕金森病","前列腺肿瘤","颅内肿瘤"],"a":3,"e":"神经源性膀胱由中枢或周围神经病变引起，常见于多发性硬化、脑梗死、帕金森病及颅内肿瘤；前列腺肿瘤属梗阻性排尿困难。"},{"q":"骨髓涂片检查中正常人粒红比值M∶E是","o":["（1～3）∶1","（2～4）∶1","（2～5）∶1","（3～5）∶1","（4～10）∶1"],"a":1,"e":"正常人骨髓粒系与红系比值即M∶E为（2～4）∶1；比值增高见于粒细胞白血病或红系受抑，降低见于红系增生或粒系减少。"},{"q":"下列患者于安静状态下均可见到颈动脉的明显搏动，除外","o":["主动脉瓣狭窄","主动脉瓣关闭不全","高血压","甲状腺功能亢进症","严重贫血"],"a":0,"e":"安静状态下颈动脉明显搏动见于脉压增大的疾病，如主动脉瓣关闭不全、高血压、甲状腺功能亢进及严重贫血；主动脉瓣狭窄心搏出量减少，颈动脉搏动减弱。"},{"q":"帕金森病的面容是","o":["面部呆板，无表情","面色苍黄，反应迟钝","牙关经闭，面肌痉挛","面色苍白，表情疲惫","面容惊愕，眼裂增宽"],"a":0,"e":"帕金森病典型表现为面具面容，面部呆板、无表情、似戴面具，伴静止性震颤与肌强直；苦笑面容见于破伤风。"},{"q":"Q-T间期的正常值是","o":["0.18～0.24秒","0.24～0.32秒","0.32～0.44秒","0.44～0.52秒","0.52～0.66秒"],"a":2,"e":"QT间期代表心室肌除极与复极全过程，心率60～100次/分时正常范围为0.32～0.44秒，心率越快则QT间期越短。"},{"q":"高血压患者心脏听诊心音变化特点为","o":["心尖部第一心音亢进","心尖部第一心音减弱","剑突下第一心音减弱","胸骨右缘第2肋间第二心音亢进","胸骨左缘第2肋间第二心音亢进"],"a":3,"e":"长期高血压使主动脉压力负荷增大、主动脉壁张力增高，主动脉瓣关闭时振动增强，故胸骨右缘第2肋间即主动脉瓣区第二心音亢进。"},{"q":"心肌梗死后较易闻及大炮音的是","o":["急性前壁心肌梗死","急性广泛前壁心肌梗死","急性下壁心肌梗死","急性前间壁心肌梗死","急性高侧壁心肌梗死"],"a":2,"e":"急性下壁心肌梗死易累及房室结及希氏束的血供，引起房室传导阻滞，心房心室几乎同时收缩时S1增强，出现大炮音。"},{"q":"系统回顾的重要性不包括","o":["是问诊的内容之一","避免忽略或遗漏问诊内容","帮助医生短时间内了解病人其他系统尚存或痊愈的疾病","有助于了解病人的社会经历，职业及工作条件","了解本次患病与其他疾病的因果关系"],"a":3,"e":"系统回顾按各系统询问症状，可避免遗漏、短时间内了解其他系统尚存或已愈的疾病，并判断本次患病与既往疾病的因果关系；社会经历与职业属个人史。"},{"q":"风湿性心脏病二尖瓣狭窄的典型面容是","o":["面色潮红，表情痛苦","面色晦暗，双颊发红，口唇发绀","面色苍白，表情疲惫","面色晦暗，额部有褐色色素沉着","表情淡漠，反应迟钝，呈无欲状态"],"a":1,"e":"二尖瓣面容表现为面色晦暗、双颊紫红、口唇轻度发绀，见于风湿性心瓣膜病二尖瓣狭窄，与长期肺淤血及心排血量降低有关。"},{"q":"关于核左移，下列正确的是","o":["见于巨幼细胞贫血","见于应用抗代谢药物治疗后","常见于化脓菌引起的感染","是由于缺乏造血物质使DNA合成障碍","表示机体反应性低下"],"a":2,"e":"核左移指外周血中性粒细胞杆状核及更幼稚细胞比例增高，常见于急性化脓性细菌感染、急性中毒和急性溶血；核右移见于巨幼细胞贫血及抗代谢药物治疗后。"},{"q":"明确诊断为右侧大量胸腔积液的患者，查体可见","o":["右胸胸廓塌陷，呼吸运动减弱，语颤消失，叩诊实音，呼吸音消失","右胸饱满，呼吸运动减弱，语颤消失，叩诊实音，呼吸音消失","右胸饱满，呼吸运动增强，语颤消失，叩诊实音，呼吸音消失","右胸饱满，呼吸运动减弱，语颤增强，叩诊实音，呼吸音消失","右胸饱满，呼吸运动减弱，语颤消失，叩诊鼓音，呼吸音消失"],"a":1,"e":"大量胸腔积液使患侧胸廓饱满、呼吸动度减弱，液体将脏、壁层胸膜隔开使语颤消失，叩诊实音，呼吸音与语音共振消失。"},{"q":"临床习惯上对营养不良做如下描述，但应除外","o":["皮肤黏膜干燥，弹性减低","皮下脂肪菲薄","肌肉松弛无力","指甲粗糙无光泽","甲床下有紫红色出血"],"a":4,"e":"营养不良表现为消瘦、皮下脂肪菲薄、肌肉松弛无力、皮肤黏膜干燥且弹性减退、指甲粗糙无光泽；甲床下紫红色出血是感染性心内膜炎的体征。"},{"q":"下列哪项是构成心脏右界的主要成分","o":["下腔静脉","右心房","右心室","降主动脉","肺动脉段"],"a":1,"e":"心右界第2肋间为升主动脉和上腔静脉，第3肋间以下为右心房，故右心房是构成心脏右界的主要成分。"},{"q":"下列描述符合正常心电图表现，除了","o":["V1导联p波可以是直立的，也可以双向","QRS波宽度不应超过0.12s","V2～V3导联Q波宽度可达0.04s","V1导联R波在成人不应超过1.0mV","V1导联可出现孤立的QS波或Qr波"],"a":2,"e":"正常人V1、V2导联不应出现Q波，偶尔可呈QS波，更不存在宽达0.04秒的Q波；Q波宽度≥0.04秒且深度超过同导联R波1/4属病理性Q波。"},{"q":"弛张热最常见于","o":["大叶性肺炎","疟疾","霍奇金病","支气管肺炎","败血症"],"a":4,"e":"弛张热又称败血症热型，体温常在39℃以上，24小时内波动超过2℃而最低仍高于正常，常见于败血症、风湿热和重症肺结核。"},{"q":"下列物质中属于舒血管物质的是","o":["儿茶酚胺","血栓烷A2","肾上腺素","前列环素","纤维蛋白肽A"],"a":3,"e":"前列环素由血管内皮细胞生成，是强效舒血管并抑制血小板聚集的物质；儿茶酚胺、肾上腺素及血栓烷A2均使血管收缩。"},{"q":"每天咯血量为多少时属于大量咯血","o":["＞100ml","＞500ml","100～500ml","＞300ml","＞600ml"],"a":1,"e":"每日咯血量100ml以内为小量，100～500ml为中等量，500ml以上或一次咯血100～500ml为大量咯血，多见于空洞性肺结核、支气管扩张和慢性肺脓肿。"},{"q":"关于嗅神经检查，下列叙述哪项不正确","o":["嗅觉的灵敏度可通过问诊了解","检查时双侧鼻孔同时进行","用醋、酒、香皂等分别放于鼻孔前，要求辨认气味","嗅觉正常时可明确分辨测试物品气味","如一侧嗅觉减退或丧失提示同侧嗅神经损害"],"a":1,"e":"嗅神经检查须先压住一侧鼻孔，用无刺激性气味的物品分别测试两侧并对比，不可双侧同时进行，也不可用酒精、氨水等刺激三叉神经末梢的液体。"},{"q":"检查腹腔深部包块时最适宜的触诊方法是","o":["浅部触诊法","深部滑行触诊法","双手触诊法","深压触诊法","冲击触诊法"],"a":2,"e":"双手触诊法将左手掌置于被检脏器或包块后方托起，使其位于两手之间并更接近体表，最适用于肝、脾、肾及腹腔深部肿物的检查。"},{"q":"王先生因全身水肿1个月，拟诊肾病综合征入院。他自述10年前患过过敏性紫癜性肾炎，这段病史应该属于","o":["现病史","既往史","个人史","家族遗传史","视情况而定"],"a":0,"e":"该病史与本次肾病综合征的病因直接相关，属现病史中对本次住院前有关诊疗经过的记述，须写明其发病、治疗及转归；与本次无关的疾病才归入既往史。"},{"q":"在无水代谢紊乱的情况下，测定尿渗量可粗略地反映","o":["肾小球的滤过功能","肾小管的浓缩稀释功能","肾小管的分泌功能","肾小管上皮细胞对ADH的敏感性","下丘脑对水的调节功能"],"a":1,"e":"尿渗量反映肾小管和集合管对水的重吸收能力，无水代谢紊乱时测定可粗略判断肾脏的浓缩稀释功能；肾小球滤过功能则以肌酐清除率表示。"},{"q":"二尖瓣区收缩期器质性杂音，除见于风湿性二尖瓣关闭不全外，还可见于","o":["乳头肌功能失调","扩张型心肌病","贫血性心脏病","高血压心脏病","主动脉瓣关闭不全"],"a":0,"e":"二尖瓣区收缩期器质性杂音除风湿性二尖瓣关闭不全外，还见于冠心病乳头肌功能失调、腱索断裂及二尖瓣脱垂；扩张型心肌病所致者属相对性关闭不全的功能性杂音。"},{"q":"下列关于甲状腺肿大的叙述均正确，但除外哪一项","o":["女性在青春发育期可略增大","女性在更年期可略增大","不能看出肿大，能触及者为Ⅰ度肿大","能看出肿大，又能触及，但在胸锁乳突肌内为Ⅱ度肿大","能看出肿大，又能触及，超过胸锁乳突肌为Ⅲ度肿大"],"a":1,"e":"女性仅在青春发育期甲状腺可略增大，更年期不出现生理性增大；肿大分度以胸锁乳突肌为界，不能看出但可触及为Ⅰ度，在胸锁乳突肌以内为Ⅱ度，超过该肌外缘为Ⅲ度。"},{"q":"下列疾病常可引起大咯血，但需除外","o":["肺梗死","肺结核空洞","慢性肺脓肿","支气管扩张","肺血管瘤破裂"],"a":0,"e":"大咯血主要见于空洞性肺结核、支气管扩张、慢性肺脓肿和肺血管瘤破裂；肺梗死咯血量一般较少，以突发胸痛和呼吸困难为主要表现。"},{"q":"下列有利于室性心动过速与室上性心动过速的鉴别的是","o":["心室率160次/min","心电图QRS波宽大畸形","既往心电图反复发现室性期前收缩","心肌缺血病史","心电图有心室夺获及室性融合波"],"a":4,"e":"心室夺获与室性融合波是室性心动过速的特异性表现，可据此确诊；QRS波宽大畸形、既往期前收缩史和心肌缺血史均不能可靠鉴别。"},{"q":"心血管疾病中，不会引起咯血的原因是","o":["肺动脉高压","二尖瓣狭窄","高血压病","肺血管炎","肺栓塞"],"a":2,"e":"肺动脉高压、二尖瓣狭窄、肺血管炎及肺栓塞均可因肺淤血或肺血管破裂引起咯血；高血压病本身不直接导致咯血。"},{"q":"慢性肺源性心脏病患者心电图一般不会出现下列哪项","o":["P波高尖","低电压","显著顺钟向转位","右室肥大","U波高大"],"a":4,"e":"慢性肺心病心电图以右心房、右心室肥大为特征，可见肺型P波、右室高电压、显著顺钟向转位及低电压；U波高大见于低钾血症。"},{"q":"凝血酶时间（TT）是测定在受检血浆中加入“标准化”凝血酶溶液，到开始出现纤维蛋白丝所需的时间，一般正常值是","o":["10～16秒","15～19秒","16～18秒","20～23秒","23～25秒"],"a":2,"e":"凝血酶时间正常参考区间为16～18秒，超过正常对照3秒以上为延长，见于血中肝素或类肝素物质增多、纤维蛋白原减少及异常纤维蛋白原血症。"},{"q":"下列是二尖瓣关闭不全杂音听诊的特征，但应除外","o":["心尖部闻及3/6级以上收缩期杂音","性质粗糙","向左腋下传导","收缩期杂音可掩盖第一心音","呼气时杂音明显增强"],"a":4,"e":"二尖瓣关闭不全的杂音为心尖区3/6级以上粗糙吹风样全收缩期杂音，向左腋下传导，常掩盖减弱的S1；其强度呈一贯型，不随呼吸明显增强。"},{"q":"属于暗示性或诱导性提问的是","o":["什么情况下感觉加重","什么时候发病的","您哪儿不舒服","胸部疼痛向左肩部放射吗","哪儿疼痛"],"a":3,"e":"诱导性提问的措辞已暗示期望答案，使病人默认或附和医生的诱问，“胸痛向左肩放射吗”即属此类；开放式提问才利于获得真实病史。"},{"q":"IgE的主要特征是","o":["在生物进化过程中最先出现","分子量最大","主要存在血管内","可通过胎盘","与超敏反应有关"],"a":4,"e":"IgE是血清中含量最少的免疫球蛋白，为介导Ⅰ型超敏反应的亲细胞性抗体，并参与抗寄生虫感染，其核心特征是与超敏反应相关。"},{"q":"第二心音反常分裂，最常见于","o":["完全性右束支传导阻滞","二尖瓣狭窄","完全性左束支传导阻滞","肺动脉高压","Ebstein畸形"],"a":2,"e":"S2反常分裂由主动脉瓣关闭迟于肺动脉瓣所致，呼气时分裂明显，最常见于完全性左束支传导阻滞，主动脉瓣狭窄、重度高血压也可出现。"},{"q":"关于病程记录的书写，错误的是","o":["主治医师首次查房记录应于患者入院48h内完成","首次病程记录应当包括病例特点、拟诊讨论及诊疗计划","抢救记录应当在抢救结束后6h内补记","接班记录应由接班医师在24h内完成","有创诊疗操作记录应当在完成操作后8h内完成"],"a":4,"e":"有创诊疗操作记录应在操作完成后即刻书写，而非8小时内；首次病程记录8小时内完成，接班记录24小时内完成，抢救记录6小时内补记。"},{"q":"下列发热性疾病中，不伴有肝脾大的是","o":["急性ITP","传染性单核细胞增多症","病毒性肝炎","淋巴瘤","白血病"],"a":0,"e":"急性ITP为血小板破坏增多所致的出血性疾病，无肝脾大；传染性单核细胞增多症、病毒性肝炎、淋巴瘤和白血病常伴肝脾大。"},{"q":"下列关于心房颤动的叙述都正确，但除外","o":["听诊能发现的心律失常","第一心音强弱不等","心律绝对不规则","心率少于脉率","常见于二尖瓣狭窄"],"a":3,"e":"房颤时心室充盈量不足使部分搏动不能形成脉搏，故脉率少于心率，称脉搏短绌；“心率少于脉率”正好颠倒，其余三项均为房颤特点。"},{"q":"触及肝时，应详细描述下列内容，但除外","o":["大小","质地","压痛","表面状态、边缘","活动度"],"a":4,"e":"肝触诊应描述大小、质地、表面状态与边缘、压痛及搏动，活动度为腹部肿块或脊柱检查的内容，不属肝触诊描述项目。"},{"q":"下列哪项因素不可能诱发急性胃黏膜病变","o":["颅脑手术","严重外伤","剧烈呕吐","大面积烧伤","非甾体类药物"],"a":2,"e":"急性胃黏膜病变由颅脑手术、严重外伤、大面积烧伤及非甾体类药物等引起；剧烈呕吐造成的是食管贲门黏膜撕裂综合征。"},{"q":"头面部的疼痛的主要传导神经是","o":["三叉神经","面神经","交感神经","视神经","听神经"],"a":0,"e":"头面部痛觉主要由三叉神经传导，其三个分支支配面部皮肤、黏膜及牙等区域；面神经、视神经和听神经均非痛觉主要传导神经。"},{"q":"正常人胸部叩诊时能查到的是","o":["Skoda叩响","Traube鼓音区","Garland三角区","Grocco三角区","Damoiseau曲线"],"a":1,"e":"左腋前线下方胃泡含气区叩诊呈鼓音，即Traube鼓音区，为正常人可叩得者；Skoda叩响、Grocco三角区等均属病理性叩诊体征。"},{"q":"少尿可见于以下情况，除外","o":["大出血","休克","肾小管酸中毒","前列腺增生","肝硬化"],"a":2,"e":"肾小管酸中毒时肾小管浓缩功能受损，临床表现为多尿；大出血、休克致肾灌注不足，前列腺增生致尿路梗阻，肝硬化致有效循环血量下降，均可引起少尿。"},{"q":"关于脾脏触诊手法下列各项均正确，但除外","o":["肿大脾脏可用右手触诊和双手触诊法","患者取仰卧位也可取右侧卧位","医生右手绕过患者腹前方，手掌置于左腰第7～10肋将脾托起","医生右手掌平放于上腹部，于左锁骨中线上触诊脾脏","脾触诊时按压不要太重"],"a":3,"e":"脾触诊时右手掌应平放于脐部，与左肋弓大致垂直，自脐平面迎触脾尖；平放上腹部沿左锁骨中线触诊不符合脾脏触诊手法。"},{"q":"Austin Flint杂音见于","o":["重度主动脉关闭不全","器质性二尖瓣狭窄","重度二尖瓣关闭不全","重度肺动脉关闭不全","重度主动脉狭窄"],"a":0,"e":"重度主动脉瓣关闭不全时左室舒张期容量负荷过重，二尖瓣处于半关闭状态而形成相对狭窄，产生心尖部柔和递减型舒张中晚期杂音，即Austin Flint杂音。"},{"q":"帕金森病患者走路的姿态是","o":["共济失调步态","剪刀步态","慌张步态","蹒跚步态","跨阈步态"],"a":2,"e":"慌张步态表现为起步后小步急速趋行、双脚擦地、身体前倾而难以止步，是帕金森病的典型步态；共济失调步态见于脊髓病变。"},{"q":"FEV1 70%，FVC 75%，FEV1/FVC 65%，TLC 75%，DLCO 80%，肺功能诊断为","o":["阻塞性通气功能障碍","限制性通气功能障碍","混合性通气功能障碍","孤立性弥散功能减低","限制性通气功能障碍伴弥散功能减低"],"a":2,"e":"FEV1/FVC 65%提示阻塞性通气障碍，FVC与TLC均低于预计值80%提示并存限制性成分，故为混合性通气功能障碍，DLCO正常说明无弥散障碍。"},{"q":"分析杂音主要注意以下几点，但除外","o":["杂音的最响部位","杂音出现的时期","杂音伴有附加心音","杂音的传导方向","杂音性质和强度"],"a":2,"e":"分析杂音应注意最响部位、出现时期、性质、强度、传导方向及体位呼吸的影响；附加心音属额外心音内容，不是杂音分析的要点。"},{"q":"关于AFP的叙述，下列错误的是","o":["胎儿早期由肝脏和卵黄囊合成的一种血清糖蛋白","生殖腺胚胎肿瘤，妊娠增加","是原发性肝癌的标志蛋白","AFP不升高，可除外原发性肝癌","急慢性肝炎、肝硬化可增加，其升高与肝细胞坏死与再生程度相关"],"a":3,"e":"约30%原发性肝癌病人AFP不升高，故AFP正常不能排除肝癌；AFP升高还见于生殖腺胚胎瘤、妊娠及急慢性肝炎和肝硬化。"},{"q":"主动脉型心（靴型心），最常见于","o":["主动脉瓣关闭不全","肺源性心脏病","二尖瓣狭窄","心包积液","二尖瓣关闭不全"],"a":0,"e":"主动脉型心又称靴型心，因左心室增大致心腰凹陷、心尖向左下移位，最常见于主动脉瓣关闭不全，高血压心脏病亦可呈此型。"},{"q":"关于支气管哮喘的描述，下列不正确的是","o":["胸廓呈呼气位","两肺语颤减弱","两肺叩诊呈过清音","两肺布满哮鸣音","肺下界下移"],"a":0,"e":"支气管哮喘发作时肺过度充气，胸廓饱满呈吸气位而非呼气位，同时有语颤减弱、两肺过清音、双肺哮鸣音及肺下界下移。"},{"q":"肾源性水肿的特点是","o":["多从下肢开始继而遍及全身","多从眼睑开始而遍及全身","多伴有双上肢静脉压升高","多为非凹陷性水肿","多伴有淋巴回流受阻"],"a":1,"e":"肾源性水肿早期晨起眼睑与颜面水肿，迅速延及全身，水肿软而移动性大；心源性水肿则从足部开始向上蔓延。"},{"q":"下述为对调节辐辏反射方法与结果的描述，其中错误的是","o":["嘱患者注视1m以外目标","将目标迅速移近眼球约20cm处","正常人瞳孔渐缩小","正常人瞳孔渐扩大","双眼球同时向内聚合"],"a":3,"e":"集合反射时嘱病人注视1m以外目标，再将目标移近眼球，正常人双眼内聚、瞳孔缩小；瞳孔扩大属异常，与调节辐辏反射相反。"},{"q":"关于问诊的方法下列各项均正确，但除外","o":["医生要向病人自我介绍","问诊要有层次，有顺序","问诊要由简单问题开始","问诊要适当地诱导提问","问诊要启发病人思考回忆"],"a":3,"e":"诱导性提问在措辞上已暗示期望答案，易使病人附和而获得错误信息，属问诊应予避免的方式；问诊应由简单问题开始并启发病人回忆。"},{"q":"心绞痛引起的放射痛最可能的机制是","o":["肋间神经感觉纤维受刺激","心脏交感神经的传入纤维受刺激","支配左肩，左臂的体表神经受刺激","膈神经的感觉纤维受刺激","心脏迷走神经受刺激"],"a":1,"e":"心脏缺血时的代谢产物刺激交感神经传入纤维，其冲动与相应体表传入纤维在脊髓同一节段后角联系，激发体表感觉神经元而产生左肩左臂放射痛。"},{"q":"诊断肠梗阻最主要的根据是","o":["腹痛","腹胀","呕吐","排便、排气减少或停止","X线见多数气液平面及胀气肠袢"],"a":4,"e":"X线见多数气液平面及胀气肠袢是肠梗阻的直接形态学证据，为诊断最主要依据；腹痛、腹胀、呕吐和排便排气停止仅为提示性症状。"},{"q":"腹腔脏器哪项病变不引起腹痛","o":["炎症","淤血","扭转","破裂","腹水"],"a":4,"e":"腹水本身只引起腹部膨隆与移动性浊音，不产生疼痛；腹痛由脏器炎症、淤血、扭转、破裂或梗阻等病变刺激痛觉神经所致。"},{"q":"判断骨髓幼红细胞增生情况最简便的方法是","o":["血红蛋白测定","周围血液涂片检查","网织红细胞计数","骨髓涂片检查","血清铁测定"],"a":2,"e":"网织红细胞计数反映骨髓红系造血功能，是判断幼红细胞增生情况最方便、最常用的指标；骨髓涂片虽准确但操作复杂。"},{"q":"下列哪项内容不包括在既往史里","o":["传染病史","预防接种史","毒物接触史","药物过敏史","输血史"],"a":2,"e":"毒物接触史属个人史中的职业与工作条件内容；既往史包括既往健康状况、传染病史、预防接种史、手术外伤史、输血史及食物药物过敏史。"},{"q":"风湿性二尖瓣关闭不全患者可有下列哪项症状","o":["咳嗽、咯血","晕厥","心绞痛","腹痛","心悸"],"a":4,"e":"慢性风湿性二尖瓣关闭不全出现症状时多为心悸、咳嗽、劳力性呼吸困难与疲乏，咯血和急性肺水肿较二尖瓣狭窄少见。"},{"q":"血小板减少到什么水平，患者易有出血症状","o":["＜10×109/L","＜20×109/L","＜50×109/L","＜100×109/L","＜200×109/L"],"a":2,"e":"血小板低于50×10⁹/L时止血功能明显受损，轻微创伤即可出血；低于20×10⁹/L常出现自发性出血，需积极处理。"},{"q":"心电图波形与心室动作电位的关系不正确的是","o":["QRS起始同动作电位的快速上升（0期）相对应","等电位ST段与动作电位的2期（平台期）相对应","T波与动作电位的3期（快速复极期）相对应","T波结束后的等电位段与动作电位的4期（恢复期）相对应","T波与动作电位的4期（恢复期）相对应"],"a":4,"e":"T波对应心室肌动作电位的3期快速复极，4期恢复期对应T波之后的等电位段，故“T波与4期相对应”的表述错误。"},{"q":"引起S1分裂最常见的是","o":["左束支传导阻滞","右束支传导阻滞","房间隔缺损","室间隔缺损","左心衰竭"],"a":1,"e":"S1分裂因三尖瓣关闭明显迟于二尖瓣所致，电活动延迟最常见于完全性右束支传导阻滞，机械活动延迟见于肺动脉高压。"},{"q":"叩诊有移动性浊音时，腹水量最少应是","o":["2000ml","1500ml","1000ml","500ml","200ml"],"a":2,"e":"腹腔内游离积液达1000ml以上时，因体位改变出现浊音区移动，方可叩出移动性浊音，故其为检出腹水的最低量。"},{"q":"高热持续期热代谢特点是","o":["散热减少，产热增加，体温增高","产热减少，散热增加，体温降低","散热减少，产热增加，体温保持高水平","产热与散热在高水平上相对平衡，体温保持高水平","产热与散热在高水平上波动，体温波动"],"a":3,"e":"高热持续期体温已升至调定点水平，寒战消失、皮肤血管舒张、出汗增多，产热与散热在高水平上保持相对平衡，体温维持于高水平。"},{"q":"病理反射中价值最大的是","o":["Babinski征","Oppenheim征","Gordon征","Gonda征","Chaddock征"],"a":0,"e":"Babinski征是最典型的病理反射，阳性表现为拇趾背伸、其余四趾扇形展开，临床价值最大；Oppenheim、Gordon、Chaddock征意义相同但阳性率较低。"},{"q":"关于听诊，下列哪项不正确","o":["心功能不全可闻及湿啰音","肺气肿可闻及湿啰音","支气管肺炎可闻及湿啰音","支气管扩张可闻及湿啰音","肺结核可闻及湿啰音"],"a":1,"e":"肺气肿时肺泡弹性减退、含气量增多，听诊呼吸音减弱、呼气延长，不出现湿啰音；湿啰音见于肺炎、心功能不全、支气管扩张和肺结核。"},{"q":"下列各项均为急性胆囊炎体征，但除外","o":["墨菲征（＋）","胆囊叩击痛","右上腹压痛","右上腹反跳痛","Courvoisier征（＋）"],"a":4,"e":"Courvoisier征是胰头癌压迫胆总管致胆囊无痛性肿大，与急性胆囊炎的墨菲征阳性、右上腹压痛及反跳痛意义相反。"},{"q":"弛张热最常见的疾病是","o":["伤寒","肺炎","支气管炎","败血症","布氏杆菌病"],"a":3,"e":"弛张热又称败血症热型，体温常在39℃以上、24小时波动超过2℃，见于败血症、风湿热、重症肺结核及化脓性炎症，故以败血症最常见。"},{"q":"关于反跳痛的手法描述下列各项均正确，但除外","o":["首先轻轻地浅触全腹部","常常选择腹部压痛明显部位触诊","手触及压痛部位后，嘱患者深吸气","手触及压痛部位后于原处稍停片刻","手触及压痛部位后当压痛感觉稳定时迅速将手抬起"],"a":2,"e":"反跳痛检查为深压痛点后稍停片刻，待压痛稳定迅速抬手，观察疼痛是否加剧；嘱病人深吸气并非反跳痛的手法内容。"},{"q":"最容易出现舒张早期奔马律的疾病是","o":["主动脉瓣狭窄","肺动脉瓣狭窄","心功能不全","二尖瓣狭窄","主动脉瓣关闭不全"],"a":2,"e":"舒张早期奔马律提示严重器质性心脏病，最常见于心力衰竭，也见于急性心肌梗死、重症心肌炎和扩张型心肌病。"},{"q":"风湿性心脏病二尖瓣关闭不全的主要体征是","o":["Graham-Steell杂音","心尖部听到舒张期隆隆样杂音","心尖部听到吹风样全收缩期杂音，向左腋下传导","Austin-Flint杂音","Duroziez双重杂音"],"a":2,"e":"风湿性二尖瓣关闭不全于心尖区闻及响亮粗糙、3/6级以上全收缩期吹风样杂音，向左腋下及左肩胛下区传导，为最主要体征。"},{"q":"咯血最常见于","o":["慢性支气管炎","肺脓肿","肺炎","肺癌","肺结核"],"a":4,"e":"我国咯血的首要病因仍为肺结核，多为浸润型、空洞型肺结核和干酪性肺炎，因病变使毛细血管通透性增高或血管破裂而出血。"},{"q":"临床诊断的内容不包括","o":["病因诊断","病史诊断","病理生理诊断","疾病的分期与分型","并发症的诊断"],"a":1,"e":"完整诊断包括病因诊断、病理解剖诊断、病理生理诊断、疾病分期分型及并发症，“病史诊断”不是诊断内容的组成部分。"},{"q":"56岁男性胸痛患者，问诊时哪个问题不合适","o":["胸痛还向指尖放射吗","胸痛是什么样的痛","胸痛的具体位置在哪","胸痛时还有其他不舒服吗","胸痛是持续性还是发作性"],"a":0,"e":"“胸痛还向指尖放射吗”以“还……吗”预设了放射痛的存在，属诱导性提问，易使病人附和；其余问法为开放式，不暗示答案。"},{"q":"毛细血管壁缺陷引起皮肤黏膜出血可见于下列疾病，但除外","o":["原发免疫性血小板减少症","过敏性紫癜","单纯性紫癜","老年性紫癜","机械性紫癜"],"a":0,"e":"单纯性紫癜、过敏性紫癜、老年性紫癜和机械性紫癜均因毛细血管壁缺陷或损伤致出血；原发免疫性血小板减少症为血小板破坏增多所致。"},{"q":"心脏叩诊的正确顺序是","o":["先右界、后左界，由上向下，由外向内","先右界、后左界，由下向上，由右向左","先左界、后右界，由下向上，由外向内","先左界、后右界，由上向下，由外向内","先左界、后右界，由上向下，由左向右"],"a":2,"e":"心脏叩诊先叩左界后叩右界，自心尖搏动外2～3cm处由外向内、逐个肋间向上叩至第2肋间，右界先定肝上界再逐肋向上。"},{"q":"下列是胸骨下角的描述，错误的是","o":["正常约80°～120°","瘦长型较小，矮胖型较大","相当于横膈的穹隆部，深吸气时可加宽","肝左叶、胃、胰在此区域","为两侧肋弓在胸骨下端汇合成的夹角"],"a":0,"e":"胸骨下角为两侧肋弓在胸骨下端汇合而成的夹角，正常约90°～110°，瘦长型较小、矮胖型较大，深吸气时可加宽。"},{"q":"引起S2逆分裂的是","o":["二尖瓣狭窄","二尖瓣关闭不全","肺动脉瓣狭窄","主动脉瓣狭窄","右心衰竭"],"a":3,"e":"S2逆分裂因主动脉瓣关闭明显延迟，分裂在呼气时明显，见于完全性左束支传导阻滞、主动脉瓣狭窄及重度高血压。"},{"q":"第二心音逆分裂是指","o":["吸气时第二心音分裂明显","呼气时第二心音分裂明显","第二心音分裂与呼吸无关","呼气时听不到第二心音分裂","吸气时听不到第二心音分裂"],"a":1,"e":"第二心音逆分裂指分裂在呼气末更明显、吸气时减轻或消失，与通常的吸气性分裂相反，提示主动脉瓣关闭延迟。"},{"q":"负性心尖搏动可见于","o":["肺气肿","缩窄性心包炎","右心室肥大","大量心包积液","左心室肥大"],"a":1,"e":"心脏收缩时心尖部胸壁内陷即负性心尖搏动，见于粘连性心包炎（含缩窄性心包炎）或心包与周围组织广泛粘连，重度右室肥厚亦可引起。"},{"q":"再次免疫应答以哪种抗体为主","o":["IgG","IgM","IgA","IgD","IgE"],"a":0,"e":"再次免疫应答以IgG为主，IgG是血清中含量最多、占总Ig 70%～80%的抗体，也是唯一能通过胎盘的Ig。"},{"q":"腹部检查有振水音，最有临床意义的是","o":["餐后1～2h","餐后2～4h","餐后4～6h","餐后6～8h","餐后8～10h"],"a":3,"e":"正常人餐后或大量饮水后可有振水音，若清晨空腹或餐后6～8小时以上仍存在，提示幽门梗阻或胃扩张。"},{"q":"窄QRS波心动过速，R-P间期小于70ms，可诊断为","o":["窦性心动过速","房性心动过速","房室结折返性心动过速","房室折返性心动过速","室性心动过速"],"a":2,"e":"窄QRS波心动过速而R-P间期小于70ms，提示折返环位于房室结，为房室结折返性心动过速（慢-快型）的特征。"},{"q":"近年来医院感染的病原体的特点为","o":["正常菌群的致病明显增多","耐药菌株减少","新的病原体不断出现","A＋C","A＋B＋C"],"a":3,"e":"医院感染病原体多为人体正常菌群或机会致病菌，耐药菌株不断增多而非减少，同时嗜肺军团菌等新病原体不断出现。"},{"q":"下列哪项属于静脉血管杂音","o":["甲亢时甲状腺侧叶的血管杂音","多发性大动脉狭窄局部的血管杂音","肝硬化门静脉高压上腹部血管杂音","冠状动静脉瘘","动脉导管未闭"],"a":2,"e":"肝硬化门静脉高压时脐周腹壁静脉曲张，血流经脐静脉形成侧支，可于脐周或上腹部闻及连续性静脉营营声，属静脉性血管杂音。"},{"q":"下列凝血因子中不参与内源性凝血途径的是","o":["Ⅻ因子","Ⅺ因子","Ⅸ因子","Ⅷ因子","Ⅶ因子"],"a":4,"e":"内源性凝血途径由Ⅻ因子接触激活启动，依次激活Ⅺ、Ⅸ、Ⅷ，再共同激活Ⅹ；Ⅶ因子参与外源性途径，不参与内源性途径。"},{"q":"奇脉最常见于","o":["急性左心衰竭","动脉导管未闭","大量心包积液","原发性高血压","室间隔缺损"],"a":2,"e":"大量心包积液时心脏舒张受限，吸气时右心回心血量增加而室间隔左移，使左室充盈减少、收缩压下降超过10mmHg，即奇脉。"},{"q":"下列哪项是检查脑膜刺激征的","o":["Babinski征","Oppenheim征","Hoffmann征","踝阵挛","颈项强直"],"a":4,"e":"脑膜刺激征包括颈项强直、Kernig征和Brudzinski征，见于脑膜炎、蛛网膜下腔出血及颅内压增高；Babinski征属病理反射。"},{"q":"哪项检查宜采用深部滑行触诊法","o":["肾脏触诊","肝脏触诊","脾脏触诊","胆囊压痛点","肠管触诊"],"a":4,"e":"深部滑行触诊法以并拢的二、三、四指末端逐渐触向腹腔脏器，并在包块上作上下左右滑动，最适于肠管等胃肠病变的检查。"},{"q":"连续性杂音最常发生于","o":["二尖瓣狭窄与关闭不全","主动脉瓣狭窄与关闭不全","肺动脉瓣狭窄与关闭不全","三尖瓣狭窄与关闭不全","动脉导管未闭"],"a":4,"e":"动脉导管未闭时主动脉血持续分流至肺动脉，杂音自收缩期开始、S2处最响并延续至舒张期，形成机器样连续性杂音。"},{"q":"下列正常人胆红素代谢相关的检查结果，错误的是","o":["结合胆红素0～6、8μmol/L","非结合胆红素1.7～10.2μmol/L","总胆红素1.7～21.1μmol/L","尿胆原阳性","尿胆红素阴性"],"a":2,"e":"正常血清总胆红素为3.4～17.1μmol/L，而非1.7～21.1μmol/L；结合胆红素0～6.8μmol/L、非结合胆红素1.7～10.2μmol/L，尿胆原阳性而尿胆红素阴性。"},{"q":"下列属于内源性致热原的是","o":["各种微生物病原体","炎症渗出物","白细胞介素Ⅰ","某些类固醇物质","多糖体成分及淋巴细胞激活因子"],"a":2,"e":"内源性致热原又称白细胞致热原，包括白介素-1、肿瘤坏死因子和干扰素，由白细胞受外源性致热原激活后释放。"},{"q":"以下为血红蛋白测定值，哪项符合轻度贫血","o":["＜100g/L","＜参考值低限～90g/L","90～60g/L","90～80g/L","＜110g/L"],"a":1,"e":"轻度贫血指血红蛋白高于90g/L但低于相应组别参考区间下限；60～90g/L为中度，30～59g/L为重度，低于30g/L为极重度。"},{"q":"低钾血症的心电图表现不包括","o":["ST段压低","T波低平","U波增高","QT间期缩短","QRS波时间延长"],"a":3,"e":"低钾血症心电图表现为ST段压低、T波低平或倒置、U波增高及QT间期延长，QT间期缩短见于高钾血症和高钙血症。"},{"q":"正常双侧上肢血压差别为","o":["5～10mmHg","10～20mmHg","20～30mmHg","40～60mmHg","30～40mmHg"],"a":0,"e":"正常双侧上肢血压差别为5～10mmHg，超过此范围提示多发性大动脉炎或先天性动脉畸形；下肢血压较上肢高20～40mmHg。"},{"q":"前列腺增生症患者最早出现的症状为","o":["进行性排尿困难","无痛性血尿","会阴部肿胀","尿频","尿路中断"],"a":0,"e":"官方答案为【进行性排尿困难】，但依据教材，正确答案为【尿频】。前列腺增生早期因前列腺充血刺激，尿频、夜尿增多常为首发症状，进行性排尿困难是残余尿增多后才出现的表现。"},{"q":"心前区触到心包摩擦感提示","o":["心脏增大","心包炎","瓣膜狭窄","瓣膜关闭不全","大量心包积液"],"a":1,"e":"心包摩擦感由急性心包炎时纤维蛋白渗出使心包膜表面粗糙，心脏收缩时脏、壁两层摩擦产生，随渗液增多而消失。"},{"q":"关于皮肤黏膜苍白的描述错误的是","o":["可由贫血所致","可见于休克","可见于主动脉瓣关闭不全","常需观察甲床、结膜、口腔黏膜、舌质等部位","肢端苍白，可判断为贫血"],"a":4,"e":"仅肢端苍白提示肢体动脉痉挛或阻塞，见于雷诺病、血栓闭塞性脉管炎，不能据此判断贫血；贫血表现为全身皮肤黏膜苍白。"},{"q":"对于心肌缺血诊断相对特异的是哪种表现","o":["ST段压低","T波倒置","T波直立高耸","T波低平","ST段抬高"],"a":0,"e":"心肌缺血时面向缺血部位的导联出现水平型或下斜型ST段压低≥0.1mV，为相对特异的缺血型改变；单纯T波改变特异性较低。"},{"q":"左肋弓下触及一包块，下列描述符合脾大的是","o":["包块较硬，近圆形","包块随呼吸移动有切迹","包块不随呼吸移动无切迹","包块边缘钝无切迹且位置深","包块与肝右叶相连无切迹"],"a":1,"e":"脾脏肿大时随呼吸上下移动，其内缘有脾切迹，是与左肾、胰尾囊肿等左上腹包块鉴别的重要形态特征。"},{"q":"下列各项为影响呼吸音强弱的因素，但应除外","o":["性别","年龄","呼吸深浅","肺组织弹性大小","听诊的方法"],"a":4,"e":"呼吸音的强弱受性别、年龄、呼吸深浅及肺组织弹性影响；听诊方法本身只影响听诊效果，不改变呼吸音的强弱。"},{"q":"呼吸运动可影响心脏杂音强度的是","o":["主动脉瓣关闭不全","三尖瓣关闭不全","二尖瓣关闭不全","二尖瓣狭窄伴关闭不全","主动脉瓣狭窄伴关闭不全"],"a":1,"e":"右心瓣膜杂音随呼吸变化明显，三尖瓣关闭不全的收缩期杂音于吸气时增强即Carvallo征，呼气时减弱。"},{"q":"关于血尿的叙述，下列正确的是","o":["每升尿液内含血量一定超过5ml","外观洗肉水样，镜下RBC＞3个/HPF，但＜15个/HPF","外观变化不明显，离心沉淀后镜检RBC＞3个/HPF称镜下血尿","外观透明，尿色深黄为肉眼血尿","外观浓茶色或酱油色，潜血试验阳性为血尿"],"a":2,"e":"镜下血尿指尿色正常、外观无血色，离心沉淀后镜检红细胞超过3个/HPF；肉眼血尿呈洗肉水色或血色，肉眼即可辨认。"},{"q":"下列对判断幽门梗阻最有意义的是","o":["可见胃蠕动波","上腹胀满不适","大量呕吐酸酵宿食","失水及代谢性碱中毒","有胃振水音"],"a":2,"e":"幽门梗阻因胃排空障碍，反复大量呕吐酸酵宿食且吐后舒适，是判断幽门梗阻最有意义的症状；振水音和蠕动波仅具提示作用。"},{"q":"下述临床诊断，根据诊断方式和步骤的不同又可分为下列各项，但应除外","o":["直接诊断","治疗试验诊断","鉴别诊断","确定诊断","确立诊断后分期和分型诊断"],"a":1,"e":"临床诊断按方式与步骤可分为直接诊断、鉴别诊断、确定诊断及确立诊断后的分期分型诊断，不含“治疗试验诊断”。"},{"q":"长期使用解热药或激素类药后，常出现的热型是","o":["消耗热","不规则热","回归热","稽留热","弛张热"],"a":1,"e":"长期应用解热药或糖皮质激素可使某些疾病的特征性热型变得不典型，或转为体温曲线无一定规律的不规则热。"},{"q":"咳嗽伴双肺哮鸣音常见于","o":["支气管扩张症","急性上呼吸道感染","肺淤血","支气管哮喘","肺脓肿"],"a":3,"e":"咳嗽伴双肺弥漫性哮鸣音提示广泛气道痉挛，最常见于支气管哮喘，也见于心源性哮喘和慢性阻塞性肺疾病。"},{"q":"患者对红霉素过敏应记录于","o":["现病史","既往史","个人史","家族史","入院诊断"],"a":1,"e":"药物过敏史属既往史内容，既往史还包括既往健康状况、传染病史、预防接种史、手术外伤史及输血史。"},{"q":"腰背痛伴有右上腹痛最常见的疾病是","o":["胸膜炎","急性胆囊炎","肺结核","支气管扩张","颈椎病"],"a":1,"e":"急性胆囊炎疼痛位于右上腹，可向右肩背部放射，故右上腹痛伴腰背痛最常见于急性胆囊炎；胰腺炎多为左上腹及左侧腰背痛。"},{"q":"健康人的血涂片进行瑞氏染色后，见到的白细胞中最多的是","o":["单核细胞","中性粒分叶核细胞","中性粒杆状核细胞","淋巴细胞","嗜酸性粒细胞"],"a":1,"e":"健康成人外周血白细胞以中性粒细胞为主，占50%～70%，其中分叶核粒细胞最多，淋巴细胞约占20%～40%。"},{"q":"最常引起意识障碍的内分泌与代谢障碍性疾病是","o":["妊娠中毒症","癫痫","高血压脑病","低氯性碱中毒","高原病"],"a":0,"e":"内分泌与代谢障碍所致意识障碍包括尿毒症、肝性脑病、低血糖及妊娠高血压综合征等，后者即妊娠中毒症，可因子痫而昏迷。"},{"q":"正常人听诊可闻及的声音，除了","o":["第一心音","肱动脉血流音","呼吸音","肠鸣音","第三心音"],"a":1,"e":"正常人可闻及第一、第二心音，青少年可闻第三心音，以及呼吸音和肠鸣音；肱动脉血流音仅在袖带压迫测压时出现。"},{"q":"以下不属于中性粒细胞反应性增多的是","o":["病毒性肝炎","铜绿假单胞菌败血症","心肌梗死","急性溶血","尿毒症"],"a":0,"e":"病毒性肝炎时白细胞总数与中性粒细胞常减少；铜绿假单胞菌败血症、心肌梗死、急性溶血和尿毒症均可致中性粒细胞反应性增多。"},{"q":"下列哪项是肝硬化门静脉高压的临床表现","o":["下肢水肿","蜘蛛痣","黄疸","食管-胃底静脉曲张","肝大"],"a":3,"e":"门静脉高压的三大表现是脾大、侧支循环建立与开放及腹水，食管胃底静脉曲张属最重要的侧支循环；蜘蛛痣、黄疸、肝大不是其特异表现。"},{"q":"下列哪种疾病时血小板减少属于血小板生成障碍","o":["系统性红斑狼疮（SLE）","过敏性药物损伤","脾大","弥散性血管内凝血","再生障碍性贫血"],"a":4,"e":"再生障碍性贫血因骨髓造血功能衰竭致血小板生成减少；SLE、药物免疫损伤、DIC为破坏或消耗增多，脾大属分布异常。"},{"q":"引起反射性呕吐的病因包括下列疾病，但除外","o":["急性胃肠炎","青光眼","尿毒症","急性心肌梗死","泌尿系结石"],"a":2,"e":"尿毒症时毒素蓄积刺激延髓呕吐中枢，属中枢性呕吐；急性胃肠炎、青光眼、急性心肌梗死和泌尿系结石均经反射途径引起呕吐。"},{"q":"Austin Flint杂音可发生于下列哪种疾病","o":["动脉导管未闭","肺动脉瓣狭窄","肺动脉瓣关闭不全","主动脉瓣狭窄","主动脉瓣关闭不全"],"a":4,"e":"中重度主动脉瓣关闭不全时反流血液限制二尖瓣开放，形成相对性二尖瓣狭窄，于心尖区产生Austin Flint杂音。"},{"q":"下列哪项不是血小板功能试验","o":["血块退缩试验","血小板黏附试验","血小板聚集试验","血小板计数","PF3有效性检测"],"a":3,"e":"血小板计数反映血小板数量，属数量检测；血块退缩试验、黏附试验、聚集试验和PF3有效性检测均反映血小板功能。"},{"q":"急性内脏穿孔引起急性弥漫性腹膜炎的腹痛特点为","o":["全腹持续性剧烈疼痛","阵发性绞痛","钻顶样疼痛","烧灼样疼痛","间歇性钝痛"],"a":0,"e":"急性内脏穿孔后胃肠内容物进入腹腔刺激腹膜，引起全腹持续性剧烈疼痛，伴腹壁板样强直、压痛及反跳痛。"},{"q":"胸腔积液患者的胸膜摩擦音消失提示","o":["胸腔积液增多","胸腔积液减少","胸腔积液不变","出现肺炎","胸腔积液完全消失"],"a":0,"e":"胸腔积液增多时脏、壁两层胸膜被液体分开，胸膜摩擦音随之消失，胸痛亦减轻，故摩擦音消失提示积液增多。"},{"q":"成年女性尿中易见","o":["小圆细胞","表层移行上皮细胞","中层移行上皮细胞","底层移行上皮细胞","扁平上皮细胞"],"a":4,"e":"成年女性尿液镜检可见3～5个/HPF鳞状（扁平）上皮细胞，来自尿道外口及阴道分泌物污染，属正常现象。"},{"q":"下列疾病均出现脾浊音区扩大，但除外","o":["胰腺炎","肝硬化","肝癌","柏-查综合征","慢性粒细胞白血病"],"a":0,"e":"胰腺炎不引起脾脏肿大，故脾浊音区不扩大；肝硬化、肝癌、柏-查综合征及慢性粒细胞白血病均可致脾大而脾浊音区扩大。"},{"q":"慢性腹泻是指腹泻时间超过","o":["1个月","2个月","3个月","4个月","5个月"],"a":1,"e":"腹泻按病程长短分为急性与慢性两类，病程超过2个月者为慢性腹泻，2个月以内者为急性腹泻。"},{"q":"下列不属于大细胞性贫血的是","o":["叶酸、维生素B12缺乏所致巨幼细胞贫血","妊娠期所致巨幼细胞贫血","婴儿期所致巨幼细胞贫血","地中海贫血","恶性贫血"],"a":3,"e":"地中海贫血因珠蛋白合成障碍致小细胞低色素性贫血；叶酸或维生素B12缺乏所致巨幼细胞贫血、妊娠期及婴儿期巨幼细胞贫血和恶性贫血均属大细胞性贫血。"},{"q":"引起发热最常见的病因是","o":["真菌感染","恶性肿瘤","变态反应","细菌感染","病毒感染"],"a":3,"e":"发热病因以感染最常见，其中细菌感染占首位；病毒、真菌感染及恶性肿瘤、变态反应所致者相对较少。"},{"q":"以下可鉴别右心衰竭和肝硬化的体征是","o":["双下肢凹陷性水肿","肝颈静脉反流征阳性","肝大","脾大","腹水"],"a":1,"e":"右心衰竭时肝脏淤血肿大，压迫肝脏使回心血量增加，已充血的右心房不能接纳而使颈静脉压上升，故肝颈静脉回流征阳性，肝硬化则阴性。"},{"q":"梗阻性黄疸的表现不包括","o":["结合胆红素明显增高","非结合胆红素轻度增高","总胆红素明显增高","尿胆原增高","尿胆红素强阳性"],"a":3,"e":"梗阻性黄疸时结合胆红素反流入血使总胆红素明显升高、尿胆红素强阳性，但胆汁排入肠道受阻，尿胆原减少或消失。"},{"q":"下列因素对体温均有影响，除了","o":["妊娠","哺乳","月经","运动","进食"],"a":1,"e":"妊娠、月经周期变化、运动及进食均可使体温发生生理性波动，而哺乳对体温无明显影响。"},{"q":"下列关于听诊的叙述均正确，但除外哪一项","o":["听诊可分为直接听诊和间接听诊两种","听诊时环境要安静、温暖、避风","间接听诊法还可听取皮下气肿音、肌束颤动音等","膜型听诊器适用于听取低调声音","听诊器的体件要紧贴于被检查的部位"],"a":3,"e":"膜型听诊器能滤过低音调而适于听取高调声音，如主动脉瓣关闭不全的叹气样杂音；钟型体件才适用于低调的隆隆样杂音。"},{"q":"血清总胆固醇降低见于","o":["甲状腺功能减退症","冠心病","肾病综合征","贫血","妊娠期"],"a":3,"e":"贫血时脂质合成与转运减少，血清总胆固醇可降低；甲状腺功能减退、肾病综合征、冠心病和妊娠期均可使胆固醇升高。"},{"q":"前列腺位于膀胱下方，其位于耻骨联合后约","o":["1cm","2cm","3cm","4cm","5cm"],"a":2,"e":"官方答案为【3cm】，但依据教材，正确答案为【2cm】。前列腺位于膀胱下方、耻骨联合后约2cm处，形似前后稍扁的栗子，尿道从中纵行穿过。"},{"q":"下列有关发热概念的叙述，哪项正确","o":["体温超过正常值0、6℃","产热过程超过散热过程","是临床上常见的疾病","由体温调节中枢调定点上移引起的体温升高","由体温调节中枢调节功能障碍引起的体温升高"],"a":3,"e":"发热是致热原使体温调定点上移，体温调节中枢重新调节后产热增多、散热减少，致体温升高超出正常范围。"},{"q":"脾于肋下3cm，属于","o":["轻度肿大","中度肿大","高度肿大","巨脾","正常"],"a":1,"e":"脾缘超过肋下2cm但在脐水平线以上者为中度肿大，故肋下3cm属中度；不超过2cm为轻度，超过脐水平线或前正中线为高度肿大。"},{"q":"成年男性血红蛋白参考值为","o":["110～150g/L","120～160g/L","110～140g/L","120～150g/L","120～140g/L"],"a":1,"e":"成年男性血红蛋白参考值为120～160g/L，成年女性为110～150g/L，低于相应参考区间下限即为贫血。"},{"q":"下列为肺下界叩诊的正确描述，但应除外","o":["两侧肺下界大致相同","平静呼吸时位于锁骨中线上第6肋间隙","平静呼吸时位于腋中线上第8肋间隙","平静呼吸时位于肩胛线上第10肋间隙","体型和发育情况不同，肺下界位置无差异"],"a":4,"e":"正常肺下界在锁骨中线、腋中线、肩胛线上分别位于第6、8、10肋间隙，两侧大致相同，但可因体型和发育情况上下移动一个肋间。"},{"q":"直接作用于体温调节中枢引起发热的是","o":["病原体产生的外源性致热源","病原体产生的内源性致热源","血液中的白细胞产生的外源性致热源","血液中的白细胞产生的内源性致热源","血液中的白细胞及病原体产生的代谢产物"],"a":3,"e":"外源性致热原分子大，不能通过血脑屏障，需激活血液中中性粒细胞和单核巨噬细胞释放内源性致热原，后者直接作用于体温调节中枢。"},{"q":"出现下列哪项表现最可确诊为器质性心脏病","o":["心尖部第三心音","心前区震颤","心率120次/min","肺动脉瓣区第二心音分裂","心尖部收缩期吹风样杂音2/6级"],"a":1,"e":"震颤是器质性心血管病的特征性体征，触及震颤即可肯定心脏有器质性病变；第三心音、S2分裂和2/6级杂音均可见于正常人。"},{"q":"以下为血红蛋白测定值，其中符合极重度贫血的是","o":["＜30g/L","＜20g/L","＜40g/L","＜50g/L","＜10g/L"],"a":0,"e":"极重度贫血指血红蛋白低于30g/L，病人休息时即有心慌气短；30～59g/L为重度，60～90g/L为中度。"},{"q":"关于弛张热的描述，不正确的是","o":["又称败血症热型，常见于败血症、风湿热","体温常在39℃以上","波动幅度大","有时达正常水平","24小时内波动范围超过2℃"],"a":3,"e":"弛张热体温虽波动幅度大，但24小时内最低体温仍高于正常水平，不会降至正常，故“有时达正常水平”不符合。"},{"q":"肝颈静脉反流征阳性是由于","o":["腹主动脉搏动传导所致","右心室的收缩搏动通过右心房、下腔静脉传导","右心衰竭引起肝淤血","左心室收缩搏动","左心衰竭"],"a":2,"e":"右心衰竭时肝脏淤血肿大，压迫肝脏使回心血量增加，已充血的右心房不能接纳，颈静脉压被动上升，形成肝颈静脉回流征阳性。"},{"q":"下列可见到负性心尖冲动的是","o":["扩张型心肌病","严重贫血患者","肺气肿患者","粘连性心包炎","高血压心脏病"],"a":3,"e":"心脏收缩时心尖部胸壁内陷为负性心尖搏动，见于粘连性心包炎或心包与周围组织广泛粘连，重度右室肥厚亦可引起。"},{"q":"消瘦的含义正确的是","o":["体重减轻到低于正常的5%","体重减轻到低于正常的10%","体重减轻到低于正常的15%","体重减轻到低于正常的20%","体重减轻到低于正常的25%"],"a":1,"e":"消瘦指体重低于标准体重的10%，或体质指数＜18.5kg/m²，由摄食不足、消耗增多或代谢异常所致。"},{"q":"关于急性白血病特点的叙述，下列中不符合的是","o":["大多起病急骤","每有发热、贫血、出血表现","血浆中血小板大都减少","骨髓中主要是接近成熟阶段细胞","骨髓中原幼细胞恶性变明显"],"a":3,"e":"急性白血病骨髓增生极度活跃，以原始细胞及早幼细胞为主，接近成熟阶段的细胞明显减少，故该项不符。"},{"q":"对下面心电图诊断正确的是","o":["左房增大","右房增大","左室肥厚","右室肥厚","心电图正常"],"a":2,"e":"官方题库缺失图片"},{"q":"高位小肠梗阻的特点是","o":["腹部可见明显肠型","腹胀明显","呕吐频繁","水电解质紊乱出现较慢","呕吐物常有粪臭"],"a":2,"e":"高位小肠梗阻呕吐出现早而频繁，呕吐量大，可含胆汁；低位梗阻呕吐出现晚，腹胀明显，呕吐物常有粪臭。"},{"q":"下列凝血因子在转变为活化凝血因子过程中不需要Ca2＋参与的是","o":["Ⅻ→Ⅻa","Ⅺ→Ⅺa","Ⅹ→Ⅹa","Ⅱ→Ⅱa","ⅩⅢ→ⅩⅢa"],"a":0,"e":"因子Ⅻ接触激活不需钙离子参与；Ⅺ→Ⅺa、Ⅹ→Ⅹa、Ⅱ→Ⅱa及ⅩⅢ→ⅩⅢa均需钙离子作为辅因子。"},{"q":"腹腔渗出液常见于以下哪种疾病","o":["慢性心功能不全","结核性腹膜炎","重度营养不良","肾病综合征","肝硬化"],"a":1,"e":"结核性腹膜炎为炎症性病变，腹腔积液属渗出液；慢性心功能不全、重度营养不良、肾病综合征和肝硬化所致腹水均为漏出液。"},{"q":"鸡鸣样咳嗽见于","o":["纵隔肿瘤","严重肺气肿","声带麻痹","肺肿瘤压迫喉返神经","百日咳"],"a":4,"e":"鸡鸣样咳嗽为连续阵发性剧咳伴高调吸气回声，多见于百日咳，也见于会厌、喉部疾病或气管受压者。"},{"q":"临床诊断思维的基本原则，下列错误的是","o":["实事求是","“一元论”原则","“首先考虑少发病”的原则","“首先考虑器质性疾病存在”的原则","“首先考虑可治疾病的诊断”的原则"],"a":2,"e":"诊断思维应首先考虑常见病、多发病，而不是少发病；此外还有“一元论”、先考虑器质性疾病和可治性疾病的原则。"},{"q":"内源性致热原的作用部位是","o":["中性粒细胞","下丘脑体温调节中枢","骨骼肌","皮肤","外周血管"],"a":1,"e":"内源性致热原经血-脑脊液屏障直接作用于下丘脑体温调节中枢的体温调定点，使其上移而引起发热。"},{"q":"引起腹痛的胃肠神经功能紊乱见于下列疾病，但除外","o":["功能性消化不良","胃神经官能症","慢性胰腺炎","胆道运动功能障碍","肠易激综合征"],"a":2,"e":"慢性胰腺炎属腹腔脏器慢性炎症，为器质性病变；功能性消化不良、胃神经官能症、胆道运动功能障碍及肠易激综合征均属胃肠神经功能紊乱。"},{"q":"血浆凝血酶原时间明显延长缺乏的凝血因子是","o":["Ⅰ、Ⅱ、Ⅴ、Ⅶ、Ⅷ","Ⅰ、Ⅱ、Ⅴ、Ⅶ、Ⅸ","Ⅰ、Ⅱ、Ⅴ、Ⅶ、Ⅹ","Ⅰ、Ⅱ、Ⅴ、Ⅶ、Ⅺ","Ⅰ、Ⅱ、Ⅴ、Ⅷ、Ⅻ"],"a":2,"e":"PT反映外源性凝血途径，延长见于因子Ⅱ、Ⅴ、Ⅶ、Ⅹ缺乏及低纤维蛋白原血症，故涉及Ⅰ、Ⅱ、Ⅴ、Ⅶ、Ⅹ。"},{"q":"正常体温在24小时内波动范围一般不超过","o":["0.5℃","1.0℃","1.5℃","2.0℃","2.5℃"],"a":1,"e":"正常体温受昼夜节律、运动、进餐等因素影响而波动，24小时内波动幅度一般不超过1℃。"},{"q":"关于鼻咽部的描述，下列哪项是错误的","o":["鼻咽位于软腭平面之上、鼻腔后方","儿童期，鼻咽部淋巴结组织丰富","儿童期后，腺样体逐渐萎缩","腺样体过度肥大，可导致语音单调","鼻咽部一侧有血性分泌物和耳鸣、耳聋，应考虑鼻咽癌"],"a":2,"e":"腺样体在儿童期增生明显，至青春期前后才逐渐萎缩，并非儿童期后即萎缩；过度肥大可引起鼻塞、张口呼吸和语音单调。"},{"q":"心包摩擦音不会出现于","o":["肺动脉栓塞","室间隔穿孔","心室壁破裂","心肌梗死后综合征","纤维素性心包炎"],"a":1,"e":"室间隔穿孔产生胸骨左缘3～4肋间粗糙全收缩期杂音伴震颤，不产生心包摩擦音；后者见于纤维素性心包炎、急性心肌梗死及梗死后综合征等。"},{"q":"胆红素在肝内的结合主要是指","o":["与白蛋白的结合","与葡萄糖醛酸的结合","与硫酸基的结合","与甘氨酸甲基的结合","与Y或Z胞浆载体的结合"],"a":1,"e":"非结合胆红素入肝后经葡萄糖醛酸转移酶催化，与葡萄糖醛酸结合形成结合胆红素；与白蛋白结合仅是其血中运输形式。"},{"q":"易合并肢端肥大症的疾病是","o":["腺垂体功能亢进","风湿性心脏病","先天性心脏病","支气管扩张","慢性肺脓肿"],"a":0,"e":"腺垂体功能亢进使生长激素分泌过多，骨骺未闭者表现为巨人症，骨骺闭合后则表现为肢端肥大症。"},{"q":"肌力检查记录分（ ）个等级","o":["5","2","3","4","6"],"a":4,"e":"肌力采用0～5级共6个等级记录，0级为完全瘫痪、无肌肉收缩，5级为正常肌力，3级可抗重力但不能抗阻力。"},{"q":"关于心脏听诊，说法正确的是","o":["心脏瓣膜听诊区就是瓣膜的解剖部位所在区域","钟型听诊体件更适宜听高音调的杂音","主动脉瓣舒张期叹气样杂音更适宜用模型体件听诊","心脏听诊区域对每个个体都是固定不变的","怀疑二尖瓣狭窄患者取坐位前倾位更易闻及"],"a":2,"e":"膜型体件能滤过低音调而适于听取高调杂音，主动脉瓣舒张期叹气样杂音属高调，故宜用膜型；钟型体件用于二尖瓣隆隆样杂音。"},{"q":"下列指标可诊断伤寒、副伤寒的是","o":["TO＞1∶80，TH＜1∶160，甲、乙、丙H凝集价＜1∶80","TO＞1∶80，TH＞1∶160，甲、乙、丙H凝集价＞1∶80","TO＞1∶80，TH＜1∶160，甲、乙、丙H凝集价＞1∶80","TO＜1∶80，TH＜1∶160，甲、乙、丙H凝集价＜1∶80","TO＜1∶80，TH＜1∶160，甲、乙、丙H凝集价＞1∶80"],"a":1,"e":"伤寒O抗体效价＞1∶80且H＞1∶160有诊断意义，副伤寒甲、乙、丙H抗体＞1∶80支持相应诊断，故该组合可诊断伤寒、副伤寒。"},{"q":"下列疾病可出现Kussmaul呼吸的是","o":["贫血","左心衰竭","右心衰竭","酮症酸中毒","吗啡中毒"],"a":3,"e":"严重代谢性酸中毒时细胞外液碳酸氢根不足、pH降低，肺脏代偿性深大呼吸以排出CO2，即Kussmaul呼吸，见于糖尿病酮症酸中毒和尿毒症酸中毒。"},{"q":"关于梨形心，下列说法正确的是","o":["可见于高血压患者","可见于升主动脉扩张","心腰凹陷，加深明显","同左心房扩大有关","以胸骨右缘心界扩大为主"],"a":3,"e":"梨形心即二尖瓣型心，由左心房增大、肺动脉段突出使心腰消失、心浊音界向左扩大所致，见于二尖瓣狭窄。"},{"q":"下列可以传导颅内外痛觉的脑神经是","o":["第1/2对脑神经","第3/4/7对脑神经","第6/7/8对脑神经","第5/9/10对脑神经","第11/12对脑神经"],"a":3,"e":"传导颅内外痛觉的脑神经主要是三叉神经、面神经、舌咽神经和迷走神经，即第Ⅴ、Ⅶ、Ⅸ、Ⅹ对，故第5/9/10对正确。"},{"q":"对骨关节炎描述错误的是","o":["多见于中老年人","晨僵时间常大于60min","爬楼、久站后疼痛加剧","休息能缓解疼痛","好发于负重较大的关节，如膝关节、髋关节"],"a":1,"e":"骨关节炎晨僵时间短，一般不超过30分钟；晨僵超过60分钟是类风湿关节炎的特点，故该项描述错误。"},{"q":"对触觉较为敏感的部位是","o":["手指指腹","掌指关节面掌部","手背皮肤","小鱼际","大鱼际"],"a":0,"e":"手指指腹对触觉最敏感，掌指关节部掌面皮肤对震动敏感，手背皮肤对温度敏感，触诊时应合理选用部位。"},{"q":"心尖部触及舒张期震颤，最常见于","o":["法洛四联症","二尖瓣狭窄","二尖瓣脱垂","室间隔缺损","三尖瓣狭窄"],"a":1,"e":"心尖区舒张期震颤提示二尖瓣狭窄，因舒张期血流经狭窄瓣口产生漩涡；收缩期震颤则见于重度二尖瓣关闭不全。"},{"q":"下列为血管内液与组织液之间保持动态平衡的主要因素，但应除外","o":["毛细血管血压","血浆胶体渗透压","毛细血管通透性","组织液静水压","组织液的胶体渗透压"],"a":2,"e":"血管内外液体交换取决于毛细血管血压、血浆胶体渗透压、组织液静水压和组织液胶体渗透压四种力量；毛细血管通透性属屏障特性，不是压力平衡因素。"},{"q":"肝颈静脉回流征是指","o":["用手压迫肝，使颈静脉怒张消失","用手压迫肝，使颈静脉怒张明显","用手压迫肝，颈静脉怒张无改变","用手压迫肝，颈静脉出现搏动","用手压迫肝，颈静脉出现震颤"],"a":1,"e":"肝颈静脉回流征指压迫肿大的肝脏后颈静脉怒张更明显，停止压迫后迅速下降，是右心衰竭体循环淤血的表现。"},{"q":"导致脉压增大的疾病是","o":["主动脉瓣狭窄","心力衰竭","低血压","主动脉瓣关闭不全","缩窄性心包炎"],"a":3,"e":"主动脉瓣关闭不全时舒张期血液反流使舒张压下降、收缩压升高，脉压增大；主动脉瓣狭窄、心衰、低血压及缩窄性心包炎均使脉压减小。"},{"q":"下列可引起混合性呼吸困难的是","o":["气管异物","喉痉挛","慢性阻塞性肺气肿","支气管哮喘","重症肺炎"],"a":4,"e":"重症肺炎因肺实质广泛病变使通气与换气功能同时受损，属混合性呼吸困难；气管异物、喉痉挛为吸气性，哮喘和肺气肿为呼气性。"},{"q":"神经浅反射不包括","o":["角膜反射","腱反射","提睾反射","跖反射","肛门反射"],"a":1,"e":"浅反射包括角膜反射、腹壁反射、提睾反射、跖反射和肛门反射；腱反射由肌腱深部感受器完成，属深反射。"},{"q":"主动脉瓣听诊区第二心音减弱，最常见于","o":["主动脉瓣狭窄","二尖瓣狭窄","高血压","主动脉粥样硬化","肺动脉瓣狭窄"],"a":0,"e":"主动脉瓣狭窄时主动脉瓣钙化、活动受限，A2减弱；高血压和主动脉粥样硬化则因主动脉内压增高使A2亢进。"},{"q":"下列关于消化性溃疡的症状均正确，但除外","o":["上腹痛","恶心呕吐","食欲缺乏","反酸嗳气","腹泻"],"a":4,"e":"消化性溃疡以上腹痛为主要症状，常伴反酸、嗳气、恶心呕吐和食欲缺乏；腹泻不属于其典型表现。"},{"q":"胸骨左缘第3～4肋间触及收缩期震颤，最常见的是","o":["房间隔缺损","动脉导管未闭","室间隔缺损","二尖瓣脱垂","二尖瓣关闭不全"],"a":2,"e":"胸骨左缘第3～4肋间收缩期震颤提示室间隔缺损，因左向右分流产生粗糙收缩期杂音伴震颤；动脉导管未闭为连续性震颤。"},{"q":"单纯性紫癜导致皮肤黏膜出血的机制是","o":["血小板数量和/或功能异常","毛细血管壁缺陷","凝血因子缺陷","抗凝物质增加","纤维蛋白溶解亢进"],"a":1,"e":"单纯性紫癜因毛细血管壁先天性或获得性缺陷，使血管不能正常收缩止血而出现皮肤黏膜出血，血小板数量和凝血因子均正常。"},{"q":"以下味觉检查方法有误的是","o":["应用不同味觉物质测试","避免有害物质进行测试","每次检查先检查患侧","每次检查先检查正常侧","患者不能讲话"],"a":3,"e":"味觉检查应先测患侧再测健侧，以免健侧结果影响判断；每次测试后需漱口，病人不能讲话，以手势示意所感受的味觉。"},{"q":"以下不符合左心衰竭心脏体征的是","o":["心脏扩大","相对性二尖瓣关闭不全的反流性杂音","肺动脉瓣区第二心音亢进","舒张期奔马律","收缩期奔马律"],"a":4,"e":"左心衰竭可闻舒张早期奔马律，而非收缩期奔马律，后者不是左心衰体征；心脏扩大、相对性二尖瓣关闭不全杂音及P2亢进均可见于左心衰。"},{"q":"S2固定分裂见于哪种疾病","o":["二尖瓣关闭不全","室间隔缺损","房间隔缺损","动脉导管未闭","法洛四联症"],"a":2,"e":"S2固定分裂指分裂的两个成分时距不受呼吸影响，见于房间隔缺损，因左向右分流使右心血流持续增加、肺动脉瓣关闭延迟。"},{"q":"血小板破坏或消耗亢进，不包括","o":["系统性红斑狼疮","弥散性血管内凝血","病毒感染","先天性血小板减少症","慢性粒细胞性白血病"],"a":4,"e":"慢性粒细胞白血病时血小板多正常或增多，不属于破坏或消耗亢进；SLE、DIC、病毒感染及先天性血小板减少症均可致血小板破坏或消耗增多。"},{"q":"脾脏高度肿大时，脾脏大小为","o":["脾缘超过左肋下2cm以上","脾缘超过左肋下5cm以上","脾缘刚达到脐平","脾缘超过前正中线","脾缘超过左肋下6cm以上"],"a":3,"e":"脾缘超过脐水平线或前正中线为高度肿大即巨脾；超过肋下2cm但在脐水平线以上为中度，不超过2cm为轻度。"},{"q":"急性心包炎的诊断最具特征性的体征是","o":["心界随体位而变","心音减弱","奇脉","大循环淤血征","心包摩擦音"],"a":4,"e":"急性心包炎时纤维蛋白渗出使心包膜粗糙，心脏搏动产生心包摩擦音，为最具特征性的体征，积液增多后反而消失。"},{"q":"膀胱刺激征是指","o":["尿频、尿急、尿痛","血尿、尿频、尿急","脓尿、尿急、尿频","尿频、尿痛、脓尿","尿频、尿痛、血尿"],"a":0,"e":"尿频、尿急、尿痛三者合称膀胱刺激征，因膀胱及尿道黏膜受炎症或理化刺激所致，最常见于膀胱炎和尿道炎；若同时有腰痛、高热，多为肾盂肾炎。"},{"q":"尿三杯试验中如第一杯为血尿，则病变部位在","o":["前尿道","后尿道","膀胱三角区","输尿管","肾脏"],"a":0,"e":"起始段血尿提示出血来自前尿道，终末段血尿多源于膀胱颈和后尿道，全程血尿则提示肾或输尿管出血，据此可粗略定位。"},{"q":"下列疾病均表现为干性咳嗽，除外","o":["急性咽喉炎","慢性支气管炎","胸膜炎","轻症肺结核","急性支气管炎初期"],"a":1,"e":"干性咳嗽指无痰或痰量甚少的咳嗽，见于急性咽喉炎、胸膜炎、轻症肺结核和急性支气管炎初期；慢性支气管炎气道分泌物多，表现为湿性咳嗽。"},{"q":"关于正常心脏浊音界的叙述，下列正确的是","o":["心左界在第2肋间几乎与胸骨左缘一致","心右界在第5肋间处稍偏离胸骨右缘","在第3肋间心左界与前正中线距离3～4cm","在第4肋间心右界与前正中线距离4～5cm","在第5肋间心左界与前正中线距离8～10cm"],"a":0,"e":"正常心左界自第2肋间起向外形成内凹弧形，第2肋间几乎与胸骨左缘重合；右界各肋间基本与胸骨右缘一致，仅第4肋间稍超出。"},{"q":"下列各项是腹部触诊内容，但除外","o":["腹壁肌紧张","压痛与反跳痛","腹部肿块","移动性浊音","振水音"],"a":3,"e":"移动性浊音靠叩诊比较体位改变前后的浊音区变动，属叩诊内容；腹壁紧张度、压痛反跳痛、肿块及振水音才是触诊项目。"},{"q":"主动脉瓣狭窄时，心脏最主要的代偿机制是","o":["心率加快","左心室肥厚","回心血量增加","左心室扩张","交感神经兴奋"],"a":1,"e":"主动脉瓣狭窄使左室排血受阻，压力负荷增高，心肌纤维呈向心性肥厚以维持射血，故左心室肥厚是最主要的代偿机制。"},{"q":"患者，女，22岁。因“腹泻3天”入院。在问诊伴随症状时，还应关注除外","o":["有无呕吐","有无腹痛","有无胸痛","有无发热","有无里急后重"],"a":2,"e":"腹泻的伴随症状应围绕消化系统，询问呕吐、腹痛、里急后重和发热有助鉴别病因；胸痛属呼吸循环系统症状，与腹泻无直接关联。"},{"q":"下列是关于色觉的正确叙述，但应除外哪一项","o":["色觉的异常可分为色弱和色盲两种","色盲是对颜色识别能力的丧失","色弱是对颜色识别能力的减弱","色觉的检查被列为检体的常规项目之一","色盲为先天性遗传性疾病"],"a":4,"e":"色盲分先天性与后天性，先天性者才属遗传性疾病，以红绿色盲最常见；后天性可由视神经或视网膜病变引起，故不能一概而论。"},{"q":"关于消化道出血，下列叙述正确的是","o":["呕血血中混有物呈碱性","上消化道出血不包括胰腺出血","鼻腔出血咽下后呕出亦称为呕血","消化性溃疡呕血后疼痛减轻","呕血后不一定有便血"],"a":3,"e":"消化性溃疡出血后胃酸被中和、溃疡局部张力降低，上腹痛随之减轻，这是其出血的典型特点；食管静脉曲张破裂则无此规律。"},{"q":"胸骨左缘第二肋间连续性机械样杂音最常见于","o":["主动脉瘤破裂","动静脉瘘","动脉导管未闭","主肺动脉间隔缺损","升主动脉夹层动脉瘤"],"a":2,"e":"动脉导管未闭时主动脉压力高于肺动脉，血液连续分流，于胸骨左缘第2肋间产生粗糙的连续性机器样杂音，常伴震颤。"},{"q":"心肌缺血时不可能的心电图改变是","o":["ST段抬高","ST段压低","T波高尖","T波倒置","P-R间期缩短"],"a":4,"e":"心肌缺血主要表现为ST段压低或抬高、T波高尖或倒置；PR间期缩短反映房室传导加速，见于预激综合征，与缺血无关。"},{"q":"Traube区叩诊音应为下列哪项","o":["清音","过清音","鼓音","浊鼓音","空瓮音"],"a":2,"e":"Traube区即胃泡鼓音区，位于左腋前线下方，由胃底含气形成，正常叩诊呈鼓音，其缩小或消失提示胃内含气减少或局部病变。"},{"q":"以下疾病不会引起多尿性尿频的是","o":["应用利尿剂","尿崩症","急性肾衰竭多尿期","糖尿病","淋菌性尿道炎"],"a":4,"e":"多尿性尿频每次尿量不少且总尿量增多，见于糖尿病、尿崩症、精神性多饮及急性肾衰竭多尿期；淋菌性尿道炎属炎症性尿频，每次尿量少。"},{"q":"机体的止血功能是由四大系统共同完成的，四大系统分别是","o":["血小板、凝血系统、血管内皮系统、纤溶系统","血小板、凝血系统、血管内皮系统、抗凝系统","血小板、凝血系统、抗凝系统、纤溶系统","凝血系统、抗凝系统、纤溶系统、血管内皮系统","血小板、抗凝系统、纤溶系统、血管内皮系统"],"a":0,"e":"止血有赖血管内皮收缩、血小板黏附聚集、凝血系统形成纤维蛋白以及纤溶系统溶解血栓，四者动态平衡方能维持血流通畅。"},{"q":"一临床医师给患者进行了一系列神经系统查体，不属于脑神经检查内容的是","o":["视力检查","瞳孔检查","咽反射检查","胸锁乳突肌力量检查","肩部肌肉力量检查"],"a":4,"e":"肩部肌肉力量主要由腋神经支配的三角肌完成，不属脑神经检查；视力、瞳孔属视神经与动眼神经，咽反射属舌咽、迷走神经，胸锁乳突肌属副神经。"},{"q":"关于舌下神经检查，下列叙述哪项正确","o":["嘱患者张口发“a”音，观察两侧软腭上抬是否有力","嘱患者伸舌，观察有无偏斜","观察患者腭垂是否居中","观察鼻唇沟及口角两侧是否对称","检查患者是否吞咽困难、饮水呛咳"],"a":1,"e":"舌下神经支配舌肌，检查时嘱伸舌观察有无偏斜与舌肌萎缩，单侧麻痹舌尖偏向病侧；软腭上抬、腭垂居中属舌咽迷走神经检查。"},{"q":"溃疡性结肠炎的内镜下表现是","o":["黏膜广泛充血、水肿、糜烂，表面有脓苔","跳跃式分布的纵形或匍行性深溃疡","黏膜呈鹅卵石样增生，肠腔明显狭窄","黏膜隆起呈息肉状、有蒂","黏膜破裂出血"],"a":0,"e":"溃疡性结肠炎病变自直肠连续向近端蔓延，黏膜弥漫充血水肿、糜烂或浅溃疡并覆脓苔；跳跃式纵行深溃疡为克罗恩病特征。"},{"q":"关于甲状腺的检查，说法错误的是","o":["观察甲状腺的大小及对称性","触诊比视诊更能明确甲状腺的轮廓及病变的性质","当触及甲状腺肿大时，选用钟型听诊器直接放在肿大的甲状腺上进行听诊","被检查者双手放于枕后，头后仰的动作不利于甲状腺的观察","触诊甲状腺侧叶时，应配合被检查者吞咽动作，重复检查"],"a":3,"e":"两手放于枕后、头后仰可使甲状腺更贴近体表、随吞咽上移更明显，利于观察；该体位是暴露甲状腺的常规方法而非不利因素。"},{"q":"以下情况可以做结肠镜检查的是","o":["急性肠道感染","严重的肺功能不全者","大量便鲜血者","肠粘连者","精神、心理原因不能配合检查者"],"a":2,"e":"下消化道出血原因未明、需明确便血来源时可行结肠镜；急性肠道感染、严重心肺功能不全、肠粘连及不能配合者属禁忌或暂缓。"},{"q":"可反映外周红细胞大小不一的参数是","o":["RDW","MCV","MCH","MCHC","Hb"],"a":0,"e":"RDW即红细胞体积分布宽度，反映外周血红细胞体积的异质性，增大提示大小不一；MCV、MCH、MCHC只描述平均值。"},{"q":"下列各项均是肝硬化门静脉高压的表现，但除外","o":["脾大及脾功亢进","脐周及腹壁静脉曲张","腹水","黄疸","食管-胃底静脉曲张"],"a":3,"e":"门静脉高压表现为脾大伴脾功能亢进、腹水、食管胃底静脉曲张及腹壁静脉曲张；黄疸由肝细胞损害或胆汁淤积引起，属肝功能减退。"},{"q":"不属于现病史内容的是","o":["手术史","起病时的情况","病情的发展与演变","主要症状及伴随症状","诊治经过"],"a":0,"e":"现病史包括起病情况、主要症状特点及伴随症状、病情发展与演变、诊治经过；手术史属既往史，应单独记录。"},{"q":"无尿是指24小时尿量","o":["0ml","＜50ml","＜100ml","＜150ml","＜400ml"],"a":2,"e":"24小时尿量少于100ml或12小时完全无尿称无尿，少于400ml为少尿，超过2500ml为多尿，均以24小时总量计。"},{"q":"下列能鉴别腹壁肿块的是","o":["患者仰卧抬头","侧卧抬头","站立抬头","平卧低头","侧卧低头"],"a":0,"e":"嘱病人仰卧屈颈抬肩使腹肌紧张，肿块更明显者位于腹壁，变得不明显或消失者位于腹腔内，被收缩的腹肌掩盖。"},{"q":"下列出现腹腔积液的是","o":["卵巢囊肿","畸胎瘤","足月妊娠","人工气腹","结核性腹膜炎"],"a":4,"e":"结核性腹膜炎因腹膜渗出而产生腹水，属真性腹腔积液；卵巢囊肿、妊娠、人工气腹及巨大肿瘤属假性膨隆，叩诊无移动性浊音。"},{"q":"需保温保湿立即送检的临床标本是","o":["可疑细菌性痢疾患者的脓血便","可疑肺结核患者的痰","可疑肾盂肾炎患者的中段尿","可疑流行性脑脊髓膜炎患者的脑脊液","可疑败血症患者的血液"],"a":3,"e":"脑脊液标本采集后应立即送检并注意保温保湿，防止细胞破坏和细菌死亡；流脑时脑脊液中的脑膜炎奈瑟菌对外界抵抗力弱，尤须如此。"},{"q":"肉眼血尿时，一般每升尿内含血量超过","o":["5ml","3ml","1ml","0.5ml","0.1ml"],"a":2,"e":"每升尿液含血量超过1ml时外观即呈淡红色洗肉水样，称肉眼血尿；仅镜检发现红细胞增多而外观正常者为镜下血尿。"},{"q":"下列不是感染性发热的是","o":["肺炎发热","外伤发热","上感发热","无菌性坏死组织吸收热","疟疾发热"],"a":3,"e":"感染性发热由病原微生物及其毒素等外源性致热原引起；无菌性坏死组织吸收热属致热原性发热中的非感染类型。"},{"q":"出血时间（Duke法）异常是","o":["＞3分","＞4分","＞5分","＞6分","＞7分"],"a":1,"e":"Duke法出血时间正常为1～3分钟，超过4分钟为异常，反映血小板数量、功能及血管壁的止血能力。"},{"q":"下列胸部听诊方法的描述错误的是","o":["被检者取坐位或卧位","听诊一般由肺尖开始自上而下检查","前后顺序为前胸部、侧胸部和背部","检查时要上下、左右对称部位进行对比","被检者闭口作均匀呼吸"],"a":4,"e":"听诊时受检者应微张口作均匀呼吸，必要时作较深呼吸或咳嗽后立即听诊，闭口呼吸会使呼吸音减弱、影响判断。"},{"q":"下列疾病中，经常见到心悸伴胸痛，但应除外","o":["心绞痛","肺梗死","心包炎","大叶性肺炎","心功能不全"],"a":4,"e":"心悸伴胸痛见于心绞痛、急性心肌梗死、心包炎、肺梗死及大叶性肺炎等；心功能不全以心悸伴呼吸困难、双下肢水肿为特点。"},{"q":"冲击触诊法，检查者以三四个并拢的手指放于腹壁上的相应部位，与腹壁的角度是","o":["30°～50°","50°～70°","70°～90°","90°～110°","110°～130°"],"a":2,"e":"冲击触诊以右手并拢的示、中、环三指取70°～90°角置于腹壁，作数次急速有力的冲击，指端可感到脏器或包块浮沉。"},{"q":"下列各项均可引起肝浊音界扩大，但除外","o":["肝癌","肝炎后肝硬化","多囊肝","右心功能不全","酒精性肝硬化"],"a":1,"e":"肝浊音界扩大见于肝癌、肝脓肿、病毒性肝炎、肝淤血和多囊肝；肝硬化因纤维化萎缩使肝浊音界缩小。"},{"q":"下列关于前列腺检查的内容，错误的是","o":["被检查者取肘膝卧位","检查者以示指进行肛诊，向背侧触诊","正常成人前列腺质韧，有弹性","前列腺分左、右两叶，之间可触及正中沟","前列腺肥大时正中沟消失"],"a":1,"e":"直肠指诊触及前列腺后应向腹侧触诊，而非背侧；正常前列腺质韧有弹性，左右两叶间可触及正中沟，肥大时沟变浅或消失。"},{"q":"下列关于凝血因子描述正确的是","o":["正常人血浆中有14种凝血因子","依赖维生素K凝血因子包括Ⅱ、Ⅴ、Ⅸ、Ⅹ","PT延长代表凝血因子Ⅱ、Ⅴ、Ⅶ、Ⅹ的活性低于正常或抗凝物质的存在","内、外源性凝血系统形成凝血活酶时都需要因子Ⅷ的参与","因子Ⅶ和因子Ⅴ主要存在于正常人新鲜血清中"],"a":2,"e":"PT为外源性凝血系统筛选试验，延长提示因子Ⅱ、Ⅴ、Ⅶ、Ⅹ活性减低或存在抗凝物质；依赖维生素K的是Ⅱ、Ⅶ、Ⅸ、Ⅹ，不含因子Ⅴ。"},{"q":"内生性致热原不包括","o":["炎性渗出物","IL-1","干扰素","IL-6","TNF"],"a":0,"e":"内源性致热原为白细胞介素-1、肿瘤坏死因子、干扰素及白细胞介素-6等细胞因子；炎性渗出物属外源性致热原。"},{"q":"在细胞质中出现粗大、圆而均匀，呈橘红色染色颗粒的白细胞为","o":["中性粒分叶核细胞","嗜酸性粒细胞","淋巴细胞","单核细胞","嗜碱性粒细胞"],"a":1,"e":"嗜酸性粒细胞胞质充满粗大、整齐均匀、紧密排列的橘红色颗粒，与嗜碱性粒细胞的粗大紫黑色颗粒易于区别。"},{"q":"不属于血清学反应的试验是","o":["双向琼脂扩散","补体结合试验","病毒血凝抑制试验","病毒血凝试验","冷凝集试验"],"a":3,"e":"病毒血凝试验利用病毒表面的血凝素直接凝集红细胞，检测的是病毒颗粒本身，不涉及抗原抗体反应；其余四项均为血清学试验。"},{"q":"触诊肾脏，首选的方法是","o":["浅部触诊","冲击触诊","深插触诊","双手触诊","滑行触诊"],"a":3,"e":"肾脏位置较深且随呼吸上下移动，需左手托起腰部、右手在腹部前方深触，双手配合方能触及，故首选双手触诊法。"},{"q":"在动脉血氧分压的叙述中，不正确的是","o":["健康成人随着年龄的增加而降低","正常值为95～100mmHg，但老年人需用预计公式计算正常值","可判断有无缺氧及缺氧的程度","可判断有无Ⅱ型呼吸衰竭","随海拔变化而变化"],"a":3,"e":"PaO2降低只能反映缺氧及其程度，判断呼吸衰竭类型须结合PaCO2，Ⅱ型需PaCO2＞50mmHg，单凭氧分压无法分型。"},{"q":"哪种疾病患侧胸廓凹陷","o":["肺炎","肺气肿","胸腔积液","胸膜肥厚","皮下气肿"],"a":3,"e":"胸膜肥厚粘连使患侧胸廓塌陷、肋间隙变窄；胸腔积液与气胸使患侧饱满，肺气肿呈桶状胸，肺炎多无明显外形改变。"},{"q":"下列有关心悸的叙述正确的是","o":["提示患有器质性心脏病","仅发生在心率增快时","仅发生在心率减弱时","提示存在心律或心率异常","一种自觉心脏跳动的不适感"],"a":4,"e":"心悸是患者自觉心脏跳动的不适感或心慌感，可见于心律失常、心脏疾病，也常见于贫血、甲亢等心外因素及健康人。"},{"q":"以下不是心肌炎体征的是","o":["第一心音增强","心动过速","舒张期奔马律","下肢水肿","肺部湿啰音"],"a":0,"e":"心肌炎时心肌收缩力减弱，第一心音低钝减弱，可伴心动过速、舒张期奔马律、下肢水肿及肺底湿啰音；S1增强不符合。"},{"q":"脊柱器质性侧凸的特点是","o":["半卧位时可以消失","改变体位不能使侧弯得到纠正","平卧时可消失","俯卧位时可消失","站位时可消失"],"a":1,"e":"姿势性侧凸无脊柱结构异常，改变体位或前屈时侧凸可消失；器质性侧凸有结构改变，任何体位均不能纠正。"},{"q":"肺动脉瓣听诊区第二心音增强，最常见于","o":["高血压","冠心病","二尖瓣狭窄","肺动脉瓣狭窄","肺动脉瓣关闭不全"],"a":2,"e":"二尖瓣狭窄致左房压升高、肺静脉及肺动脉高压，肺动脉瓣关闭有力而使P2亢进，故肺动脉瓣区第二心音增强。"},{"q":"有关于心脏杂音的正确叙述中，应除外","o":["收缩期杂音2/6级以下者，多属功能性","收缩期杂音3/6级以上者，肯定为器质性","心衰时，器质性杂音可减弱或消失","杂音是否为器质性主要根据杂音的性质及粗糙程度","舒张期杂音均有病理意义"],"a":1,"e":"收缩期杂音3/6级以上多为器质性，但分级并非绝对界限，仍需结合性质、传导及是否伴震颤判断；舒张期及连续性杂音均属器质性。"},{"q":"常见尿胆素原排泄减少的情况是","o":["肠梗阻","溶血","碱中毒","胆道梗阻","肝细胞性黄疸"],"a":3,"e":"胆道梗阻时胆红素不能进入肠道，尿胆原生成减少或缺如，同时尿胆红素阳性；溶血、肝细胞性黄疸及碱中毒时尿胆原多增多。"},{"q":"下列说法错误的是","o":["胆囊炎多表现为持续性腹痛","幽门梗阻者一般呕吐后疼痛会缓解","钻顶样疼痛一般见于胆道蛔虫症","胃、十二指肠穿孔多为慢性胀痛","结肠病变，疼痛多在排便后减轻"],"a":3,"e":"胃十二指肠穿孔时胃肠内容物溢入腹腔，突发刀割样剧痛并迅速波及全腹，腹壁板样强直；慢性胀痛不符合穿孔表现。"},{"q":"慢性心功能不全产生水肿的最主要机制包括","o":["毛细血管内静水压减低","各种原因致水、钠潴留","肝脏合成白蛋白轻度减少","淋巴回流受阻","肾小球毛细血管滤过率增加"],"a":1,"e":"慢性心功能不全时心排血量减少，肾血流量下降激活肾素-血管紧张素-醛固酮系统，水钠潴留使血容量增加而形成水肿。"},{"q":"出血后促使血小板发生凝聚的重要物质是","o":["ATP","活化素","因子Ⅻ","PF3","ADP"],"a":4,"e":"血小板释放的ADP可激活血小板膜受体，引起血小板聚集并进一步释放颗粒内容物；ATP本身不具此聚集作用。"},{"q":"Kussmaul呼吸常见于","o":["肺炎","腹水","发热","尿毒症晚期","胸腔积液"],"a":3,"e":"严重代谢性酸中毒时细胞外液碳酸氢根不足，pH降低刺激呼吸中枢，出现深长而规则的Kussmaul呼吸，见于尿毒症和糖尿病酮症酸中毒。"},{"q":"第一心音的特点包括","o":["音调较高（62Hz）","强度低，性质清脆","历时时间短（0.08s）","在心尖搏动之后出现","心尖部听诊最清楚"],"a":4,"e":"第一心音音调较低、时限较长、强度较响，在心尖部最清楚，与心尖搏动同时出现；第二心音则在心底部最响。"},{"q":"以下不是动眼神经麻痹的临床表现的是","o":["上睑下垂","瞳孔散大","眼球内收受限","眼球外展受限","眼球向下受限"],"a":3,"e":"动眼神经支配上睑提肌及上、下、内直肌和下斜肌，麻痹表现为上睑下垂、瞳孔散大、眼球内收及上下运动受限；外展受限属展神经。"},{"q":"外源性凝血途径的筛查试验是","o":["APTT","SCT","RT","CT","PT"],"a":4,"e":"PT测定血浆凝固时间，反映外源性凝血途径功能，是外源性凝血系统最灵敏、最常用的筛选试验；APTT则反映内源性途径。"},{"q":"蛙腹见于","o":["腹膜有炎症或肿瘤浸润","腹腔大量积液","腹腔大量积气","腹腔巨大肿瘤","腹壁上的肿物"],"a":1,"e":"腹腔大量积液时仰卧腹壁向两侧膨出、中部平坦，呈蛙腹状；大量积气呈球形膨隆，巨大肿瘤多表现为局部不对称膨隆。"},{"q":"外观清亮，比重为1.010，蛋白质浓度为1.5g/dl，单核细胞小于500×106/L的浆液提示","o":["感染性","渗出液","漏出液","无菌","结核"],"a":2,"e":"外观清亮、比重低于1.015、蛋白定量低于25g/L、细胞数少的积液符合漏出液，多由血浆胶体渗透压降低或静水压升高所致。"},{"q":"如腹水量少于1000ml，最合适的检查体位是","o":["左侧卧位","肘膝位","坐位","俯卧位","右侧卧位"],"a":1,"e":"腹水少于1000ml时仰卧位难以叩出，可取肘膝位使脐部最低，由侧腹向脐叩诊，鼓音转浊即水坑征阳性，可发现120ml以上积液。"},{"q":"Graham-Steell杂音最常见于","o":["三尖瓣关闭不全","主动脉瓣狭窄","肺动脉瓣狭窄","二尖瓣狭窄","主动脉瓣关闭不全"],"a":3,"e":"Graham-Steell杂音为肺动脉瓣区舒张期递减型吹风样杂音，系肺动脉高压致肺动脉扩张、瓣环相对关闭不全所致，常见于二尖瓣狭窄。"},{"q":"正常人直立、骨盆固定的条件下，腰椎活动范围为","o":["后伸40°","前屈75°","右侧曲50°","左侧曲45°","旋转（一侧）35°"],"a":1,"e":"正常人直立、骨盆固定时腰椎前屈可达75°～90°，后伸约30°，左右侧弯20°～35°，旋转约30°，故前屈75°属正常范围。"},{"q":"慢性阻塞性肺气肿表现为","o":["FEV1及FVC下降","功能残气量及FVC下降","FEV1及RC/TLC（残气量/肺总量）下降","FEV1及FEV1/FVC下降","FEV1/FVC及FVC增加"],"a":3,"e":"慢性阻塞性肺气肿属阻塞性通气障碍，FEV1与FEV1/FVC均降低，残气量及残气量/肺总量升高，肺总量也可增加。"},{"q":"正常成年人能够听到支气管肺泡呼吸音的部位为","o":["胸骨两侧第2、3肋间隙","胸骨两侧第3、4肋间隙","肩胛间区第2、3胸椎水平","肩胛间区第3、4胸椎水平","肩胛下区"],"a":3,"e":"正常人仅在胸骨两侧第1、2肋间隙、肩胛间区第3、4胸椎水平及肺尖前后部听到支气管肺泡呼吸音，其他部位听到属异常。"},{"q":"血氨正常的疾病是","o":["肝性脑病","重症肝炎","尿毒症","休克","贫血"],"a":4,"e":"血氨升高见于肝性脑病、重症肝炎、肝硬化及尿毒症等，也可见于休克致肝灌注不足；贫血不影响氨的生成与清除，血氨正常。"},{"q":"关于弛张热的描述，下列不正确的是","o":["体温在39℃以上","体温波动大","每日温差达2℃以上","每日体温波动在1℃以内","常见于败血症、化脓性炎症等"],"a":3,"e":"弛张热体温常在39℃以上，24小时内波动超过2℃，最低体温仍高于正常，见于败血症、化脓性炎症及风湿热；波动1℃以内者为稽留热。"},{"q":"下述各项均能判断黄疸，但除外","o":["巩膜黄染","口腔黏膜黄染","皮肤黄染","掌心黄染","血清总胆红素测定"],"a":3,"e":"黄疸时巩膜、软腭黏膜及皮肤黄染，血清总胆红素升高可确诊；掌心黄染多为胡萝卜素血症，与胆红素代谢无关。"},{"q":"肺泡呼吸音增强可见于下列情况，但需除外","o":["发热","甲亢","贫血","患侧全肺不张","酸中毒"],"a":3,"e":"肺泡呼吸音增强见于发热、甲亢、贫血、酸中毒等使呼吸运动增强、通气量增加的情况；患侧全肺不张时该侧呼吸音减弱或消失。"},{"q":"心性混合性发绀常见于","o":["二尖瓣狭窄","缩窄性心包炎","法洛四联症","扩张型心肌病","高血压心脏病"],"a":2,"e":"心性混合性发绀因心内或大血管异常通道致静脉血未经氧合直接进入体循环，分流量超过心排血量1/3即出现，见于法洛四联症。"},{"q":"一医生接诊一个患者后交代患者闭眼，往患者手里放置了一支钢笔，要求患者描述该物体的形状。这是检查","o":["触觉","实体觉","体表图形觉","皮肤定位觉","位置觉"],"a":1,"e":"实体觉是在闭眼下通过触摸辨别物体形状、质地并说出名称的能力，属皮质复合感觉，其障碍提示顶叶病变。"},{"q":"下列各种药物或化学物质不会引起高铁血红蛋白血症的是","o":["亚硝酸盐","硝基胺","磺胺","氯化钾","伯氨喹"],"a":3,"e":"高铁血红蛋白血症常由苯胺、硝基苯、伯氨喹、亚硝酸盐及磺胺类药物中毒引起；氯化钾不氧化血红蛋白的二价铁。"},{"q":"代谢性碱中毒时","o":["血浆pH值增高，PaCO2代偿性增高，HCO3－下降","血浆pH值增高，PaCO2代偿性增高，HCO3－增高","血浆pH值增高，PaCO2下降，HCO3－下降","血浆pH值增高，PaCO2代偿性增高，HCO3－不变","血浆pH值下降，PaCO2代偿性增高，HCO3－下降"],"a":1,"e":"代谢性碱中毒时HCO3-原发性升高，pH增高，经肺代偿PaCO2继发性升高，预计代偿幅度约为ΔHCO3-×0.9。"},{"q":"一般与遗传无关的是","o":["慢性支气管炎","血友病","白化病","遗传性球形红细胞增多症","糖尿病"],"a":0,"e":"慢性支气管炎由吸烟、大气污染、感染等环境因素长期作用所致，遗传因素并非主要病因；其余疾病均有明确遗传基础。"},{"q":"肝病并发弥散性血管内凝血时下列哪一组试验最有诊断价值","o":["FⅧ：C降低，vWFAg/FⅧ：C比值增高","APTT、PT、TT均延长","AT、PC、PLG降低","b-TG、PF4和血清FDP均增高","3P试验阳性，FDP含量增高"],"a":0,"e":"肝病时FⅧ由肝外内皮合成，多不降低甚至升高；并发DIC时FⅧ被大量消耗而降低，vWFAg/FⅧ:C比值随之增高，可与单纯肝病鉴别。"},{"q":"肺气肿患者突然出现呼吸困难，对确定并发气胸有意义的检查是","o":["呼吸运动","触觉语颤","叩诊音","支气管语音","听觉语颤"],"a":2,"e":"气胸时患侧胸腔积气，叩诊由过清音转为鼓音，并与对侧对比明显；肺气肿本身即过清音，叩诊音的变化对判断并发气胸最有价值。"},{"q":"外源性凝血从哪个因子开始激活","o":["Ⅲ","Ⅴ","Ⅻ","Ⅹ","Ⅱ"],"a":0,"e":"外源性凝血途径由受损组织释放的组织因子（Ⅲ因子）启动，与Ⅶ因子结合成复合物，激活Ⅹ因子而进入共同途径。"},{"q":"下列均为消化性溃疡穿孔的体征，除外","o":["全腹压痛","肠鸣音减弱或消失","腹壁呈板样强直","肝浊音界缩小或消失","肠鸣音亢进"],"a":4,"e":"消化性溃疡穿孔后腹膜受刺激，全腹压痛、反跳痛、腹壁板样强直，肝浊音界缩小或消失，肠鸣音减弱或消失；肠鸣音亢进见于机械性肠梗阻。"},{"q":"无症状性血尿最常见于","o":["肾盂肾炎","薄基底膜肾病","神经源性膀胱","丝虫病","多囊肾"],"a":1,"e":"无症状性血尿指无水肿、高血压及肾功能损害的血尿，最常见于薄基底膜肾病，属良性家族性血尿；多囊肾、肾盂肾炎多有其他表现。"},{"q":"血清钾的生物学作用包括","o":["是维持细胞生理活动的主要阴离子","是保持机体的正常渗透压的主要离子","不参与糖及蛋白质代谢","保证神经肌肉的正常功能","大部分存在于细胞内液"],"a":3,"e":"血钾是细胞内主要的阳离子，维持神经肌肉的兴奋性与心肌的正常功能，血钾过低可出现肌无力、腱反射减弱甚至心律失常。"},{"q":"Grey Turner征见于","o":["Addison病","多发性神经纤维瘤","急性出血性胰腺炎","血色病","妊娠"],"a":2,"e":"Grey-Turner征指腰部、季肋部及下腹部皮肤呈蓝色，系血液自腹膜后间隙渗至侧腹壁皮下，见于重症急性胰腺炎和肠绞窄。"},{"q":"下列各项均可出现肝浊音界扩大，但除外","o":["肝炎","肝癌","肝包虫","晚期肝炎后肝硬化","肝脓肿"],"a":3,"e":"肝浊音界扩大见于肝炎、肝癌、肝脓肿、肝包虫及肝淤血；晚期肝炎后肝硬化肝脏萎缩、纤维化，肝浊音界缩小。"},{"q":"诊断甲状腺功能亢进的特征性改变是","o":["甲状腺弥漫、对称肿大","甲状腺质地较柔软","甲状腺出现结节改变","甲状腺可随吞咽动作上下移动","触诊有震颤或听诊能听到血管杂音"],"a":4,"e":"甲状腺功能亢进时腺体血管增多增粗、血流加速，触诊可及震颤，听诊闻及连续性静脉嗡鸣音或收缩期动脉杂音，为特征性体征。"},{"q":"二尖瓣狭窄患者咳粉红色泡沫痰，两肺布满水泡音时，说明病情至少已处于","o":["肺动脉高压期","左心室衰竭期","左心房衰竭期","右心功能衰竭","疾病的终末阶段"],"a":2,"e":"二尖瓣狭窄时左心房压升高致肺静脉淤血，咳粉红色泡沫痰、双肺满布水泡音提示急性肺水肿，说明已进入左心房衰竭期。"},{"q":"下列哪种情况出现语音震颤增强","o":["肺泡内含气量过多","支气管阻塞","大量胸腔积液","肺泡内大面积炎症浸润","胸膜高度增厚"],"a":3,"e":"肺泡内大面积炎性浸润使肺组织实变、传导性增强，语音震颤增强；含气量过多、支气管阻塞、胸腔积液及胸膜增厚均使其减弱。"},{"q":"最可能导致室性心动过速和心室颤动的心电图表现是","o":["每分钟6个以上的室性期前收缩","多源性室性期前收缩","成对室性期前收缩","偶发室性期前收缩","R-on-T型室性期前收缩"],"a":4,"e":"R-on-T型室性期前收缩落在前一心搏T波易损期，极易诱发室性心动过速甚至心室颤动，临床意义最严重。"},{"q":"尿频、尿急伴下肢感觉障碍，最常见的疾病是","o":["精神紧张","急性前列腺炎","神经源性膀胱","尿崩症","急性肾盂肾炎"],"a":2,"e":"神经源性膀胱因中枢或周围神经病变致膀胱功能失调，出现尿频、尿急并伴下肢感觉运动障碍；尿崩症表现为多尿，前列腺炎无感觉障碍。"},{"q":"以下哪一项属于心电图的正常变异","o":["儿童右室占优势","V1～V3导联ST段弓背向上抬高","右束支传导阻滞","V1～V2导联呈QS型，V3呈QRS型","V1～V3导联R/S＞1，伴ST段压低"],"a":0,"e":"儿童期右心室电位占优势属生理性演变，随年龄增长逐渐转为左室占优势；V1～V3 ST段弓背向上抬高、右束支阻滞及R/S＞1均属异常。"},{"q":"ST段抬高不可见于下列哪种临床情况","o":["急性心肌梗死","应激性心肌病","心包炎","冠脉痉挛","主动脉瓣反流"],"a":4,"e":"ST段抬高见于急性心肌梗死、变异型心绞痛（冠脉痉挛）、心包炎及应激性心肌病；主动脉瓣反流多表现为ST段压低与左室肥厚。"},{"q":"慢性阻塞性肺疾病（COPD）的分级主要依赖","o":["FEV1及FVC","功能残气量及FVC","FEV1","FEV1及残气量/肺总量（RC/TLC）","FEV1/FVC及FVC"],"a":2,"e":"COPD严重程度分级以FEV1占预计值百分比为依据，划分为轻、中、中重、重及极重度，FEV1/FVC用于确诊气流受限。"},{"q":"关于A型血型，说法正确的是","o":["红细胞膜上有A抗原","红细胞膜上有B抗原","血清中有A抗原","血清中有抗A抗体","红细胞膜上有A抗体"],"a":0,"e":"A型血红细胞膜上含A抗原，血清中含抗B抗体；抗原决定血型，抗体则与输入的红细胞抗原相对应，故不可含同种抗原。"},{"q":"下列为胸部正常叩诊音的正确描述，但应除外","o":["正常胸部叩诊为清音","其音响的强弱及高低与肺的含气量多少有关","其音响的强弱及高低与胸壁的厚薄有关","其音响的强弱及高低与邻近器官的影响有关","前胸下部较上部叩诊音相对稍浊"],"a":4,"e":"正常胸部叩诊为清音，其强弱高低与肺含气量、胸壁厚薄及邻近器官有关；因上胸肌肉较厚、肺上叶含气少，前胸上部较下部稍浊。"},{"q":"出血时间正常的疾病是","o":["急性粒细胞性白血病","再生障碍性贫血","血小板减少性紫癜","血友病","放射线损伤"],"a":3,"e":"血友病为凝血因子Ⅷ或Ⅸ缺乏，凝血时间延长而出血时间正常；血小板减少、血小板功能异常及血管壁病变则出血时间延长。"},{"q":"退热期可导致","o":["Na＋潴留","Cl－潴留","水潴留","脱水","出汗减少"],"a":3,"e":"退热期皮肤血管扩张、大量出汗，水分与电解质经汗液丢失，加之饮水不足，易致脱水甚至虚脱，故应补液。"},{"q":"消化性溃疡的主要症状是","o":["反酸","嗳气","恶心呕吐","上腹胀","节律性上腹痛"],"a":4,"e":"消化性溃疡以上腹部周期性、节律性疼痛为主要症状，胃溃疡餐后痛、十二指肠溃疡饥饿痛，反酸嗳气仅为伴随表现。"},{"q":"下述心包摩擦音的听诊特点均正确，但应除外","o":["性质粗糙，呈搔抓样","与心跳一致，声音呈三相","屏气时摩擦音消失","胸骨左缘第3、4肋间最响","坐位前倾位时更明显"],"a":2,"e":"心包摩擦音与心搏一致，呈收缩期与舒张期双相，屏气时仍然存在，可与屏气即消失的胸膜摩擦音鉴别；胸骨左缘第3、4肋间最响，前倾坐位更明显。"},{"q":"人体内最不稳定的凝血因子，同时也是构成凝血和血栓形成共同环节的凝血因子是","o":["Ⅴ因子","Ⅷ因子","Ⅸ因子","Ⅹ因子","Ⅻ因子"],"a":0,"e":"Ⅴ因子最不稳定，易被加热和贮存破坏，且参与凝血酶原复合物形成，是凝血与血栓形成的共同环节。"},{"q":"面容惊愕、眼裂增宽、眼球突出、目光炯炯、兴奋不安、烦躁易怒的面容是","o":["急性病容","贫血面容","黏液性水肿面容","甲状腺功能亢进面容","伤寒面容"],"a":3,"e":"甲状腺功能亢进面容表现为面容惊愕、眼裂增宽、眼球突出、目光炯炯、兴奋不安、烦躁易怒，与黏液性水肿面容的面色苍黄、表情呆滞相反。"},{"q":"以下属于髓系细胞免疫标志是","o":["CD13","CD19","CD20","CD4","TdT"],"a":0,"e":"CD13表达于粒系及单核系细胞，是识别髓系细胞的常用标志；CD19、CD20属B细胞标志，CD4属T细胞标志，TdT提示原始淋巴细胞。"},{"q":"判定腹部膨隆时的体位是","o":["立位","左侧卧位","坐位","仰卧位","右侧卧位"],"a":3,"e":"判断腹部是否膨隆应在仰卧位下观察，前腹壁明显高于肋缘至耻骨联合平面即为膨隆；立位受胃肠气体和重力影响，不利于判断。"},{"q":"关于移动性浊音检查手法下列各项均正确，但除外","o":["患者仰卧位时，腹中部呈鼓音，两侧浊音","左侧卧位后，右侧腹叩呈鼓音，左侧浊音","右侧卧位后，右侧腹叩呈浊音，左侧鼓音","常常采用轻叩手法","常常采用多次变换体位反复叩诊"],"a":3,"e":"移动性浊音需用中等强度叩诊并多次变换体位对比浊音界移动，轻叩声弱、界限不清，难以判断浊音区是否随体位移动。"},{"q":"急性无黄疸型病毒性肝炎的实验室表现是","o":["血清蛋白各项均有改变","血清蛋白电泳示异常蛋白带","ALT、AST升高","MAO增高","ALP明显增高"],"a":2,"e":"急性无黄疸型病毒性肝炎以肝细胞损伤为主，ALT、AST显著升高，ALT升高更明显，DeRitis比值小于1；血清蛋白及ALP改变不明显。"},{"q":"下列选项均为病理反射，除外","o":["Oppenheim征","Gordon征","Chaddock征","Romberg征","Hoffman征"],"a":3,"e":"Romberg征检查闭目时的姿势平衡，阳性提示感觉性共济失调或小脑病变，属共济运动检查；Oppenheim、Gordon、Chaddock及Hoffman征均为病理反射。"},{"q":"病情较轻患者的病程记录，记录的频率应该","o":["1日1次","1日数次","2～3日记录1次","5日记录1次","1周记录1次"],"a":2,"e":"病情稳定者至少3天记录一次病程记录，故每2～3日记录一次即可；病危者每日至少一次，病重者至少2天一次。"},{"q":"在心浊音界各部的组成中心腰是指","o":["左心房与左心室交接处","升主动脉与上腔静脉交接处","主动脉与肺动脉段交接处","右心房与右心室交接处","主动脉与左心室交接处"],"a":4,"e":"心腰是心脏左界血管与左心交接处向内凹陷所成的部位，位于主动脉与左心室之间，叩诊该处相对浊音界内收；左心室增大时心腰加深，心界呈靴形。"},{"q":"深压触诊法可检查的体征是","o":["体表浅在病变，神经，阴囊精索","肠管，索条状包块，胃肠病变","肝、脾、肾和腹腔肿物的检查","腹腔压痛点，反跳痛","大量腹水时肝、脾检查"],"a":3,"e":"深压触诊以并拢的手指逐渐深压腹壁，探测腹腔深部病变，可确定阑尾、胆囊、输尿管等压痛点并引出反跳痛；双手触诊用于肝、脾、肾和腹腔肿物的检查。"},{"q":"代谢性碱中毒的代偿反应为","o":["HCO3－升高","PaO2升高","PaO2下降","PaCO2升高","PaCO2下降"],"a":4,"e":"官方答案为【PaCO2下降】，但依据教材，正确答案为【PaCO2升高】。代谢性碱中毒时HCO3-原发性升高，机体通过呼吸抑制、通气量减少使PaCO2代偿性升高，以维持pH接近正常。"},{"q":"Courvoisier氏征常见于","o":["急性胆囊炎","胆石症","胰头癌","胆囊炎","肝癌"],"a":2,"e":"胰头癌压迫胆总管致胆道梗阻，黄疸进行性加深而胆囊因胆汁淤积显著肿大、无压痛，即库瓦西耶征阳性；胆总管结石时胆囊多因慢性炎症纤维化而不肿大。"},{"q":"以下不属于胃镜检查的并发症的是","o":["下颌关节脱位","食管或胃穿孔","腮腺肿大","心动过速","心搏骤停"],"a":3,"e":"胃镜并发症包括下颌关节脱位、腮腺肿大、咽喉部损伤、食管或胃穿孔及心搏骤停等，多由机械刺激或迷走反射引起；心动过速属心律失常，不属胃镜并发症。"},{"q":"下列各项为异常支气管肺泡呼吸音的特点，但应除外","o":["在正常肺泡呼吸音的区域内听到支气管肺泡呼吸音","产生机制为肺部实变区域较小且与正常肺组织混合存在","肺实变部位较深，并被正常肺组织所覆盖","常见于支气管肺炎及大叶肺炎初期","在胸腔积液的上方，肺膨胀不全区域很难听到"],"a":4,"e":"胸腔积液上方肺组织受压膨胀不全，实变使声音传导增强，支气管肺泡呼吸音反而容易听到，故该项不是其特点；异常支气管肺泡呼吸音见于支气管肺炎及大叶肺炎初期。"},{"q":"急性腹膜炎患者采取的体位正确的是","o":["被动体位","强迫仰卧位","强迫俯卧位","强迫侧卧位","强迫坐位"],"a":1,"e":"急性腹膜炎时取仰卧位并屈曲双腿，可松弛腹肌、减轻腹膜牵张与疼痛，故表现为强迫仰卧位；强迫侧卧位见于一侧胸膜疾病，强迫坐位见于心肺功能不全。"},{"q":"二尖瓣狭窄时，舒张期隆隆样杂音的强度变化属下列哪种形式","o":["递增型","递减型","递增递减型","连续型","一贯型"],"a":0,"e":"二尖瓣狭窄的舒张中晚期隆隆样杂音由弱渐强，属递增型，窦性心律时因舒张晚期心房收缩、跨瓣血流加速而进一步增强；递减型见于主动脉瓣关闭不全的叹气样杂音。"},{"q":"腹部肥胖与腹腔内容物增多（积液、积气或巨大包块）进行鉴别时最简单的方法是","o":["腹部外形的变化","脐部凸出或凹陷","脐周腹围的大小程度","腹壁静脉有无曲张","腹式呼吸存在与否"],"a":1,"e":"腹部肥胖者脂肪堆积而腹压不高，脐部多凹陷；腹腔积液、积气或巨大包块使腹内压升高，脐部常凸出，故观察脐部形态是最简便的鉴别方法。"},{"q":"本例心电图最可能的导联反接情况是（图12）","o":["V3和V4反接","V1和V2反接","V5和V6反接","V1和V6反接","V2和V3反接"],"a":0,"e":"官方题库缺失图片"},{"q":"肝素的抗凝作用尚需依赖下列哪一项","o":["抗凝血酶","肝素酶","蛋白C","α2巨球蛋白","血栓调节蛋白"],"a":0,"e":"肝素本身无直接抗凝活性，须与血浆抗凝血酶Ⅲ结合，使其构象改变并显著增强灭活凝血酶及因子Ⅹa的能力；抗凝血酶缺乏时肝素疗效明显降低。"},{"q":"心尖部有收缩期吹风样杂音时，下列哪项最支持二尖瓣关闭不全的诊断","o":["杂音音调较低","杂音向左腋下传导","第一心音亢进","可闻及第三心音","杂音于吸气时增强"],"a":1,"e":"二尖瓣关闭不全的收缩期吹风样杂音沿左心房血流方向传向左腋下及左肩胛下区，是与其他心尖区收缩期杂音鉴别的要点；主动脉瓣狭窄的杂音则向颈部传导。"},{"q":"局限性水肿不包括","o":["踝关节炎","蜂窝织炎","丝虫病","血栓性静脉炎","心源性水肿"],"a":4,"e":"心源性水肿为右心衰竭引起的全身性水肿，自足部开始向上蔓延并伴颈静脉怒张、肝大；踝关节炎、蜂窝织炎、丝虫病及血栓性静脉炎均属局部回流障碍所致的局限性水肿。"},{"q":"咳嗽伴有声音嘶哑，最可能发生病变的是","o":["喉下神经","三叉神经","喉返神经","舌咽神经","迷走神经"],"a":2,"e":"声带炎症、喉部肿瘤或纵隔病变压迫喉返神经致声带麻痹，发声时声门闭合不全，咳嗽声音嘶哑；喉返神经支配除环甲肌以外的全部喉内肌。"},{"q":"高钾血症初期，心电图主要表现为","o":["T波高尖","T波平坦","U波明显","ST段延长","ST段缩短"],"a":0,"e":"血钾升高使心肌复极加速，心电图最早出现T波高尖、基底变窄、QT间期缩短，见于血钾超过5.5mmol/L的初期；血钾继续升高才出现QRS增宽、P波低平或消失。"},{"q":"关于干啰音的特点阐述正确的是","o":["干啰音性质不易改变","部位不易变，较恒定","音调较低","是一种持续时间较长的带乐性的呼吸附加音","吸气及呼气均可闻及，但以吸气时为明显"],"a":3,"e":"干啰音是气流通过狭窄或部分阻塞的支气管产生湍流振动所致，为持续时间较长、音调较高的带乐性附加音，部位与性质易随咳嗽、体位改变，呼气时更明显。"},{"q":"左室肥大，QRS波群电压增高，在各导联电压变化的标准是","o":["RaVL＜1.1mV","RaVR＞0.5mV","RⅠ＞1.0mV","RV5＋SV1＞4.0mV（男性）或＞3.5mV（女性）","RV1＋SV5＞1.2mV"],"a":3,"e":"左心室肥厚时面向左室的导联R波振幅增高，胸导联电压标准为RV5或RV6＞2.5mV、RV5+SV1＞4.0mV（男）或＞3.5mV（女）；肢体导联RⅠ＞1.5mV。"},{"q":"潮气容积是指","o":["平静呼吸时，一次吸入的气量","平静呼吸时，一次呼出的气量","运动时，一次吸入的气量","运动时，一次呼出的气量","平静呼吸时，一次吸入和呼出的气量"],"a":4,"e":"潮气容积是平静呼吸时一次吸入或呼出的气量，正常成人约500ml，主要靠吸气肌特别是膈肌收缩完成，呼吸肌功能不全时明显降低。"},{"q":"引起心悸最常见的病因是","o":["心力衰竭","心律失常","冠心病","神经官能症","心肌病"],"a":1,"e":"心律失常时舒张期缩短、心室充盈不足，收缩期室内压上升速率增快，心室肌与瓣膜紧张度骤增而致心悸，为病理性心悸最常见的病因；心力衰竭多表现为劳力性心悸。"},{"q":"叩诊肺尖时，其正常宽度为","o":["1～2cm","3～4cm","4～6cm","7～8cm","叩不清"],"a":2,"e":"肺尖清音带即Kronig峡，正常宽度4～6cm，因右肺尖位置较低且右肩胛带肌肉较发达，右侧略窄于左侧；肺尖结核浸润时变窄，肺气肿时增宽。"},{"q":"关于副神经检查，下列叙述哪项不正确","o":["观察胸锁乳突肌及斜方肌有无萎缩","有无斜颈及垂肩","嘱患者转颈测试胸锁乳突肌的肌力","嘱患者耸肩比较两侧肌力","观察双上肢肌肉有无萎缩"],"a":4,"e":"副神经支配胸锁乳突肌和斜方肌，检查应观察有无斜颈、垂肩及两肌萎缩，并令病人转颈、耸肩比较两侧肌力；双上肢肌肉萎缩反映颈神经或臂丛病变，与副神经无关。"},{"q":"白细胞分类计数时，应在油镜下选择哪个部位有秩序地检查","o":["涂片头体部染色较好处","涂片体、尾交界处染色较好处","涂片体部染色较好处","涂片尾部染色较好处","涂片的两侧染色较好处"],"a":1,"e":"血涂片体、尾交界处细胞分布均匀、形态舒展清晰，是油镜下分类计数200～500个白细胞的常规区域；涂片头部细胞重叠、尾部细胞变形，均不宜分类。"},{"q":"关于血清学试验结果的分析错误的是","o":["试验阳性说明机体接触过病原体","单次试验阳性不能完全证明新近感染","试验阴性不能完全排除相应病原体感染的可能性","试验阳性即有诊断意义","试验有假阴性的可能"],"a":3,"e":"血清学试验阳性仅提示机体接触过该病原体，可因交叉反应出现假阳性，须结合临床及确诊试验判断；单次阳性不能证明新近感染，阴性亦不能排除感染。"},{"q":"墨菲征阳性最常见于","o":["急性胰腺炎","急性胆囊炎","急性胃穿孔","胆石症","急性肝炎"],"a":1,"e":"墨菲征是深压胆囊点后嘱病人深吸气，发炎的胆囊随膈下移触及手指引起剧痛而突然屏气，为急性胆囊炎的特征性体征；单纯胆石症无急性炎症时多为阴性。"},{"q":"用于判断通气功能障碍性质的指标为","o":["FEV1/FVC","FEV1%pred","PEF","FVC","MEF50"],"a":0,"e":"阻塞性通气障碍以FEV1/FVC降低为特征，限制性通气障碍则肺容量减少而该比值正常或增高，故FEV1/FVC是判断通气障碍性质的指标；FEV1%pred主要反映损害程度。"},{"q":"既能听到心脏杂音又能触到震颤的疾病是","o":["风湿性心脏病二尖瓣狭窄","风湿性心脏病二尖瓣关闭不全","先天性心脏病房间隔缺损","高血压心脏病左心室大","甲状腺功能亢进"],"a":0,"e":"震颤是杂音强度达4级以上时触及的振动，风湿性二尖瓣狭窄的舒张期隆隆样杂音粗糙，常伴心尖部舒张期震颤；二尖瓣关闭不全的杂音虽响却极少触及震颤。"},{"q":"消化性溃疡的疼痛特点是","o":["上腹痛","剑突下痛","脐周痛","上腹部节律性，周期性痛","下腹痛"],"a":3,"e":"消化性溃疡疼痛位于上腹，呈慢性反复发作的周期性与节律性，胃溃疡多为餐后痛，十二指肠溃疡多为空腹痛与夜间痛，进餐后缓解是其特点。"},{"q":"常见血清总胆固醇增高的疾病是","o":["贫血","急性重型肝炎","冠状动脉粥样硬化","甲状腺功能亢进症","肝硬化"],"a":2,"e":"冠状动脉粥样硬化存在脂代谢紊乱，血清总胆固醇及低密度脂蛋白升高是重要危险因素；甲状腺功能亢进、肝硬化、急性重型肝炎和贫血时胆固醇多降低。"},{"q":"反映肝纤维化的血清学指标是","o":["胆固醇","乳酸脱氢酶（LDH）","γ-谷氨酰转肽酶（γ-GT，GGT）","透明质酸（HA）","胆汁酸"],"a":3,"e":"透明质酸由肝血窦内皮细胞摄取降解，肝纤维化时合成增加、清除减少而血清HA升高，是反映肝纤维化程度的常用血清学指标；胆汁酸主要反映肝排泄功能。"},{"q":"胸痛患者伴有心前区杂音及血压下降，其最可能的诊断是","o":["二尖瓣狭窄","心包炎","肺梗死","主动脉缩窄","自发性气胸"],"a":3,"e":"主动脉缩窄时血流通过狭窄段产生收缩期杂音，可传至心前区及背部，下肢血压显著低于上肢，狭窄严重者可出现血压下降并伴胸痛。"},{"q":"书写病程记录的要求，以下各项错误的是","o":["首先要标明记录时间（采用12小时制或24小时制均可）","对病危患者应当根据病情变化随时记录书写，每天至少1次","对病重患者，至少2天记录1次病程记录","对病情稳定的患者，至少3天记录1次病程记录","常规会诊记录应该由会诊医师在会诊申请发出后48小时内完成"],"a":0,"e":"病历书写规定日期与时间一律用阿拉伯数字并按24小时制记录；病危者每天至少记录1次、病重者至少2天1次、病情稳定者至少3天1次，会诊记录应于48小时内完成。"},{"q":"动态心电图的导联中显示P波清楚，最有助于分析心律失常的导联是","o":["CM5","CM1","MaVF","CM2","CM3和MaVF"],"a":1,"e":"CM1导联正极置于胸骨右缘第4肋间，能清晰显示P波，便于判断房性与室性心律失常及房室传导关系，是分析心律失常的首选导联；CM5对缺血性ST段下移最敏感。"},{"q":"充盈膀胱与卵巢囊肿最有鉴别意义的体征是","o":["囊性感与实体感","有无移动性浊音","触诊形态","按之有无尿意","排尿或导尿后肿块体积变化"],"a":4,"e":"胀大的膀胱触之有囊性感、按压有尿意，排尿或导尿后体积明显缩小或消失；卵巢囊肿不随排尿改变，故排尿或导尿后肿块体积变化最有鉴别意义。"},{"q":"下列中最符合大红细胞直径的是","o":["12μm","11μm","10μm","＞10μm","≥10μm"],"a":3,"e":"正常红细胞直径6～9μm，平均7.5μm；直径＞10μm者为大红细胞，见于巨幼细胞贫血及溶血性贫血，直径＜6μm者为小红细胞。"},{"q":"怀疑原发性肝癌时，下列中首选的检查项目为","o":["ALP","AFP","γ-GT","AFU","ALT"],"a":1,"e":"血清甲胎蛋白是辅助诊断原发性肝癌最常用的肿瘤标志物，AFP≥400ng/ml持续4周或≥200ng/ml持续8周，排除妊娠、活动性肝病及生殖腺胚胎瘤后高度提示肝癌。"},{"q":"患者大量蛋白尿5年，诊断为肾病综合征，其蛋白尿的性质为","o":["肾小球性蛋白尿","肾小管性蛋白尿","溢出性蛋白尿","组织性蛋白尿","其他"],"a":0,"e":"肾病综合征时肾小球滤过膜的电荷屏障与孔径屏障受损，血浆蛋白尤其白蛋白大量漏出，形成非选择性肾小球性蛋白尿，24小时尿蛋白定量常超过3.5g。"},{"q":"下面是医生观察患者全身状况的视诊检查内容，但不包括","o":["年龄","发育","营养","体温","意识状态"],"a":3,"e":"视诊是一般检查的主要方法，观察性别、年龄、发育、营养、意识状态、面容、体位与步态等；体温须用体温计测量，属测量内容而非视诊所见。"},{"q":"关于稽留热的描述，下列不正确的是","o":["体温维持在39～40℃以上","恒定维持高水平达数天或数周","体温波动范围不超过1℃","常见于大叶肺炎，斑疹伤寒及伤寒高热期","也见于疟疾、布鲁菌病"],"a":4,"e":"稽留热体温恒定于39～40℃以上、日波动不超过1℃，持续数天至数周，见于大叶性肺炎、斑疹伤寒及伤寒高热期；疟疾为间歇热，布鲁菌病为波状热。"},{"q":"空洞巨大、位置表浅且腔壁光滑的叩诊音应为","o":["过清音","浊鼓音","空瓮音","浊音","实音"],"a":2,"e":"空洞巨大、位置表浅且腔壁光滑时，叩诊呈鼓音并带金属性回响，称空瓮音；浊鼓音见于肺不张、肺炎充血期等含气与实变并存的部位。"},{"q":"再生障碍性贫血的血象不会表现为","o":["红细胞减少","白细胞减少","血小板减少","淋巴细胞比例下降","单核细胞减少"],"a":3,"e":"再生障碍性贫血骨髓造血功能衰竭，红系、粒系及巨核系均减少，中性粒细胞减少使淋巴细胞比例相对增高；淋巴细胞绝对值并不增多，比例不会下降。"},{"q":"叩诊肝脏相对浊音界时，其叩诊音应是","o":["由清音转为实音","由浊音变为实音","由过清音转为实音","由清音转为鼓音","由清音转为浊音"],"a":4,"e":"沿右锁骨中线自上而下叩诊，音响由清音转为浊音处为肝上界，即被肺遮盖的肝顶部，称相对浊音界；再下移1～2肋间浊音变实音处为绝对浊音界。"},{"q":"关于过敏性紫癜关节痛，描述有误的是","o":["常伴双下肢皮肤紫癜","可伴消化道症状","可伴血尿、蛋白尿","血小板计数常减少","可由多种过敏原诱发"],"a":3,"e":"过敏性紫癜属血管壁功能异常所致的出血性疾病，血小板计数正常、束臂试验可阳性；紫癜多对称分布于双下肢，可伴关节痛、腹痛及血尿、蛋白尿。"},{"q":"关于肌张力下列哪项正确","o":["指肌肉运动时的最大收缩力","肌张力减弱时肢体强直","是指静息状态下的肌肉紧张度","肌张力增加时表现为关节过伸","肌张力增加主要由周围神经损害引起"],"a":2,"e":"肌张力是静息状态下肌肉的紧张度，即被动运动肢体时检查者感受到的阻力，实质为牵张反射；锥体束损害时呈痉挛性增高，周围神经损害时减低。"},{"q":"不会出现肝大的疾病是","o":["急性病毒性肝炎伴黄疸","肝硬化伴腹水","肝癌伴肝性脑病","肝脓肿伴右侧胸腔积液","右心衰竭伴下肢水肿"],"a":1,"e":"肝硬化时肝细胞坏死、纤维组织增生收缩，肝脏缩小、质硬、表面呈结节状而不肿大，出现腹水提示失代偿；急性肝炎、肝癌、肝脓肿及右心衰竭均可致肝大。"},{"q":"纤维支气管镜不容易发现下列哪部位的病灶","o":["肺尖","肺门","隆突","段支气管","声门"],"a":0,"e":"纤维支气管镜经声门进入，可观察隆突、肺门及各叶段支气管，肺尖部亚段支气管细小、镜身难以到达，故肺尖病灶不易被发现。"},{"q":"内源性凝血从哪个因子开始激活","o":["Ⅷ","Ⅸ","Ⅺ","Ⅻ","Ⅴ"],"a":3,"e":"内源性凝血途径由因子Ⅻ接触胶原、玻璃等带负电荷表面而被激活启动，继而依次激活Ⅺ、Ⅸ、Ⅷ，与因子Ⅹ共同形成凝血酶原激活物。"},{"q":"进行性排尿困难最常见的病因是","o":["尿道狭窄","膀胱癌","前列腺增生","膀胱颈部纤维性增生","膀胱结石"],"a":2,"e":"良性前列腺增生使前列腺移行带增大并压迫尿道，出现尿频、尿线变细、排尿踌躇及进行性排尿困难，是老年男性最常见的病因；尿道狭窄多有外伤或感染史。"},{"q":"检测外源性凝血途径有无障碍的试验是","o":["凝血时间的测定","血浆复钙时间的测定","血浆凝血酶原时间的测定","血清凝血酶原时间的测定","简易凝血活酶生成试验"],"a":2,"e":"血浆凝血酶原时间在组织凝血活酶和钙离子参与下测定，是反映外源性凝血途径的筛选试验，延长见于因子Ⅱ、Ⅴ、Ⅶ、Ⅹ缺乏及纤维蛋白原减少。"},{"q":"下列关于艾滋病的叙述，除哪项外均正确","o":["其病原体为HIV","HIV为逆转录酶病毒","AIDS为严重的细胞免疫缺陷性疾患","AIDS为先天性免疫缺陷综合征","其血清学检查有间接荧光免疫法及病毒检查法"],"a":3,"e":"艾滋病由人免疫缺陷病毒引起，是获得性免疫缺陷综合征，病毒属逆转录病毒，主要破坏CD4+T淋巴细胞造成严重细胞免疫缺陷，并非先天性免疫缺陷。"},{"q":"造血物质缺乏所起的贫血包含","o":["尿毒症贫血","白血病贫血","巨幼细胞贫血","骨髓纤维化","地中海贫血"],"a":2,"e":"巨幼细胞贫血由叶酸和/或维生素B12缺乏致DNA合成障碍，属造血原料缺乏所致；尿毒症贫血因促红细胞生成素减少，白血病与骨髓纤维化为骨髓浸润，地中海贫血为珠蛋白合成异常。"},{"q":"为了确定肝外胆管阻塞的部位，需选择的检查是","o":["十二指肠引流","电子计算机体层扫描","经内镜逆行胰胆管造影","肝穿刺活检","B型超声检查"],"a":2,"e":"经内镜逆行胰胆管造影可直视壶腹部并注入造影剂，清楚显示胆管狭窄或梗阻的部位与形态，对确定肝外胆管阻塞部位价值最大；B超仅用于初筛。"},{"q":"普氏立克次体主要的传播途径是","o":["消化道","蚤叮咬后入血","螨叮咬后入血","虱叮咬后入血","鼠咬伤感染"],"a":3,"e":"普氏立克次体是流行性斑疹伤寒的病原体，以人虱为传播媒介，虱叮咬后立克次体经叮咬处或搔抓破损的皮肤侵入人体；恙虫病由恙螨传播。"},{"q":"胸部语音震颤不减弱的疾病是","o":["肺组织炎性浸润","胸腔积液","肺气肿","胸膜肥厚","阻塞性肺不张"],"a":0,"e":"肺组织炎性浸润发生实变，声音传导增强，语颤反而增强；胸腔积液、肺气肿、胸膜肥厚及阻塞性肺不张均使声波传导受阻或含气量异常，语颤减弱或消失。"},{"q":"肾小球性蛋白尿见于以下疾病，但除外","o":["隐匿性肾小球肾炎","肾病综合征","急性肾小球肾炎","肾盂肾炎","慢性肾小球肾炎"],"a":3,"e":"肾盂肾炎是肾小管间质的化脓性炎症，产生以α1微球蛋白、β2微球蛋白为主的小分子肾小管性蛋白尿；肾病综合征及急、慢性、隐匿性肾小球肾炎均为肾小球性蛋白尿。"},{"q":"吸气时增强的杂音是","o":["三尖瓣关闭不全的杂音","二尖瓣关闭不全的杂音","二尖瓣狭窄的杂音","主动脉瓣狭窄的杂音","主动脉瓣关闭不全的杂音"],"a":0,"e":"吸气时胸腔负压增大，右心回心血量增加，源于右心的杂音增强，故三尖瓣关闭不全的杂音吸气时增强；源于左心的二尖瓣、主动脉瓣杂音多在呼气时增强。"},{"q":"以下哪个临床表现不是右侧三叉神经损伤表现","o":["右侧面部痛觉减退","右侧直接角膜反射消失","右侧咀嚼肌无力","下颌偏向右侧","右侧闭眼不紧"],"a":4,"e":"三叉神经损害出现同侧面部痛温觉减退、角膜反射消失、咀嚼肌萎缩无力及张口时下颌偏向患侧；闭眼不紧由面神经支配的眼轮匝肌瘫痪所致。"},{"q":"下列疾病不会引起中心型发绀的是","o":["慢性阻塞性肺疾病","感染性休克","急性左心衰竭","法洛四联症","Eisenmenger综合征"],"a":1,"e":"感染性休克时心排血量减少、外周血管痉挛、血流缓慢淤滞，毛细血管氧摄取增多，属周围性发绀；中心性发绀见于慢阻肺、急性左心衰竭、法洛四联症及Eisenmenger综合征。"},{"q":"深反射检查时发现存在阵挛时，反射强度应该为","o":["0","1＋","2＋","3＋","4＋"],"a":4,"e":"深反射按强度分为-至++++，出现阵挛时反射强度为++++，表示反射亢进并伴病理状态，提示锥体束损害；+++为反射增强，可见于正常人或病理情况。"},{"q":"下列哪项试验能较早的反映肾小球滤过功能的损害并估计其损害程度","o":["血尿素氮定量","血肌酐定量","内生肌酐清除率","自由水清除率","浓缩稀释试验"],"a":2,"e":"内生肌酐清除率基本反映肾小球滤过率，其下降早于血肌酐和尿素氮升高，能较早发现肾小球滤过功能受损，并据下降程度估计损害轻重。"},{"q":"患者疑似大叶性肺炎，下列哪项对诊断最有帮助","o":["呼吸困难","咳嗽","咳铁锈色痰","发热","发绀"],"a":2,"e":"铁锈色痰是肺炎链球菌肺炎的典型表现，由肺泡内红细胞破坏后血红蛋白变性所致，对诊断帮助最大；发热、咳嗽、呼吸困难及发绀均缺乏特异性。"},{"q":"间歇热最常见的疾病是","o":["渗出性胸膜炎","斑疹伤寒","疟疾","风湿热","败血症"],"a":2,"e":"间歇热指体温骤升达高峰后持续数小时又骤降至正常，无热期与发热期交替出现，常见于疟疾和急性肾盂肾炎；败血症多为弛张热。"},{"q":"有机磷中毒","o":["双侧瞳孔扩大","双侧瞳孔缩小","双侧瞳孔大小不等","瞳孔缩小伴眼睑下垂","眼睑下垂"],"a":1,"e":"有机磷抑制胆碱酯酶使乙酰胆碱蓄积，瞳孔括约肌收缩，出现双侧瞳孔缩小，并伴多汗、流涎、肌纤维颤动；单侧瞳孔缩小伴眼睑下垂见于Horner综合征。"},{"q":"成年男性红细胞参考值为","o":["（3.5～5.5）×1012/L","（4.0～5.5）×1012/L","（4.0～6.0）×1012/L","（3.5～5.0）×1012/L","（3.0～5.0）×1012/L"],"a":1,"e":"成年男性红细胞计数参考区间为（4.0～5.5）×10¹²/L，血红蛋白130～175g/L；成年女性分别为（3.5～5.0）×10¹²/L和115～150g/L。"},{"q":"有关捻发音错误的是","o":["是一种极细小而均匀一致的湿啰音","多在吸气末易听到","听诊时好像在耳旁用手指捻搓一束头发所产生的声音","高音调、高频率的细小破裂声","就是Velcro啰音"],"a":4,"e":"捻发音是极细而均匀一致的湿啰音，多在吸气终末出现，似耳边捻搓一束头发的声音，见于肺淤血、肺炎早期；Velcro啰音是肺间质纤维化时高调粗糙的爆裂音，二者不同。"},{"q":"腋测法体温的正常值是","o":["35～36℃","36.3～37.2℃","36.5～37.7℃","36～37℃","37.3～38℃"],"a":3,"e":"腋测法将体温计置于腋窝深处5～10分钟后读数，正常值36～37℃，简便安全且不易发生交叉感染；口测法为36.3～37.2℃，肛测法为36.5～37.7℃。"},{"q":"最常见血清铁降低的疾病是","o":["急性重型肝炎","溶血性贫血","再生障碍性贫血","巨幼细胞贫血","消化道肿瘤"],"a":4,"e":"消化道肿瘤慢性失血使铁丢失超过摄入，储存铁耗竭后血清铁降低，是缺铁最常见的原因；溶血性贫血、再生障碍性贫血及巨幼细胞贫血血清铁多正常或增高。"},{"q":"长期反复咳大量脓臭痰伴咯血最可能为","o":["肺结核","急性肺炎","支气管扩张","慢性支气管炎","支气管哮喘"],"a":2,"e":"支气管扩张时气道分泌物潴留并合并厌氧菌感染，长期反复咳大量脓臭痰，病变侵蚀支气管动脉可反复咯血；肺脓肿虽也咳脓臭痰，但病程多较短。"},{"q":"关于皮肤划痕试验，正确的是","o":["用针加适度压力在皮肤上划压","几分钟后就会出现白色划痕","白色划痕持续时间较久，提示副交感神经兴奋性增高","红色划痕迅速出现且持续时间长，提示副交感神经兴奋性增高","不属于自主神经功能检查"],"a":3,"e":"皮肤划痕试验用钝器加适度压力划压皮肤，红色划痕迅速出现、持续较久且增宽隆起，提示副交感神经兴奋性增高或交感神经麻痹；白色划痕持续超过5分钟提示交感兴奋性增高。"},{"q":"关于镜下血尿是指尿沉渣镜检红细胞","o":["0～3个/HPF","＞3个/HPF","＞5个/HPF","＞10个/HPF","＞20个/HPF"],"a":1,"e":"离心尿沉渣镜检每高倍视野红细胞超过3个而尿外观无血色，即为镜下血尿；0～2个/HPF属参考范围，需结合尿蛋白及红细胞形态判断出血来源。"},{"q":"正常脑脊液中为主的细胞是","o":["单个核细胞","吞噬细胞","中性粒细胞","脉络丛细胞","室管膜细胞"],"a":0,"e":"正常脑脊液白细胞成人0～8×10⁶/L，分类以淋巴细胞和单核细胞等单个核细胞为主，二者约7∶3，偶见软脑膜及蛛网膜内皮细胞；化脓性脑膜炎则以中性粒细胞为主。"},{"q":"关于左房舒张晚期奔马律下述正确的是","o":["心室克服舒张末期压力增高方面加强收缩所致","病理性S4距S2较近，距S1较远","在心尖部稍内侧听诊最清晰","在吸气末加强","反映心室收缩期容量负荷过重"],"a":2,"e":"左房舒张晚期奔马律即病理性S4，由心房为克服增高的舒张末期压力加强收缩而产生，音调低、强度弱，距S2较远而靠近S1，于心尖部稍内侧听诊最清晰。"},{"q":"不常见球蛋白升高的疾病是","o":["肝硬化","慢性炎症","急性肝炎","M蛋白血症","淋巴瘤"],"a":2,"e":"球蛋白升高见于肝硬化、慢性炎症、淋巴瘤及M蛋白血症，由慢性抗原刺激使免疫球蛋白合成增加；急性肝炎以转氨酶升高为主，球蛋白多无明显改变。"},{"q":"对于一个已确诊患者的治疗措施不包括","o":["病因治疗","对症治疗","心理安慰","推拿、按摩","诊断性治疗"],"a":4,"e":"已确诊后应针对病因治疗和对症处理，并给予心理安慰、推拿按摩等康复措施；诊断性治疗用于诊断未明时，通过治疗反应验证诊断，不属确诊后的治疗。"},{"q":"关于Kronig峡阐述不正确的是","o":["Kronig峡正常宽度为4～6cm","左侧较右侧宽","左侧较右侧窄","当肺炎浸润性结核时Kronig峡变窄","肺气肿时Kronig峡增宽"],"a":2,"e":"Kronig峡正常宽度4～6cm，因右肺尖位置较低且右肩胛带肌肉较发达，右侧较左侧窄，故“左侧较右侧窄”的叙述错误；肺尖浸润型结核时变窄，肺气肿时增宽。"},{"q":"下列各项均为“急腹症”的病因，但除外","o":["肠梗阻","胃肠穿孔","卵巢扭转","宫外孕","肝淤血"],"a":4,"e":"急腹症指需紧急处理的腹内脏器急性病变，如肠梗阻、胃肠穿孔、卵巢囊肿扭转及宫外孕破裂；肝淤血为右心衰竭所致肝肿大，起病缓慢，不属急腹症。"},{"q":"Austin-Flint杂音最常见于下列何种疾病","o":["风湿性心脏病，二尖瓣狭窄","风湿性心脏病，主动脉瓣关闭不全","风湿性心脏病，二尖瓣关闭不全","风湿性心脏病，主动脉瓣狭窄","风湿性心脏病，三尖瓣狭窄"],"a":1,"e":"中重度主动脉瓣关闭不全时，反流血液使二尖瓣前叶在舒张期被抬起、处于半关闭状态，形成相对性二尖瓣狭窄，于心尖区产生舒张中晚期柔和递减型杂音，即Austin-Flint杂音。"},{"q":"体温调节中枢的高级部分是","o":["视前区-前下丘脑","延髓","脑桥","中脑","脊髓"],"a":0,"e":"体温调节的高级中枢位于视前区-前下丘脑，该处含温度敏感神经元并整合内外温度信息，通过调节产热与散热维持体温恒定；延髓和脊髓属低级调节部位。"},{"q":"患者与人吵架后情绪激动，晕厥。情绪激动时可出现","o":["呼吸浅慢","Kussmaul呼吸","Biot呼吸","Cheyne-Stokes呼吸","呼吸深快"],"a":4,"e":"情绪激动时交感神经兴奋、呼吸中枢兴奋性增高，出现呼吸深快并过度通气，PaCO2降低引起呼吸性碱中毒，可致口周及肢端发麻，重者手足搐搦。"},{"q":"关于肺部叩诊音，叙述不正确的是","o":["叩诊音类型与病变性质、范围及部位有关","当肺内含气量增多、肺张力减弱时，叩诊呈过清音","少量胸腔积液，叩诊不易发现","距胸部表面5cm以上、直径小于3cm的病灶，叩诊可以发现异常","肺内不含气的占位病变，叩诊呈浊音"],"a":3,"e":"距胸壁5cm以上、直径小于3cm的深部小病灶及少量胸腔积液，叩诊不能发现异常；肺内含气量增多、张力减弱时呈过清音，不含气病变呈浊音。"},{"q":"下列哪种情况胸骨左缘第2肋间可见异常搏动","o":["右心室肥大","肺动脉高压","升主动脉瘤","主动脉弓瘤","大动脉炎"],"a":1,"e":"胸骨左缘第2肋间为肺动脉瓣区，该处收缩期搏动见于肺动脉高压或肺动脉扩张；升主动脉瘤在胸骨右缘第1、2肋间搏动，主动脉弓瘤则见于胸骨上窝。"},{"q":"心电图上的P波反应的是","o":["窦房结除极","窦房结复极","心房除极","心房复极","房室结除极"],"a":2,"e":"P波反映左右心房除极的电位变化，窦房结除极本身的电位过小，在体表心电图上不能记录；P波增宽呈双峰提示左房肥大，高尖提示右房肥大。"},{"q":"在下列病变时，叩诊心界可发生如下改变，但应除外","o":["左心室增大，叩诊心界向左、向下扩大","右心室明显肥大，叩诊心界同时向两侧扩大，以向左侧扩大为主","心包积液，立位和卧位时，叩诊心界不一样","肺气肿，叩诊心浊音界变小","缩窄性心包炎，叩诊心浊音界叩不出"],"a":4,"e":"缩窄性心包炎心包增厚、钙化，心室舒张受限，心浊音界多正常或轻度增大，并非叩不出；心包积液时浊音界向两侧扩大，并随体位改变。"},{"q":"正常情况下血液在血管内流动而不发生凝固主要取决于","o":["血液中凝血物质＞抗凝物质","血液中凝血物质＜抗凝物质","血液中凝血物质和抗凝物质呈动态平衡","血管壁维持正常功能","血小板的作用"],"a":2,"e":"血管内皮完整，血小板与凝血因子活性同抗凝及纤溶系统保持动态平衡，血液既不外溢也不在血管内凝固；平衡失调则引起血栓形成或出血。"},{"q":"呕血最常见的原因为","o":["急性胃黏膜病变","食管静脉曲张破裂","消化性溃疡","食管贲门黏膜撕裂","胃癌"],"a":2,"e":"呕血以上消化道疾病为病因，其中消化性溃疡最常见，其次为食管胃底静脉曲张破裂、急性糜烂出血性胃炎和胃癌；食管贲门黏膜撕裂多见于剧烈呕吐后。"},{"q":"在第一心音听诊的特点中，应除外下列哪项","o":["音调低（55～58Hz）","强度较第二心音响","性质较第二心音清脆","心尖部听诊最清晰","与心尖冲动同时出现"],"a":2,"e":"第一心音音调较低（55～58Hz）、时限较长、强度较响，在心尖部最清晰，并与心尖搏动同时出现；第二心音音调高而短促、清脆，在心底部最响。"},{"q":"机体黏膜抗感染的主要抗体是","o":["IgG","sIgA","IgM","IgE","IgD"],"a":1,"e":"分泌型IgA为二聚体，由黏膜固有层浆细胞产生后经上皮细胞分泌至唾液、泪液、乳汁及呼吸道、消化道分泌液中，是黏膜局部抗感染的主要抗体。"},{"q":"主诉的概念是","o":["最主要的症状、体征及疾病演变过程","最主要的症状及伴随症状","最主要的症状及主要诱因","最主要症状起病情况","最主要症状、体征及持续时间"],"a":4,"e":"主诉是病人感受最主要的痛苦或最明显的症状和/或体征及其持续时间，即本次就诊最主要的原因，文字简明，一般不超过1～2句、约20字。"},{"q":"血氯降低最常见于","o":["严重呕吐，腹泻","心力衰竭","尿道梗阻","呼吸性碱中毒","急性肾功能不全"],"a":0,"e":"严重呕吐丢失富含盐酸的胃液，腹泻丢失大量肠液和氯化钠，均使血氯降低，常伴低钠及代谢性碱中毒；心力衰竭、尿道梗阻时血氯多正常或升高。"},{"q":"常见误诊的原因，不包括","o":["查体不详细、不确切","以一元论为指导","完全依赖辅助检查","多做检查","照搬指南"],"a":1,"e":"一元论指用一种疾病解释病人的全部临床表现，是有助于减少诊断分散的思维原则，并非误诊原因；查体不细、过度依赖辅助检查、多做检查及照搬指南才是常见误诊原因。"},{"q":"患者嗜好烟酒茶等习惯属于","o":["主诉","家族史","既往史","个人史","现病史"],"a":3,"e":"个人史记录出生地、居住地、生活与饮食习惯、烟酒嗜好、职业及毒物接触史和冶游史，故烟酒茶嗜好属个人史；家族史记录直系亲属健康及遗传病情况。"},{"q":"凝血过程中起加速（催化）作用的因子是","o":["Ca2＋","FⅤ","FⅩ","FⅫ","FⅡa"],"a":4,"e":"凝血酶即因子Ⅱa不仅使纤维蛋白原转变为纤维蛋白，还能激活因子Ⅴ、Ⅷ、Ⅺ及血小板，具有强大的催化放大作用，是凝血过程中起加速作用的因子。"},{"q":"下列心律失常不会伴有心悸症状的是","o":["偶发室性期前收缩","阵发性室上性心动过速","心房颤动","右束支传导阻滞","二度房室传导阻滞"],"a":3,"e":"右束支传导阻滞仅使心室除极顺序改变，心率与心律基本规则，心室收缩力变化轻微，通常不引起心悸；期前收缩、阵发性室上速、房颤及二度房室传导阻滞均可致心悸。"},{"q":"引起非淋菌性尿道炎最常见的病原体是","o":["解脲支原体","沙眼衣原体","性病淋巴肉芽肿衣原体","杜克雷嗜血杆菌","白假丝酵母菌"],"a":1,"e":"非淋菌性尿道炎主要由沙眼衣原体和支原体引起，其中沙眼衣原体最常见，经性接触传播，表现为尿道刺痒及少量稀薄分泌物；杜克雷嗜血杆菌引起软下疳。"},{"q":"血浆缓冲系统中缓冲能力最强的是","o":["NaHCO3/H2CO3","KHb/Hb","血浆蛋白质-Na/血浆蛋白质","NaHPO4/NaH2PO4","KHCO3/H2CO3"],"a":0,"e":"血浆中NaHCO3/H2CO3缓冲对含量最多、缓冲能力最强，二者比值维持20∶1使血浆pH恒定于7.40；血红蛋白缓冲对主要在红细胞内发挥作用。"},{"q":"正常情况下肠鸣音次数是","o":["1～2次/min","2～3次/min","3～4次/min","4～5次/min","5～10次/min"],"a":3,"e":"正常肠鸣音每分钟4～5次，听诊部位多在脐周；超过10次/分称肠鸣音活跃，见于急性胃肠炎或消化道出血，3～5分钟未闻及称肠鸣音减弱或消失。"},{"q":"用轻叩诊法确定脾脏上界正常在","o":["腋中线第9肋间～11肋间","腋中线第10肋间～12肋间","腋前线第9肋间～11肋间","腋后线第10肋间～12肋间","腋后线第9肋间～11肋间"],"a":0,"e":"脾脏叩诊用轻叩法在左腋中线上进行，正常于第9～11肋间叩得浊音区，宽度约4～7cm，前缘不超过腋前线；浊音区扩大提示脾肿大。"},{"q":"左侧面神经损伤的临床表现不包括","o":["左侧闭眼不紧","左侧面部痛觉减退","左侧额纹浅","左侧鼻唇沟浅","左侧鼓腮漏气"],"a":1,"e":"面神经运动纤维受损出现同侧额纹变浅、闭眼不紧、鼻唇沟变浅、鼓腮漏气及口角歪向健侧；面部痛觉由三叉神经传导，不属面神经损伤的表现。"},{"q":"有关问诊的方法，错误的是","o":["一般从礼节性的交谈开始","先自我介绍，讲明自己的职责","尽可能让患者充分的陈述他认为重要的情况","不可生硬的打断患者的叙述","收集病史，必须严格按时间顺序收集"],"a":4,"e":"问诊时应让病人充分陈述、不随意打断，但采集资料并非严格按症状出现的时间顺序进行，整理后的主诉与现病史才按时间先后书写。"},{"q":"若颈部包块弹性大又无全身症状，应考虑","o":["囊肿","非特异性淋巴结炎","囊状瘤","淋巴结结核","血液系统疾病"],"a":0,"e":"颈部包块弹性大、无压痛且无全身症状者多为囊肿，其内容物为液体故触之有弹性感；淋巴结结核常伴粘连破溃及结核中毒症状，血液病多为无痛性多发淋巴结肿大。"},{"q":"问诊现病史时应遵循的原则是","o":["先由开放性问题开始，再进行特殊提问","先搞清复杂问题","多进行特殊的诱导提问","多进行逼问，以免遗漏信息","尽量使用医学术语"],"a":0,"e":"问诊现病史应先采用开放性提问，让病人像讲故事一样叙述病情以获得大量资料，再针对重点用直接提问追问细节；诱导提问和逼问会引入偏差。"},{"q":"下列是免疫性血小板减少性紫癜骨髓象，但应除外","o":["增生活跃或明显活跃","粒红二系无明显异常","巨核细胞明显减少，增生减低","幼核型或颗粒型巨核明显增多","产板型巨核细胞减少"],"a":2,"e":"ITP骨髓增生活跃或明显活跃，粒红二系大致正常，巨核细胞数正常或增多但伴成熟障碍，幼巨核与颗粒型巨核增多、产板型巨核减少；巨核细胞明显减少伴增生减低见于再生障碍性贫血。"},{"q":"关于窦性心律的心电图诊断，错误的是","o":["Ⅰ导联P波直立","Ⅱ导联P波直立","aVR导联P波直立","V5导联P波直立","V6导联P波直立"],"a":2,"e":"窦性P波在Ⅰ、Ⅱ、aVF及V4～V6导联直立，在aVR导联必定倒置；aVR导联P波直立提示激动起源于心房下部或导联错接，故属错误描述。"},{"q":"用于评价小气道功能障碍的指标为","o":["FEV1/FVC","FEV1%pred","PEF","FVC","MEF50"],"a":4,"e":"MEF50即FEF50%，反映呼气中期小气道流量，与FEF75%、FEF25%～75%共同用于判断小气道功能障碍；FEV1/FVC与FEV1%pred反映大气道通气，不敏感于早期小气道病变。"},{"q":"下列关于间接叩诊法的叙述，正确的是","o":["为了更好地分辨叩诊音，在每个部位叩诊时，每次均可叩4～5次","确定心脏和肝脏的相对浊音界，宜采取轻叩诊法","确定心脏和肝脏的绝对浊音界，宜采取重叩诊法","病灶位置距体表深达7cm左右，需使用中度叩诊法","确定肝上界时，应采取重叩诊法"],"a":1,"e":"病灶范围小或位置浅时宜用轻（弱）叩诊，如确定心、肝相对浊音界及脾界；心、肝绝对浊音界用中等力量叩诊，病灶深达7cm才需重叩，同一部位连续叩2～3次即可。"},{"q":"关于肝界叩诊下列各项均正确，但除外","o":["右肩胛线上第10肋间","右锁骨中线上第5肋间","右锁骨中线上肝上、下界为9～11cm","叩诊肝下界比触诊的肝下缘高1～2cm","右腋中线上为第8肋间"],"a":4,"e":"肝上界位于右锁骨中线第5肋间、右腋中线第7肋间、右肩胛线第10肋间，右锁骨中线上肝上下径为9～11cm；右腋中线第8肋间是肺下界，并非肝上界。"},{"q":"下列关于过氧化物酶（POX）染色，正确的是","o":["急性粒细胞白血病，白血病细胞呈强阳性反应","急性单核细胞白血病，白血病细胞呈强阳性反应","急性淋巴细胞白血病，白血病细胞呈强阳性反应","急性粒细胞白血病，白血病细胞呈阴性反应","嗜碱性粒细胞为阳性"],"a":0,"e":"急性粒细胞白血病原始及幼稚粒细胞过氧化物酶染色多呈阳性、强阳性；急性单核细胞白血病为弱阳性或阴性，急性淋巴细胞白血病为阴性，故POX是鉴别三型急性白血病的主要染色。"},{"q":"关于肝大的下列描述均正确，但除外","o":["急性肝炎时，肝轻度肿大，光滑，缘钝，有压痛","肝淤血时，肝明显肿大，光滑，缘钝，有压痛","脂肪肝时，肝大，质硬，光滑，有压痛","肝硬化早期，肝大，质硬，不光滑，无压痛","肝癌时，肝大，质坚硬，不光滑，有压痛"],"a":2,"e":"脂肪肝所致肝大表面光滑、质软或稍韧且无压痛；质硬伴压痛不属脂肪肝特点，肝硬化质较硬、边缘锐利，肝癌质地坚硬如石、表面高低不平、压痛明显。"},{"q":"支气管呼吸音易见于","o":["肺气肿","胸腔积液","气胸","压迫性肺不张","胸膜粘连"],"a":3,"e":"胸腔积液压迫肺组织形成压迫性肺不张，肺组织变致密有利于支气管呼吸音传导，故于积液区上方可闻及支气管呼吸音；肺气肿与气胸时肺泡含气增多，呼吸音减弱。"},{"q":"下列疾病均可引起腹部揉面感，但除外","o":["结核性腹膜炎","癌性腹膜炎","异位妊娠","急性胃肠穿孔","肝癌肝破裂"],"a":3,"e":"柔韧感（揉面感）见于结核性腹膜炎、腹膜转移癌及异位妊娠破裂等慢性腹腔内出血；急性胃肠穿孔致急性弥漫性腹膜炎，腹膜受刺激使腹肌强直呈板状腹。"},{"q":"下列情况中凝血时间延长，但应除外","o":["严重肝损害","纤维蛋白原严重减少","甲、乙、丙型血友病","原发性血小板减少","应用肝素等抗凝药"],"a":3,"e":"凝血时间反映内源性凝血途径，严重肝损害、纤维蛋白原严重减少、血友病及应用肝素时均延长；原发性血小板减少只影响初期止血，出血时间延长而凝血时间正常。"},{"q":"二尖瓣关闭不全时，可有下列哪种杂音","o":["心尖部全收缩期杂音，并在吸气时增强","心尖部全收缩期杂音，并在呼气时增强","心尖部舒张期杂音，并在呼气时增强","心尖部第一心音亢进","常伴有肺动脉瓣相对关闭不全"],"a":1,"e":"二尖瓣关闭不全产生心尖区全收缩期吹风样杂音，属左心系统杂音，呼气时肺内血量减少、左心回流血量增多而增强；右心杂音则在吸气时增强。"},{"q":"关于大叶肺炎，哪项不正确","o":["稽留热","呼吸急促","铁锈色痰","多见于老年人","可出现胸痛"],"a":3,"e":"大叶性肺炎多见于青壮年，受凉、疲劳、酗酒为诱因，起病急骤，表现为稽留热、呼吸急促、病侧胸痛及铁锈色痰；老年人并非好发人群。"},{"q":"引起S2固定分裂的是","o":["右束支传导阻滞","右心衰竭","左束支传导阻滞","房间隔缺损","二尖瓣狭窄"],"a":3,"e":"S2固定分裂指分裂时距不受呼吸影响，见于房间隔缺损，因左房向右房持续分流使右心血流增多、肺动脉瓣关闭明显延迟；右束支阻滞仅引起S2通常分裂。"},{"q":"心电图示RV1＋SV5为1.5mV，额面电轴为110°，最可能的诊断是","o":["左房肥大","右房肥大","左室肥大","右室肥大","右束支传导阻滞"],"a":3,"e":"RV1＋SV5＞1.05mV加心电轴右偏≥＋90°是右心室肥厚的心电图标准，本例两项均具备；左室肥厚表现为RV5、RV5＋SV1电压增高伴电轴左偏。"},{"q":"流行性出血热的常见症状体征是","o":["发热伴寒战","发热伴口角疱疹","发热伴肝脾肿大","发热伴出血","发热伴昏迷"],"a":3,"e":"发热伴皮肤黏膜出血见于重症感染及流行性出血热等急性传染病，出血为本病特征性表现；发热伴口角疱疹多见于大叶性肺炎、流行性脑脊髓膜炎等。"},{"q":"正常P波形态特点是大部分导联上","o":["呈正负双向","与QRS波主波方向不一致","有切迹呈双峰样","一般是钝圆形，有时可能有轻度切迹","呈高尖形"],"a":3,"e":"正常P波在大部分导联呈钝圆形，有时可有轻度切迹，时限≤0.12秒、振幅＜0.25mV；明显双峰且增宽提示左房肥大，高尖P波提示右房肥大。"},{"q":"免疫性血小板减少性紫癜可出现","o":["BT及PT都正常","BT延长，PT减少","BT延长，PT增多","BT延长，PT正常","BT正常，PT减少"],"a":1,"e":"官方答案为【BT延长，PT减少】，但依据教材，正确答案为【BT延长，PT正常】。ITP为血小板数量减少所致的初期止血障碍，出血时间延长，而凝血因子及外源性凝血途径正常，凝血酶原时间不缩短。"},{"q":"下列关于第四心音（S4）叙述正确的是","o":["青年患者的正常所见","在心底部听诊最清楚","在收缩早期时可听到","心房收缩引起的震动","在房颤的患者中可听到"],"a":3,"e":"S4由心房收缩使房室瓣及其附属结构突然紧张、振动产生，出现于舒张晚期、S1之前，心尖部及其内侧最清楚，低调沉浊而弱，属病理性；心房颤动时心房无有效收缩，故听不到S4。"},{"q":"关于头颈部姿势的描述，下列哪项是错误的","o":["正常人颈部伸屈、转动自如","头不能抬起见于多发性肌炎","斜颈可见于颈肌外伤","颈部强直见于蛛网膜下腔出血","先天性斜颈者，健侧胸锁乳突肌粗短"],"a":4,"e":"先天性斜颈为病侧胸锁乳突肌挛缩粗短，头向患侧偏斜、下颌转向健侧；颈部强直见于脑膜炎、蛛网膜下腔出血，头不能抬起见于严重虚弱及多发性肌炎。"},{"q":"最不可能出现肢体导联低电压的是","o":["大量心包积液","心脏淀粉样变性","扩张型心肌病","肺栓塞","肥胖"],"a":3,"e":"肢体导联低电压见于大量心包积液、心脏淀粉样变性、扩张型心肌病、肥胖与肺气肿，因心肌电动力减弱或组织传导衰减；肺栓塞主要表现为SⅠQⅢTⅢ及电轴右偏。"},{"q":"肝大常见于下列疾病，但除外","o":["肝炎","肝淤血","脂肪肝","早期肝硬化","肺气肿"],"a":4,"e":"肺气肿时肺过度充气、膈肌下降，肝脏被下推而可触及，并非肝大；肝炎、肝淤血、脂肪肝及早期肝硬化均有肝脏体积增大。"},{"q":"肠鸣音亢进不会出现在","o":["腹泻","急性肠炎","胃肠道大出血","服用泻剂","麻痹性肠梗阻"],"a":4,"e":"麻痹性肠梗阻时肠壁蠕动减弱或消失，肠鸣音减弱甚至消失；腹泻、急性肠炎、胃肠道大出血及服泻剂后肠蠕动增强，肠鸣音活跃或亢进。"},{"q":"心源性水肿发病机制说法正确的是","o":["毛细血管通透性增高","淋巴液回流受阻","毛细血管滤过压升高","血浆胶体渗透压降低","组织液蛋白含量高"],"a":2,"e":"心源性水肿的核心机制是右心衰体循环淤血，毛细血管内静水压（滤过压）升高使组织液生成增多；血浆胶体渗透压降低是肾性、肝性与营养不良性水肿的机制。"},{"q":"腰椎间盘突出症患者、坐骨神经痛患者检查结果均阳性的试验是","o":["摇摆试验","拾物试验","直腿抬高试验","屈颈试验","股神经牵拉试验"],"a":2,"e":"直腿抬高试验（Lasegue征）牵拉坐骨神经，腰椎间盘突出症与单纯坐骨神经痛均可因神经根受压或炎性刺激而阳性；拾物试验反映腰椎活动受限，屈颈试验见于脑膜刺激征。"},{"q":"哪些常规导联出现特征性心电图改变提示可能有左室后壁心肌梗死","o":["V1～V3导联Q波","V3、V4（V5）导联或Q波","Ⅰ、aVL、V5、V6导联或Q波","V1、V2导联出现R波增高、S-T段压低及T波增高","Ⅱ、Ⅲ、aVF导联或Q波"],"a":3,"e":"正后壁心肌梗死时V7～V9出现异常Q波，对应导联V1、V2呈R波增高、ST段压低及T波增高的镜像改变；下壁梗死则在Ⅱ、Ⅲ、aVF出现异常Q波。"},{"q":"下列各项均为腹部触诊注意事项，但除外","o":["一般采取半卧位，两腿对称稍屈曲","患者保持镇静，避免紧张","患者做缓慢腹式呼吸运动","检查肾脏可采取坐位或立位","检查脾脏时可左侧卧位"],"a":0,"e":"腹部触诊应取低枕仰卧位，两手置于体侧，两腿屈起并稍分开使腹肌松弛，再做缓慢腹式呼吸；半卧位、两腿对称屈曲不是腹部触诊的规范体位。"},{"q":"以下哪项心电图表现不会出现在急性广泛前壁ST段抬高型心肌梗死的患者","o":["V1～V5导联T波高尖","V1～V4导联ST段弓背抬高","Ⅰ、avL导联ST段弓背抬高","Ⅱ、Ⅲ、avF导联ST段弓背抬高","V7～V9导联ST段压低"],"a":3,"e":"广泛前壁梗死时V1～V5及Ⅰ、aVL导联ST段弓背向上抬高，Ⅱ、Ⅲ、aVF为下壁导联，其抬高提示下壁梗死；V7～V9ST段压低可属后壁镜像改变。"},{"q":"下列疾病均可有明显腹壁肌紧张，除外","o":["急性胃肠穿孔","坏死性胰腺炎","急性胆囊炎","阑尾炎穿孔","慢性盆腔炎症"],"a":4,"e":"慢性盆腔炎症位置深在、对腹膜刺激轻微，不引起明显腹壁紧张；急性胃肠穿孔、坏死性胰腺炎、急性胆囊炎及阑尾炎穿孔均可致腹肌紧张甚至板状腹。"},{"q":"下述为检查腹部反跳痛的方法，但不包括","o":["以一两个手指逐渐深压腹部病变部位","在深压触诊的基础上迅速将手抬起","在深压触诊的基础上缓慢将手抬起","抬手同时询问患者是否感觉疼痛加重","抬手同时要观察患者的面部表情"],"a":2,"e":"检查反跳痛应在深压基础上稍停2～3秒后迅速抬手，同时询问疼痛是否加重或观察面部表情；缓慢抬手不能使腹膜骤然牵张，故不属检查方法。"},{"q":"关于肥胖的测量，下列说法正确的是","o":["超过标准体重的10%为肥胖","BMI＝25是正常体重","BMI＝30是肥胖","BMI＝20是偏瘦","女性腰围≥90cm为肥胖"],"a":2,"e":"按世界卫生组织标准BMI≥30kg/m²为肥胖，25～29.9为超重；我国标准以BMI≥28为肥胖，体重超过标准体重20%为肥胖。"},{"q":"维生素K缺乏导致皮肤黏膜出血的机制是","o":["毛细血管壁通透性增加","血小板聚集功能异常","血小板数量异常","肝脏产生的凝血酶原等减少","ATⅢ缺陷"],"a":3,"e":"维生素K是γ-羧化酶的辅因子，缺乏时肝脏合成的凝血酶原（因子Ⅱ）及因子Ⅶ、Ⅸ、Ⅹ羧化障碍、活性下降，导致皮肤黏膜出血。"},{"q":"Ca2＋是凝血因子中的","o":["Ⅲ因子","Ⅳ因子","Ⅴ因子","Ⅷ因子","Ⅹ因子"],"a":1,"e":"凝血因子Ⅳ即钙离子，参与因子Ⅹa-Ⅴ、Ⅸa-Ⅷa等复合物的形成，是凝血瀑布多个环节必需的辅因子，本身不具蛋白酶活性。"},{"q":"在胸骨左缘第2肋间触到一连续性震颤，最常见于","o":["法洛四联症","动脉导管未闭","室间隔缺损","房间隔缺损","右位心"],"a":1,"e":"胸骨左缘第2肋间连续性机器样震颤伴连续性杂音是动脉导管未闭的特征；室间隔缺损的震颤在胸骨左缘第3～4肋间且为收缩期，肺动脉瓣狭窄亦为收缩期震颤。"},{"q":"脾大测量结果记录为-2cm，测量的线是在","o":["甲乙线","甲丙线","丁戊线","锁骨中线","腋中线"],"a":2,"e":"脾右缘未超过前正中线时，测量脾右缘至前正中线的最短距离并以负值记录，此即丁戊线；-2cm表示脾右缘距前正中线2cm，属轻度肿大。"},{"q":"下列哪种情况肺泡呼吸音增强","o":["发绀","胸痛","重症肌无力","肺实变早期","胸腔积液"],"a":3,"e":"肺实变早期肺组织充血、渗出使呼吸音传导增强，缺氧又使呼吸运动代偿性增强，故肺泡呼吸音可增强；胸痛、重症肌无力使呼吸运动受限，胸腔积液压迫肺组织，均使肺泡呼吸音减弱。"},{"q":"右室心肌梗死ST段抬高出现在下列哪些导联","o":["V1，V2，V3导联","V3，V4，V5导联","V3R，V4R，V5R导联","V7，V8，V9导联","Ⅰ，aVL导联"],"a":2,"e":"右心室心肌梗死时右胸导联V3R～V5R（尤其V3R、V4R）ST段抬高≥0.1mV，且常与下壁梗死并存；V7～V9用于正后壁，Ⅰ、aVL反映高侧壁。"},{"q":"FEV1 81%，FVC 75%，FEV1/FVC 90%，TLC 75%，DLCO 80%。肺功能诊断为","o":["阻塞性通气功能障碍","限制性通气功能障碍","混合性通气功能障碍","孤立性弥散功能减低","限制性通气功能障碍伴弥散功能减低"],"a":1,"e":"FEV1/FVC90%正常而FVC、TLC降低，符合限制性通气功能障碍；阻塞性者以FEV1/FVC降低为主，混合性者二者均降低，本例DLCO正常故未合并弥散障碍。"},{"q":"关于心源性水肿机制，错误的是","o":["有效循环血量减少","肾血流量减少","低蛋白血症","继发性醛固酮增多","静脉压增高"],"a":2,"e":"心源性水肿由右心衰体循环淤血引起，有效循环血量与肾血流量减少、继发醛固酮增多致钠水潴留，静脉压及毛细血管滤过压升高；低蛋白血症是肾性、肝性及营养不良性水肿的机制。"},{"q":"湿啰音如发生在两肺底，多见于","o":["肺脓肿","支气管炎","肺结核","左心功能不全","大叶性肺炎"],"a":3,"e":"两肺底湿啰音是左心功能不全肺淤血的典型体征，液体因重力潴积于下垂部位肺泡；肺脓肿、肺结核多为局限性湿啰音，支气管炎以干啰音为主。"},{"q":"下列疾病中S1减弱的是","o":["二尖瓣狭窄","大面积心肌梗死","严重贫血","运动员运动后","甲状腺功能亢进"],"a":1,"e":"S1强度取决于心肌收缩力与收缩开始时房室瓣的位置，大面积心肌梗死时心肌收缩力显著减弱，S1低钝；二尖瓣狭窄时S1亢进，贫血、甲亢及运动后S1增强。"},{"q":"腹部听到连续性血管杂音，常见的病征是","o":["动脉瘤","动脉狭窄","腹壁静脉严重曲张","腹块压迫腹主动脉","肝癌压迫肝动脉"],"a":2,"e":"门静脉高压时脐静脉重新开放，腹壁静脉严重曲张形成侧支，血流经迂曲扩张的静脉产生连续性静脉营营声，于脐周或剑突下闻及；动脉瘤、动脉狭窄为收缩期杂音。"},{"q":"下列各项均为腹部听诊内容，但除外","o":["肠鸣音","血管杂音","摩擦音","搔弹音","振水音"],"a":4,"e":"腹部听诊内容包括肠鸣音、血管杂音、摩擦音和搔弹音；振水音需以冲击触诊法振动胃部听取气液撞击声，按教材列为独立检查项目，不属听诊内容。"},{"q":"下列关于右心衰竭发生呼吸困难机制的叙述均正确，但除外","o":["右心房压升高，反射性兴奋呼吸中枢","上腔静脉压升高，反射兴奋呼吸中枢","肺循环压力升高，反射兴奋呼吸中枢","血氧含量减少，刺激呼吸中枢","淤血性肝大、胸腔积液等使呼吸受限"],"a":2,"e":"右心衰呼吸困难的机制为右心房及上腔静脉压升高刺激压力感受器、血氧降低及代谢产物增多兴奋呼吸中枢、淤血性肝大与胸腹腔积液限制呼吸运动；肺循环压力升高属左心衰机制。"},{"q":"红细胞大小不均在何种情况下最明显","o":["再生障碍性贫血","地中海贫血","溶血性贫血","失血性贫血","巨幼细胞贫血"],"a":4,"e":"红细胞大小不均指红细胞直径相差一倍以上，属病理造血表现，中度以上贫血均可出现，以巨幼细胞贫血最为明显；缺铁性贫血以小细胞低色素改变为主。"},{"q":"下列哪项诊断门脉性肝硬化最可靠","o":["腹水","脾大","肝掌及蜘蛛痣","白蛋白/球蛋白倒置","肝穿刺活检有假小叶形成"],"a":4,"e":"肝穿刺活检见假小叶形成是肝硬化最可靠的诊断依据，属病理形态学确诊；腹水、脾大、肝掌与蜘蛛痣、白/球蛋白倒置均缺乏特异性。"},{"q":"蜘蛛痣的发生与下列哪一因素有关","o":["雄激素增高","雄激素减少","甲状腺激素增高","雌激素减少","雌激素增高"],"a":4,"e":"蜘蛛痣与肝脏对雌激素灭活作用减弱、血中雌激素水平增高有关，常见于急慢性肝炎和肝硬化；雄激素增高则引起女性男性化表现。"},{"q":"二尖瓣关闭不全时，最主要的体征是","o":["心尖冲动向左下移位","心尖冲动呈抬举性","肺动脉瓣区第二心音亢进分裂","心尖区收缩期吹风样杂音，粗糙，3/6级以上","心界向左下扩大"],"a":3,"e":"二尖瓣关闭不全最主要的体征是心尖区响亮粗糙、3/6级以上的全收缩期吹风样杂音，向左腋下及左肩胛下区传导；心尖冲动左下移位与心界扩大均为继发改变。"},{"q":"下列是肺部叩诊呈浊音时正确的描述，但应除外","o":["与清音相反","叩诊音较长","高调而不响亮","叩诊时板指下的振动感较少","可见于肺部含气量减少"],"a":1,"e":"浊音是音调较高、音响较弱、振动持续时间较短的叩诊音，与清音相反，见于肺炎、肺不张、肺水肿等肺含气量减少的病变；叩诊音较长不符合浊音特点。"},{"q":"梅尼埃病的临床特点不包括","o":["恶心、呕吐","眩晕","眼球震颤","听力减退","鼓膜穿孔"],"a":4,"e":"梅尼埃病以发作性眩晕、耳鸣、听力减退、眼球震颤伴恶心呕吐为特点，反复发作，鼓膜完整；鼓膜穿孔见于化脓性中耳炎、迷路炎等。"},{"q":"最易引起S1增强的疾病是","o":["主动脉瓣关闭不全","二尖瓣关闭不全","二尖瓣狭窄","原发性高血压","主动脉瓣狭窄"],"a":2,"e":"二尖瓣狭窄时左室充盈减少，收缩开始时二尖瓣位置低垂、左室内压上升加速，瓣膜关闭振幅增大，故S1亢进；二尖瓣关闭不全、主动脉瓣病变均使S1减弱。"},{"q":"下列各项是心包积液的体征，但应除外","o":["心包叩击音","奇脉","颈静脉Kussmaul征","Ewart征","枪击音"],"a":4,"e":"心包积液可有心包叩击音、奇脉、颈静脉Kussmaul征及Ewart征；枪击音是脉压增大时于股动脉闻及的周围血管征，见于主动脉瓣关闭不全、甲亢等。"},{"q":"小量咯血是指每日咯血量","o":["＜50ml","＜100ml","＜200ml","＜300ml","＜500ml"],"a":1,"e":"每日咯血量在100ml以内为小量咯血，100～500ml为中等量，500ml以上或一次100～500ml为大量咯血；大咯血多见于空洞型肺结核、支气管扩张和慢性肺脓肿。"},{"q":"下列贫血属于小细胞低色素性贫血的是","o":["尿毒症所致贫血","恶性肿瘤所致贫血","缺铁性贫血","再生障碍性贫血","溶血性贫血"],"a":2,"e":"缺铁性贫血因铁缺乏使血红蛋白合成障碍，红细胞体积小、中央淡染区扩大，呈小细胞低色素性；肾性贫血、恶性肿瘤性贫血及再生障碍性贫血多为正细胞正色素性。"},{"q":"上腹部听到振水音时可见于","o":["胃溃疡","胃扩张","急性胃炎","慢性胃炎","十二指肠球部溃疡"],"a":1,"e":"清晨空腹或餐后6～8小时以上仍有上腹振水音，提示幽门梗阻或胃扩张，因胃内潴留大量液体与气体；胃溃疡、胃炎及十二指肠球部溃疡不引起胃潴留。"},{"q":"下列是支气管哮喘体征，哪项不正确","o":["胸廓呈吸气位","两肺叩诊过清音","两肺布满干鸣","呈混合性呼吸困难","呼吸动度变小"],"a":3,"e":"支气管哮喘因下呼吸道阻塞、气流呼出不畅而呈呼气性呼吸困难，呼气延长、两肺满布哮鸣音，胸廓呈吸气位、叩诊过清音；混合性呼吸困难见于肺或胸膜广泛病变。"},{"q":"水肿伴体重减轻、消瘦者最可能是","o":["肝源性水肿","心源性水肿","营养不良性水肿","肾源性水肿","特发性水肿"],"a":2,"e":"营养不良性水肿因慢性消耗、蛋白丢失致低蛋白血症和维生素B1缺乏，常伴体重减轻与消瘦；心源性、肝源性及肾源性水肿多不伴明显消瘦。"},{"q":"引起吸收热的为","o":["急性溶血反应","结缔组织病","甲亢","心力衰竭","中暑"],"a":0,"e":"吸收热属无菌性坏死物质吸收所致，急性溶血时红细胞破坏产物被吸收可引起发热，常伴寒战、黄疸；结缔组织病属免疫性发热，甲亢与中暑分别因产热增多和散热障碍。"},{"q":"主动脉瓣关闭不全，出现周围血管征的原因是","o":["外周动脉硬化","回心血量增加","心输出量增大","收缩压增高、舒张压下降","中小动脉弹性增加"],"a":3,"e":"主动脉瓣关闭不全时舒张期血液反流入左室，心搏量增大使收缩压升高，舒张期反流使舒张压下降、脉压增大，故出现水冲脉、枪击音等周围血管征。"},{"q":"肺动脉瓣第二心音（P2）减弱见于","o":["二尖瓣狭窄","肺动脉瓣狭窄","二尖瓣关闭不全","房间隔缺损","左心衰竭"],"a":1,"e":"肺动脉瓣狭窄时瓣叶增厚、活动受限，肺动脉内压力与血流减少，P2减弱，常伴收缩期喷射性杂音和震颤；二尖瓣狭窄、房间隔缺损及左心衰均使P2亢进。"},{"q":"急性胰腺炎患者呕吐后腹痛常可","o":["减轻","缓解","加重","消失","无变化"],"a":4,"e":"急性胰腺炎腹痛由胰腺水肿、炎症及胰酶自身消化刺激腹腔神经丛引起，与胃肠内容物无关，故呕吐后腹痛不减轻，此点可与胃源性呕吐鉴别。"},{"q":"玫瑰花结形成试验测值降低见于","o":["免疫缺陷性疾病","甲状腺功能亢进","甲状腺炎","重症肌无力","慢性活动性肝炎"],"a":0,"e":"E玫瑰花结形成试验检测T细胞数量与功能，降低见于免疫缺陷性疾病、恶性肿瘤、某些病毒感染及大面积烧伤；甲亢、甲状腺炎、重症肌无力及慢性活动性肝炎时升高。"},{"q":"急性阑尾炎临床症状发生的顺序一般是","o":["先恶心后低热，再右下腹疼痛","先低热几小时后右下腹痛，呕吐","先呕吐，随即发热，腹痛","先上腹或脐周痛，继之恶心或呕吐，再右下腹痛","没有明确的顺序"],"a":3,"e":"急性阑尾炎早期为内脏神经支配的中上腹或脐周弥散痛，数小时后炎症波及壁腹膜，疼痛固定于右下腹，约70%～80%病人有典型转移性右下腹痛，常伴恶心呕吐。"},{"q":"下列疾病中通过骨髓检查可确诊的是","o":["缺铁性贫血","急性白血病","淋巴瘤","原发免疫性血小板减少症","溶血性贫血"],"a":1,"e":"急性白血病经骨髓涂片见原始细胞明显增生即可确诊并分型；缺铁性贫血、原发免疫性血小板减少症与溶血性贫血须分别结合铁代谢、血小板抗体及溶血试验判断。"},{"q":"成人清晨安静状态下的舌下温度正常范围是","o":["36～37℃","36.3～37.2℃","36.6～37.7℃","36.2～37.3℃","36.5～37.7℃"],"a":1,"e":"口测法测温5分钟后读数，正常范围36.3～37.2℃，结果较准确，但婴幼儿及神志不清者不宜使用；肛测法正常值36.5～37.7℃，较口测法高0.2～0.5℃。"},{"q":"在正常骨髓抽吸中发现的最大的细胞是","o":["成骨细胞","巨核细胞","成髓细胞","原红细胞","晚幼粒细胞"],"a":1,"e":"巨核细胞是骨髓中体积最大的细胞，直径可达30～100μm，胞体大、核多叶、胞质丰富含颗粒，低倍镜下即可辨认并计数全片巨核细胞数。"},{"q":"外周血中白细胞的组成主要的细胞是","o":["中性粒细胞","淋巴细胞","单核细胞","嗜酸性粒细胞","嗜碱性粒细胞"],"a":0,"e":"外周血白细胞以中性粒细胞为主，占40%～75%，是数量最多的白细胞；淋巴细胞占20%～40%，单核细胞、嗜酸性及嗜碱性粒细胞比例均低。"},{"q":"临床诊断中，实践循证医学的基本步骤不包括下列哪一项","o":["临床问题的提出与构建","检索相关研究证据","进行诊断试验","诊断性试验证据的评价与应用","后效评价"],"a":2,"e":"实践循证医学包括提出并构建临床问题、检索证据、评价证据、应用证据和后效评价；实施诊断试验属具体临床研究，不属其基本步骤。"},{"q":"在主动脉瓣及二尖瓣听诊区均听到舒张期杂音的患者，下列哪项检查结果可以明确该患者为单纯的主动脉瓣病变","o":["X线检查无左室增大","心电图检查示左室肥厚","主动脉影增宽","心脏彩超无左房扩大","第一心音不亢进"],"a":3,"e":"主动脉瓣关闭不全的反流束冲击二尖瓣前叶可产生Austin Flint杂音，使心尖区也闻及舒张期杂音；此时超声示左房不大而左室扩大，可与二尖瓣狭窄鉴别。"},{"q":"外致热原引起发热主要是","o":["激活局部的血管内皮细胞，释放致炎物质","刺激局部的神经末梢，释放神经介质","直接作用于下丘脑的体温调节中枢","激活产EP细胞导致内生致热原的产生和释放","加速分解代谢，产热增加"],"a":3,"e":"外源性致热原分子量大，不能通过血脑屏障，须激活血液中中性粒细胞、单核巨噬细胞等产EP细胞，使其释放IL-1、TNF等内源性致热原，再作用于体温调节中枢。"},{"q":"听诊能发现的心律失常最常见于","o":["室上性心动过速","窦性心动过速","室性心动过速","心房颤动","一度房室传导阻滞"],"a":3,"e":"心房颤动的心音强弱不等、心律绝对不规则及脉搏短绌经听诊即可诊断；一度房室传导阻滞听诊无异常，各类心动过速需心电图区分类型。"},{"q":"正常成年人静息状态下呼吸频率为","o":["14～18次/min","12～20次/min","16～18次/min","16～20次/min","18～22次/min"],"a":1,"e":"正常成人静息状态下呼吸频率为12～20次/分，呼吸与脉搏之比约1∶4；超过24次/分为呼吸过速，低于12次/分为呼吸过缓。"},{"q":"以下哪项属于T细胞膜分子","o":["CD20","CD40","CD8","CD80","CD22"],"a":2,"e":"CD8是T细胞的表面分化抗原，表达于细胞毒性T细胞，识别MHCⅠ类分子提呈的抗原；CD19、CD20、CD22为B细胞标志，CD40与CD80主要见于B细胞和抗原提呈细胞。"},{"q":"暂时性尿失禁常见于下列疾患，除了","o":["尿路感染","前列腺增生","急性精神错乱性疾病","药物反应","心理性忧郁症"],"a":1,"e":"暂时性尿失禁见于尿路感染、急性精神错乱性疾病、药物反应和心理性忧郁症，去除病因后可恢复；前列腺增生引起长期性尿失禁及充溢性尿失禁。"},{"q":"血清铁降低而总铁结合力增高，提示","o":["再生障碍性贫血","溶血性贫血","缺铁性贫血","铁粒幼细胞贫血","慢性感染性贫血"],"a":2,"e":"缺铁性贫血时贮存铁耗竭，血清铁降低而总铁结合力代偿性增高，转铁蛋白饱和度下降；慢性感染性贫血血清铁亦低，但总铁结合力降低，可资鉴别。"},{"q":"叹气样呼吸见于","o":["喉炎","左心衰竭","右心衰竭","肺气肿","癔症"],"a":4,"e":"叹气样（叹息样）呼吸属精神性呼吸困难，因过度通气致呼吸性碱中毒，见于焦虑症、癔症；喉炎为吸气性呼吸困难，左心衰为夜间阵发性呼吸困难。"},{"q":"血浆阴离子间隙（AG）指","o":["血浆阳离子减去阴离子","血浆阴离子减去阳离子","血浆阴离子总和","血浆[Cl－]与[HCO3－]之和减去[Na＋]","血浆[Na＋]减去[Cl－]与[HCO3－]之和"],"a":4,"e":"阴离子间隙指血浆未测定阴离子与未测定阳离子之差，按AG＝Na⁺－（Cl⁻＋HCO₃⁻）计算，参考值8～16mmol/L，用于判断代谢性酸中毒类型。"},{"q":"以下哪项是B细胞的表面标志","o":["CD28","CD19","CD4","CD8","CD2"],"a":1,"e":"CD19是B细胞特异的表面分化抗原，贯穿B细胞发育全程，为鉴定B细胞最常用的标志；CD4、CD8、CD2、CD28均为T细胞标志。"},{"q":"红细胞染色反应为低色素性，不见于","o":["缺铁性贫血","地中海贫血","铁粒幼细胞贫血","巨幼细胞贫血","某些血红蛋白病"],"a":3,"e":"巨幼细胞贫血因DNA合成障碍使红细胞体积增大、血红蛋白充盈良好，呈大细胞高色素性，中央淡染区消失；缺铁性贫血、地中海贫血、铁粒幼细胞贫血及部分血红蛋白病为低色素性。"},{"q":"肾在维持酸碱平衡中最主要的作用是","o":["直接排出酮体","排H＋保Na＋","重吸收HCO3－以恢复血中HCO3－浓度","对付气化酸","排出铵盐"],"a":2,"e":"肾脏通过H⁺-Na⁺交换排出H⁺、重吸收滤过的HCO₃⁻，并分泌NH₃、排泄可滴定酸；其中重吸收HCO₃⁻是回收碱储备、维持血浆HCO₃⁻浓度的主要方式。"},{"q":"不符合心肌缺血心电图改变的是","o":["ST段弓背向上抬高","T波高耸呈帐篷型改变","ST段水平型下移","ST段下垂型下移","T波倒置呈冠状T"],"a":1,"e":"心肌缺血的心电图改变为T波低平、倒置（冠状T）及ST段水平型或下垂型下移，急性损伤期才出现ST段抬高；T波高耸呈帐篷型是高钾血症的表现。"},{"q":"大叶肺炎典型患者咳何种痰","o":["黄痰","白色泡沫痰","铁锈色痰","胶冻状痰","暗红色黏稠血痰"],"a":2,"e":"铁锈色痰是肺炎链球菌肺炎的典型表现，因肺泡内红细胞被巨噬细胞吞噬破坏、血红蛋白转变为含铁血黄素所致；黄绿色痰提示铜绿假单胞菌感染。"},{"q":"呼吸性酸中毒时血浆PaCO2为","o":["40mmHg","45mmHg","35mmHg","20mmHg","＞80mmHg"],"a":1,"e":"PaCO₂参考区间为35～45mmHg，以PaCO₂原发性升高为呼吸性酸中毒，超过45mmHg即可判断；低于35mmHg为呼吸性碱中毒。"},{"q":"下列疾病均可出现肠鸣音亢进，但除外","o":["肠梗阻","低血钾","胃肠炎","消化道出血","服泻剂后"],"a":1,"e":"低血钾使肠壁肌肉张力降低、蠕动减弱，肠鸣音减弱；机械性肠梗阻、胃肠炎、消化道出血及服泻剂后肠蠕动增强，肠鸣音活跃或亢进。"},{"q":"镜下血尿是指尿液离心沉淀后镜检结果显示红细胞","o":["＞3个/HPF","＞5个/HPF","＞2个/HPF","＞10个/HPF","＞8个/HPF"],"a":0,"e":"离心沉淀后尿沉渣镜检每高倍视野红细胞超过3个即为镜下血尿，尿外观可无血色；肉眼血尿则尿呈洗肉水色或血色，肉眼即可辨认。"},{"q":"请问以下哪个凝血因子不存在于血浆中","o":["Ⅰ因子","Ⅱ因子","Ⅲ因子","Ⅳ因子","Ⅴ因子"],"a":2,"e":"组织因子（Ⅲ因子）由组织及内皮细胞释放，存在于组织中而不存在于血浆；钙离子为Ⅳ因子，Ⅰ、Ⅱ、Ⅴ等因子均存在于血浆。"},{"q":"心脏听诊能确定诊断的心律失常是","o":["室性期前收缩","房性期前收缩","心房颤动","窦性心动过速","窦性心动过缓"],"a":2,"e":"心房颤动的心律绝对不规则、S1强弱不等及脉搏短绌，听诊即可确诊；期前收缩、窦性心动过速与过缓需靠心电图区分类型。"},{"q":"二度Ⅰ型房室传导阻滞，文氏现象的心电图特征是","o":["P-R间期进行性缩短","R-R间距进行性缩短","固定的房室3∶1传导","P-R间期进行性延长，伴QRS波脱漏","P-R间期进行性延长"],"a":3,"e":"二度Ⅰ型房室传导阻滞表现为PR间期逐渐延长直至P波后QRS波脱漏，漏搏后PR间期趋短，如此周而复始即文氏现象；PR间期恒定伴脱漏为Ⅱ型。"},{"q":"分泌性腹泻可见于下列疾病，但除外","o":["慢性肠炎","霍乱","血管活性肽瘤","胃泌素瘤","小肠吸收不良综合征"],"a":4,"e":"分泌性腹泻由肠黏膜分泌大量电解质和水所致，见于霍乱、血管活性肠肽瘤、胃泌素瘤及慢性肠炎；小肠吸收不良综合征属渗透性腹泻，因吸收面积减少与消化不良引起。"},{"q":"因为电延迟造成第一心音分裂的是","o":["右心衰竭","右束支传导阻滞","肺动脉高压","肺源性心脏病","Ebstein畸形"],"a":1,"e":"电活动延迟见于完全性右束支传导阻滞，右室激动及三尖瓣关闭明显迟于二尖瓣，形成S1分裂；肺动脉高压、Ebstein畸形属机械活动延迟所致。"},{"q":"正常脑脊液蛋白电泳含量最高的是","o":["α1球蛋白","α2球蛋白","β球蛋白","γ球蛋白","白蛋白"],"a":4,"e":"正常脑脊液蛋白电泳以白蛋白含量最高，占一半以上，因血脑屏障对白蛋白通透相对容易；β、γ球蛋白含量均明显低于白蛋白。"},{"q":"某患者复钙试验延长，吸附血浆能纠正，贮存血清不能纠正，最可能的诊断是","o":["因子Ⅵ缺乏","因子Ⅶ缺乏","因子Ⅷ缺乏","因子Ⅸ缺乏","因子Ⅹ缺乏"],"a":2,"e":"复钙试验反映内源性凝血，因子Ⅷ存在于吸附血浆而不存在于贮存血清，故吸附血浆能纠正、贮存血清不能纠正，提示因子Ⅷ缺乏。"},{"q":"对痛风性关节炎描述错误的是","o":["常因饮酒或高嘌呤饮食而诱发","关节痛剧烈，但间歇期常无症状","足跖趾关节常受累","常伴皮肤红肿热痛","多为对称性小关节肿痛"],"a":4,"e":"痛风性关节炎多累及单侧足跖趾关节等小关节，急性发作红肿热痛剧烈，饮酒及高嘌呤饮食可诱发，间歇期无症状；对称性小关节肿痛是类风湿关节炎的特点。"},{"q":"下列各项均为肠梗阻的临床共同表现，但除外","o":["腹痛","腹胀","休克","呕吐","便秘"],"a":2,"e":"肠梗阻的共同表现为腹痛、呕吐、腹胀及停止排便排气；休克仅在绞窄性梗阻、肠穿孔或严重脱水时出现，不是各型肠梗阻的共同表现。"},{"q":"主要用于鉴别急性单核细胞白血病与急性粒细胞白血病的染色方法是","o":["糖原染色","非特异性酯酶染色","酸性磷酸酶染色","特异性酯酶染色","铁染色"],"a":1,"e":"α-乙酸萘酚酯酶即非特异性酯酶，主要存在于单核系细胞，急性单核细胞白血病呈强阳性且可被氟化钠抑制，急性粒细胞白血病阴性或弱阳性，故用于二者鉴别。"},{"q":"触到右肾下极在正常人中不可见于","o":["身材瘦长者","肾下垂","游走肾","肾代偿性增大","肾肿瘤"],"a":4,"e":"正常人有时可触及右肾下极，身材瘦长者、肾下垂、游走肾及肾脏代偿性增大时更易触及；肾肿瘤属病理性肾肿大伴质硬、表面不平，与上述生理或位置性因素不同。"},{"q":"心电图检查V1导联位于胸骨右缘","o":["第一肋间","第二肋间","第三肋间","第四肋间","第五肋间"],"a":3,"e":"V1导联电极置于胸骨右缘第4肋间，V2在胸骨左缘第4肋间，V4在左锁骨中线第5肋间；V1是观察P波及右心病变的常用导联。"},{"q":"白细胞计数正常值是","o":["（4.0～10）×109/L","（3.0～10）×109/L","（3.5～100）×109/L","（4.0～100）×109/L","（4.5～10）×109/L"],"a":0,"e":"成人外周血白细胞计数参考值为（4.0～10）×10⁹/L，以中性粒细胞为主；低于4.0×10⁹/L为白细胞减少，高于10×10⁹/L为白细胞增多。"},{"q":"某咯血患者面色晦暗、两颊暗红、口唇发绀，其病因应首先考虑","o":["肺结核","支气管扩张","二尖瓣狭窄","急性白血病","钩端螺旋体病"],"a":2,"e":"面色晦暗、双颊紫红、口唇发绀构成二尖瓣面容，是风湿性二尖瓣狭窄的典型表现；该病致肺淤血、肺血管破裂，故咯血常见。"},{"q":"关于病程记录的书写，下列哪项不正确","o":["症状及体征的变化","体检结果及分析","各级医师查房及会诊意见","每天均应记录1次","临床操作及治疗措施"],"a":3,"e":"病程记录频次依病情而定：病危者每天至少1次，病重者至少2天1次，病情稳定者至少3天1次，故并非所有住院病人每天均须记录一次。"},{"q":"72岁男性，胸痛来诊，下列哪个问题不合适","o":["您哪里不舒服","您胸痛时有没有心慌","胸痛时还有没有其他地方痛","胸痛的程度如何","胸痛怎样才能缓解"],"a":1,"e":"采集胸痛病史应采用开放式提问，让病人自主描述部位、性质、程度、诱因及缓解方式；B项为封闭式暗示性提问，以“有没有”限定回答，不利于获取完整信息。"},{"q":"肝区叩击痛对下列诊断最有意义的是","o":["肝硬化","脂肪肝","肝内胆管结石","门静脉血栓","肝脓肿"],"a":4,"e":"肝区叩击痛是肝脏炎症累及肝包膜的表现，对病毒性肝炎、肝脓肿和肝癌均有诊断意义，其中肝脓肿时肝脏迅速肿大牵张包膜，叩击痛最为显著。"},{"q":"假性斑秃秃发区的特点不包括","o":["局部皮肤萎缩变薄","毛囊口消失","境界清楚","形状不规则","无明显炎症性改变"],"a":4,"e":"假性斑秃属瘢痕性秃发，表现为局部皮肤萎缩变薄、毛囊口消失、境界清楚而形状不规则，且多继发于伴明显炎症的头皮疾病，故“无明显炎症性改变”不是其特点。"},{"q":"抗ds-DNA抗体阳性最常见于","o":["系统性红斑狼疮","类风湿性关节炎","硬化病","皮肌炎","干燥综合征"],"a":0,"e":"抗ds-DNA抗体是系统性红斑狼疮的标志性自身抗体，特异性高，其滴度还与狼疮活动度及狼疮肾炎相关。"},{"q":"问诊时，下列哪句话欠妥","o":["您腹痛的部位在何处","您的腹痛是锐痛？钝痛？饭前和饭后一样吗","您病后是否服过药","哪种情况下，腹痛会更严重一些","请谈谈你腹痛的情况吧"],"a":1,"e":"一句话连续提出两个问题并要求患者一并回答，属连珠式提问，易使患者顾此失彼、回答含混，故应一次只提一个问题。"},{"q":"尿试带法临床应用对疾病的价值最小的是","o":["筛检","诊断","监测","预后","确诊"],"a":4,"e":"尿干化学试带法灵敏度高、操作简便，适用于筛检、疗效监测和预后判断，但特异性不足，阳性结果须经沉渣镜检或定量检查证实，不能作为确诊依据。"},{"q":"患痔疮或肛裂，排出的粪便最可能的性状是","o":["脓血便","冻状便","鲜血便","干结便","黏液便"],"a":2,"e":"痔与肛裂的出血部位在齿状线以下的肛管，血液未与粪便混合，故呈鲜红色，附着于粪便表面或于排便后滴落。"},{"q":"诊断肥胖标准是","o":["超过标准体重15%以上","超过标准体重17%以上","超过标准体重20%以上","超过标准体重22%以上","超过标准体重25%以上"],"a":2,"e":"超过标准体重20%即为肥胖，超过10%为超重，判断时须排除肌肉发达或水钠潴留所致体重增加。"},{"q":"凝血因子中纤维蛋白原是（ ）因子","o":["Ⅰ","Ⅱ","Ⅲ","Ⅶ","Ⅷ"],"a":0,"e":"纤维蛋白原即凝血因子Ⅰ，由肝细胞合成，在凝血酶作用下转变为纤维蛋白单体，是血凝块形成的底物。"},{"q":"镜下脓尿是指尿沉渣镜检白细胞","o":["0～5个/HPF","＞5个/HPF","＞10个/HPF","＞15个/HPF","＞20个/HPF"],"a":1,"e":"离心尿沉渣镜检白细胞超过5个/HPF称为镜下脓尿，提示肾盂肾炎、膀胱炎等泌尿系统化脓性炎症。"},{"q":"多发性骨髓瘤是下列哪种细胞恶性增生性疾病","o":["网状细胞","浆细胞","内皮细胞","肥大细胞","脂肪细胞"],"a":1,"e":"多发性骨髓瘤是浆细胞克隆性恶性增生性疾病，瘤细胞分泌单克隆免疫球蛋白，引起骨破坏、贫血、肾功能损害和高钙血症。"},{"q":"下列疾病都可引起S1增强，但除外","o":["二尖瓣狭窄","二尖瓣关闭不全","PR间期缩短","舒张期缩短","完全性房室传导阻滞"],"a":1,"e":"二尖瓣关闭不全时瓣叶闭合不全，收缩期血液反流使左房压迅速升高，S1反而减弱；二尖瓣狭窄、PR间期缩短及心动过速时房室瓣处于开放低位，S1增强。"},{"q":"先让患者仰卧，行腹部叩诊时，其中腹部呈鼓音，两侧呈浊音；转成左侧位时，左侧腹部浊音区增大，而右侧腹部转为鼓音，称为移动性浊音阳性，表示病征是","o":["幽门梗阻","急性胃扩张","巨大卵巢囊肿","腹腔内有游离腹水","尿潴留"],"a":3,"e":"移动性浊音是腹腔内游离液体随体位改变而移动所形成的浊音区变动，腹水量达1000ml以上即可查出，为腹腔积液的重要体征。"},{"q":"过氧化物酶染色呈阴性反应的疾病为","o":["急性淋巴细胞白血病","急性粒细胞白血病","急性早幼粒细胞白血病","急性粒-单核细胞白血病","急性单核细胞白血病"],"a":0,"e":"急性淋巴细胞白血病的原始及幼稚淋巴细胞不含髓过氧化物酶，故POX染色呈阴性；急性粒细胞、急性单核细胞白血病均呈阳性或弱阳性。"},{"q":"GFR测定的参考方法是","o":["肌酐清除率","对氨基马尿酸清除率","尿素清除率","尿酸清除率","菊粉清除率"],"a":4,"e":"菊粉可自由经肾小球滤过，且不被肾小管重吸收和分泌，其清除率能完全反映肾小球滤过率，是GFR测定的参考方法。"},{"q":"易致高血钾的是","o":["因长期不能进食而由静脉补充营养时","严重呕吐","静脉输入过多钾盐","糖和蛋白代谢旺盛","进食含钾较多食物"],"a":2,"e":"静脉输注大量钾盐使钾摄入超过肾脏排泄能力，是致高钾血症的常见原因；严重呕吐、长期禁食则引起低钾血症。"},{"q":"下列关于出血性疾病的皮肤黏膜出血情况，描述不正确的是","o":["可由血小板数量或功能异常引起","可由止血与凝血功能障碍引起","可引起全身性皮肤黏膜自发性出血","严重伤后出血不止","受轻伤后出血不止"],"a":3,"e":"皮肤黏膜出血的特点为自发性出血或受轻伤后出血不止，与血小板数量或功能异常、血管壁异常及凝血功能障碍有关；严重创伤后出血不止属正常止血反应。"},{"q":"严重腹泻患者常引起","o":["血[Na＋HCO3－]上升","代谢性碱中毒","血中CO2结合力上升","低血钾","血液pH增加"],"a":3,"e":"严重腹泻使胃肠液大量丢失，钾随粪便排出增多，加之血容量不足致醛固酮增多、尿钾排出增加，故引起低血钾。"},{"q":"下列哪项反映100ml动脉血中含氧总量","o":["P（A-a）O2","AG","BB","TCO2","SaO2"],"a":4,"e":"动脉血氧饱和度指单位血红蛋白与氧结合的程度，即血红蛋白含氧百分数，正常95%～98%，可反映动脉血的氧合状态。"},{"q":"正后壁心肌梗死的心电图改变不包括","o":["V7～V9导联出现异常Q波或QS波","V3R～V4R导联出现异常Q波或QS型","V1、V2导联R波增高","V7～V9导联ST段抬高0、1mV","V7～V9导联T波倒置"],"a":1,"e":"右心室梗死时V3R～V4R导联出现异常Q波或QS波；正后壁梗死则表现为V7～V9导联异常Q波、ST段抬高与T波倒置，V1、V2导联R波增高。"},{"q":"Beck三联征见于","o":["亚急性细菌性心内膜炎","渗出性心包炎","缩窄性心包炎","纤维蛋白性心包炎","心脏压塞"],"a":4,"e":"Beck三联征即静脉压升高、心音遥远、动脉血压下降，为急性心脏压塞的典型表现，常见于大量心包积液或积血。"},{"q":"下列哪种疾病引起的二尖瓣区收缩期吹风样杂音属功能性","o":["贫血性心脏病","甲状腺功能亢进","高血压心脏病","风湿性二尖瓣关闭不全","二尖瓣脱垂"],"a":1,"e":"甲状腺功能亢进时血流加速、心率增快，可在二尖瓣区产生柔和的收缩期吹风样功能性杂音；贫血性心脏病、高血压心脏病所致者属病理性杂音。"},{"q":"下列疾病BT不延长的是","o":["血小板减少性紫癜","血小板无力症","遗传性毛细血管扩张症","血友病A","血管性血友病"],"a":3,"e":"血友病A是凝血因子Ⅷ缺乏所致的内源性凝血途径障碍，血小板数量和血管壁功能正常，故出血时间不延长而凝血时间延长。"},{"q":"正常人支气管呼吸音不易见于","o":["喉部","胸骨上窝","肩胛下区","背部第6、7颈椎附近","背部第1、2胸椎附近"],"a":2,"e":"支气管呼吸音正常可在喉部、胸骨上窝、第6、7颈椎及第1、2胸椎附近听到，肩胛下区正常为肺泡呼吸音，出现支气管呼吸音即为异常。"},{"q":"空腹痛常见于","o":["胃溃疡","十二指肠溃疡","胰腺炎","胆囊炎","胃炎"],"a":1,"e":"十二指肠溃疡的疼痛呈空腹痛或夜间痛，进食后缓解；胃溃疡多为餐后痛，二者的节律性不同。"},{"q":"诊断学是用医学科学的方法对疾病的表现所作出的本质的判断，包括以下内容，除外","o":["对病人要进行问诊","对病人要进行体格检查","对病人要进行必要的实验室检查","对所得材料要进行综合归纳、分析、推理、判断，作出结论","要按上级医生的意见对病人作出临床诊断"],"a":4,"e":"诊断学要求通过问诊、体格检查和必要的实验室检查收集资料，再经综合归纳、分析推理作出结论，不能以照搬上级医师意见代替独立诊断。"},{"q":"下列疾病肝浊音界均可扩大，但除外","o":["肝癌","急性重症肝衰竭","酒精性肝硬化","右心功能不全","多囊肝"],"a":1,"e":"肝浊音界扩大见于肝癌、多囊肝、右心功能不全肝淤血和酒精性肝硬化，而急性重型肝炎因肝细胞大量坏死、肝体积缩小，肝浊音界缩小。"},{"q":"患者入院心电图如图所示，下一步最关键的处理是","o":["给予心室起搏","给予心房起搏","静脉给予胺碘酮","静脉给予异丙肾上腺素","静脉补钾"],"a":0,"e":"官方题库缺失图片"},{"q":"疑为回归热的患者，血液涂片检查应做什么染色","o":["厚涂片吉姆萨染色","印度墨汁染色","革兰氏染色","瑞特染色","Fontana镀银染色"],"a":0,"e":"回归热螺旋体在血液中数量少，须取厚血涂片行吉姆萨染色后镜检以提高检出率，薄血片或普通染色易漏诊。"},{"q":"心包叩击音主要见于","o":["心力衰竭","心房黏液瘤","缩窄性心包炎","急性心肌梗死","正常人"],"a":2,"e":"心包叩击音出现在S2后0.09～0.12秒，是舒张早期心室快速充盈受僵硬心包限制、室壁突然振动所致，为缩窄性心包炎的体征。"},{"q":"胸膜摩擦音最常听到的部位是","o":["锁骨上窝","锁骨下窝","前下侧胸壁","肩胛间区","肩胛下区"],"a":2,"e":"胸膜摩擦音最常出现在前下侧胸壁，该处呼吸动度最大，脏、壁胸膜易于相互摩擦；肺尖呼吸动度小，故很少闻及。"},{"q":"Duroziez征是指","o":["明显颈动脉搏动","毛细血管搏动","枪击音","动脉双重杂音","点头运动"],"a":3,"e":"Duroziez征即Duroziez双重杂音，将钟型体件稍加压于股动脉，可闻及收缩期与舒张期双期吹风样杂音，见于主动脉瓣关闭不全。"},{"q":"重叠性奔马律见于","o":["心功能不全伴心动过速","心功能不全伴心动过缓","风湿性心脏病伴二度房室传导阻滞","冠状动脉粥样硬化性心脏病伴三度房室传导阻滞","肥厚型心肌病"],"a":0,"e":"重叠性奔马律是舒张早期奔马律与舒张晚期奔马律重叠，见于心功能不全伴心动过速、舒张期明显缩短时。"},{"q":"临床诊断思维的步骤和具体内容包括","o":["从解剖的观点，有何结构异常","考虑几个可能的致病因素","考虑病情的轻重，勿放过严重情况","寻找特殊的症状体征组合，进行鉴别诊断","以上都正确"],"a":4,"e":"临床诊断思维包括从解剖、病理生理和病因角度分析，考虑多个致病因素，警惕严重情况，并寻找症状体征组合进行鉴别诊断，故各项均属其内容。"},{"q":"下列哪种情况出现肝浊音界消失","o":["膈下脓肿","急性重型肝炎","急性胃肠穿孔","肝癌","肺气肿"],"a":2,"e":"肝浊音界消失代之以鼓音，提示肝表面覆有游离气体，是急性胃肠穿孔的重要征象；膈下脓肿、肝癌时肝浊音界多扩大。"},{"q":"大量心包积液的脉搏是","o":["奇脉","迟脉","交替脉","水冲脉","重搏脉"],"a":0,"e":"大量心包积液时吸气期右心舒张受限、回心血量减少，左心排血随之下降，脉搏减弱甚至消失，形成奇脉。"},{"q":"关于漏出液的特点，下列哪项是错误的","o":["漏出液多为非炎症所致","漏出液黏蛋白定性试验阳性","漏出液多为透明或微浊","漏出液比重多低于1.018","漏出液一般不自凝"],"a":1,"e":"漏出液黏蛋白含量少，Rivalta试验呈阴性，蛋白定量多小于25g/L、比重低于1.018、细胞数少且不易自凝，为非炎症性积液。"},{"q":"心电图检查的标准走纸速度是","o":["10mm/s","75mm/s","25mm/s","40mm/s","50mm/s"],"a":2,"e":"心电图标准走纸速度为25mm/s，此时横向1mm代表0.04秒；标准电压为10mm/mV，纵向1mm代表0.1mV。"},{"q":"蛙状腹多见于","o":["巨大卵巢囊肿","肠梗阻","肠麻痹","气腹","腹腔积液"],"a":4,"e":"蛙状腹指仰卧位时腹部向两侧对称膨出而中央凹陷，是大量腹腔积液时液体沉聚于两侧腹部的表现。"},{"q":"诊断急性腹膜炎的最主要的体征是","o":["腹部压痛和反跳痛","腹式呼吸减弱或消失","腹胀的出现","肠鸣音的改变","移动性浊音"],"a":0,"e":"急性腹膜炎时腹膜受炎症刺激，出现腹肌紧张、压痛与反跳痛三联征，其中腹部压痛和反跳痛是诊断最主要的体征。"},{"q":"胸腔积液的体征主要与哪种因素有关","o":["积液形成的缓急","积液的性质","原发病变","单侧或双侧","积液量"],"a":4,"e":"胸腔积液的体征主要取决于积液量，少量积液可无明显体征，中量以上才出现患侧胸廓饱满、语颤减弱、叩诊浊音及呼吸音减低。"},{"q":"第一心音的组成主要是","o":["半月瓣开放","心房收缩","房室瓣关闭的震动","乳头肌的收缩","血流冲击大血管的震动"],"a":2,"e":"第一心音主要由心室收缩开始时二尖瓣、三尖瓣突然关闭，瓣叶及腱索振动所形成，房室瓣关闭是其主要成分。"},{"q":"下列哪种疾病是骨髓穿刺禁忌证","o":["粒细胞缺乏症","白血病","脾功亢进","血友病","再生障碍贫血"],"a":3,"e":"血友病病人存在凝血因子缺陷，骨髓穿刺可致出血不止，属禁忌证；白血病、再生障碍性贫血、脾功能亢进恰需骨髓检查明确诊断。"},{"q":"出院记录不包括","o":["入院诊断","出院医嘱","出院诊断","出院情况","门诊病历诊断"],"a":4,"e":"出院记录包括入院诊断、出院诊断、出院情况、出院医嘱及住院经过，门诊病历诊断属门诊资料，不列入出院记录。"},{"q":"风湿性心瓣膜病，此诊断属于","o":["病因诊断","病理生理诊断","解剖诊断","功能诊断","临床诊断"],"a":0,"e":"风湿性心瓣膜病指明病因为风湿热，属病因诊断；二尖瓣狭窄等为病理解剖诊断，心功能不全为病理生理诊断。"},{"q":"进行腹部视诊时，不会见到胃肠型和蠕动波的是","o":["腹壁菲薄或松弛的老年人","幽门梗阻","小肠梗阻","结肠梗阻","大量腹水"],"a":4,"e":"大量腹水使腹壁紧张、腹压增高并掩盖肠管轮廓，故看不到胃肠型与蠕动波；幽门梗阻、小肠或结肠梗阻时则可见。"},{"q":"过氧化酶染色（POX）阴性的白血病是","o":["急性粒细胞白血病","急性淋巴细胞白血病","急性早幼粒细胞白血病","急性单核细胞白血病","急性粒-单核细胞白血病"],"a":1,"e":"过氧化物酶染色阴性是急性淋巴细胞白血病的特点；急性粒细胞白血病呈强阳性，急性单核细胞白血病多呈阴性或弱阳性。"},{"q":"溶血法总补体检测以什么作为终点指标","o":["25%溶血","50%溶血","75%溶血","80%溶血","100%溶血"],"a":1,"e":"总补体溶血活性以50%溶血作为检测终点，因溶血程度与补体量呈S形曲线，50%溶血处对补体量的变化最敏感。"},{"q":"对老年人问诊，下列哪项是错误的","o":["老年人问诊，应先简单清楚通俗易懂的问题","减慢问诊进度","问诊同时观察患者反应，判断有无思维障碍","老年人不易交流，可以直接问家属","仔细询问过去史及用药史"],"a":3,"e":"老年人问诊应使用简单通俗的问题、放慢进度并观察反应，病史仍须向本人核实，不能因交流困难而直接询问家属代替。"},{"q":"检查心脏震颤常用","o":["手掌尺侧","全手掌","2～4指指腹","2、3指指尖","手掌桡侧"],"a":0,"e":"触诊震颤时用手掌尺侧（小鱼际）或并拢的示指、中指、环指指腹，手掌尺侧对细小震动的感觉最敏感。"},{"q":"有关问诊的医德要求，医师不正确的做法是","o":["认真倾听患者的病情","对患者的隐私详细了解","对特殊患者，给予更多的关怀","对患者评价以前治疗方法是否得当","与患者及家属仔细沟通疾病相关知识"],"a":3,"e":"追问并评价前医的诊疗是否得当，易使患者对既往治疗产生不信任，属违反医德的做法；认真倾听、保护隐私和充分沟通均为应尽义务。"},{"q":"钟摆律最常见于下列哪种疾病","o":["急性心肌梗死","二尖瓣狭窄","甲状腺功能亢进症","贫血","发热"],"a":0,"e":"钟摆律指心率增快时收缩期与舒张期时限几乎相等、S1减弱，听诊似钟摆声，最常见于急性心肌梗死和重症心肌炎。"},{"q":"心脏听诊时应注意下列各项，但除外","o":["诊察室环境安静","医生精神高度集中","患者必须采取仰卧位","医生站在病床的右侧","必要时需让患者改变体位"],"a":2,"e":"心脏听诊要求环境安静、医生注意力集中并立于患者右侧，必要时改变体位以暴露杂音如左侧卧位、前倾坐位，体位按需要选择而非必须仰卧。"},{"q":"下列哪组血浆离子浓度的变化能帮助诊断呼吸性酸中毒","o":["HCO3－升高，伴有K＋下降","HCO3－升高，伴有K＋升高","HCO3－升高，而K＋不变","HCO3－下降，伴有K＋下降","HCO3－下降，伴有K＋升高"],"a":1,"e":"呼吸性酸中毒时CO2潴留，肾代偿使HCO3-升高，同时H+进入细胞、K+外移，血钾升高，故HCO3-升高伴K+升高支持该诊断。"},{"q":"炎热环境中皮肤散热的主要形式是","o":["发汗","对流","血流","传导","辐射"],"a":0,"e":"炎热环境中体表温度接近或高于环境温度，辐射、传导和对流散热受限，汗液蒸发即发汗成为主要的散热形式。"},{"q":"以下中性粒细胞减少见于","o":["放线菌病","流行性出血热","斑疹伤寒","梅毒","伤寒杆菌感染"],"a":4,"e":"伤寒、副伤寒杆菌属革兰氏阴性杆菌，感染时白细胞总数与中性粒细胞均减少，是感染致粒细胞减少的典型例子。"},{"q":"关于S3听诊特点，哪项是错误的","o":["出现在心室舒张早期","心尖部及其内上方听诊较清晰","坐位或立位时清晰","呼气末较清晰","成年人一般听不到"],"a":2,"e":"第三心音在左侧卧位及呼气末最清楚，坐位或立位时可消失，故“坐位或立位时清晰”错误；成年人一般听不到。"},{"q":"代表心脏实际大小的界限为","o":["心脏绝对浊音界","心脏相对浊音界","心左界","心右界","心底部界限"],"a":1,"e":"心脏相对浊音界是心脏未被肺组织遮盖部分的投影，代表心脏的实际大小；绝对浊音界仅代表右心室贴近胸壁的部分。"},{"q":"室性奔马律提示","o":["左室充盈压下降","左房压下降","PCWP升高","心脏指数升高","左室射血分数升高"],"a":2,"e":"室性奔马律提示心室舒张期负荷过重、左室充盈压升高，故肺毛细血管楔压升高而射血分数降低、心脏指数下降。"},{"q":"为了解近端肾小管的功能损害程度，应选择的试验是","o":["尿β2微球蛋白定量","血尿素氮定量","血肌酐定量","尿比重测定","尿渗透压测定"],"a":0,"e":"尿β2-微球蛋白分子量小，可自由经肾小球滤过并被近端肾小管重吸收，尿中升高反映近端肾小管损伤，须同时测血β2-MG排除滤过增多。"},{"q":"风湿性心脏病严重主动脉瓣关闭不全时，脉搏触诊时可有","o":["平脉","重搏脉","交替脉","水冲脉","奇脉"],"a":3,"e":"主动脉瓣重度关闭不全时收缩期左室射血增多、舒张期血液快速反流，脉搏骤起骤落，触诊呈水冲脉。"},{"q":"以下不符合渗出液特点的是","o":["穿刺液自凝","呈现不同颜色或混浊","比重大于1.018","李凡他试验阴性","细胞数大于500×106/L"],"a":3,"e":"渗出液蛋白含量高、含大量黏蛋白，Rivalta试验呈阳性，故“李凡他试验阴性”不符合渗出液的特点。"},{"q":"患者肢体能抬离床面，能对抗重力，但不能完全对抗阻力，其肌力为","o":["1级","2级","3级","4级","5级"],"a":3,"e":"肌力4级表现为能对抗部分阻力完成动作，但较正常减弱；3级仅能抬离床面而不能对抗阻力。"},{"q":"因长期大量使用抗生素引起的腹泻或鹅口疮多属于","o":["内源性感染","医源性感染","交叉感染","外源性感染","隐性感染"],"a":0,"e":"长期大量使用抗生素使正常菌群失调，耐药菌或真菌在体内繁殖引起腹泻、鹅口疮，病原体源于自身菌群，属内源性感染。"},{"q":"诊断二尖瓣狭窄最有意义的体征是","o":["心尖部第一心音亢进","肺动脉瓣区第二心音亢进","二尖瓣区收缩期杂音","肺动脉瓣区收缩期杂音","心尖部舒张期隆隆样杂音"],"a":4,"e":"二尖瓣狭窄时舒张期左房血液经狭窄瓣口流入左室，产生心尖部舒张中晚期隆隆样杂音，是诊断最有意义的体征。"},{"q":"以下不是胃镜检查适应证的是","o":["原因不明的上消化道出血","胃内异物","食管静脉曲张破裂出血","急性腹痛伴肝浊音界消失","胃癌术后随访"],"a":3,"e":"急性腹痛伴肝浊音界消失提示胃肠穿孔、腹腔游离气体，此时进镜可加重穿孔与腹膜炎，属胃镜检查禁忌。"},{"q":"脑膜刺激征不会见于","o":["脑膜炎","蛛网膜下腔出血","颅压增高状态","脑膜脑炎","脑梗死"],"a":4,"e":"脑膜刺激征由脑膜受激惹引起，见于脑膜炎、蛛网膜下腔出血和颅内压增高；脑梗死为脑实质缺血坏死，一般不出现该征。"},{"q":"下列不会引起周围性发绀的疾病是","o":["肺炎","右心衰竭","缩窄性心包炎","严重休克","上腔静脉阻塞综合征"],"a":0,"e":"肺炎因通气/血流比例失调和弥散障碍引起中心性发绀；右心衰竭、缩窄性心包炎、休克及上腔静脉阻塞则因周围循环障碍致周围性发绀。"},{"q":"下列影响心音强弱改变因素的叙述是正确的，但除外","o":["心室收缩力和收缩速度","血压高低及心率快慢","瓣膜完整性与活动性","心室充盈情况与瓣膜位置","大量心包积液"],"a":1,"e":"血压高低和心率快慢不直接改变心音强度；心音强弱取决于心肌收缩力、心室充盈程度与瓣膜位置，以及瓣膜结构和活动性，心包积液则使心音遥远。"},{"q":"下列疾病可见中性粒细胞减少，但应除外","o":["病毒感染","骨髓转移癌","脾功能亢进","慢性粒细胞白血病","系统性红斑狼疮"],"a":3,"e":"慢性粒细胞白血病时粒细胞系极度增生，中性粒细胞明显增多而非减少；病毒感染、骨髓转移癌、脾功能亢进和系统性红斑狼疮均可致粒细胞减少。"},{"q":"从临床思维的角度看，常见造成误诊漏诊的原因不包括下列哪一项","o":["基本素材不齐","观察不细致或检验结果误差","医学知识不足，缺乏临床经验","早期罕见疑难病例","医患关系不佳"],"a":4,"e":"误诊漏诊多因临床资料不全、观察不细或检验误差、医学知识不足及疾病早期表现不典型所致，医患关系不属于常见原因。"},{"q":"常见惊厥伴高血压、脑膜刺激征阳性的疾病是","o":["蛛网膜下腔出血","高血压脑病","肺性脑病","癔症","丘脑出血"],"a":0,"e":"蛛网膜下腔出血时血液刺激脑膜并引起颅内压升高，故惊厥可伴血压增高和脑膜刺激征阳性；高血压脑病以血压骤升、脑水肿为主。"},{"q":"二尖瓣狭窄的杂音性质是","o":["吹风样","隆隆样","叹气样","机器样","乐音样"],"a":1,"e":"二尖瓣狭窄时舒张期血流经狭窄瓣口产生低调、递增型隆隆样杂音，局限于心尖区，左侧卧位时更清楚。"},{"q":"血小板在凝血过程中的主要作用是","o":["作为因子Ⅲ参与凝血过程","激活因子Ⅻ","释放ADP","提高PF3（磷脂）活性","稳定纤维蛋白"],"a":3,"e":"血小板膜磷脂即PF3为因子Ⅹa、Ⅴ与Ca2+结合形成凝血酶原酶提供催化表面，故血小板的主要促凝作用是提高PF3活性。"},{"q":"右心室肥大心尖冲动的位置为","o":["向左下移位","向右移位","向右上移位","向左上移位","向左移位"],"a":4,"e":"右心室增大时心脏沿长轴顺时针转位，心尖搏动向左移位而不向下；左心室增大则向左下移位。"},{"q":"收缩期杂音伴收缩中晚期喀喇音，最常见于下列何种疾病","o":["二尖瓣脱垂","二尖瓣狭窄","二尖瓣上赘生物形成","肺动脉瓣狭窄","主动脉瓣狭窄"],"a":0,"e":"收缩中晚期喀喇音由二尖瓣叶在收缩中晚期脱入左房、腱索突然拉紧所致，常伴收缩晚期杂音，是二尖瓣脱垂的典型体征。"},{"q":"粒细胞减少症主要是指外周血中性粒细胞计数持续低于","o":["5.0×109/L","1.5×109/L","4.0×109/L","2.0×109/L","3.0×109/L"],"a":1,"e":"成人外周血中性粒细胞绝对值低于1.5×10⁹/L称粒细胞减少症，低于0.5×10⁹/L称粒细胞缺乏症。"},{"q":"判断肺实变最敏感的指标是","o":["病理性支气管呼吸音","胸语音","耳语音","叩诊浊音","语音震颤增强"],"a":2,"e":"耳语音对肺实变的诊断最敏感，实变肺组织传音增强，耳语音变为清晰响亮、音调增高的声音，常早于其他体征出现。"},{"q":"正常情况下，哪个腔室产生最大的电活动","o":["左心房","左心室","右心房","右心室","心房"],"a":1,"e":"心室肌细胞数量多、除极向量大，正常时左心室除极产生的电活动最强，构成心室除极综合向量左室占优势的基础。"},{"q":"IgA IgD和IgE型的免疫球蛋白不能与C1q结合，是由于","o":["分子结构容易","Fc段无补体结合位点","Fab段无补体结合位点","VH无补体结合位点","VL无补体结合位点"],"a":1,"e":"IgA、IgD和IgE的Fc段缺乏与C1q结合的补体结合位点，故不能激活补体经典途径；IgG与IgM可借助CH2、CH3段结合C1q。"},{"q":"下列情况可见血块退缩不良，不会见于下列哪一种情况","o":["血小板减少性紫癜","血小板功能异常","凝血因子异常","纤维蛋白原显著降低","过敏性紫癜"],"a":4,"e":"血块退缩依赖血小板的数量和功能以及纤维蛋白原含量，过敏性紫癜为血管壁异常，血小板与凝血因子正常，故血块退缩良好。"},{"q":"下列是吸气性呼吸困难的特点，但应除外","o":["吸气显著困难","重者出现“三凹征”","常伴有干咳及高调吸气性喉鸣","常伴有手足搐搦","常见于喉部及气管疾病（如喉水肿、气管异物）"],"a":3,"e":"手足搐搦见于过度通气致呼吸性碱中毒或低钙血症，属精神性呼吸困难的表现；吸气性呼吸困难以三凹征和高调喉鸣为特点。"},{"q":"下列因素均是功能性便秘的原因，但除外","o":["进食量少","甲状腺功能亢进症","肠易激综合征","应用抗胆碱能药","腹肌及盆肌张力不足"],"a":1,"e":"甲状腺功能亢进使肠蠕动加快、排便次数增多，引起腹泻而非便秘；进食量少、肠易激综合征、抗胆碱能药及腹肌盆肌无力均可致功能性便秘。"},{"q":"焦虑症的核心症状是","o":["紧张不安","过度担心","胸闷气短","睡眠困难","警觉性增高"],"a":1,"e":"焦虑症精神症状的核心是过度担心，即对未来可能发生的危险或不幸事件持续担忧，且担心的程度与现实不相称。"},{"q":"在各种免疫球蛋白中，初次免疫应答有关的是","o":["IgG","IgA","IgM","IgE","IgD"],"a":2,"e":"IgM是初次免疫应答最早出现的抗体，无论个体发育还是受抗原刺激后均先于IgG产生，在早期免疫防御中起主要作用。"},{"q":"下列为舒张期额外心音，但应除外哪项","o":["奔马律","喀喇音","开瓣音","心包叩击音","肿瘤扑落音"],"a":1,"e":"喀喇音属收缩期额外心音，出现于S1之后；奔马律、开瓣音、心包叩击音和肿瘤扑落音均出现于舒张期。"},{"q":"胸骨左缘第2肋间的收缩期震颤，最常见于","o":["主动脉瓣狭窄","肺动脉瓣狭窄","主动脉瓣关闭不全","肺动脉瓣关闭不全","动脉导管未闭"],"a":1,"e":"胸骨左缘第2肋间即肺动脉瓣区，该处收缩期震颤最常见于肺动脉瓣狭窄；胸骨右缘第2肋间收缩期震颤则为主动脉瓣狭窄。"},{"q":"肝细胞中与胆红素结合的主要物质是","o":["乙酰基","硫酸根","甲基","葡萄糖醛酸","甘氨酸"],"a":3,"e":"非结合胆红素入肝后经葡萄糖醛酸转移酶催化与葡萄糖醛酸结合，生成结合胆红素，由脂溶性变为水溶性而便于随胆汁排泄。"},{"q":"关于主诉的描述，以下正确的是","o":["主诉不能出现疾病名称","主诉是患者的主要症状，不能包括客观体征","主诉多于一个症状时，一般按照症状的重要程度排序","主诉一般不能超过20个字","主诉应包括患者的所有症状"],"a":3,"e":"主诉要求简明精练，一般1～2句、20字左右，多项症状按发生先后排列，尽量用症状名称，主诉可包含体征。"},{"q":"正常成人肺下界的移动范围是","o":["4～6cm","6～8cm","5～7cm","7～9cm","3～5cm"],"a":1,"e":"正常成人肺下界移动范围为6～8cm，腋中线及腋后线处移动度最大，其大小与肋膈窦的大小有关。"},{"q":"下述问诊方法，正确的是","o":["问诊中可以经常做些疾病相关情况的引导提示","可以对病人重复提问","避免使用有特定意义的医学术语","不要在问诊中核实病人陈述过去的不确切病史","问诊时医生语音要严肃、锐利"],"a":2,"e":"问诊须用常人易懂的词语，避免使用有特定含义的医学术语；随意提示、重复提问和态度生硬均会影响资料的真实性。"},{"q":"门诊接诊一名发热的患者，首先应主要收集哪方面病史","o":["发热的伴随症状","发热的治疗过程","患者做过哪些检查","患者发热的时间、规律及热型","患者有无特殊人群接触史"],"a":3,"e":"问诊发热患者应首先了解发热的时间、规律与热型，据此判断热型特点并推断感染性或非感染性病因。"},{"q":"二尖瓣相对性关闭不全的杂音可见于下列疾病，但应除外","o":["扩张型心脏病","贫血性心脏病","高血压心脏病","乳头肌功能失调","风湿性心脏病主动脉瓣狭窄"],"a":3,"e":"相对性二尖瓣关闭不全见于左心室扩大、二尖瓣环扩张所致者，如扩张型心肌病、贫血性心脏病和高血压心脏病；乳头肌功能失调引起的是器质性关闭不全。"},{"q":"主动脉瓣狭窄重要的体征是","o":["主动脉瓣区可闻及收缩期喷射性杂音","主动脉瓣区第二心音减弱","脉压小","杂音向颈部传导","脉细弱，呈迟脉"],"a":0,"e":"主动脉瓣狭窄的特征性体征是主动脉瓣区响亮而粗糙的收缩期喷射性杂音，递增递减型，向颈部传导，常伴震颤和A2减弱。"},{"q":"作Valsalva动作时，可使下列疾病的杂音增强的是","o":["特发性肥厚性主动脉瓣下狭窄","主动脉瓣狭窄","肺动脉瓣狭窄","扩张型心肌病","法洛四联症"],"a":0,"e":"Valsalva动作使胸腔内压升高、回心血量减少，经瓣膜产生的杂音减轻，而梗阻性肥厚型心肌病因心室容量减少、梗阻加重，杂音反而增强。"},{"q":"胸壁有静脉曲张，血流方向自下而上，见于","o":["上腔静脉梗阻","下腔静脉梗阻","哺乳期妇女","胸腔淋巴管阻塞","门静脉高压"],"a":1,"e":"下腔静脉梗阻时下半身血液经腹壁浅静脉向上、再经胸壁静脉回流入上腔静脉，故胸腹壁曲张静脉的血流方向自下而上。"},{"q":"第二心音通常分裂中，由肺动脉瓣关闭明显迟于主动脉瓣关闭时间所致的病变中，最常见的是","o":["完全右束支传导阻滞","二尖瓣关闭不全","室间隔缺损","完全左束支传导阻滞","主动脉瓣狭窄"],"a":0,"e":"完全性右束支传导阻滞使右心室除极和收缩延迟，肺动脉瓣关闭明显迟于主动脉瓣，产生第二心音通常分裂。"},{"q":"关于Damoiseau曲线的描述，下列正确的是","o":["患者取坐位时，积液的上界呈一弓形曲线","曲线的最低点位于同侧脊柱旁","曲线的最高点在腋中线上","曲线由内上方向外下方下降","曲线形成是因为胸腔内侧承受液体的阻力最大"],"a":0,"e":"胸腔积液患者取坐位时，积液上界呈弓形线，最低点位于对侧脊柱旁，最高点在腋后线上，称为Damoiseau曲线。"},{"q":"下列均为腹部触诊的内容，但除外","o":["腹壁紧张度","压痛","腹部肿块","振水音","移动性浊音"],"a":4,"e":"移动性浊音须经叩诊并变换体位引出，属叩诊内容；腹壁紧张度、压痛、腹部肿块及振水音均属触诊范畴。"},{"q":"仅与体液免疫有关的细胞是","o":["Th2细胞","TDTH细胞","Th0","Th1细胞","CTL细胞"],"a":0,"e":"Th2细胞主要分泌IL-4、IL-5、IL-6等，辅助B细胞增殖分化产生抗体，仅参与体液免疫；Th1细胞和CTL介导细胞免疫。"},{"q":"由凝血障碍引起皮肤黏膜出血的疾病是","o":["原发免疫性血小板减少症","严重肝脏疾病","再生障碍性贫血","巨幼细胞贫血","过敏性紫癜"],"a":1,"e":"严重肝病时肝细胞合成纤维蛋白原、凝血酶原等凝血因子减少，引起皮肤黏膜出血；其余各项分别由血小板减少或血管壁异常所致。"},{"q":"网织红细胞成人参考值（百分数）为","o":["0.1%～1.1%","0.2%～1.2%","0.3%～1.3%","0.4%～1.4%","0.5%～1.5%"],"a":4,"e":"成人网织红细胞百分数为0.5%～1.5%，新生儿为3%～6%；该指标反映骨髓红系造血活跃程度，增多见于溶血性贫血，减少见于再生障碍性贫血。"},{"q":"有关PEF的描述正确的是","o":["反映日变异率","是用力肺活量测定过程中，呼气流速最快的瞬间流速","日常变异率≥15%对支气管哮喘诊断有意义","日常变异率正常值＜15%","主要反映小气道有无阻塞"],"a":1,"e":"最大呼气流量是用力肺活量测定过程中呼气流速最快时的瞬间流速，亦称峰值呼气流量，主要反映呼吸肌的力量及气道有无阻塞。"},{"q":"波状热最常见的疾病是","o":["霍奇金病","重症肺结核","疟疾","伤寒","布氏杆菌病"],"a":4,"e":"波状热指体温逐渐上升达39℃以上，数天后又逐渐降至正常，持续数天后再升高，如此反复多次，为布鲁氏菌病的典型热型。"},{"q":"下面关于第二心音的叙述中，不正确的是","o":["标志着心室舒张的开始","半月瓣突然关闭引起的瓣膜振动所产生的","房室瓣的关闭也参与第二心音的形成","在心尖搏动之后出现","心底部听诊最清楚"],"a":2,"e":"第二心音由半月瓣突然关闭及血流在主动脉、肺动脉内突然减速引起瓣膜振动产生，房室瓣的开放参与其形成；房室瓣关闭产生的是第一心音。"},{"q":"下列关于心脏视诊要点的叙述都正确，但除外","o":["应在温暖环境自然光线下进行","患者采取仰卧位，检查者站在患者右侧","观察心前区异常隆起和搏动时，两眼应与胸廓同高","视诊心尖冲动时，双眼应与心尖区呈垂直位置","检查者站在患者右侧，双眼视线与心尖呈切线位"],"a":3,"e":"视诊心尖搏动时视线应与心尖区呈切线位，观察心前区异常隆起和搏动时两眼方与胸廓同高；垂直位观察无法判断搏动范围。"},{"q":"如图，心电图诊断正确的是","o":["三度房室传导阻滞","窦性心动过缓","窦性停搏","二度房室传导阻滞","心房扑动"],"a":0,"e":"官方题库缺失图片"},{"q":"脑脊液白细胞数1000×106/L以上，以多核细胞为主，蛋白质增高，糖和氯化物降低，首先考虑哪种诊断的可能","o":["细菌性脑膜炎","病毒性脑膜炎","结核性脑膜炎","隐球菌性脑膜炎","流行性乙型脑炎"],"a":0,"e":"细菌性脑膜炎脑脊液白细胞常超过1000×10⁶/L，以多核细胞为主，蛋白质明显增高，糖和氯化物降低；结核性脑膜炎则以单核细胞为主。"},{"q":"55岁男性，胸痛1小时入院，现病史还需要问","o":["胸痛发生的急缓","有无冠心病","胸痛的性质和程度","胸痛的部位及有无放射","胸痛的诱因"],"a":1,"e":"现病史应围绕本次胸痛询问诱因、部位、性质、程度、放射及起病急缓；有无冠心病属既往史内容，是尚需补充询问的病史。"},{"q":"左心功能减退时，出现第二心音逆分裂，是因为","o":["吸气时，右室射血期延长","吸气时，左室射血期延长","呼气时，左室射血期延长","呼气时，右室射血期延长","呼气时，左室射血期缩短"],"a":2,"e":"逆分裂指S2分裂在呼气时明显、吸气时消失，因左室射血期延长使主动脉瓣关闭延迟，呼气时更落后于肺动脉瓣关闭，见于左心功能减退及主动脉瓣狭窄。"},{"q":"下列可以传导头痛感觉的脊神经是","o":["第1/2/3颈神经","第4/5/6颈神经","第7颈神经","第1/2胸神经","第3/4/5胸神经"],"a":0,"e":"头部痛觉由三叉神经及第1～3颈神经传导，故第1、2、3颈神经受刺激、挤压或牵拉均可引起头痛。"},{"q":"关于再生障碍性贫血的骨髓象和血象，错误的是","o":["呈全血细胞减少，少数病例早期可仅1系或2系细胞减少","网织红细胞减低","骨髓小粒镜检空虚","非造血细胞减少","骨髓造血功能低下"],"a":3,"e":"再生障碍性贫血呈全血细胞减少、网织红细胞减低、骨髓增生低下及骨髓小粒空虚，骨髓中非造血细胞比例增高而非减少。"},{"q":"引起中枢性呕吐的病因包括下列疾病，但除外","o":["脑膜炎","迷路炎","颅内血肿","脑出血","抗癌药物"],"a":1,"e":"迷路炎属前庭障碍性呕吐，伴发作性眩晕、耳鸣、听力减退及眼球震颤；脑膜炎、颅内血肿、脑出血与抗癌药物所致呕吐均属中枢性。"},{"q":"不出现枪击音的病理情况是","o":["主动脉瓣关闭不全","甲状腺功能亢进症","严重贫血","心力衰竭","动脉导管未闭"],"a":3,"e":"枪击音属脉压增大的周围血管征，见于主动脉瓣关闭不全、甲状腺功能亢进、严重贫血及动脉导管未闭；心力衰竭时脉压减小，不出现枪击音。"},{"q":"当体重增加超过标准体重多少时称为肥胖","o":["超过10%","超过18、5%","超过20%","超过28%","超过30%"],"a":2,"e":"超过标准体重10%为超重，超过20%为肥胖，须排除肌肉发达或水分潴留；按BMI判断，我国标准≥28kg/m²为肥胖。"},{"q":"第三心音（S3）符合下述哪项描述","o":["一种音调高的声音","老年患者的正常发现","呼气末听诊较清楚","坐位或立位时增强","胸骨左缘Ⅳ肋间听诊最清楚"],"a":2,"e":"S3出现在心室舒张早期快速充盈之末，由心室壁、腱索及乳头肌突然紧张振动产生，音调低钝，局限于心尖部或其内上方，仰卧位及呼气时较清楚。"},{"q":"下列关于正常体温的描述哪项是正确的","o":["腋窝体温一般为36.5～37℃","正常体温每日波动范围不超过0.5℃","一般下午体温较早晨稍低","一般肛门内体温比腋窝体温略低","剧烈运动或进餐后体温可略升高"],"a":4,"e":"24小时内下午体温较早晨稍高，剧烈运动、劳动或进餐后可略升高，波动一般不超过1℃；腋温36～37℃，肛温较腋温高约0.3～0.5℃。"},{"q":"下述是深部滑行触诊的方法，哪项是不正确的","o":["检查时嘱病人张口平静呼吸","检查时嘱病人深呼气后屏气","可以与病人谈话以转移其注意力","医生同时并拢二、三、四指末端逐渐触向腹腔的脏器或包块","触诊时在触及物上做上、下、左、右滑动触摸"],"a":1,"e":"深部滑行触诊应嘱病人张口平静呼吸或谈话以松弛腹肌，以并拢的二、三、四指末端逐渐触向脏器，并在包块上作上下左右滑动触摸；深呼气末屏气为肝穿刺要求。"},{"q":"下列哪项不是导致假性血尿的原因","o":["服用利福平","食用甜菜","卟啉代谢障碍或损伤引起的肌红蛋白尿","痔疮出血","精囊腺炎"],"a":4,"e":"假性血尿指尿呈红色而并非真性血尿，见于服用利福平、食用甜菜、卟啉代谢障碍及肌红蛋白尿、痔疮出血污染；精囊腺炎所致属真性血尿。"},{"q":"血友病A B分别缺乏以下哪种凝血因子","o":["FⅣ、FⅧ","FⅢ、FⅤ","FⅧ、FⅪ","FⅧ、FⅨ","FⅪ、FⅨ"],"a":3,"e":"血友病A缺乏因子Ⅷ，血友病B缺乏因子Ⅸ，二者均致内源性凝血途径障碍，表现为APTT及凝血时间延长，而血小板计数正常。"},{"q":"RBC结构异常见于下列情况，但应除外","o":["嗜碱性点彩","染色质小体","Cabot环","有核RBC","镰形细胞"],"a":4,"e":"红细胞结构异常包括嗜碱性点彩、染色质小体、Cabot环和有核红细胞；镰形细胞属红细胞形态异常，由血红蛋白S聚合成管状所致。"},{"q":"门诊病历的书写，下列哪项不正确","o":["症状及体征","检查结果及分析","急症患者在24h内完成即可","现病史","治疗措施"],"a":2,"e":"门（急）诊病历应及时书写，入院记录方于病人入院后24小时内完成；抢救记录应于抢救结束后6小时内据实补记。"},{"q":"适用于体表浅在病变检查和评估的是","o":["冲击触诊法","双手触诊法","深压触诊法","滑动触诊法","浅部触诊法"],"a":4,"e":"浅部触诊法适用于关节、软组织、浅部动静脉、神经、阴囊和精索等体表浅在病变的检查与评估，腹部可触及深度约1cm。"},{"q":"发作性呼吸困难伴哮鸣音，最常见于","o":["大叶性肺炎","渗出性胸膜炎","气胸","喉癌","支气管哮喘"],"a":4,"e":"发作性呼吸困难伴哮鸣音最常见于支气管哮喘和心源性哮喘，前者多见于有过敏史者，呈发作性呼气性呼吸困难。"},{"q":"E试验与纸片琼脂扩散法的不同之处是","o":["接种菌准备","平板接种","测出药物的MIC","孵育时间","孵育温度"],"a":2,"e":"E试验用含梯度浓度抗菌药物的试条，可定量测出药物的最低抑菌浓度MIC；纸片琼脂扩散法仅以抑菌圈直径作定性或半定量判断。"},{"q":"下列均为临床诊断思维方法，但除外","o":["实事求是的对待客观临床资料","首先考虑功能性疾病，然后再考虑器质性疾病","尽量用一种疾病解释多种临床表现","几种诊断同时存在，首先选择多发病的诊断","简化思维程序的原则"],"a":1,"e":"器质性疾病与功能性疾病鉴别困难时应首先考虑器质性诊断，以免延误治疗；诊断功能性疾病之前必须排除器质性疾病。"},{"q":"治疗史隶属于","o":["既往史","系统回顾","现病史","婚姻史","个人史"],"a":2,"e":"现病史包括发病情况、主要症状特点、伴随症状、诊治经过及一般情况，治疗史属诊疗经过的一部分。"},{"q":"以下哪项是输血同意书不需包括的内容","o":["患者年龄","科别","输血指征","血型","医师签名"],"a":3,"e":"输血治疗同意书应载明患者姓名、性别、年龄、科别、输血指征、拟输血液成分、相关风险及医师签名；血型于输血前另行核对，不属同意书内容。"},{"q":"下列疾病均出现肝大，但除外","o":["脂肪肝","早期肝硬化","Budd-Chiari综合征","肝炎","亚急性重型肝炎"],"a":4,"e":"亚急性重型肝炎因肝细胞大量坏死，肝脏体积缩小、肝浊音界缩小；脂肪肝、肝炎、早期肝硬化及Budd-Chiari综合征均表现为肝大。"},{"q":"下述情况可出现异常支气管呼吸音，但除外","o":["大叶肺炎实变期","肺脓肿","空洞型肺结核","气胸","胸腔积液"],"a":3,"e":"异常支气管呼吸音见于肺实变、肺内大空洞（肺脓肿、空洞型肺结核）及胸腔积液上方的压迫性肺不张；气胸时胸膜腔积气，呼吸音减弱或消失。"},{"q":"本例患者行本次心电图检查时，心室率大约是","o":["65次/min","55次/min","40次/min","35次/min","80次/min"],"a":2,"e":"官方题库缺失图片"},{"q":"以下各诊断属于病因诊断的是","o":["肝硬化","风湿性心脏病","尿毒症","肾小球肾炎","心功能不全"],"a":1,"e":"风湿性心脏病指明病因，属病因诊断；肝硬化、肾小球肾炎属病理解剖诊断，心功能不全、尿毒症属病理生理诊断。"},{"q":"肺泡呼吸音减弱不易见于","o":["肺气肿","胸腔积液","气胸","尿毒症性酸中毒","肺不张"],"a":3,"e":"代谢性酸中毒时呼吸深快，肺泡呼吸音增强；肺气肿、胸腔积液、气胸及肺不张均使肺泡通气量减少或传导受阻而致呼吸音减弱。"},{"q":"呕吐过程中包括下列动作，但除外","o":["胃引力减弱","膈肌上升","腹肌收缩","胃窦部收缩","贲门开放"],"a":1,"e":"呕吐时胃窦收缩、胃逆蠕动，贲门开放，膈肌与腹肌强力收缩使腹压骤增而排出胃内容物；膈肌在呕吐时下降而非上升。"},{"q":"慢性上腹痛最常见的病因是","o":["消化性溃疡","慢性胰腺炎","胃癌","肠寄生虫病","慢性胆囊炎"],"a":0,"e":"慢性反复发作的上腹痛具有周期性与节律性，最常见于消化性溃疡；中老年人无规律上腹痛伴厌食、消瘦应警惕胃癌。"},{"q":"梗阻性黄疸的原因最常见的是","o":["肝细胞内胆红素蓄积过多","大量红细胞破坏","肝细胞膜通透性增大","肝内胆管胆汁淤积","肝细胞内胆红素结合过多"],"a":3,"e":"胆汁淤积性黄疸因胆道梗阻致梗阻上方胆管内压升高、小胆管与毛细胆管破裂，胆红素反流入血；肝内泥沙样结石、癌栓及胆总管结石、肿瘤所致梗阻均属此类。"},{"q":"血浆内常被测定的主要阴离子是","o":["Cl－与HCO3－","Cl－与SO42－","HCO3－与SO42－","HCO3－与HPO42－","Cl－与HPO42－"],"a":0,"e":"血浆中主要阴离子为Cl⁻和HCO3⁻，二者与Na⁺等共同维持电中性；阴离子间隙即Na⁺减去Cl⁻与HCO3⁻之和。"},{"q":"下列关于测量血压的描述哪项是正确的","o":["正常人从左右两臂测出的数值相差大约20mmHg","当Korotkoff音消失时为收缩压","听诊器胸件塞在袖带下","测下肢血压应选较窄的袖带","测量前，病人应在安静环境下休息5～10min"],"a":4,"e":"测量前30分钟禁烟、禁咖啡并排空膀胱，安静环境下坐位休息至少5分钟；Korotkoff第1音为收缩压，第5音为舒张压。"},{"q":"以手按压胸部皮下气肿的部位，可出现","o":["水泡音","捻发音","握雪感","压痛","揉面感"],"a":2,"e":"皮下气肿时气体在皮下组织内移动，触诊可有握雪感或捻发感，听诊器按压局部可闻及类似捻动头发的声音，多为肺、气管或胸膜损伤后气体逸出所致。"},{"q":"下列为自主神经功能检查项目，但不包括","o":["眼心反射","卧立试验","竖毛反射","角膜反射","皮肤划纹征"],"a":3,"e":"自主神经功能检查包括眼心反射、卧立试验、竖毛反射及皮肤划纹征；角膜反射属脑神经检查，反映三叉神经传入与面神经传出功能。"},{"q":"在心电图上最早出现的幅度较小的P波，反映的是","o":["心房的复极过程","心房的除极过程","心室的复极过程","心室的除极过程","心房到心室激动的一个完整过程"],"a":1,"e":"P波是心电图最早出现的幅度较小的波，反映心房除极过程；PR段反映心房复极及房室结、希氏束、束支的电活动，QRS波反映心室除极。"},{"q":"入院记录应该在患者入院后（ ）内完成","o":["6h","8h","12h","24h","上级医生查完前"],"a":3,"e":"入院记录应于病人入院后24小时内完成，由住院医师书写，内容要求原则上同住院病历但简明扼要；抢救记录于抢救结束后6小时内完成。"},{"q":"下列病变的查体所见错误的是","o":["胸腔积液时患侧呼吸音减弱","支气管肺炎时可闻及湿啰音","肺栓塞时可闻及胸膜摩擦音","阻塞性肺不张时呼吸音增强","肺结核时可闻及湿啰音"],"a":3,"e":"阻塞性肺不张时支气管阻塞、肺泡含气减少，语音震颤与呼吸音均减弱或消失，并非增强；肺栓塞时可因胸膜纤维素渗出闻及胸膜摩擦音。"},{"q":"下列关于便潜血试验的描述，哪项错误","o":["该试验对少量消化道出血有诊断价值","消化性溃疡活动期呈间断阳性","消化道肿瘤时呈持续阳性","服用铋剂药物，便为黑便，便潜血试验为阳性","便潜血试验前应素食3天"],"a":3,"e":"铋剂使粪便染成黑色属药物性着色，隐血试验仍为阴性；隐血试验前应素食3天，并停用铁剂、铋剂及维生素C。"},{"q":"心前区隆起主要见于","o":["肺源性心脏病","先天性心脏病","大量心包积液","肥厚性心肌病","高血压心脏病"],"a":1,"e":"心前区隆起多见于儿童期患先天性心脏病或慢性风湿性心瓣膜病伴右心室肥大者，因胸廓骨骼尚软，心脏增大可致局部膨隆。"},{"q":"患者胸痛、咳嗽、呼吸困难，下列哪项有助于鉴别气胸和胸腔积液","o":["呼吸运动","叩诊音","气管位置","呼吸音","摩擦音"],"a":1,"e":"气胸叩诊呈鼓音，胸腔积液叩诊为实音；二者气管均移向健侧、呼吸音均减弱，故叩诊音最有鉴别价值。"},{"q":"触诊心尖冲动常用","o":["右手全手掌","右手掌尺侧","右手掌桡侧","右手示指、中指指腹","右手第2～4指指腹"],"a":3,"e":"确定心尖搏动部位和范围时先用右手全手掌，进一步触诊以并拢的示指、中指指腹进行，指腹对触觉最为敏感。"},{"q":"下列体征，提示心源性水肿特异性最高的是","o":["肝颈静脉反流征阳性","腹腔积液","肝脾肿大","胸腔积液","双下肢水肿"],"a":0,"e":"肝颈静脉回流征阳性提示右心衰竭，压迫淤血的肝脏使回心血量增加，已充血的右心房不能承受，颈静脉压被动上升，为该病早期体征。"},{"q":"患者，男，66岁。发现高血压3年，未治疗。查体：BP 150/85mmHg。该患者的血压属于","o":["正常高值","单纯收缩期高血压","理想血压","正常血压","2级高血压"],"a":1,"e":"收缩压≥140mmHg而舒张压＜90mmHg即单纯收缩期高血压；该患者收缩压150mmHg属1级高血压范围，舒张压正常。"},{"q":"尿失禁的病因不包括","o":["尿道、膀胱先天性疾患","尿道、膀胱创伤","累及尿道、膀胱的手术","神经源性膀胱","前尿道疾患"],"a":4,"e":"尿失禁病因包括尿道膀胱先天畸形、创伤、手术及神经源性膀胱；前尿道狭窄、结石、肿瘤多致排尿困难或尿潴留，不属尿失禁病因。"},{"q":"关于临床诊断思维，以下说法不正确的是","o":["模式识别的诊断活动多数是在潜意识中进行，不是正确的临床思维","临床思维的基石是正确收集临床资料","诊断应优先考虑常见病和多发病","当诊断不清时，如患者存在可治性疾病的可能，可给予诊断性治疗的手段尽可能减轻患者痛苦","临床思维应考虑患者整体，而不是只考虑患者的诊断"],"a":0,"e":"模式识别是有经验医师常采用的诊断方法，虽多在潜意识中进行，仍属正确临床思维，结合其他方法可提高诊断效率与准确性。"},{"q":"下列是再生障碍性贫血外周血象，但应除外","o":["血红蛋白显著减少","红细胞显著减少","网织红细胞增多","白细胞显著减少","血小板显著减少"],"a":2,"e":"再生障碍性贫血外周血呈全血细胞减少，网织红细胞绝对值减低，提示骨髓红系造血功能低下；网织红细胞增多见于溶血性贫血及急性失血。"},{"q":"区别心肌梗死和变异型心绞痛，最有诊断意义的心电图改变是","o":["频发室性期前收缩","ST段抬高","T波异常高耸","病理性Q波","QRS波群低"],"a":3,"e":"变异型心绞痛发作时ST段抬高，但无病理性Q波，ST-T改变随症状缓解而恢复；心肌梗死出现病理性Q波，提示心肌坏死。"},{"q":"下图所示心电图的正确诊断是","o":["窦性心律，心电图正常","窦性心律，左房增大","窦性心律，预激综合征","窦性心律，左室肥厚","窦性心律，右室肥厚"],"a":2,"e":"官方题库缺失图片"},{"q":"多发性骨髓瘤时引起的红细胞形态异常可见于下列哪种情况","o":["靶形RBC","镰形RBC","RBC缗钱状改变","球形RBC","嗜碱点彩RBC"],"a":2,"e":"多发性骨髓瘤时血浆单克隆免疫球蛋白显著增高，降低红细胞表面负电荷，使红细胞呈缗钱状排列，血沉明显增快。"},{"q":"心肌梗死时心电图通常不会有","o":["ST段弓背向下抬高","镜像导联ST段压低","可见Q波","ST段抬高伴T波倒置","PR段无明显压低或者抬高"],"a":0,"e":"急性心肌梗死ST段呈弓背向上型抬高，与T波融合成单向曲线，并出现病理性Q波及镜像导联ST段压低；弓背向下抬高见于急性心包炎和早期复极。"},{"q":"不符合原发免疫性血小板减少症实验室检查结果的是","o":["血小板相关抗体增多","血小板计数减少","凝血酶原时间延长","网织血小板百分率增高","巨核细胞正常或增加"],"a":2,"e":"原发免疫性血小板减少症为血小板破坏增多，血小板计数减少、网织血小板百分率增高、血小板相关抗体增多、巨核细胞正常或增多；凝血因子正常，PT不延长。"},{"q":"间歇热与回归热的区别是","o":["热度高低不一","发热期与无热期交替存在","体温上升急缓","体温下降急缓","发热期与无热期持续时间的长短"],"a":4,"e":"间歇热高热期与无热期交替，无热期可持续1天至数天；回归热高热期与无热期各持续数天后规律交替，二者区别在于两期持续时间的长短。"},{"q":"关于疾病的诊断，下列哪种说法错误","o":["病因诊断首先考虑常见病、多发病","疾病诊断首先考虑器质性疾病","疾病诊断首先考虑可治性疾病的诊断","尽可能以多种疾病去解释多种临床表现","诊断应尽可能考虑当地流行和发生的传染病和地方病"],"a":3,"e":"应尽可能以一种疾病解释多种临床表现，减少诊断数目；器质性与功能性疾病鉴别困难时先考虑器质性，并优先考虑可治性疾病及当地流行的传染病、地方病。"},{"q":"下列哪一项为外源性凝血系统活性的综合性检查","o":["活化部分凝血活酶时间","简易凝血活酶生成试验","血清凝血酶原时间","血浆凝血酶原时间","血浆复钙时间"],"a":3,"e":"血浆凝血酶原时间检测外源性凝血途径，是外源性凝血系统较为灵敏、常用的筛选试验；活化部分凝血活酶时间反映内源性凝血途径。"},{"q":"下列疾病引起腹部膨隆均考虑出现腹腔积液，但除外","o":["肝硬化门静脉高压","腹膜癌转移","缩窄性心包炎","结核性腹膜炎","卵巢囊肿"],"a":4,"e":"卵巢囊肿所致浊音位于腹中部、鼓音在两侧，浊音不呈移动性，尺压试验阳性；肝硬化、腹膜癌转移、缩窄性心包炎及结核性腹膜炎均可致腹腔积液。"},{"q":"下列体征对于诊断胸腔积液，正确的是","o":["气管移向健侧，有支气管呼吸音，病侧叩诊浊音","气管移向健侧，病侧叩诊浊音，听到胸膜摩擦音","气管移向健侧，病侧叩诊鼓音，支气管语音弱","气管移向病侧，病侧叩诊浊音，支气管语音弱","气管居中，病侧叩诊浊音，听到胸膜摩擦音"],"a":0,"e":"中大量胸腔积液时气管移向健侧，病侧语音震颤减弱、叩诊实音、呼吸音减弱，积液区上方因压迫性肺不张可闻及支气管呼吸音。"},{"q":"用力解便后出现发绀，血压升高，心率增高，继而出现胸闷、呼吸困难、端坐位，两肺满布哮鸣音，可能诊断为","o":["支气管哮喘","喘息性支气管炎","心源性哮喘","心绞痛发作","肺炎"],"a":2,"e":"排便用力使回心血量骤增，诱发急性左心衰竭，出现端坐呼吸、双肺满布哮鸣音及湿啰音，称心源性哮喘，患者多有心脏病史。"},{"q":"呼吸系统系统回顾应包括下述项目，应除外","o":["咳嗽的性质和程度","咳痰的颜色、黏稠度","呼吸困难的性质、程度和出现时间","胸痛的部位、性质","发热的时间、程度"],"a":4,"e":"系统回顾呼吸系统应询问咳嗽性质、咳痰性状、咯血、呼吸困难性质及胸痛特点；发热属一般情况，在其他项目或全身症状中询问。"},{"q":"患者明确诊断为大叶性肺炎，下列说法错误的是","o":["常呈稽留热","多见于有基础疾病的人","主要病原体为病毒","可表现为头痛、咳嗽、咳铁锈色痰","病情易转为慢性，迁延不愈"],"a":2,"e":"大叶性肺炎主要病原体为肺炎链球菌，多见于青壮年，起病急、稽留热、咳铁锈色痰，病程短，多能痊愈而不转为慢性。"},{"q":"下列为正常人出现支气管肺泡呼吸音的常见部位，但应除外","o":["胸骨左侧第1、2肋间隙","胸骨右侧第1、2肋间隙","背部第6、7颈椎水平","肩胛间区第3、4胸椎水平","两肺尖的前后部位"],"a":2,"e":"支气管肺泡呼吸音正常见于胸骨两侧第1、2肋间隙、肩胛间区第3、4胸椎水平及肺尖前后；背部第6、7颈椎处听到的是支气管呼吸音。"},{"q":"下列有关脉压减小的叙述正确的是","o":["系指脉压30mmHg","为上下肢血压差异常所致","常伴有交替脉","主要见于主动脉瓣狭窄","也可见于动静脉瘘"],"a":3,"e":"脉压＜30mmHg为脉压减小，主要见于主动脉瓣狭窄、心包积液及严重心力衰竭；动静脉瘘、主动脉瓣关闭不全及甲亢则使脉压增大。"},{"q":"正常QTc应","o":["≤320ms","≤360ms","≤400ms","≤440ms","≤480ms"],"a":3,"e":"校正QT间期按Bazett公式计算，即QT除以RR间期的平方根，正常上限为0.44秒，超过此时限即认为QT间期延长。"},{"q":"正常输卵管的长度是","o":["7～14cm","8～14cm","6～14cm","9～15cm","10～15cm"],"a":1,"e":"正常输卵管长约8～14cm，表面光滑、质韧无压痛；增粗、结节、弯曲僵直并触痛者多见于急慢性炎症或结核。"},{"q":"患十二指肠球部溃疡的患者，当发生幽门梗阻时可发现的体征是","o":["肠型","移动性浊音阳性","液波震颤","振水音","高亢肠鸣音"],"a":3,"e":"幽门梗阻时胃内大量液体与气体潴留，空腹或餐后6～8小时以上仍可查出上腹部振水音，并可见胃型及胃蠕动波。"},{"q":"站立位胸膜腔最低位置是","o":["左脏胸膜下界","肋膈窦","心脏切迹","斜裂","右肺前界"],"a":1,"e":"肋胸膜与膈胸膜在肺下界以下的转折处构成肋膈窦，有2～3个肋间高度，为站立位胸膜腔最低处，胸腔积液常先积聚于此。"},{"q":"关于心脏视诊的叙述，下列哪项是正确的","o":["左心室肥大时，胸骨左缘第3肋间可见异常搏动","剑突下搏动亦可见于腹动脉瘤","右心室肥大心尖冲动向右移位","胸腔积液心尖冲动向患侧移位","小儿心脏扩大都有心前区隆起"],"a":1,"e":"剑突下搏动可为右心室收缩期搏动，也可由腹主动脉搏动产生，后者常由腹主动脉瘤引起；深吸气后搏动增强提示来自右心室。"},{"q":"体格检查时，对淋巴结的检查，正确的是","o":["先全身各部分查体，再系统地检查全身浅表淋巴结","查体一般只能检查身体各部浅表淋巴结","检查淋巴结应该双手同时触诊","肿大淋巴结的个数对判断良恶性疾病最重要","肿大淋巴结的大小对判断良恶性疾病最重要"],"a":1,"e":"体格检查一般仅能检查各部浅表淋巴结，应随相应部位检查顺序进行，注意其部位、大小、数目、硬度、压痛、活动度及有无粘连。"},{"q":"关于病理反射，正确的是","o":["指锥体束病损时，大脑失去了对脑干和脊髓的抑制作用而出现的异常反射","1岁半以内的婴儿由于神经系统发育不完善，不能出现病理反射","成人在正常时亦可出现病理反射","跟腱反射和膝反射属于病理反射","肱二头肌反射是病理反射"],"a":0,"e":"病理反射指锥体束病损时大脑失去对脑干和脊髓的抑制作用而出现的异常反射；1岁半以内婴幼儿神经系统发育未完善，也可出现而不属病理性。"},{"q":"符合上消化道出血粪便隐血试验阳性，最少出血量为","o":["2ml","5ml","10ml","15ml","20ml"],"a":1,"e":"消化道每日出血5～10ml即可使粪便隐血试验呈阳性而肉眼无颜色改变；出血量达50～100ml才出现黑便。"},{"q":"肺在维持酸碱平衡中的作用","o":["排出CO2是肺的唯一的功能","对固定酸没有作用","通过调节CO2排出，肺可恢复HCO3－浓度","可直接呼出酮体","对气化酸和固定酸都起作用"],"a":2,"e":"肺通过增减CO2排出量调节PaCO2，改变H2CO3浓度，使HCO3⁻/H2CO3比值恢复至20∶1，代偿代谢性酸碱失衡；肺不能直接排出固定酸。"},{"q":"主动脉瓣关闭不全时Austin-Flint杂音的产生机制正确的是","o":["经主动脉瓣逆流的血液将二尖瓣后叶推起","经主动脉瓣逆流的血液将二尖瓣前叶推起","肺动脉扩张血液反流所致","左心房舒张期负荷增加所致","左心室扩张使二尖瓣相对关闭不全所致"],"a":1,"e":"主动脉瓣关闭不全时，舒张期经主动脉瓣反流的血液冲击并推起二尖瓣前叶，使其开放受限，形成相对性二尖瓣狭窄而产生Austin-Flint杂音。"},{"q":"关于医嘱单，描述正确的是","o":["医师不得下达口头医嘱","取消医嘱需用红笔标注并签字","每项医嘱可包括多个内容","护士给药完毕后书写医嘱停止时间","抢救时，护士可直接执行口头医嘱，无需复述"],"a":1,"e":"医嘱不得涂改，需要取消时应以红色墨水标注“取消”字样并签名；每项医嘱只包含一个内容，抢救时口头医嘱须复述确认、事后补记。"},{"q":"关于肾脏功能检测，下列哪项不正确","o":["菊粉清除率可准确代表肾小球滤过率","β2-MG测定是诊断肾脏近曲小管受损的敏感指标","尿内出现大量蛋白尿并不能说明肾功能损伤严重","酚红排泌试验可反映肾小管的重吸收功能","血尿素和肌酐主要反映肾小球滤过功能"],"a":3,"e":"酚红排泌试验反映肾小管排泌功能而非重吸收功能；菊粉清除率可准确代表肾小球滤过率，β2-微球蛋白是近曲小管受损的敏感指标。"},{"q":"全身神经系统检查不包括","o":["脑神经检查","运动神经检查","感觉神经检查","大脑精神状态的检查","自主神经的检查"],"a":3,"e":"神经系统检查包括脑神经、运动神经、感觉神经、自主神经及反射检查；精神状态检查属一般检查内容，不列入神经系统检查。"},{"q":"慢性睾丸肿痛多见于","o":["流行性腮腺炎后","隐睾症","白血病睾丸浸润","精索静脉曲张","睾丸结核"],"a":4,"e":"睾丸慢性肿痛多由结核引起；急性肿痛、压痛明显者见于急性睾丸炎，常继发于流行性腮腺炎、淋病。"},{"q":"纸片扩散法药敏试验中，MH平板的厚度应为","o":["1mm","2mm","3mm","4mm","5mm"],"a":3,"e":"纸片扩散法药敏试验的MH琼脂平板厚度应为4mm，厚度均匀以保证抑菌圈直径可比；接种菌液浊度需调至0.5麦氏标准。"},{"q":"心前区触及心包摩擦感提示","o":["右侧胸膜炎","主动脉瓣狭窄","二尖瓣狭窄","心包炎","二尖瓣反流"],"a":3,"e":"心包摩擦感是急性心包炎时心包膜纤维素渗出致表面粗糙，脏层与壁层心包随心脏搏动摩擦产生的振动；渗液增多使两层分离后摩擦感消失。"},{"q":"正常尿比重范围，应是","o":["1.010±0.003","1.003～1.040","1.010～1.030","1.015～1.025","1.025以上"],"a":3,"e":"尿比重反映肾脏浓缩稀释功能，正常成人多为1.015～1.025；随机尿受饮水影响可低至1.003或高达1.030，持续固定在1.010左右提示浓缩稀释功能丧失。"},{"q":"反映胆汁淤滞的酶包括","o":["ALT、AST","MAO、PH","LDH、PK","ALP、ALT","ALP、GGT"],"a":4,"e":"胆汁淤积时ALP与GGT显著升高，并与血清胆红素平行增加；ALT、AST主要反映肝细胞损伤，LDH缺乏特异性。"},{"q":"高血压时心电图最不可能出现下列哪种改变","o":["左室面高电压","电轴左偏","复极异常","QRS波轻度增宽","胸前导联T波高尖"],"a":4,"e":"高血压致左心室肥厚，心电图表现为左室面高电压、电轴左偏、QRS波轻度增宽及ST-T复极异常；T波高尖见于高血钾和超急性期心肌梗死。"},{"q":"局部视诊包括下列各项，但应除外","o":["胸廓","腹形","包块硬度","关节外形","骨骼"],"a":2,"e":"局部视诊观察胸廓、腹形、关节外形及骨骼等；包块硬度须靠触诊判断，触诊还可明确包块大小、轮廓、表面性质及移动度。"},{"q":"发热时体温上升期的表现不包括","o":["疲乏无力","肌肉酸痛","皮肤苍白","出汗多，皮肤潮湿","畏寒或寒战"],"a":3,"e":"体温上升期因体温调定点上移、皮肤血管收缩，出现畏寒、寒战、皮肤苍白、疲乏无力及肌肉酸痛；出汗多、皮肤潮湿见于高热期和体温下降期。"},{"q":"肺动脉瓣听诊区第二心音减弱，最常见于","o":["肺动脉瓣狭窄","二尖瓣狭窄","二尖瓣关闭不全","房间隔缺损","室间隔缺损"],"a":0,"e":"肺动脉瓣狭窄时右室射血受阻、肺动脉内压力降低，P2减弱，常伴收缩期喷射性杂音与震颤；二尖瓣狭窄、房缺及室缺时P2多亢进。"},{"q":"心电图Ⅱ、Ⅲ、aVF导联ST段弓背向上抬高提示哪个部位的心肌梗死","o":["高侧壁","后侧壁","下壁","前壁","后壁"],"a":2,"e":"Ⅱ、Ⅲ、aVF导联反映下壁心肌，其ST段弓背向上抬高提示急性下壁心肌梗死；V1～V5导联异常Q波提示前壁梗死。"},{"q":"正常成年人体内HbA占","o":["98%","60%","50%","3%","＜1%"],"a":0,"e":"正常成人血红蛋白以HbA为主，约占98%，HbA2占2.5%～3.5%，HbF＜1%；HbA2增高是诊断β轻型地中海贫血的重要依据。"},{"q":"红细胞内游离原卟啉增多最常见于","o":["巨幼细胞贫血","溶血性贫血","再生障碍性贫血","恶性贫血","铁粒幼细胞贫血"],"a":4,"e":"铁粒幼细胞贫血时血红素合成障碍、铁利用不良，原卟啉不能与铁结合，红细胞内游离原卟啉明显增多，骨髓可见环形铁粒幼红细胞。"},{"q":"标准V7导联位置正确的是","o":["左侧腋前线V4导联同一水平","左侧腋中线V4和V5同一水平","左侧肩胛线V4～V6同一水平","左侧脊柱旁线V4～V6同一水平","左侧腋后线V4～V6同一水平"],"a":4,"e":"V7导联置于左腋后线，V8在左肩胛骨线，V9在左脊旁线，均与V4同一水平，用于诊断正后壁心肌梗死。"},{"q":"正常人潮气容积为500ml，其中无效腔气有","o":["150ml","200ml","100ml","250ml","50ml"],"a":0,"e":"正常成人潮气容积约500ml，其中150ml为解剖无效腔气，不参与气体交换；按呼吸15次/分计，肺泡通气量约5.25L/min。"},{"q":"心脏杂音的强度与哪项因素无关","o":["狭窄程度","血流速度","压力阶差","血液黏度","心肌收缩力"],"a":3,"e":"杂音强度取决于狭窄程度、血流速度、压力阶差及心肌收缩力；血液黏度主要影响血流阻力，与杂音响度无明显关系。"},{"q":"典型的再生障碍性贫血（急性型）的骨髓增生程度是","o":["增生极度活跃","增生明显活跃","增生活跃","增生减低","增生极度减低"],"a":4,"e":"急性再生障碍性贫血骨髓有核细胞显著减少，成熟红细胞与有核细胞之比达200∶1，每高倍视野有核细胞少于5个，属增生极度减低。"},{"q":"下列各项均为正常腹部可触到的包块，但除外","o":["腹直肌腱划","触及胆囊","右肾下极","乙状结肠索","骶骨岬"],"a":1,"e":"正常腹部可触及腹直肌腱划、右肾下极、乙状结肠索及骶骨岬；胆囊隐存于肝脏之后，正常不能触及，肿大超过肝缘时才可触到。"},{"q":"下列各项均为消化性溃疡的并发症，但除外","o":["出血","幽门梗阻","恶性贫血","恶变","穿孔"],"a":2,"e":"消化性溃疡的并发症为出血、穿孔、幽门梗阻和恶变；恶性贫血由内因子缺乏致维生素B12吸收障碍引起，见于萎缩性胃炎。"},{"q":"关于未结合胆红素的叙述，错误的是","o":["在溶血性黄疸时显著增高","在血浆中与白蛋白的结合是可逆的","在血浆中与白蛋白结合后毒性变小","在梗阻性黄疸时显著增高","肝细胞损伤也会升高"],"a":3,"e":"未结合胆红素在血浆中与白蛋白可逆结合，结合后毒性变小，溶血性黄疸及肝细胞损伤时升高；梗阻性黄疸以结合胆红素升高为主。"},{"q":"下列情况是中性粒细胞病理增多的原因，但应除外","o":["急性感染","急性溶血","急性失血","恶性肿瘤","再生障碍性贫血"],"a":4,"e":"中性粒细胞增多见于急性感染、急性溶血、急性失血、恶性肿瘤及大面积组织损伤；再生障碍性贫血时中性粒细胞减少。"},{"q":"下列哪种试验准确地反映肾小球滤过率","o":["内生肌酐清除率","菊粉清除率","尿素清除率","血尿素酸","β2-微球蛋白"],"a":1,"e":"菊粉可自由滤过肾小球，且不被肾小管重吸收或排泌，其清除率能准确代表肾小球滤过率，为GFR测定的参考方法。"},{"q":"关于血培养的运送和处理，下列错误的是","o":["血培养抽取后，立即送到微生物实验室","如不能立即送往实验室，置4℃冰箱冷藏","如不能立即送往实验室，置35～37℃孵箱中","如暂不能立即送往实验室，可放室温保存","实验室接受到培养瓶，应立即置35～37℃孵箱或血培养仪中"],"a":1,"e":"血培养瓶采集后应室温保存或置35～37℃孵箱，不可冷藏，冷藏会使苛养菌死亡而降低检出率；细菌学标本应在2小时内送检，脑脊液须立即送检。"},{"q":"两侧肺底出现湿啰音最常见于哪种疾病","o":["肺气肿","心力衰竭","肺结核","支气管哮喘","支气管扩张"],"a":1,"e":"两侧肺底湿啰音多见于心力衰竭所致肺淤血和支气管肺炎，肺淤血时液体受重力作用积聚于肺底；局限性湿啰音才提示肺炎、肺结核或支气管扩张。"},{"q":"左心衰竭咯血的痰液特点为","o":["浆液性粉红色泡沫样痰","黏稠暗红色血痰","砖红色胶冻样痰","铁锈色样痰","鲜红色样痰"],"a":0,"e":"左心衰竭肺淤血、肺水肿时血浆和红细胞渗入肺泡，与气体混合形成浆液性粉红色泡沫样痰；砖红色胶冻样痰见于肺炎克雷伯菌肺炎，铁锈色痰见于肺炎链球菌肺炎。"},{"q":"动脉导管未闭的脉搏是","o":["奇脉","迟脉","交替脉","水冲脉","重搏脉"],"a":3,"e":"动脉导管未闭时主动脉血液大量分流至肺动脉，舒张压下降、脉压增大，故出现骤起骤落的水冲脉；迟脉见于主动脉瓣狭窄，交替脉见于左心衰竭。"},{"q":"下列哪项为左心室肥大的心电图表现","o":["RV1＋SV5＞1.2mV","RV1＞1.0mV","RaVL＜1.1mV","RV5＋SV1＞4.5mV","RaVR＞0.5mV"],"a":3,"e":"左心室肥大以左室高电压为主要表现，RV5或RV6＞2.5mV、RV5＋SV1＞4.0mV（男性）或＞3.5mV（女性），伴电轴左偏和ST-T改变；RV1＋SV5＞1.2mV、RaVR＞0.5mV为右心室肥大标准。"},{"q":"成年男性与女性颈部外形较明显的区别是","o":["男性静坐时颈部血管可显露","男性颈部较细长","男性甲状软骨较突出","男性转头时可见胸锁乳突肌突出","男性颈部直立，两侧对称"],"a":2,"e":"男性甲状软骨比较突出，女性则平坦不显著，是颈部外形较明显的性别差异；颈部直立对称、转头时胸锁乳突肌突起为两性共有表现。"},{"q":"隐性黄疸时，血清总胆红素含量为","o":["1.71～3.42μmol/L","5.13～6.84μmol/L","8.55～15.4μmol/L","17.1～34.2μmol/L","73.4μmol/L"],"a":3,"e":"血清总胆红素17.1～34.2μmol/L时临床不易察觉，称隐性黄疸；超过34.2μmol/L出现肉眼可见黄疸，正常上限为17.1μmol/L。"},{"q":"关于内源性致热原的描述，错误的是","o":["又称白细胞致热源","可通过副交感神经使机体散热减少","包括白介素-1、肿瘤坏死因子","通过垂体内分泌因素使机体产热增多","可通过血脑脊液屏障"],"a":1,"e":"内源性致热原经交感神经使皮肤血管和竖毛肌收缩、停止排汗而散热减少，并非副交感神经；它经血-脑脊液屏障作用于体温调定点，属白细胞致热原，包括IL-1、TNF和干扰素。"},{"q":"关于体温的论述，下列正确的是","o":["体温低于36.5℃称体温过低","甲状腺功能亢进患者常有体温过低","体温升高超出正常范围称为发热","无菌性炎症一般无发热","慢性消耗性疾病患者常有体温升高"],"a":2,"e":"发热是机体在致热原作用下或体温调节中枢功能障碍时，体温升高超出正常范围；体温低于正常称体温过低，甲亢常致体温升高，无菌性炎症也可引起发热。"},{"q":"以下为血红蛋白测定值，其中符合中度贫血的是","o":["＜60g/L","90～60g/L","90～70g/L","80～60g/L","＜70g/L"],"a":1,"e":"中度贫血血红蛋白为60～90g/L，体力劳动时心慌气短；轻度＞90g/L，重度30～59g/L，极重度＜30g/L。"},{"q":"患者，女，25岁，腹痛来诊。下述哪个问题不合适","o":["请告诉我你哪里不舒服","请告诉我你痛的情况","疼痛像什么样","疼痛是刺痛吗","痛的部位有变动吗"],"a":3,"e":"问诊应先以开放式提问让病人自主叙述，再酌情采用直接提问；疼痛是刺痛吗属诱导性提问，易使病人顺承作答而失去真实性。"},{"q":"关于阵发性室上性心动过速的心电图特点，下列哪项不正确","o":["突发突止","频率在160～250次/min","节律快而规律，RR间期绝对匀齐","QRS波一般不正常","可见逆传p波"],"a":4,"e":"官方答案为可见逆传p波，但依据教材，正确答案为QRS波一般不正常。阵发性室上速QRS波群形态与时限一般正常，仅伴室内差异性传导或束支阻滞时才宽大畸形，故QRS波一般不正常一说不成立；其特点为突发突止、频率160～250次/分、节律绝对匀齐，可见逆行P波。"},{"q":"固定型上气道阻塞在F/V曲线上的典型表现为","o":["吸气相平台","呼气相平台","吸气相平台＋呼气相平台","双蝶形改变","高位平台"],"a":2,"e":"固定型上气道阻塞时吸气和呼气均受限，流量-容积曲线呈现吸气相与呼气相双平台；可变型才表现为吸气相或呼气相单侧平台。"},{"q":"冠心病患者出现哪项体征，提示早期左心功能不全","o":["颈静脉怒张","左心室扩大","心尖部舒张期奔马律","肺部啰音","肝大，下肢水肿"],"a":2,"e":"舒张早期奔马律提示心室舒张期负荷过重、心肌顺应性减退，是左心功能不全的早期体征，心尖区稍内侧、呼气末最清楚；颈静脉怒张、肝大及下肢水肿属右心衰竭表现。"},{"q":"下列均为正确触诊脾脏的方法，但除外","o":["患者仰卧位两腿稍屈曲","医生右手掌平放于上腹部与肋大致成垂直方向","医生左手掌置于患者左腰部第4～6肋处","随患者深呼吸运动进行触脾","右侧卧位触脾时，右下肢伸直，左下肢屈曲"],"a":2,"e":"脾脏双手触诊时左手应绕过腹前方，手掌置于左胸下部第9～11肋处，将脾从后向前托起并限制胸廓运动；置于左腰部第4～6肋处并非脾触诊手法。"},{"q":"现病史的内容不包括","o":["发病情况","主要症状特点及其发展变化情况","手术外伤史","发表以来诊治经过及结果","伴随症状"],"a":2,"e":"现病史记述起病情况、主要症状特点及演变、伴随症状、诊治经过和病程中一般情况；手术外伤史属既往史内容。"},{"q":"迟脉最常见于","o":["主动脉瓣关闭不全","主动脉瓣狭窄","伤寒","心包积液","原发性高血压"],"a":1,"e":"迟脉脉搏升支缓慢、波峰低平，因主动脉瓣狭窄致左室射血受阻、每搏量减少；主动脉瓣关闭不全则因脉压增大出现水冲脉。"},{"q":"肌肉松弛，伸屈阻力低，关节活动范围扩大。这不见于以下哪种病变","o":["周围神经病变","脊髓前角病变","肌源性病变","长时间上单位神经元损伤病变","小脑病变"],"a":3,"e":"肌张力降低见于下运动神经元病变如周围神经炎、脊髓前角灰质炎，以及小脑病变和肌源性病变；上运动神经元损伤表现为痉挛性肌张力增高。"},{"q":"奇脉的产生与下列因素有关","o":["周围血管弹性差","呼气时胸腔压力改变","心肌收缩力差","左室心搏出量低","周围血管扩张"],"a":3,"e":"奇脉指吸气时脉搏明显减弱或消失，因吸气时胸腔负压增大、右心回心血量增多致室间隔左移，左室充盈和每搏输出量减少，收缩压下降超过10mmHg。"},{"q":"蛋白尿是指尿蛋白定量试验","o":["＞50mg/24h","＞80mg/24h","＞100mg/24h","＞150mg/24h","＞200mg/24h"],"a":3,"e":"尿蛋白定量＞150mg/24h或＞100mg/L、定性试验阳性即称蛋白尿；生理性蛋白尿定量一般不超过500mg/24h。"},{"q":"上消化道出血部位一般是指","o":["食道","贲门","幽门","十二指肠球部","屈氏韧带以上的消化器官"],"a":4,"e":"上消化道指屈氏韧带即十二指肠悬韧带以上的消化道，包括食管、胃、十二指肠、肝、胆、胰及胃空肠吻合术后的空肠上段。"},{"q":"关于心脏触诊，正确的是","o":["心底部异位搏动提示肺动脉高压","二尖瓣狭窄可触及心尖区舒张期震颤","大面积心肌梗死可触及心尖抬举样搏动","大量心包积液可触及心包摩擦感","主动脉狭窄可触及胸骨右缘第2肋间舒张期震颤"],"a":1,"e":"二尖瓣狭窄时心尖区可触及舒张期震颤，伴S1亢进及舒张中晚期隆隆样杂音；心包摩擦感见于纤维蛋白性心包炎，大量心包积液时反而消失。"},{"q":"急性肝损伤时，改变最早的血清蛋白成分是","o":["白蛋白","α球蛋白","前白蛋白","β球蛋白","γ球蛋白"],"a":2,"e":"前白蛋白半衰期约2天，明显短于白蛋白，急性肝细胞损害时血清浓度迅速下降，故比白蛋白更早反映肝功能变化。"},{"q":"下列情况均可引起P2增强，但除外","o":["房间隔缺损","二尖瓣狭窄","二尖瓣关闭不全","肺动脉瓣狭窄","动脉导管未闭"],"a":3,"e":"P2增强见于肺动脉高压及肺血增多的疾病，如房间隔缺损、动脉导管未闭、二尖瓣狭窄和二尖瓣关闭不全；肺动脉瓣狭窄时肺动脉压不高，P2减弱。"},{"q":"稽留热常见于","o":["风湿热","疟疾","伤寒","布鲁菌病","渗出性胸膜炎"],"a":2,"e":"稽留热体温恒定于39～40℃以上、24小时波动不超过1℃，见于大叶性肺炎、斑疹伤寒和伤寒高热期；疟疾呈间歇热，布鲁菌病呈波状热。"},{"q":"下述查体所见均可在胸腔积液与气胸时出现，但应除外","o":["患侧饱满","气管向健侧移位","呼吸音减弱或消失","患侧呼吸动度减弱","叩诊呈浊音"],"a":4,"e":"气胸叩诊呈鼓音或过清音，胸腔积液才呈浊音或实音，故叩诊浊音不是二者共有体征；患侧饱满、呼吸动度与呼吸音减弱、气管移向健侧则两者均可见。"},{"q":"采集病史时，不恰当的提问是","o":["发病后用过哪些药物","您的尿液是红色的吗","什么情况下疼痛加重","多在什么情况下发病","您哪儿不舒服"],"a":1,"e":"问诊宜用开放式提问，避免暗示性语言；您的尿液是红色的吗属诱导性提问，易使病人按医生预设作答，其余各项为中性提问。"},{"q":"单纯性收缩期高血压的诊断标准是","o":["收缩压≥140mmHg","收缩压≥160mmHg或舒张压≤90mmHg","收缩压≥140mmHg和舒张压＜90mmHg","收缩压≥140～160mmHg","收缩压≥160mmHg"],"a":2,"e":"单纯收缩期高血压指收缩压≥140mmHg且舒张压＜90mmHg；收缩压与舒张压分属不同级别时以较高者为准。"},{"q":"该心电图的诊断考虑","o":["完全性右束支传导阻滞","窦性心律，完全性左束支传导阻滞","窦性心律，左前分支传导阻滞","窦性心律，左后分支传导阻滞","窦性心律，完全性右束支传导阻滞"],"a":4,"e":"官方题库缺失图片"},{"q":"听到开瓣音常提示","o":["二尖瓣狭窄伴二尖瓣关闭不全","二尖瓣严重狭窄，瓣膜钙化","二尖瓣狭窄分离术的禁忌证","二尖瓣狭窄伴左心衰竭","二尖瓣轻、中度狭窄，瓣膜弹性和活动性较好"],"a":4,"e":"开瓣音在S2后0.05～0.06秒出现，音调高、清脆呈拍击样，提示二尖瓣叶弹性及活动度尚好，是二尖瓣分离术适应证的参考；瓣叶钙化僵硬时开瓣音消失。"},{"q":"下述哪种物质可刺激T淋巴细胞发生细胞分化","o":["抗体","补体","植物血凝素","绵羊RBC","小鼠RBC"],"a":2,"e":"植物血凝素是非特异性有丝分裂原，与T细胞表面受体结合后促其转化为淋巴母细胞，用于T细胞转化试验评价细胞免疫功能。"},{"q":"周围血管征不见于","o":["伤寒","动静脉瘘","主动脉瓣关闭不全","甲亢","严重贫血"],"a":0,"e":"周围血管征由脉压增大引起，包括水冲脉、枪击音和毛细血管搏动，见于主动脉瓣关闭不全、甲状腺功能亢进、严重贫血及动静脉瘘；伤寒脉搏相对缓慢，无此征。"},{"q":"下列是关于舒张晚期奔马律的正确描述，但应除外","o":["也称收缩前期奔马律","也称第四心音奔马律","也称房性奔马律","也称室性奔马律","实际上是由病理性第四心音与第一、第二心音构成"],"a":3,"e":"舒张晚期奔马律又称收缩期前奔马律、房性奔马律或第四心音奔马律，是增强的病理性S4；室性奔马律指舒张早期即第三心音奔马律。"},{"q":"发热时糖代谢变化为","o":["糖原分解增多，糖异生增强，血糖升高，乳酸增多","糖原分解增多，糖异生减少，血糖升高，乳酸减少","糖原分解减少，糖异生减少，血糖降低，乳酸增多","糖原分解减少，糖异生增加，血糖降低，乳酸减少","糖原分解增多，糖异生不变，血糖波动，乳酸减少"],"a":0,"e":"发热时交感神经兴奋、儿茶酚胺和糖皮质激素增多，肝糖原分解与糖异生增强使血糖升高；组织耗氧增加、无氧酵解增强使乳酸增多。"},{"q":"不常见杵状指（趾）表现的疾病是","o":["支气管肺癌","先天性心脏病，法洛四联症","肢端肥大症","肺性肥大性骨关节病","支气管扩张症"],"a":2,"e":"杵状指多见于支气管肺癌、支气管扩张、慢性肺脓肿、发绀型先天性心脏病及肺性肥大性骨关节病；肢端肥大症表现为手足和面容增大，不出现杵状指。"},{"q":"体温上升期的热代谢特点是","o":["产热和散热平衡","散热大于产热","产热大于散热","产热障碍","散热障碍"],"a":2,"e":"体温上升期体温调定点上移，产热增加而散热减少，产热大于散热使体温上升；骤升型常伴寒战，缓升型无寒战。"},{"q":"下列为测量体温时，可能出现的误差，但不包括","o":["测量体温前未把体温计汞柱甩到36℃以下","测量体温时未将体温计夹紧","体温计附近有影响局部体温的冰袋或热水袋","测体温常在早晨低、下午高，日温总在1℃内波动","测体温前用热水漱口、热毛巾擦腋下"],"a":3,"e":"24小时内下午体温较早晨稍高、波动不超过1℃属正常生理变异，不是测量误差；汞柱未甩至36℃以下、未夹紧、局部有冷热源及热漱口均可致读数偏差。"},{"q":"细胞免疫的主要效应细胞CTL由下列哪种细胞辅助产生","o":["Th1细胞","TDTH细胞","Th2细胞","B细胞","NK细胞"],"a":0,"e":"Th1细胞分泌IL-2和IFN-γ，辅助CD8+T细胞活化、增殖并分化为细胞毒性T细胞；Th2细胞主要辅助B细胞产生抗体。"},{"q":"建立慢性阻塞性肺疾病的诊断需要以下哪项","o":["FEV1降低","FVC降低","FEV1/FVC降低","咳嗽、咳痰","RV降低"],"a":2,"e":"持续气流受限是诊断慢性阻塞性肺疾病的必需条件，吸入支气管舒张剂后FEV1/FVC降低可确定存在不能完全逆转的气道阻塞。"},{"q":"下列哪种情况在常规导联心电图上不出现典型心肌梗死图形","o":["前间壁心肌梗死","前壁心肌梗死","下壁心肌梗死","后壁心肌梗死","前侧壁心肌梗死"],"a":3,"e":"后壁心肌梗死需加做V7～V9导联才能记录到异常Q波，常规12导联仅表现为V1、V2导联R波增高、ST段压低和T波高耸的对应性改变。"},{"q":"下列哪项心电图表现提示室内传导阻滞","o":["心电图上QRS波群的时限超过0.10s","QRS波群的形态与典型的LBBB和RBBB均不相似","整个希氏-浦肯野系统的冲动传导弥漫性减慢的结果，导致心室心肌的激动全面性一致延迟","肢体导联上呈现RBBB，而心前区导联上呈现LBBB表现，或反之","肢体导联呈左前分支阻滞，胸导联呈左后分支阻滞，或反之"],"a":0,"e":"室内传导阻滞时激动经心室肌缓慢传导，QRS时限延长超过0.10s，完全性阻滞≥0.12s，是心电图判断室内传导阻滞的基本依据。"},{"q":"尿失禁的概念是指","o":["尿液从不正常的径路流出","由于严重的膀胱炎有尿液不断从尿道流出","由于膀胱肌损伤，尿液不自主流出","输尿管口异位，尿液从尿道口旁或尿道排出","由于膀胱挛缩，尿液不断从尿道流出"],"a":2,"e":"尿失禁是膀胱括约肌损伤或神经功能障碍使排尿自控能力下降或丧失，尿液不自主流出；尿液从不正常径路流出属尿瘘。"},{"q":"关于急性阑尾炎，哪项正确","o":["右下腹无压痛，可排除阑尾炎","凡是上腹痛或下腹痛都要考虑阑尾炎可能","急性阑尾炎穿孔时，X线检查见膈下有游离气体","保守治疗时，腹痛突然减轻肯定炎症消退","急性阑尾炎都有恶心、呕吐、腹泻等消化道症状"],"a":1,"e":"急性阑尾炎早期疼痛位于中上腹或脐周，为内脏神经痛，数小时后转移至右下腹McBurney点，故上腹或下腹痛均需考虑其可能；穿孔不一定出现膈下游离气体。"},{"q":"最容易发生心房颤动的疾病是","o":["贫血","心肌炎","二尖瓣狭窄","高热","预激综合征"],"a":2,"e":"二尖瓣狭窄使左房压力升高、左房扩大及心房肌纤维化，心房电活动紊乱，故最易发生心房颤动，是房颤最主要的病因。"},{"q":"尿中胆红素阳性，主要是由于血中增加的是","o":["未结合胆红素","结合胆红素","胆绿素","血红素","与清蛋白结合的胆红素"],"a":1,"e":"结合胆红素为水溶性，可经肾小球滤过，血中浓度超过肾阈34μmol/L时即从尿排出；非结合胆红素与清蛋白结合，不能经肾滤过，故尿中不出现。"},{"q":"以下是医生运用血压计正确的测血压方法，但哪项是错误的","o":["患者采取坐位，安静休息10min以后","肘部应与心脏同一水平，上臂伸直并稍外展","袖带气囊部分对准肱动脉，紧贴皮肤缚于上臂","袖带下缘应距肘弯横纹上2cm处","再将听诊器胸件放于袖带下肱动脉上"],"a":4,"e":"听诊器体件应置于袖带下缘下方、肱动脉搏动处，不能塞入袖带内，否则局部受压过紧使测值偏低；袖带下缘应在肘窝上约2.5cm。"},{"q":"骨髓细胞学检查对下列哪种疾病具有明确诊断作用","o":["失血性贫血","溶血性贫血","再生障碍性贫血","粒细胞缺乏症","类白血病反应"],"a":2,"e":"再生障碍性贫血骨髓增生减低、造血细胞减少而脂肪组织增多，结合骨髓活检可明确诊断；失血性和溶血性贫血骨髓呈代偿性增生，需靠其他检查确定病因。"},{"q":"慢性充血性心力衰竭的患者胸腔积液中蛋白质与血清中蛋白质的比值常小于","o":["0.1","0.2","0.3","0.5","0.6"],"a":3,"e":"慢性充血性心力衰竭所致胸腔积液为漏出液，积液蛋白/血清蛋白＜0.5、积液蛋白＜25g/L、Rivalta试验阴性；比值＞0.5提示渗出液。"},{"q":"下列情况下常发生“火车头”奔马律的是","o":["舒张早期奔马律与舒张晚期奔马律的互相重叠","舒张早期奔马律与舒张晚期奔马律的同时存在","收缩晚期喀喇音与舒张早期奔马律的同时存在","收缩早期喀喇音与舒张晚期奔马律的同时存在","收缩中期喀喇音与舒张晚期奔马律的同时存在"],"a":1,"e":"舒张早期与舒张晚期奔马律同时存在、心率较慢时可闻及S1、S2、病理性S3和S4四个心音，称舒张期四音律，节律酷似火车奔跑，故称火车头奔马律；二者重叠则形成重叠型奔马律。"},{"q":"凝血时间延长，出血时间正常的疾病是","o":["特发性或继发性血小板减少性紫癜","过敏性紫癜","血友病","血管性假血友病","再生障碍性贫血"],"a":2,"e":"血友病为内源性凝血因子Ⅷ、Ⅸ缺乏，凝血时间和APTT延长而出血时间、血小板计数正常；血小板减少性紫癜及血管性血友病则出血时间延长。"},{"q":"S2反常分裂可见于","o":["正常儿童和青年","完全性右束支传导阻滞","完全性左束支传导阻滞","房间隔缺损","二尖瓣关闭不全"],"a":2,"e":"S2反常分裂又称逆分裂，指主动脉瓣关闭迟于肺动脉瓣，吸气时分裂变窄、呼气时变宽，见于完全性左束支传导阻滞、主动脉瓣狭窄和重度高血压。"},{"q":"关于病程记录说法不正确的是","o":["由经治医师书写，不能由实习医师或试用期医务人员书写","内容要真实，记录及时","要有分析判断和预见","病危患者每天至少记录1次","病重患者至少2天记录1次"],"a":0,"e":"日常病程记录由住院医师书写，也可由实习或试用期医务人员书写，但须有住院医师签名；病危患者每天至少记录1次，病重者至少2天1次。"},{"q":"急性弥漫性腹膜炎患者为减轻腹痛，常采取何种体位","o":["侧卧位","仰卧位、双下肢屈曲","仰卧位、两下肢伸直","俯卧位","半卧位"],"a":1,"e":"急性弥漫性腹膜炎取强迫仰卧位、双腿蜷曲，可减轻腹肌紧张和腹痛；半卧位用于使腹腔感染局限并改善膈肌活动。"},{"q":"下列是二尖瓣狭窄时经常出现的症状，但应除外","o":["声音嘶哑","吞咽困难","劳力性呼吸困难","咯血","心绞痛"],"a":4,"e":"二尖瓣狭窄时左房扩大压迫喉返神经致声音嘶哑、压迫食管致吞咽困难，肺淤血引起劳力性呼吸困难和咯血；心绞痛是主动脉瓣狭窄典型三联征之一。"},{"q":"关于肝脏触诊下列各项均正确，但除外","o":["正常成人的肝肋缘下触不到","深吸气，肋弓下触及肝下缘1cm内，不属于肝大","剑下触及肝下缘3cm内，不属于肝大","如肋下触及肝大3cm，质软、光滑，无压痛，可判定为肝大","肝脏质地分三级，正常肝无压痛"],"a":3,"e":"判定肝大须先叩诊肝上界，肝上界下移而肋下可及肝缘者属肝下移，见于肺气肿和右侧胸腔积液；正常成人肋缘下多触不到肝，瘦长体型深吸气可达1cm以内。"},{"q":"关于细湿啰音的描述，正确的是","o":["又称捻发音","发生于细支气管","多在呼气末出现","常见于肺淤血","咳嗽后不能消失"],"a":3,"e":"细湿啰音又称小水泡音，发生于小支气管，多在吸气后期出现，见于细支气管炎、支气管肺炎、肺淤血和肺梗死；捻发音为极细而均匀的爆裂音，与细湿啰音不同。"},{"q":"下列对确诊支气管哮喘最有意义是","o":["支气管激发实验阳性","静脉输注氨茶碱有效","血中嗜酸性粒细胞增多","反复发作的喘息、呼吸困难","发作时双肺弥漫性哮鸣音"],"a":0,"e":"气道高反应性是支气管哮喘的特征，支气管激发试验阳性可判定气道反应性增高，对症状不典型或肺功能正常者最具诊断价值。"},{"q":"患者腹胀半年余，粪便中见到较多的淀粉颗粒，常见于","o":["慢性胰腺炎","慢性肝炎","乙状结肠癌","溃病性结肠炎","直肠癌"],"a":0,"e":"粪便中见到较多淀粉颗粒、脂肪小滴或肌肉纤维，提示胰外分泌功能不全、消化吸收障碍，常见于慢性胰腺炎。"},{"q":"巨幼细胞贫血易引起以下哪种改变","o":["空泡变性","棒状小体","核右移","核左移","Dohle体"],"a":2,"e":"巨幼细胞贫血时DNA合成障碍，中性粒细胞分叶过多，5叶以上者超过3%，外周血呈核右移；核左移见于急性感染等。"},{"q":"心源性哮喘可见于以下疾病，但哪一项除外","o":["急性左心衰竭","高血压心脏病","扩张性心脏病","肺源性心脏病","液体负荷过重"],"a":3,"e":"心源性哮喘由急性左心衰竭致肺淤血、肺水肿引起，见于急性左心衰竭、高血压心脏病、扩张型心肌病和液体负荷过重；肺源性心脏病为右心病变，不引起左心衰竭性哮喘。"},{"q":"急性心包炎早期具有诊断价值的症状或体征是","o":["奇脉","血压下降，脉压减少","心包摩擦音","Kussmaul征（＋）","Ewart征（＋）"],"a":2,"e":"纤维蛋白性心包炎早期，脏、壁层心包粗糙摩擦产生心包摩擦音，与心搏一致、屏气时仍存在，是急性心包炎最具诊断价值的体征；积液增多后摩擦音可消失。"},{"q":"S2通常分裂见于下列疾病，但除外","o":["完全右束支阻滞","肺动脉瓣狭窄","二尖瓣狭窄","肺动脉高压","主动脉瓣狭窄"],"a":4,"e":"S2通常分裂因右室排血时间延长、肺动脉瓣关闭延迟，见于完全性右束支阻滞、肺动脉瓣狭窄、二尖瓣狭窄和肺动脉高压；主动脉瓣狭窄使A2延迟，产生反常分裂。"},{"q":"肺泡呼吸音减弱或消失的原因不包括","o":["胸廓活动受限","呼吸肌疾病","支气管阻塞","压迫性肺膨胀不全","机体需氧量增加"],"a":4,"e":"机体需氧量增加时肺泡呼吸音增强而非减弱；减弱见于胸廓活动受限、呼吸肌疾病、支气管阻塞、压迫性肺膨胀不全及胸腔积液、气胸等。"},{"q":"脑积水时的头颅改变是","o":["方颅","小颅","尖颅","巨颅","长颅"],"a":3,"e":"脑积水时颅内压增高使额、顶、颞及枕部膨大呈圆形，颜面相对很小，伴眼球下视、巩膜外露的落日现象，称巨颅。"},{"q":"能确定有心肌缺血的心电图改变是","o":["电轴显著左偏","左心室面电压增高","V5导联ST段近似水平下移＜0.1mV","P波电压＞0、3mV","V4、V5、V6的ST段水平下移＞0.2mV伴T波倒置"],"a":4,"e":"ST段水平或下斜型压低≥0.1mV即提示心内膜下心肌缺血，压低＞0.2mV并伴T波倒置诊断意义更明确；单纯电轴左偏和左室高电压不能确定心肌缺血。"},{"q":"心包积液叩诊时","o":["心浊音界向左下增大","心浊音界向右增大","梨形心","心界向两侧增大，同时心浊音界可随体位而改变","靴型心"],"a":3,"e":"心包积液时心浊音界向两侧扩大，相对与绝对浊音界几乎相同并随体位改变，坐位呈烧瓶样、卧位心底部增宽。"},{"q":"临床出血患者，APTT延长而PT正常，最可能缺陷的是","o":["FⅩ","FⅡ","FⅤ","FⅧ","FⅫ"],"a":3,"e":"APTT反映内源性凝血途径，FⅧ、Ⅸ、Ⅺ、Ⅻ缺乏时APTT延长而PT正常；FⅩ、Ⅴ、Ⅱ及纤维蛋白原缺乏则PT与APTT同时延长。"},{"q":"急性病毒性肝炎时，反映肝损伤的最敏感指标是","o":["ALT","AST","ALP","AFP","MAO"],"a":0,"e":"ALT主要位于肝细胞胞质，半衰期47小时长于AST的17小时，急性肝细胞损伤时释放早而持久，升高幅度大于AST，是最敏感的指标。"},{"q":"正常心尖冲动直径的范围为","o":["0.5～1.0cm","1.0～1.5cm","1.5～2.0cm","2.0～2.5cm","2.5～3.0cm"],"a":3,"e":"正常成人心尖搏动位于第5肋间、左锁骨中线内侧0.5～1.0cm，搏动范围直径2.0～2.5cm。"},{"q":"一中年职业女性患者，择期行子宫肌瘤切除术，手术同意书不能由谁签字","o":["患者丈夫","患者本人","患者父母","患者子女","患者朋友"],"a":4,"e":"手术同意书应由病人本人签署，病人不具备完全民事行为能力时由其法定代理人签字；朋友不具法定代理资格，不能代签。"},{"q":"凝血功能障碍所致出血的实验室筛选试验，其主要表现是","o":["出血时间延长，束臂试验阳性","血小板减少，凝血时间延长","血小板减少，出血时间延长","血块回缩不佳，血小板聚集率下降","血浆凝血酶原时间延长，部分凝血活酶时间延长"],"a":4,"e":"凝血功能障碍累及共同途径凝血因子时，反映外源途径的PT与反映内源途径的APTT均延长；出血时间延长主要提示血小板或血管壁异常。"},{"q":"急性发热或体温上升期","o":["交感神经兴奋，心率加快，外周血管收缩，血压上升","交感神经兴奋，心率加快，外周血管舒张，血压下降","迷走神经兴奋，心率减慢，外周血管舒张，血压下降","迷走神经兴奋，心率减慢，外周血管收缩，血压上升","交感神经兴奋，心率减慢，外周血管舒张，血压上升"],"a":0,"e":"体温上升期交感神经兴奋，皮肤血管收缩、排汗停止使散热减少，心率加快、心输出量增加，血压可轻度上升，临床可见畏寒、寒战和面色苍白。"},{"q":"面容潮红、兴奋不安、鼻翼翕动、口唇疱疹、表情痛苦的面容是","o":["肾病面容","贫血面容","慢性病容","急性病容","黏液水肿面容"],"a":3,"e":"急性病容表现为面色潮红、兴奋不安、鼻翼扇动、口唇疱疹、表情痛苦，多见于肺炎链球菌肺炎、疟疾和流行性脑脊髓膜炎等急性感染性疾病。"},{"q":"患者对青霉素、磺胺等药物过敏应记录于","o":["现病史","既往史","家族史","个人史","婚育史"],"a":1,"e":"既往史包括既往健康状况、传染病史、手术外伤史、预防接种史、输血史及食物或药物过敏史，药物过敏应记录于此。"},{"q":"临床表现为咯血伴脓痰常见于下列疾病，但需除外","o":["干性支气管扩张","湿性支气管扩张","肺脓肿","化脓性肺炎","空洞型肺结核并发感染"],"a":0,"e":"干性支气管扩张以反复咯血为唯一表现，无大量脓痰；湿性支气管扩张、肺脓肿、化脓性肺炎和空洞型肺结核合并感染均可表现为咯血伴脓痰。"},{"q":"舒张早期奔马律由下列哪项构成","o":["S1分裂及S2","S1及主动脉瓣S2分裂","S1S2及病理性S4","S1及肺动脉瓣S2分裂","S1S2及病理性S3"],"a":4,"e":"舒张早期奔马律即病理性S3，出现在S2之后，与S1、S2共同构成三音律，心率增快时S2-S3间距与S1-S2相仿。"},{"q":"与血小板黏附功能无关的是","o":["血管内皮损伤","需有vWF","需有GPⅠb","需有Fg","需有GPV"],"a":3,"e":"血小板黏附依赖GPⅠb/Ⅴ/Ⅸ经vWF与暴露的内皮下胶原结合；纤维蛋白原经GPⅡb/Ⅲa介导血小板聚集，与黏附无关。"},{"q":"下列关于肋骨和肋间隙的描述，错误的是","o":["肋骨在背部与相应的胸椎相连","第11、12肋骨不与胸骨相连","肋间隙为两个肋骨之间的空隙","第1肋骨和第2肋骨之间的间隙为第2肋间隙","大多数肋骨可在胸壁上触及"],"a":3,"e":"肋间隙以其上方肋骨序号命名，第1肋骨下方的间隙为第1肋间隙；胸骨角两侧平第2肋软骨，是计数肋骨和肋间隙的标志。"},{"q":"下列主诉，哪一项最为确切","o":["咽痛、高热、寒战、气短","右胸痛、咳嗽","胃溃疡3年，呕血1h","活动后心悸气短2年，下肢水肿2周","2天来无诱因发热"],"a":3,"e":"主诉须简明扼要地概括主要症状及持续时间，含两个时间时应分段表述；胃溃疡3年属疾病诊断，不宜写入主诉。"},{"q":"风湿性心脏病，主动脉瓣狭窄最主要的体征是","o":["心脏向左下扩大明显","胸骨左缘第3、4肋间有舒张期杂音","周围血管征（＋）","抬举样心尖冲动","主动脉瓣区收缩期喷射性杂音伴第二心音减弱"],"a":4,"e":"主动脉瓣狭窄时血流经狭窄瓣口产生喷射性收缩中期杂音，向颈部传导并常伴震颤，因A2减弱而S2减弱；周围血管征见于主动脉瓣关闭不全。"},{"q":"安静状态下，出现ST段抬高，持续数分钟后回落，且不形成Q波，诊断上首先应该考虑","o":["劳力性心绞痛","急性心肌炎","急性肺栓塞","变异性心绞痛","主动脉夹层"],"a":3,"e":"变异型心绞痛由冠状动脉痉挛引起，发作时ST段暂时性抬高伴高耸T波和对应导联ST段下移，数分钟后回落，不出现异常Q波。"},{"q":"左侧大量胸腔积液时心浊音界出现的改变为","o":["心浊音界变小，甚至叩不出","使心脏呈横位，心界向两侧扩大","心界在患侧叩不出，在健侧向外移位","心底部浊音区增宽","心界向患侧移位"],"a":2,"e":"左侧大量胸腔积液遮盖心脏，患侧心浊音界叩不出，同时纵隔和心脏被推向健侧，故健侧心界向外移位。"},{"q":"中枢性发热见于","o":["肺炎","脑膜炎","脑出血","风湿热","肿瘤"],"a":2,"e":"中枢性发热由体温调节中枢直接受损引起，见于脑出血、脑外伤和脑炎等；肺炎、风湿热和肿瘤属致热原性发热。"},{"q":"下列哪种疾病不会引起消瘦","o":["糖尿病","甲状腺功能低下","慢性胆囊炎","胃溃疡","先天性乳糖酶缺乏"],"a":1,"e":"甲状腺功能减退时基础代谢率降低，体重增加而非消瘦；甲亢、糖尿病、慢性胆囊炎、胃溃疡及乳糖酶缺乏所致吸收不良均可引起消瘦。"},{"q":"下列为严重肺气肿的体征，但不符合的是","o":["视诊胸廓呈漏斗状","触诊语颤减弱","叩诊肺肝界下移","叩诊双肺呈过清音","听诊双侧呼吸音减弱"],"a":0,"e":"严重肺气肿胸廓呈桶状、前后径增大、肋间隙增宽，语颤减弱、双肺过清音、肺肝界下移、呼吸音减弱；漏斗胸为胸骨下段内陷的胸廓畸形。"},{"q":"心包叩击音最常见于","o":["大量心包积液","二尖瓣狭窄","缩窄性心包炎","主动脉瓣关闭不全","右束支传导阻滞"],"a":2,"e":"心包叩击音出现于S2后0.09～0.12秒，系舒张早期心室快速充盈受增厚心包限制而骤然中止所致，是缩窄性心包炎的特征性额外心音。"},{"q":"呕血时，出血量超过（ ）可致循环障碍（失血性休克）","o":["400ml","800ml","1000ml","1500ml","2000ml"],"a":2,"e":"上消化道短时间出血量超过1000ml，约占循环血容量20%，即可出现周围循环衰竭；出血量400～500ml仅引起头晕、心悸等全身症状。"},{"q":"以下均为急性腹膜炎感染中毒后期的表现，除外","o":["精神抑郁，面色灰白","皮肤及舌面干燥，眼球及两颊内陷","脉搏频数而无力","血压下降","呼吸频速表浅"],"a":4,"e":"感染中毒后期出现精神萎靡、面色灰白、皮肤及舌面干燥、眼球和两颊内陷、脉搏频数无力、血压下降；呼吸浅速是早期因腹痛限制腹式呼吸的表现。"},{"q":"反映肝脏纤维化的酶是","o":["γ-GT","ALP","MAO","ALT","AST"],"a":2,"e":"单胺氧化酶参与胶原纤维交联，血清MAO活性与肝内结缔组织增生程度正相关，用于观察肝纤维化和肝硬化程度；ALT、AST反映肝细胞损伤。"},{"q":"下列各项为产生局部水肿的原因，但应除外","o":["淋巴回流受阻","局部蜂窝织炎","低蛋白血症","局部静脉受压","毛细血管通透性增加"],"a":2,"e":"低蛋白血症使血浆胶体渗透压降低，引起全身性水肿；局部水肿由淋巴回流受阻、静脉受压、局部感染和毛细血管通透性增加所致。"},{"q":"病史中最重要的是","o":["个人史","婚姻史","家族史","既往史","现病史"],"a":4,"e":"现病史是病史的主体部分，完整反映疾病发生、发展、演变和诊治经过，是诊断与鉴别诊断的主要依据。"},{"q":"自律性最低的组织是","o":["窦房结","心房传导阻滞","房室交界组织","房室束","浦肯野纤维"],"a":4,"e":"传导系统自律性以窦房结最高，为60～100次/分，房室交界区次之，浦肯野纤维最低，约15～40次/分，故窦房结为正常起搏点。"},{"q":"关于心源性水肿的特点，正确的是","o":["从眼睑面部开始延及全身","从足部开始向上延及全身","水肿时最先出现腹水","上肢、颈部水肿","单侧下肢凹陷性水肿"],"a":1,"e":"心源性水肿因体循环静脉压升高、毛细血管滤过压增高，从下垂部位足部开始向上蔓延至全身，性质较坚实、移动性小，伴颈静脉怒张和肝大。"},{"q":"对退行性骨关节炎描述错误的是","o":["多见于中老年人","晨僵时间小于30min","关节肿痛对称分布","爬楼、久站后疼痛加剧","休息能缓解疼痛"],"a":2,"e":"退行性骨关节炎多见于中老年肥胖者，累及负重关节，晨僵小于30分钟，活动后加重而休息缓解，呈不对称分布；对称性多关节肿痛为类风湿关节炎特点。"},{"q":"临床上，一旦心房颤动患者的心室律变得规则，出现下列哪种情况的可能性最小","o":["恢复窦性心律","房扑及固定的房室传导比例","房性心动过速","如心室律变慢而规则，提示完全房室传导阻滞","出现二度Ⅰ型房室传导阻滞"],"a":4,"e":"二度Ⅰ型房室传导阻滞PR间期逐渐延长后脱漏QRS波，心室律不规则；房颤心室律变规则提示恢复窦性心律、房扑固定比例传导、房性心动过速或完全性房室传导阻滞伴逸搏心律。"},{"q":"下列关于心音分裂的说法正确的是","o":["S2分裂一般不因呼吸而变异","生理情况下心尖区最容易听到S2分裂","S2分裂都是病理性的","生理情况下吸气时S2分裂更加明显","反常分裂是指S2的主动脉瓣成分早于肺动脉瓣成分"],"a":3,"e":"深吸气时胸腔负压增大、右心回心血量增多，右室射血时间延长使P2延迟，故生理性S2分裂在吸气末更明显，青少年常见；反常分裂则吸气时变窄、呼气时变宽。"},{"q":"下列各项均为肝脏触诊检查方法，但除外","o":["单手触诊法","双手触诊法","钩指触诊法","浮沉触诊法","滑行触诊法"],"a":4,"e":"肝脏触诊采用单手触诊法、双手触诊法、钩指触诊法和浮沉触诊法；滑行触诊属深部触诊基本手法，多用于胆囊、膀胱及腹腔肿块的检查。"},{"q":"肛门指诊的正确方法是","o":["探查示指与肛门口垂直","探查示指先在肛门轻轻按摩","探查示指通过肛门后快速插入直肠","探查示指戴手套后即进行指诊","探查示指不需等待肛门括约肌放松后才进行指诊"],"a":1,"e":"肛门指诊时示指戴指套并涂润滑剂，先于肛门外口轻轻按摩，待肛门括约肌适应放松后再徐徐插入直肠，可减轻疼痛并避免损伤。"},{"q":"水冲脉的发生机制为","o":["脉压缩小","脉压增大","脉压正常","收缩压降低","舒张压升高"],"a":1,"e":"水冲脉由脉压增大所致，收缩压升高、舒张压降低使脉搏骤起骤落，见于主动脉瓣关闭不全、动脉导管未闭、甲状腺功能亢进和严重贫血。"},{"q":"下列说法正确的是","o":["心悸即心跳加快","心脏神经官能症时出现心悸，但不伴有心前区疼痛","心悸可见于窦性心动过缓","心悸与心律失常发生的严重程度成正比","心悸代表患有心脏疾病"],"a":2,"e":"心悸与心率快慢、心搏强弱及心律是否规则有关，心动过速、心动过缓及心律不齐均可引起；其程度与心律失常严重程度不成正比，也不代表必有器质性心脏病。"},{"q":"腹痛伴里急后重可见于","o":["肠结核","急性细菌性痢疾","伤寒","副伤寒","结肠癌"],"a":1,"e":"里急后重提示病变以直肠、乙状结肠为主，系直肠壁感觉神经受炎症刺激所致。急性细菌性痢疾好发于直肠和乙状结肠，故腹痛常伴里急后重。结肠癌、肠结核虽可累及肠道，但多数不出现典型里急后重。"},{"q":"对化脓性关节炎的特点描述不正确的是","o":["细菌直接侵入关节","多累及双下肢","伴有高热、寒战","开放性外伤是重要感染途径","常有多关节同时受累"],"a":4,"e":"化脓性关节炎由细菌直接侵入关节腔所致，多为单关节受累，故“多关节同时受累”的描述不正确。开放性外伤、关节穿刺是重要感染途径，起病急，常伴高热、寒战及局部红肿灼热。"}];
